/*Java program to insert element in binary tree*/

import java.util.LinkedList;
import java.util.Queue;
public class GFG {

/* A binary tree node has key, pointer to
    left child and a pointer to right child */

    static class Node {
        int key;
        Node left, right;

/*        constructor*/

        Node(int key)
        {
            this.key = key;
            left = null;
            right = null;
        }
    }
    static Node root;
    static Node temp = root;

/* Inorder traversal of a binary tree*/

    static void inorder(Node temp)
    {
        if (temp == null)
            return;
        inorder(temp.left);
        System.out.print(temp.key + " ");
        inorder(temp.right);
    }

/*function to insert element in binary tree */

    static void insert(Node temp, int key)
    {
        if (temp == null) {
            root = new Node(key);
            return;
        }
        Queue<Node> q = new LinkedList<Node>();
        q.add(temp);

/*        Do level order traversal until we find
        an empty place.*/

        while (!q.isEmpty()) {
            temp = q.peek();
            q.remove();
            if (temp.left == null) {
                temp.left = new Node(key);
                break;
            }
            else
                q.add(temp.left);
            if (temp.right == null) {
                temp.right = new Node(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        root = new Node(10);
        root.left = new Node(11);
        root.left.left = new Node(7);
        root.right = new Node(9);
        root.right.left = new Node(15);
        root.right.right = new Node(8);
        System.out.print(
            "Inorder traversal before insertion:");
        inorder(root);
        int key = 12;
        insert(root, key);
        System.out.print(
            "\nInorder traversal after insertion:");
        inorder(root);
    }
}

/*Java program to delete element
in binary tree*/

import java.util.LinkedList;
import java.util.Queue;
class GFG{

/*A binary tree node has key, pointer to
left child and a pointer to right child*/

static class Node
{
    int key;
    Node left, right;

/*    Constructor*/

    Node(int key)
    {
        this.key = key;
        left = null;
        right = null;
    }
}
static Node root;
static Node temp = root;

/*Inorder traversal of a binary tree*/

static void inorder(Node temp)
{
    if (temp == null)
        return;
    inorder(temp.left);
    System.out.print(temp.key + " ");
    inorder(temp.right);
}

/*Function to delete deepest
element in binary tree*/

static void deleteDeepest(Node root,
                          Node delNode)
{
    Queue<Node> q = new LinkedList<Node>();
    q.add(root);
    Node temp = null;

/*    Do level order traversal until last node*/

    while (!q.isEmpty())
    {
        temp = q.peek();
        q.remove();
        if (temp == delNode)
        {
            temp = null;
            return;
        }
        if (temp.right!=null)
        {
            if (temp.right == delNode)
            {
                temp.right = null;
                return;
        }
        else
            q.add(temp.right);
    }
    if (temp.left != null)
    {
        if (temp.left == delNode)
        {
            temp.left = null;
            return;
        }
        else
            q.add(temp.left);
    }
}
}

/*Function to delete given element
in binary tree*/

static void delete(Node root, int key)
{
    if (root == null)
        return;
    if (root.left == null &&
       root.right == null)
    {
        if (root.key == key)
        {
              root=null;
              return;
        }
        else
            return;
    }
    Queue<Node> q = new LinkedList<Node>();
    q.add(root);
    Node temp = null, keyNode = null;

/*    Do level order traversal until
    we find key and last node.*/

    while (!q.isEmpty())
    {
        temp = q.peek();
        q.remove();
        if (temp.key == key)
            keyNode = temp;
        if (temp.left != null)
            q.add(temp.left);
        if (temp.right != null)
            q.add(temp.right);
    }
    if (keyNode != null)
    {
        int x = temp.key;
        deleteDeepest(root, temp);
        keyNode.key = x;
    }
}

/*Driver code*/

public static void main(String args[])
{
    root = new Node(10);
    root.left = new Node(11);
    root.left.left = new Node(7);
    root.left.right = new Node(12);
    root.right = new Node(9);
    root.right.left = new Node(15);
    root.right.right = new Node(8);
    System.out.print("Inorder traversal " +
                     "before deletion:");
    inorder(root);
    int key = 11;
    delete(root, key);
    System.out.print("\nInorder traversal " +
                     "after deletion:");
    inorder(root);
}
}

/*JAVA implementation of tree using array
numbering starting from 0 to n-1.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class Array_imp {
    static int root = 0;
    static String[] str = new String[10];

/*create root*/

    public void Root(String key)
    {
        str[0] = key;
    }

/*create left son of root*/

    public void set_Left(String key, int root)
    {
        int t = (root * 2) + 1;
        if (str[root] == null) {
            System.out.printf("Can't set child at %d, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*create right son of root*/

    public void set_Right(String key, int root)
    {
        int t = (root * 2) + 2;
        if (str[root] == null) {
            System.out.printf("Can't set child at %d, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*Print tree*/

    public void print_Tree()
    {
        for (int i = 0; i < 10; i++) {
            if (str[i] != null)
                System.out.print(str[i]);
            else
                System.out.print("-");
        }
    }
}

/*Driver Code*/

class Tree {
    public static void main(String[] args)
    {
        Array_imp obj = new Array_imp();
        obj.Root("A");
        obj.set_Right("C", 0);
        obj.set_Left("D", 1);
        obj.set_Right("E", 1);
        obj.set_Left("F", 2);
        obj.print_Tree();
    }
}

/*Java program of AVL tree that handles duplicates*/

import java.util.*;
class solution {

/*    An AVL tree node*/

    static class node {
        int key;
        node left;
        node right;
        int height;
        int count;
    }

/*    A utility function to get height of the tree*/

    static int height(node N)
    {
        if (N == null)
            return 0;
        return N.height;
    }

/*    A utility function to get maximum of two integers*/

    static int max(int a, int b)
    {
        return (a > b) ? a : b;
    }

/* Helper function that allocates a new node with the given key and 
    null left and right pointers. */

    static node newNode(int key)
    {
        node node = new node();
        node.key = key;
        node.left = null;
        node.right = null;

/*new node is initially added at leaf*/

node.height = 1; 
        node.count = 1;
        return (node);
    }

/*    A utility function to right rotate subtree rooted with y
    See the diagram given above.*/

    static node rightRotate(node y)
    {
        node x = y.left;
        node T2 = x.right;

/*        Perform rotation*/

        x.right = y;
        y.left = T2;

/*        Update heights*/

        y.height = max(height(y.left), height(y.right)) + 1;
        x.height = max(height(x.left), height(x.right)) + 1;

/*        Return new root*/

        return x;
    }

/*    A utility function to left rotate subtree rooted with x
    See the diagram given above.*/

    static node leftRotate(node x)
    {
        node y = x.right;
        node T2 = y.left;

/*        Perform rotation*/

        y.left = x;
        x.right = T2;

/*        Update heights*/

        x.height = max(height(x.left), height(x.right)) + 1;
        y.height = max(height(y.left), height(y.right)) + 1;

/*        Return new root*/

        return y;
    }

/*    Get Balance factor of node N*/

    static int getBalance(node N)
    {
        if (N == null)
            return 0;
        return height(N.left) - height(N.right);
    }
    static node insert(node node, int key)
    {

/*1.  Perform the normal BST rotation */

        if (node == null)
            return (newNode(key));

/*        If key already exists in BST, increment count and return*/

        if (key == node.key) {
            (node.count)++;
            return node;
        }

/* Otherwise, recur down the tree */

        if (key < node.key)
            node.left = insert(node.left, key);
        else
            node.right = insert(node.right, key);

/* 2. Update height of this ancestor node */

        node.height = max(height(node.left), height(node.right)) + 1;

/* 3. Get the balance factor of this ancestor node to check whether 
       this node became unbalanced */

        int balance = getBalance(node);

/*        If this node becomes unbalanced, then there are 4 cases
        Left Left Case*/

        if (balance > 1 && key < node.left.key)
            return rightRotate(node);

/*        Right Right Case*/

        if (balance < -1 && key > node.right.key)
            return leftRotate(node);

/*        Left Right Case*/

        if (balance > 1 && key > node.left.key) {
            node.left = leftRotate(node.left);
            return rightRotate(node);
        }

/*        Right Left Case*/

        if (balance < -1 && key < node.right.key) {
            node.right = rightRotate(node.right);
            return leftRotate(node);
        }

/* return the (unchanged) node pointer */

        return node;
    }

/* Given a non-empty binary search tree, return the node with minimum 
   key value found in that tree. Note that the entire tree does not 
   need to be searched. */

    static node minValueNode(node node)
    {
        node current = node;

/* loop down to find the leftmost leaf */

        while (current.left != null)
            current = current.left;
        return current;
    }
    static node deleteNode(node root, int key)
    {

/*        STEP 1: PERFORM STANDARD BST DELETE*/

        if (root == null)
            return root;

/*        If the key to be deleted is smaller than the root's key,
        then it lies in left subtree*/

        if (key < root.key)
            root.left = deleteNode(root.left, key);

/*        If the key to be deleted is greater than the root's key,
        then it lies in right subtree*/

        else if (key > root.key)
            root.right = deleteNode(root.right, key);

/*        if key is same as root's key, then This is the node
        to be deleted*/

        else {

/*            If key is present more than once, simply decrement
            count and return*/

            if (root.count > 1) {
                (root.count)--;
                return null;
            }

/*            ElSE, delete the node
            node with only one child or no child*/

            if ((root.left == null) || (root.right == null)) {
                node temp = root.left != null ? root.left : root.right;

/*                No child case*/

                if (temp == null) {
                    temp = root;
                    root = null;
                }

/*One child case*/

else

/*Copy the contents of the non-empty child*/

root = temp; 
            }
            else {

/*                node with two children: Get the inorder successor (smallest
                in the right subtree)*/

                node temp = minValueNode(root.right);

/*                Copy the inorder successor's data to this node and update the count*/

                root.key = temp.key;
                root.count = temp.count;
                temp.count = 1;

/*                Delete the inorder successor*/

                root.right = deleteNode(root.right, temp.key);
            }
        }

/*        If the tree had only one node then return*/

        if (root == null)
            return root;

/*        STEP 2: UPDATE HEIGHT OF THE CURRENT NODE*/

        root.height = max(height(root.left), height(root.right)) + 1;

/*        STEP 3: GET THE BALANCE FACTOR OF THIS NODE (to check whether
        this node became unbalanced)*/

        int balance = getBalance(root);

/*        If this node becomes unbalanced, then there are 4 cases
        Left Left Case*/

        if (balance > 1 && getBalance(root.left) >= 0)
            return rightRotate(root);

/*        Left Right Case*/

        if (balance > 1 && getBalance(root.left) < 0) {
            root.left = leftRotate(root.left);
            return rightRotate(root);
        }

/*        Right Right Case*/

        if (balance < -1 && getBalance(root.right) <= 0)
            return leftRotate(root);

/*        Right Left Case*/

        if (balance < -1 && getBalance(root.right) > 0) {
            root.right = rightRotate(root.right);
            return leftRotate(root);
        }
        return root;
    }

/*    A utility function to print preorder traversal of the tree.
    The function also prints height of every node*/

    static void preOrder(node root)
    {
        if (root != null) {
            System.out.printf("%d(%d) ", root.key, root.count);
            preOrder(root.left);
            preOrder(root.right);
        }
    }

/* Driver program to test above function*/

    public static void main(String args[])
    {
        node root = null;

/* Coning tree given in the above figure */

        root = insert(root, 9);
        root = insert(root, 5);
        root = insert(root, 10);
        root = insert(root, 5);
        root = insert(root, 9);
        root = insert(root, 7);
        root = insert(root, 17);
        System.out.printf("Pre order traversal of the constructed AVL tree is \n");
        preOrder(root);
        deleteNode(root, 9);
        System.out.printf("\nPre order traversal after deletion of 9 \n");
        preOrder(root);
    }
}

/*JAVA Code to check if the tree is continuos or not*/

import java.util.*;
class GFG
{

/*Node structure*/

static class node
{
    int val;
    node left;
    node right;
    node()
    {
        this.val = 0;
        this.left = null;
        this.right= null;
    }
    node(int x)
    {
        this.val = x;
        this.left = null;
        this.right= null;
    }
    node(int x, node left, node right)
    {
        this.val = x;
        this.left = left;
        this.right= right;   
    }
};

/*Function to check if the tree is continuos or not*/

static boolean continuous(node root)
{

/*    If root is Null then tree isn't Continuos*/

    if (root == null)
        return false;
    int flag = 1;
    Queue<node> Q = new LinkedList<>();
    Q.add(root);
    node temp;

/*    BFS Traversal*/

    while (!Q.isEmpty())
    {
        temp = Q.peek();
        Q.remove();

/*        Move to left child*/

        if (temp.left != null)
        {

/*            if difference between parent and child is
            equal to 1 then do continue otherwise make
            flag = 0 and break*/

            if (Math.abs(temp.left.val - temp.val) == 1)
                Q.add(temp.left);
            else
            {
                flag = 0;
                break;
            }
        }

/*        Move to right child*/

        if (temp.right != null)
        {

/*            if difference between parent and child is
            equal to 1 then do continue otherwise make
            flag = 0 and break*/

            if (Math.abs(temp.right.val - temp.val) == 1)
                Q.add(temp.right);
            else           
            {
                flag = 0;
                break;
            }
        }
    }
    if (flag != 0)
        return true;
    else
        return false;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Constructing the Tree*/

    node root = new node(3);
    root.left = new node(2);
    root.right = new node(4);
    root.left.left = new node(1);
    root.left.right = new node(3);
    root.right.right = new node(5);

/*    Function Call*/

    if (continuous(root))
        System.out.print("True\n");
    else
        System.out.print("False\n");
}
}

/*Java program to construct an expression tree*/

import java.util.Stack;

/*Java program for expression tree*/

class Node {
    char value;
    Node left, right;
    Node(char item) {
        value = item;
        left = right = null;
    }
}
class ExpressionTree {

/*    A utility function to check if 'c'
    is an operator*/

    boolean isOperator(char c) {
        if (c == '+' || c == '-'
                || c == '*' || c == '/'
                || c == '^') {
            return true;
        }
        return false;
    }

/*    Utility function to do inorder traversal*/

    void inorder(Node t) {
        if (t != null) {
            inorder(t.left);
            System.out.print(t.value + " ");
            inorder(t.right);
        }
    }

/*    Returns root of constructed tree for given
    postfix expression*/

    Node constructTree(char postfix[]) {
        Stack<Node> st = new Stack<Node>();
        Node t, t1, t2;

/*        Traverse through every character of
        input expression*/

        for (int i = 0; i < postfix.length; i++) {

/*            If operand, simply push into stack*/

            if (!isOperator(postfix[i])) {
                t = new Node(postfix[i]);
                st.push(t);

/*operator*/

} else 
            {
                t = new Node(postfix[i]);

/*                Pop two top nodes
                Store top
Remove top*/

t1 = st.pop();      
                t2 = st.pop();

/*                  make them children*/

                t.right = t1;
                t.left = t2;

/*                System.out.println(t1 + "" + t2);
                Add this subexpression to stack*/

                st.push(t);
            }
        }

/*          only element will be root of expression
        tree*/

        t = st.peek();
        st.pop();
        return t;
    }

/*Driver program to test above*/

    public static void main(String args[]) {
        ExpressionTree et = new ExpressionTree();
        String postfix = "ab+ef*g*-";
        char[] charArray = postfix.toCharArray();
        Node root = et.constructTree(charArray);
        System.out.println("infix expression is");
        et.inorder(root);
    }
}

/*Java program to print inorder
traversal without recursion
and stack*/

/* A binary tree tNode has data,
   a pointer to left child
   and a pointer to right child */

class tNode {
    int data;
    tNode left, right;
    tNode(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree {
    tNode root;

/* Function to traverse a
       binary tree without recursion
       and without stack */

    void MorrisTraversal(tNode root)
    {
        tNode current, pre;
        if (root == null)
            return;
        current = root;
        while (current != null)
        {
            if (current.left == null)
            {
                System.out.print(current.data + " ");
                current = current.right;
            }
            else {

/* Find the inorder
                    predecessor of current
                 */

                pre = current.left;
                while (pre.right != null
                       && pre.right != current)
                    pre = pre.right;

/* Make current as right
                   child of its
                 * inorder predecessor */

                if (pre.right == null) {
                    pre.right = current;
                    current = current.left;
                }

/* Revert the changes made
                   in the 'if' part
                   to restore the original
                   tree i.e., fix
                   the right child of predecessor*/

                else
                {
                    pre.right = null;
                    System.out.print(current.data + " ");
                    current = current.right;
                } 
            } 
        } 
    }

/*    Driver Code*/

    public static void main(String args[])
    {

/* Constructed binary tree is
               1
             /   \
            2      3
          /   \
         4     5
        */

        BinaryTree tree = new BinaryTree();
        tree.root = new tNode(1);
        tree.root.left = new tNode(2);
        tree.root.right = new tNode(3);
        tree.root.left.left = new tNode(4);
        tree.root.left.right = new tNode(5);
        tree.MorrisTraversal(tree.root);
    }
}

/*Java program for finding postorder
traversal of BST from preorder traversal*/

import java.util.*;
class Solution {
    static class INT {
        int data;
        INT(int d) { data = d; }
    }

/*    Function to find postorder traversal from
    preorder traversal.*/

    static void findPostOrderUtil(int pre[], int n,
                                  int minval, int maxval,
                                  INT preIndex)
    {

/*        If entire preorder array is traversed then
        return as no more element is left to be
        added to post order array.*/

        if (preIndex.data == n)
            return;

/*        If array element does not lie in range specified,
        then it is not part of current subtree.*/

        if (pre[preIndex.data] < minval
            || pre[preIndex.data] > maxval) {
            return;
        }

/*        Store current value, to be printed later, after
        printing left and right subtrees. Increment
        preIndex to find left and right subtrees,
        and pass this updated value to recursive calls.*/

        int val = pre[preIndex.data];
        preIndex.data++;

/*        All elements with value between minval and val
        lie in left subtree.*/

        findPostOrderUtil(pre, n, minval, val, preIndex);

/*        All elements with value between val and maxval
        lie in right subtree.*/

        findPostOrderUtil(pre, n, val, maxval, preIndex);
        System.out.print(val + " ");
    }

/*    Function to find postorder traversal.*/

    static void findPostOrder(int pre[], int n)
    {

/*        To store index of element to be
        traversed next in preorder array.
        This is passed by reference to
        utility function.*/

        INT preIndex = new INT(0);
        findPostOrderUtil(pre, n, Integer.MIN_VALUE,
                          Integer.MAX_VALUE, preIndex);
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int pre[] = { 40, 30, 35, 80, 100 };
        int n = pre.length;

/*        Calling function*/

        findPostOrder(pre, n);
    }
}

/*        run loop from 1 to length of pre*/
import java.io.*;
class GFG {
    public void getPostOrderBST(int pre[])
    {
        int pivotPoint = 0;

/*        print from pivot length -1 to zero*/

        for (int i = 1; i < pre.length; i++)
        {
            if (pre[0] <= pre[i])
            {
                pivotPoint = i;
                break;
            }
        }

/*        print from end to pivot length*/

        for (int i = pivotPoint - 1; i > 0; i--)
        {
            System.out.print(pre[i] + " ");
        }

/*    Driver Code*/

        for (int i = pre.length - 1; i >= pivotPoint; i--)
        {
            System.out.print(pre[i] + " ");
        }
        System.out.print(pre[0]);
    }

/*Java program to find binary tree with given inorder
traversal*/

import java.util.Vector;

/* Class containing left and right child of current 
 node and key value*/

class Node {
    int data;
    Node left, right;
    public Node(int item) {
        data = item;
        left = null;
        right = null;
    }
}

/* Class to print Level Order Traversal */

class BinaryTree {
    Node root;

/*    A utility function to do preorder traversal of BST*/

    void preOrder(Node node) {
        if (node != null) {
            System.out.print(node.data + " "    );
            preOrder(node.left);
            preOrder(node.right);
        }
    }

/*    Function for constructing all possible trees with
    given inorder traversal stored in an array from
    arr[start] to arr[end]. This function returns a
    vector of trees.*/

    Vector<Node> getTrees(int arr[], int start, int end) {

/*        List to store all possible trees*/

        Vector<Node> trees= new Vector<Node>();

/* if start > end then subtree will be empty so
         returning NULL in the list */

        if (start > end) {
            trees.add(null);
            return trees;
        }

/* Iterating through all values from start to end
         for constructing left and right subtree
         recursively */

        for (int i = start; i <= end; i++) {

/* Constructing left subtree */

            Vector<Node> ltrees = getTrees(arr, start, i - 1);

/* Constructing right subtree */

            Vector<Node> rtrees = getTrees(arr, i + 1, end);

/* Now looping through all left and right subtrees
             and connecting them to ith root below */

            for (int j = 0; j < ltrees.size(); j++) {
                for (int k = 0; k < rtrees.size(); k++) {

/*                    Making arr[i] as root*/

                    Node node = new Node(arr[i]);

/*                    Connecting left subtree*/

                    node.left = ltrees.get(j);

/*                    Connecting right subtree*/

                    node.right = rtrees.get(k);

/*                    Adding this tree to list*/

                    trees.add(node);
                }
            }
        }
        return trees;
    }

/*Driver Program to test above functions*/

public static void main(String args[]) {
        int in[] = {4, 5, 7};
