/*Java program to populate inorder traversal of all nodes*/

/*A binary tree node*/

class Node
{
    int data;
    Node left, right, next;
    Node(int item)
    {
        data = item;
        left = right = next = null;
    }
}
class BinaryTree
{
    Node root;
    static Node next = null;

/* Set next of p and all descendants of p by traversing them in
       reverse Inorder */

    void populateNext(Node node)
    {

/*        The first visited node will be the rightmost node
        next of the rightmost node will be NULL*/

        if (node != null)
        {

/*            First set the next pointer in right subtree*/

            populateNext(node.right);

/*            Set the next as previously visited node in reverse Inorder*/

            node.next = next;

/*            Change the prev for subsequent node*/

            next = node;

/*            Finally, set the next pointer in left subtree*/

            populateNext(node.left);
        }
    }

/* Constructed binary tree is
            10
           /   \
          8      12
         /
        3    */
    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(12);
        tree.root.left.left = new Node(3);

/*        Populates nextRight pointer in all nodes*/

        tree.populateNext(tree.root);

/*        Let us see the populated values*/

        Node ptr = tree.root.left.left;
        while (ptr != null)
        {

/*            -1 is printed if there is no successor*/

            int print = ptr.next != null ? ptr.next.data : -1;
            System.out.println("Next of " + ptr.data + " is: " + print);
            ptr = ptr.next;
        }
    }
}

/*Java program to populate inorder traversal of all nodes*/

class Node
{
    int data;
    Node left, right, next;

    Node(int item)
    {
        data = item;
        left = right = next = null;
    }
}

/*A wrapper over populateNextRecur*/

    void populateNext(Node node) {

/*        The first visited node will be the rightmost node
        next of the rightmost node will be NULL*/

        populateNextRecur(node, next);
    }

/* Set next of all descendants of p by traversing them in reverse Inorder */

    void populateNextRecur(Node p, Node next_ref) {
        if (p != null) {

/*           First set the next pointer in right subtree*/

            populateNextRecur(p.right, next_ref);

/*            Set the next as previously visited node in reverse Inorder*/

            p.next = next_ref;

/*            Change the prev for subsequent node*/

            next_ref = p;

/*            Finally, set the next pointer in right subtree*/

            populateNextRecur(p.left, next_ref);
        }
    }

/*Java program to find inorder successor of a node */

class Solution
{

/*A Binary Tree Node */

 static class Node
{ 
    int data; 
     Node left, right; 
}

/*Temporary node for case 2 */

static Node temp = new Node();

/*Utility function to create a new tree node */

static Node newNode(int data) 
 {
    Node temp = new Node(); 
    temp.data = data; 
    temp.left = temp.right = null; 
    return temp; 
}

/*function to find left most node in a tree */

static Node leftMostNode(Node node) 
 {
    while (node != null && node.left != null) 
        node = node.left; 
    return node; 
}

/*function to find right most node in a tree */

static Node rightMostNode(Node node) 
 {
    while (node != null && node.right != null) 
        node = node.right; 
    return node; 
}

/*recursive function to find the Inorder Scuccessor 
when the right child of node x is null */

static Node findInorderRecursive(Node root, Node x ) 
 {
    if (root==null) 
        return null; 
    if (root==x || (temp = findInorderRecursive(root.left,x))!=null || 
                (temp = findInorderRecursive(root.right,x))!=null) 
    { 
        if (temp!=null) 
        { 
            if (root.left == temp) 
            { 
                System.out.print( "Inorder Successor of "+x.data); 
                System.out.print( " is "+ root.data + "\n"); 
                return null; 
            } 
        } 
        return root; 
    } 
    return null; 
}

/*function to find inorder successor of 
a node */

static void inorderSuccesor(Node root, Node x) 
 {

/*    Case1: If right child is not null */

    if (x.right != null) 
    { 
        Node inorderSucc = leftMostNode(x.right); 
        System.out.print("Inorder Successor of "+x.data+" is "); 
        System.out.print(inorderSucc.data+"\n"); 
    }

/*    Case2: If right child is null */

    if (x.right == null) 
    {     
        int f = 0; 
        Node rightMost = rightMostNode(root);

/*        case3: If x is the right most node */

        if (rightMost == x) 
            System.out.print("No inorder successor! Right most node.\n"); 
        else
            findInorderRecursive(root, x); 
    } 
}

