        root.right.left = new Node(24); 
        root.right.right = new Node(32); 
        int N = 6;

/*        prints n-th node found */

        NthPostordernode(root, N);
    }
}

/*Java program to do level order
traversal line by line*/

import java.util.LinkedList;
import java.util.Queue;
public class GFG {

/*A Binary Tree Node*/

  static class Node {
    int data;
    Node left;
    Node right;
    Node(int data) {
      this.data = data;
      left = null;
      right = null;
    }
  }

/*  Prints level order traversal line
  by line using two queues.*/

  static void levelOrder(Node root) {
    if (root == null)
      return;

/* Create an empty queue for
    level order traversal*/

    Queue<Node> q = new LinkedList<>();

/*    Pushing root node into the queue.*/

    q.add(root);

/*    Pushing delimiter into the queue.*/

    q.add(null);

/*    Executing loop till queue becomes
    empty*/

    while (!q.isEmpty()) {
      Node curr = q.poll();

/*      condition to check the
      occurence of next level*/

      if (curr == null) {
        if (!q.isEmpty()) {
          q.add(null);
          System.out.println();
        }
      } else {

/*        Pushing left child current node*/

        if (curr.left != null)
          q.add(curr.left);

/*        Pushing right child current node*/

        if (curr.right != null)
          q.add(curr.right);
        System.out.print(curr.data + " ");
      }
    }
  }

/*  Driver function*/

  public static void main(String[] args) {

/*    Let us create binary tree
    shown above*/

    Node root = new Node(1);
    root.left = new Node(2);
    root.right = new Node(3);
    root.left.left = new Node(4);
    root.left.right = new Node(5);
    root.right.right = new Node(6);
    levelOrder(root);
  }
}

/*Java program to print Zig-Zag traversal
in groups of size 2.*/

import java.util.*;
class GFG
{

/*A Binary Tree Node*/

static class Node
{
    Node left;
    int data;
    Node right;
};

/* Function to print the level order of
given binary tree. Direction of printing
level order traversal of binary tree changes
after every two levels */

static void modifiedLevelOrder(Node node)
{

/*    For null root*/

    if (node == null)
        return;
    if (node.left == null && node.right == null)
    {
        System.out.print(node.data);
        return;
    }

/*    Maintain a queue for normal
    level order traversal*/

    Queue<Node> myQueue = new LinkedList<>();

/* Maintain a stack for
    printing nodes in reverse
    order after they are popped
    out from queue.*/

    Stack<Node> myStack = new Stack<>();
    Node temp = null;

/*    sz is used for storing
    the count of nodes in a level*/

    int sz;

/*    Used for changing the direction
    of level order traversal*/

    int ct = 0;

/*    Used for changing the direction
    of level order traversal*/

    boolean rightToLeft = false;

/*    Push root node to the queue*/

    myQueue.add(node);

/*    Run this while loop till queue got empty*/

    while (!myQueue.isEmpty())
    {
        ct++;
        sz = myQueue.size();

/*        Do a normal level order traversal*/

        for (int i = 0; i < sz; i++)
        {
            temp = myQueue.peek();
            myQueue.remove();

/*For printing nodes from left to right,
            simply print the nodes in the order in which
            they are being popped out from the queue.*/

            if (rightToLeft == false)
                System.out.print(temp.data + " ");

/* For printing nodes from right to left,
            push the nodes to stack instead of printing them.*/

            else
                myStack.push(temp);        
            if (temp.left != null)
                myQueue.add(temp.left);
            if (temp.right != null)
                myQueue.add(temp.right);
        }
        if (rightToLeft == true)
        {

/*            for printing the nodes in order
            from right to left*/

            while (!myStack.isEmpty())
            {
                temp = myStack.peek();
                myStack.pop();
                System.out.print(temp.data + " ");
            }
        }

/*Change the direction of printing
        nodes after every two levels.*/

        if (ct == 2)
        {
            rightToLeft = !rightToLeft;
            ct = 0;
        }
        System.out.print("\n");
    }
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Let us create binary tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(6);
    root.right.right = newNode(7);
    root.left.left.left = newNode(8);
    root.left.left.right = newNode(9);
    root.left.right.left = newNode(3);
    root.left.right.right = newNode(1);
    root.right.left.left = newNode(4);
    root.right.left.right = newNode(2);
    root.right.right.left = newNode(7);
    root.right.right.right = newNode(2);
    root.left.right.left.left = newNode(16);
    root.left.right.left.right = newNode(17);
    root.right.left.right.left = newNode(18);
    root.right.right.left.right = newNode(19);
    modifiedLevelOrder(root);
}
}

/*JAVA program to print Zig-Zag traversal
in groups of size 2.*/

import java.util.*;
class GFG
{
static final int LEFT = 0;
static final int RIGHT = 1;
static  int ChangeDirection(int Dir)
{
Dir = 1 - Dir;
return Dir;
}

/*A Binary Tree Node*/

static class node
{
    int data;
    node left, right;
};

/*Utility function to create a new tree node*/

static node newNode(int data)
{
    node temp = new node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/* Function to print the level order of
   given binary tree. Direction of printing
   level order traversal of binary tree changes
   after every two levels */

static void modifiedLevelOrder(node root)
{
    if (root == null)
        return ;   
    int dir = LEFT;
    node temp;
    Queue <node > Q = new LinkedList<>();
    Stack <node > S = new Stack<>();
    S.add(root);

/*    Run this while loop till queue got empty*/

    while (!Q.isEmpty() || !S.isEmpty())
    {
        while (!S.isEmpty())
        {
            temp = S.peek();
            S.pop();
            System.out.print(temp.data + " ");
            if (dir == LEFT)
            {
                if (temp.left != null)
                    Q.add(temp.left);
                if (temp.right != null)
                    Q.add(temp.right);
            }

/* For printing nodes from right to left,
            push the nodes to stack
             instead of printing them.*/

            else {
                if (temp.right != null)
                    Q.add(temp.right);
                if (temp.left != null)
                    Q.add(temp.left);
            }
        }      
        System.out.println();

/*            for printing the nodes in order
            from right to left*/

        while (!Q.isEmpty())
        {
            temp = Q.peek();
            Q.remove();
            System.out.print(temp.data + " ");
            if (dir == LEFT) {
                if (temp.left != null)
                    S.add(temp.left);
                if (temp.right != null)
                    S.add(temp.right);
            } else {
                if (temp.right != null)
                    S.add(temp.right);
                if (temp.left != null)
                    S.add(temp.left);
            }
        }
        System.out.println();

/*        Change the direction of traversal.*/

        dir = ChangeDirection(dir);
    }
}

/*Driver code*/

public static void main(String[] args)
{

/*    Let us create binary tree*/

    node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(6);
    root.right.right = newNode(7);
    root.left.left.left = newNode(8);
    root.left.left.right = newNode(9);
    root.left.right.left = newNode(3);
    root.left.right.right = newNode(1);
    root.right.left.left = newNode(4);
    root.right.left.right = newNode(2);
    root.right.right.left = newNode(7);
    root.right.right.right = newNode(2);
    root.left.right.left.left = newNode(16);
    root.left.right.left.right = newNode(17);
    root.right.left.right.left = newNode(18);
    root.right.right.left.right = newNode(19);
    modifiedLevelOrder(root);
}
}

/*A recursive java program to print reverse level order traversal*/

/*A binary tree node*/

class Node 
{
    int data;
    Node left, right;
    Node(int item) 
    {
        data = item;
        left = right;
    }
}
class BinaryTree 
{
    Node root;

/* Function to print REVERSE level order traversal a tree*/

    void reverseLevelOrder(Node node) 
    {
        int h = height(node);
        int i;
        for (i = h; i >= 1; i--) 
        {
            printGivenLevel(node, i);
        }
    }

/* Print nodes at a given level */

    void printGivenLevel(Node node, int level) 
    {
        if (node == null)
            return;
        if (level == 1)
            System.out.print(node.data + " ");
        else if (level > 1) 
        {
            printGivenLevel(node.left, level - 1);
            printGivenLevel(node.right, level - 1);
        }
    }

/* Compute the "height" of a tree -- the number of
     nodes along the longest path from the root node
     down to the farthest leaf node.*/

    int height(Node node) 
    {
        if (node == null)
            return 0;
        else
        {

/* compute the height of each subtree */

            int lheight = height(node.left);
            int rheight = height(node.right);

/* use the larger one */

            if (lheight > rheight)
                return (lheight + 1);
            else
                return (rheight + 1);
        }
    }

/*    Driver program to test above functions*/

    public static void main(String args[]) 
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create trees shown in above diagram*/

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        System.out.println("Level Order traversal of binary tree is : ");
        tree.reverseLevelOrder(tree.root);
    }
}

/*Java program to Reverse Tree path*/

import java.util.*;
class solution
{

/*A Binary Tree Node*/

static class Node {
    int data;
     Node left, right;
};

/*class for int values*/

static class INT {
    int data;
};

/*'data' is input. We need to reverse path from
root to data.
'level' is current level.
'temp' that stores path nodes.
'nextpos' used to pick next item for reversing.*/

 static Node reverseTreePathUtil(Node root, int data,
       Map<Integer, Integer> temp, int level, INT nextpos)
{

/*    return null if root null*/

    if (root == null)
        return null;

/*    Final condition
    if the node is found then*/

    if (data == root.data) {

/*        store the value in it's level*/

        temp.put(level,root.data);

/*        change the root value with the current 
        next element of the map*/

        root.data = temp.get(nextpos.data);

/*        increment in k for the next element*/

        nextpos.data++;
        return root;
    }

/*    store the data in perticular level*/

    temp.put(level,root.data);

/*    We go to right only when left does not 
    contain given data. This way we make sure
    that correct path node is stored in temp[]*/

    Node left, right=null;
    left = reverseTreePathUtil(root.left, data, temp, 
                                  level + 1, nextpos);
    if (left == null)
        right = reverseTreePathUtil(root.right, data, 
                            temp, level + 1, nextpos);

/*    If current node is part of the path,
    then do reversing.*/

    if (left!=null || right!=null) {
        root.data = temp.get(nextpos.data);
        nextpos.data++;
        return (left!=null ? left : right);
    }

/*    return null if not element found*/

    return null;
}

/*Reverse Tree path*/

 static void reverseTreePath(Node root, int data)
{

/*    store per level data*/

    Map< Integer, Integer> temp= new HashMap< Integer, Integer>();

/*    it is for replacing the data*/

    INT nextpos=new INT();
    nextpos.data = 0;

/*    reverse tree path*/

    reverseTreePathUtil(root, data, temp, 0, nextpos);
}

/*INORDER*/

static void inorder(Node root)
{
    if (root != null) {
        inorder(root.left);
        System.out.print( root.data + " ");
        inorder(root.right);
    }
}

/*Utility function to create a new tree node*/

 static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver program to test above functions*/

public static void main(String args[])
{

/*    Let us create binary tree shown in above diagram*/

    Node root = newNode(7);
    root.left = newNode(6);
    root.right = newNode(5);
    root.left.left = newNode(4);
    root.left.right = newNode(3);
    root.right.left = newNode(2);
    root.right.right = newNode(1);

/*   7
         /    \
        6       5
       / \     / \
      4  3     2  1         */

    int data = 4;

/*    Reverse Tree Path*/

    reverseTreePath(root, data);

/*    Traverse inorder*/

    inorder(root);
}
}

/*Java program for the above approach*/

import java.util.*;
class GFG
{
static class Node {
    int data;
    Node left;
    Node right;
    Node(int value)
    { this.data = value; }
};

/*Function to print inorder
traversal of the tree*/

static void inorder(Node temp)
{
    if (temp == null)
        return;
    inorder(temp.left);
    System.out.print(temp.data+" ");
    inorder(temp.right);
}

/*Utility function to track
root to leaf paths*/

static void reverseTreePathUtil(Node root, ArrayList<Node> path,
                         int pathLen, int key)
{

/*    Check if root is null then return*/

    if (root == null)
        return;

/*    Store the node in path array*/

    path.set(pathLen, root);
    pathLen++;

/*    Check if we find the node upto
    which oath needs to be
    reversed*/

    if (root.data == key) {

/*        Current path array contains
        the path which needs
        to be reversed*/

        int i = 0, j = pathLen - 1;

/*        Swap the data of two nodes*/

        while (i < j)
        {
            int temp = path.get(i).data;
            path.get(i).data = path.get(j).data;
            path.get(j).data = temp;
            i++;
            j--;
        }
    }

/*    Check if the node is a
    leaf node then return*/

    if (root.left == null && root.right == null)
        return;

/*    Call utility function for
    left and right subtree
    recursively*/

    reverseTreePathUtil(root.left, path,
                             pathLen, key);
    reverseTreePathUtil(root.right, path,
                              pathLen, key);
}

/*Function to reverse tree path*/

static void reverseTreePath(Node root, int key)
{
    if (root == null)
        return;

/*    Initialize a vector to store paths*/

    ArrayList<Node> path = new ArrayList<Node>();
    for(int i = 0; i < 50; i++)
    {
        path.add(null);
    }
    reverseTreePathUtil(root, path, 0, key);
}

/*Driver Code*/

public static void main(String []args)
{
    Node root = new Node(7);
    root.left = new Node(6);
    root.right = new Node(5);
    root.left.left = new Node(4);
    root.left.right = new Node(3);
    root.right.left = new Node(2);
    root.right.right = new Node(1);

/*     7
         /    \
        6       5
       / \     / \
      4  3     2  1          */

    int key = 4;
    reverseTreePath(root, key);
    inorder(root);
}
}

/*Java program for special level order traversal*/

import java.util.LinkedList;
import java.util.Queue;

/* Class containing left and right child of current 
   node and key value*/

class Node 
{
    int data;
    Node left, right;
    public Node(int item) 
    {
        data = item;
        left = right = null;
    }
}

/* Given a perfect binary tree, print its nodes in specific
       level order */
class BinaryTree 
{
    Node root;
    void printSpecificLevelOrder(Node node) 
    {
        if (node == null)
            return;

/*        Let us print root and next level first*/

        System.out.print(node.data);

/*          Since it is perfect Binary Tree, right is not checked*/

        if (node.left != null)
            System.out.print(" " + node.left.data + " " + node.right.data);

/*        Do anything more if there are nodes at next level in
        given perfect Binary Tree*/

        if (node.left.left == null)
            return;

/*        Create a queue and enqueue left and right children of root*/

        Queue<Node> q = new LinkedList<Node>();
        q.add(node.left);
        q.add(node.right);

/*        We process two nodes at a time, so we need two variables
        to store two front items of queue*/

        Node first = null, second = null;

/*        traversal loop*/

        while (!q.isEmpty()) 
        {

/*            Pop two items from queue*/

            first = q.peek();
            q.remove();
            second = q.peek();
            q.remove();

/*            Print children of first and second in reverse order*/

            System.out.print(" " + first.left.data + " " +second.right.data);
            System.out.print(" " + first.right.data + " " +second.left.data);

/*            If first and second have grandchildren, enqueue them
            in reverse order*/

            if (first.left.left != null) 
            {
                q.add(first.left);
                q.add(second.right);
                q.add(first.right);
                q.add(second.left);
            }
        }
    }

/*    Driver program to test for above functions*/

    public static void main(String args[]) 
    {
