/*Java program for special order traversal*/

import java.util.*;

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

class Node
{
    int data;
    Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
class BinaryTree
{
    Node root;

/*Function body*/

    void printSpecificLevelOrderUtil(Node root, Stack<Node> s)
    {
        if (root == null)
            return;

/*        Create a queue and enqueue left and right
        children of root*/

        Queue<Node> q = new LinkedList<Node>();
        q.add(root.left);
        q.add(root.right);

/*        We process two nodes at a time, so we
        need two variables to store two front
        items of queue*/

        Node first = null, second = null;

/*        traversal loop*/

        while (!q.isEmpty())
        {

/*            Pop two items from queue*/

            first = q.peek();
            q.poll();
            second = q.peek();
            q.poll();

/*            Push first and second node's chilren
            in reverse order*/

            s.push(second.left);
            s.push(first.right);
            s.push(second.right);
            s.push(first.left);

/*            If first and second have grandchildren,
            enqueue them in specific order*/

            if (first.left.left != null)
            {
                q.add(first.right);
                q.add(second.left);
                q.add(first.left);
                q.add(second.right);
            }
        }
    }

/* Given a perfect binary tree, print its nodes in
       specific level order */

    void printSpecificLevelOrder(Node root)
    {

/*        create a stack and push root*/

        Stack<Node> s = new Stack<Node>();

/*        Push level 1 and level 2 nodes in stack*/

        s.push(root);

/*        Since it is perfect Binary Tree, right is
        not checked*/

        if (root.left != null)
        {
            s.push(root.right);
            s.push(root.left);
        }

/*        Do anything more if there are nodes at next
        level in given perfect Binary Tree*/

        if (root.left.left != null)
            printSpecificLevelOrderUtil(root, s);

/*        Finally pop all Nodes from stack and prints
        them.*/

        while (!s.empty())
        {
            System.out.print(s.peek().data + " ");
            s.pop();
        }
    }

/*    Driver program to test the above functions*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        System.out.println("Specific Level Order Traversal "
                + "of Binary Tree is ");
        tree.printSpecificLevelOrder(tree.root);
    }

/*Java program to reverse alternate 
levels of  perfect binary tree*/

/*A binary tree node*/

class Node {
    char data;
    Node left, right;
    Node(char item) {
        data = item;
        left = right = null;
    }
}

/*class to access index value by reference*/

class Index {
    int index;
}
class BinaryTree {
    Node root;
    Index index_obj = new Index();

/*    function to store alternate levels in a tree*/

    void storeAlternate(Node node, char arr[], 
                         Index index, int l) 
    {

/*        base case*/

        if (node == null) {
            return;
        }

/*        store elements of left subtree*/

        storeAlternate(node.left, arr, index, l + 1);

/*        store this node only if level is odd*/

        if (l % 2 != 0) {
            arr[index.index] = node.data;
            index.index++;
        }
        storeAlternate(node.right, arr, index, l + 1);
    }

/*    Function to modify Binary Tree 
    (All odd level nodes are
    updated by taking elements from 
    array in inorder fashion)*/

    void modifyTree(Node node, char arr[], 
                      Index index, int l) 
    {

/*        Base case*/

        if (node == null) {
            return;
        }

/*        Update nodes in left subtree*/

        modifyTree(node.left, arr, index, l + 1);

/*        Update this node only if 
        this is an odd level node*/

        if (l % 2 != 0) {
            node.data = arr[index.index];
            (index.index)++;
        }

/*        Update nodes in right subtree*/

        modifyTree(node.right, arr, index, l + 1);
    }

/*    A utility function to reverse an array from index
    0 to n-1*/

    void reverse(char arr[], int n) {
        int l = 0, r = n - 1;
        while (l < r) {
            char temp = arr[l];
            arr[l] = arr[r];
            arr[r] = temp;
            l++;
            r--;
        }
    }
    void reverseAlternate() 
    {
        reverseAlternate(root);
    }

/*    The main function to reverse 
    alternate nodes of a binary tree*/

    void reverseAlternate(Node node) 
    {

/*        Create an auxiliary array to store 
        nodes of alternate levels*/

        char[] arr = new char[100];

/*        First store nodes of alternate levels*/

        storeAlternate(node, arr, index_obj, 0);

/*        index_obj.index = 0;
        Reverse the array*/

        reverse(arr, index_obj.index);

/*        Update tree by taking elements from array*/

        index_obj.index = 0;
        modifyTree(node, arr, index_obj, 0);
    }
    void printInorder() {
        printInorder(root);
    }

/*    A utility function to print 
    indorder traversal of a
    binary tree*/

    void printInorder(Node node) {
        if (node == null) {
            return;
        }
        printInorder(node.left);
        System.out.print(node.data + " ");
        printInorder(node.right);
    }

/*    Driver program to test the above functions*/

    public static void main(String args[]) {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node('a');
        tree.root.left = new Node('b');
        tree.root.right = new Node('c');
        tree.root.left.left = new Node('d');
        tree.root.left.right = new Node('e');
        tree.root.right.left = new Node('f');
        tree.root.right.right = new Node('g');
        tree.root.left.left.left = new Node('h');
        tree.root.left.left.right = new Node('i');
        tree.root.left.right.left = new Node('j');
        tree.root.left.right.right = new Node('k');
        tree.root.right.left.left = new Node('l');
        tree.root.right.left.right = new Node('m');
        tree.root.right.right.left = new Node('n');
        tree.root.right.right.right = new Node('o');
        System.out.println("Inorder Traversal of given tree");
        tree.printInorder();
        tree.reverseAlternate();
        System.out.println("");
        System.out.println("");
        System.out.println("Inorder Traversal of modified tree");
        tree.printInorder();
    }
}

/*Java program to reverse
alternate levels of a tree*/

class Sol 
{
    static class Node 
    {
        char key;
        Node left, right;
    };
    static void preorder(Node root1, 
                       Node root2, int lvl)
    {

/*        Base cases*/

        if (root1 == null || root2 == null)
            return;

/*        Swap subtrees if level is even*/

        if (lvl % 2 == 0) {
            char t = root1.key;
            root1.key = root2.key;
            root2.key = t;
        }

/*        Recur for left and right subtrees
        (Note : left of root1
        is passed and right of root2 in first
        call and opposite
        in second call.*/

        preorder(root1.left, root2.right, 
                                  lvl + 1);
        preorder(root1.right, root2.left, 
                                    lvl + 1);
    }

/*    This function calls preorder() 
    for left and right
    children of root*/

    static void reverseAlternate(Node root)
    {
        preorder(root.left, root.right, 0);
    }

/*    Inorder traversal (used to 
    print initial and
    modified trees)*/

    static void printInorder(Node root)
    {
        if (root == null)
            return;
        printInorder(root.left);
        System.out.print(root.key + " ");
        printInorder(root.right);
    }

/*    A utility function to create a new node*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.left = temp.right = null;
        temp.key = (char)key;
        return temp;
    }

/*    Driver program to test above functions*/

    public static void main(String args[])
    {
        Node root = newNode('a');
        root.left = newNode('b');
        root.right = newNode('c');
        root.left.left = newNode('d');
        root.left.right = newNode('e');
        root.right.left = newNode('f');
        root.right.right = newNode('g');
        root.left.left.left = newNode('h');
        root.left.left.right = newNode('i');
        root.left.right.left = newNode('j');
        root.left.right.right = newNode('k');
        root.right.left.left = newNode('l');
        root.right.left.right = newNode('m');
        root.right.right.left = newNode('n');
        root.right.right.right = newNode('o');
        System.out.print(
            "Inorder Traversal of given tree\n");
        printInorder(root);
        reverseAlternate(root);
        System.out.print(
            "\n\nInorder Traversal of modified tree\n");
        printInorder(root);
    }
}

/*Java program to implement Morris preorder traversal
A binary tree node*/

class Node {
    int data;
    Node left, right;
    Node(int item) {
        data = item;
        left = right = null;
    }
}
class BinaryTree {
    Node root;
    void morrisTraversalPreorder()
    {
        morrisTraversalPreorder(root);
    }

/*    Preorder traversal without recursion and without stack*/

    void morrisTraversalPreorder(Node node) {
        while (node != null) {

/*            If left child is null, print the current node data. Move to
            right child.*/

            if (node.left == null) {
                System.out.print(node.data + " ");
                node = node.right;
            } else {

/*                Find inorder predecessor*/

                Node current = node.left;
                while (current.right != null && current.right != node) {
                    current = current.right;
                }

/*                If the right child of inorder predecessor 
                already points to this node*/

                if (current.right == node) {
                    current.right = null;
                    node = node.right;
                }

/*                If right child doesn't point to this node, then print
                this node and make right child point to this node*/

                else {
                    System.out.print(node.data + " ");
                    current.right = node;
                    node = node.left;
                }
            }
        }
    }
    void preorder()
    {
        preorder(root);
    }

/*    Function for Standard preorder traversal*/

    void preorder(Node node) {
        if (node != null) {
            System.out.print(node.data + " ");
            preorder(node.left);
            preorder(node.right);
        }
    }

/*    Driver programs to test above functions*/

    public static void main(String args[]) {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        tree.root.left.left.left = new Node(8);
        tree.root.left.left.right = new Node(9);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(11);
        tree.morrisTraversalPreorder();
        System.out.println("");
        tree.preorder();
    }
}

/*Java program to implement iterative preorder traversal*/

import java.util.Stack;

/*A binary tree node*/

class Node {
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*    An iterative process to print preorder traversal of Binary tree*/
class BinaryTree {
    Node root;
    void iterativePreorder()
    {
        iterativePreorder(root);
    }
    void iterativePreorder(Node node)
    {

/*        Base Case*/

        if (node == null) {
            return;
        }

/*        Create an empty stack and push root to it*/

        Stack<Node> nodeStack = new Stack<Node>();
        nodeStack.push(root);

/* Pop all items one by one. Do following for every popped item
         a) print it
         b) push its right child
         c) push its left child
         Note that right child is pushed first so that left is processed first */

        while (nodeStack.empty() == false) {

/*            Pop the top item from stack and print it*/

            Node mynode = nodeStack.peek();
            System.out.print(mynode.data + " ");
            nodeStack.pop();

/*            Push right and left children of the popped node to stack*/

            if (mynode.right != null) {
                nodeStack.push(mynode.right);
            }
            if (mynode.left != null) {
                nodeStack.push(mynode.left);
            }
        }
    }

/*    driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(2);
        tree.iterativePreorder();
    }
}

import java.util.Stack;

/*A binary tree node*/

class Node
{
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree{
Node root;
void preorderIterative()
{
    preorderIterative(root);
}

/*Iterative function to do Preorder
traversal of the tree*/

void preorderIterative(Node node)
{
    if (node == null)
    {
        return;
    }
    Stack<Node> st = new Stack<Node>();

/*    Start from root node (set curr
    node to root node)*/

    Node curr = node;

/*    Run till stack is not empty or
    current is not NULL*/

    while (curr != null || !st.isEmpty())
    {

/*        Print left children while exist
        and keep pushing right into the 
        stack.*/

        while (curr != null)
        {
            System.out.print(curr.data + " ");
            if (curr.right != null)
                st.push(curr.right);
            curr = curr.left;
        }

/*        We reach when curr is NULL, so We
        take out a right child from stack*/

        if (!st.isEmpty())
        {
            curr = st.pop();
        }
    }
}

/*Driver code*/

public static void main(String args[])
{
    BinaryTree tree = new BinaryTree();
    tree.root = new Node(10);
    tree.root.left = new Node(20);
    tree.root.right = new Node(30);
    tree.root.left.left = new Node(40);
    tree.root.left.left.left = new Node(70);
    tree.root.left.right = new Node(50);
    tree.root.right.left = new Node(60);
    tree.root.left.left.right = new Node(80);
    tree.preorderIterative();
}
}

/*JAVA program or postorder traversal*/

import java.util.*;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

 class Node
 {
    int data;
    Node left, right;
    Node(int data)
    {
        this.data = data;
        this.left = this.right = null;       
    }
};
class GFG
{
Node root;

/* Helper function that allocates a new node with the
given data and null left and right pointers. */

 void postorder(Node head)
{
    Node temp = root;   
    HashSet<Node> visited = new HashSet<>();
    while ((temp != null  && !visited.contains(temp)))
    {

/*        Visited left subtree*/

        if (temp.left != null &&
         !visited.contains(temp.left))
            temp = temp.left;

/*        Visited right subtree*/

        else if (temp.right != null &&
        !visited.contains(temp.right))
            temp = temp.right;

/*        Print node*/

        else
        {
            System.out.printf("%d ", temp.data);
            visited.add(temp);
            temp = head;
        }
    }
}

/* Driver program to test above functions*/

public static void main(String[] args)
{
    GFG gfg = new GFG();
    gfg.root = new Node(8);
    gfg.root.left = new Node(3);
    gfg.root.right = new Node(10);
    gfg.root.left.left = new Node(1);
    gfg.root.left.right = new Node(6);
    gfg.root.left.right.left = new Node(4);
    gfg.root.left.right.right = new Node(7);
    gfg.root.right.right = new Node(14);
    gfg.root.right.right.left = new Node(13);
    gfg.postorder(gfg.root);
}
}

/*Java program or postorder traversal*/

class GFG
{

/* A binary tree node has data,
    pointer to left child
    and a pointer to right child */

static class Node
{
    int data;
    Node left, right;
    boolean visited;
}
static void postorder( Node head)
{
    Node temp = head;
    while (temp != null &&
            temp.visited == false)
    {

/*        Visited left subtree*/

        if (temp.left != null &&
            temp.left.visited == false)
            temp = temp.left;

/*        Visited right subtree*/

        else if (temp.right != null &&
                temp.right.visited == false)
            temp = temp.right;

/*        Print node*/

        else
        {
            System.out.printf("%d ", temp.data);
            temp.visited = true;
            temp = head;
        }
    }
}
static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = null;
    node.right = null;
    node.visited = false;
    return (node);
}

/* Driver code*/

public static void main(String []args)
{
    Node root = newNode(8);
    root.left = newNode(3);
    root.right = newNode(10);
    root.left.left = newNode(1);
    root.left.right = newNode(6);
    root.left.right.left = newNode(4);
    root.left.right.right = newNode(7);
    root.right.right = newNode(14);
    root.right.right.left = newNode(13);
    postorder(root);
}
}

/*Java program for diagonal
traversal of Binary Tree*/

import java.util.HashMap;
import java.util.Map.Entry;
import java.util.Vector;
public class DiagonalTraversalBTree
{

/*    Tree node*/

    static class Node
    {
        int data;
        Node left;
        Node right;
        Node(int data)
        {
            this.data=data;
            left = null;
            right =null;
        }
    }

/* root - root of the binary tree
       d -  distance of current line from rightmost
            -topmost slope.
       diagonalPrint - HashMap to store Diagonal
                       elements (Passed by Reference) */

    static void diagonalPrintUtil(Node root,int d,
          HashMap<Integer,Vector<Integer>> diagonalPrint)
    {

/*         Base case*/

        if (root == null)
            return;

/*        Store all nodes of same line
        together as a vector*/

        Vector<Integer> k = diagonalPrint.get(d);
        if (k == null)
        {
            k = new Vector<>();
            k.add(root.data);
        }
        else
        {
            k.add(root.data);
        }
        diagonalPrint.put(d,k);

/*        Increase the vertical distance
        if left child*/

        diagonalPrintUtil(root.left,
                         d + 1, diagonalPrint);

/*        Vertical distance remains
        same for right child*/

        diagonalPrintUtil(root.right,
                          d, diagonalPrint);
    }

/*    Print diagonal traversal
    of given binary tree*/

    static void diagonalPrint(Node root)
    {

/*        create a map of vectors
        to store Diagonal elements*/

        HashMap<Integer,Vector<Integer>>
             diagonalPrint = new HashMap<>();
        diagonalPrintUtil(root, 0, diagonalPrint);
        System.out.println("Diagonal Traversal
                                of Binnary Tree");
        for (Entry<Integer, Vector<Integer>> entry :
                          diagonalPrint.entrySet())
        {
            System.out.println(entry.getValue());
        }
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        Node root = new Node(8);
        root.left = new Node(3);
        root.right = new Node(10);
        root.left.left = new Node(1);
        root.left.right = new Node(6);
        root.right.right = new Node(14);
        root.right.right.left = new Node(13);
        root.left.right.left = new Node(4);
        root.left.right.right = new Node(7);
        diagonalPrint(root);
    }
}

/*Java program to con string from binary tree*/

import java.util.*;
class solution
{

/*A binary tree node has data, pointer to left
   child and a pointer to right child*/

static class Node {
    int data;
    Node left, right;
};

/*Helper function that allocates a new node*/

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
}

/*Iterative function to print diagonal view*/

static void diagonalPrint(Node root)
{

/*    base case*/

    if (root == null)
        return;

/*    inbuilt queue of Treenode*/

    Queue<Node> q= new LinkedList<Node>();

/*    add root*/

    q.add(root);

/*    add delimiter*/

    q.add(null);
    while (q.size()>0) {
        Node temp = q.peek();
        q.remove();

/*        if current is delimiter then insert another
        for next diagonal and cout nextline*/

        if (temp == null) {

/*            if queue is empty return*/

            if (q.size()==0)
                return;

/*            output nextline*/

            System.out.println();

/*            add delimiter again*/

            q.add(null);
        }
        else {
            while (temp!=null) {
                System.out.print( temp.data + " ");

/*                if left child is present 
                add into queue*/

                if (temp.left!=null)
                    q.add(temp.left);

/*                current equals to right child*/

                temp = temp.right;
            }
        }
    }
}

