/*Java program to print boundary traversal of binary tree*/

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node {
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree {
    Node root;

/*    A simple function to print leaf nodes of a binary tree*/

    void printLeaves(Node node)
    {
        if (node == null)
            return;
        printLeaves(node.left);

/*        Print it if it is a leaf node*/

        if (node.left == null && node.right == null)
            System.out.print(node.data + " ");
        printLeaves(node.right);
    }

/*    A function to print all left boundary nodes, except a leaf node.
    Print the nodes in TOP DOWN manner*/

    void printBoundaryLeft(Node node)
    {
        if (node == null)
            return;
        if (node.left != null) {

/*            to ensure top down order, print the node
            before calling itself for left subtree*/

            System.out.print(node.data + " ");
            printBoundaryLeft(node.left);
        }
        else if (node.right != null) {
            System.out.print(node.data + " ");
            printBoundaryLeft(node.right);
        }

/*        do nothing if it is a leaf node, this way we avoid
        duplicates in output*/

    }

/*    A function to print all right boundary nodes, except a leaf node
    Print the nodes in BOTTOM UP manner*/

    void printBoundaryRight(Node node)
    {
        if (node == null)
            return;
        if (node.right != null) {

/*            to ensure bottom up order, first call for right
            subtree, then print this node*/

            printBoundaryRight(node.right);
            System.out.print(node.data + " ");
        }
        else if (node.left != null) {
            printBoundaryRight(node.left);
            System.out.print(node.data + " ");
        }

/*        do nothing if it is a leaf node, this way we avoid
        duplicates in output*/

    }

/*    A function to do boundary traversal of a given binary tree*/

    void printBoundary(Node node)
    {
        if (node == null)
            return;
        System.out.print(node.data + " ");

/*        Print the left boundary in top-down manner.*/

        printBoundaryLeft(node.left);

/*        Print all leaf nodes*/

        printLeaves(node.left);
        printLeaves(node.right);

/*        Print the right boundary in bottom-up manner*/

        printBoundaryRight(node.right);
    }

/*    Driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);
        tree.root.right = new Node(22);
        tree.root.right.right = new Node(25);
        tree.printBoundary(tree.root);
    }
}

/*Java code to modify binary tree for 
traversal using only right pointer */

class GFG
{

/*A binary tree node has data, 
left child and right child */

static class Node 
{ 
    int data; 
    Node left; 
    Node right; 
};

/*function that allocates a new node 
with the given data and null left 
and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return (node); 
}

/*Function to modify tree */

static Node modifytree( Node root) 
{ 
    Node right = root.right; 
    Node rightMost = root;

/*    if the left tree exists */

    if (root.left != null) 
    {

/*        get the right-most of the 
        original left subtree */

        rightMost = modifytree(root.left);

/*        set root right to left subtree */

        root.right = root.left; 
        root.left = null; 
    }

/*    if the right subtree does 
    not exists we are done! */

    if (right == null) 
        return rightMost;

/*    set right pointer of right-most 
    of the original left subtree */

    rightMost.right = right;

/*    modify the rightsubtree */

    rightMost = modifytree(right); 
    return rightMost; 
}

/*printing using right pointer only */

static void printpre( Node root) 
{ 
    while (root != null) 
    { 
        System.out.print( root.data + " "); 
        root = root.right; 
    } 
}

