    root.left = newNode(8); 
    root.right = newNode(2); 
    root.left.left = newNode(3); 
    root.left.right = newNode(5); 
    modifytree(root); 
    printpre(root); 
}
}

/*Java code to modify binary tree for 
traversal using only right pointer */

import java.util.*;
class GfG {

/*A binary tree node has data, 
left child and right child */

static class Node { 
    int data; 
    Node left; 
    Node right; 
}

/*Helper function that allocates a new 
node with the given data and NULL 
left and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return (node); 
}

/*An iterative process to set the right 
pointer of Binary tree */

static void modifytree(Node root) 
{

/*    Base Case */

    if (root == null) 
        return;

/*    Create an empty stack and push root to it */

    Stack<Node> nodeStack = new Stack<Node> (); 
    nodeStack.push(root);

/* Pop all items one by one. 
        Do following for every popped item 
    a) print it 
    b) push its right child 
    c) push its left child 
    Note that right child is pushed first 
    so that left is processed first */

    Node pre = null; 
    while (nodeStack.isEmpty() == false) {

/*        Pop the top item from stack */

        Node node = nodeStack.peek(); 
        nodeStack.pop();

/*        Push right and left children of 
        the popped node to stack */

        if (node.right != null) 
            nodeStack.push(node.right); 
        if (node.left != null) 
            nodeStack.push(node.left);

/*        check if some previous node exists */

        if (pre != null) {

/*            set the right pointer of 
            previous node to currrent */

            pre.right = node; 
        }

/*        set previous node as current node */

        pre = node; 
    } 
}

/*printing using right pointer only */

static void printpre(Node root) 
{ 
    while (root != null) { 
        System.out.print(root.data + " "); 
        root = root.right; 
    } 
}

/*Driver code */

public static void main(String[] args) 
{

/* Constructed binary tree is 
            10 
        / \ 
        8     2 
    / \     
    3     5 
*/

    Node root = newNode(10); 
    root.left = newNode(8); 
    root.right = newNode(2); 
    root.left.left = newNode(3); 
    root.left.right = newNode(5); 
    modifytree(root); 
    printpre(root); 
}
}

/* Java program to construct tree using inorder
   and preorder traversals */

import java.io.*;
import java.util.*;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node
{
  char data;
  Node left,right;
  Node(char item)
  {
    data = item;
    left = right = null;
  }
}
class Tree
{
  public static Node root;

/*  Store indexes of all items so that we
  we can quickly find later*/

  static HashMap<Character,Integer> mp = new HashMap<>();
  static int preIndex = 0;

/* Recursive function to construct binary of size
    len from Inorder traversal in[] and Preorder traversal
    pre[]. Initial values of inStrt and inEnd should be
    0 and len -1. The function doesn't do any error
    checking for cases where inorder and preorder
    do not form a tree */

  public static Node buildTree(char[] in, char[] pre, int inStrt, int inEnd)
  {
    if(inStrt > inEnd)
    {
      return null;
    }

/* Pick current node from Preorder traversal using preIndex
        and increment preIndex */

    char curr = pre[preIndex++];
    Node tNode;
    tNode = new Node(curr);

/* If this node has no children then return */

    if (inStrt == inEnd)
    {
      return tNode;
    }

/* Else find the index of this node in Inorder traversal */

    int inIndex = mp.get(curr);

/* Using index in Inorder traversal, construct left and
        right subtress */

    tNode.left = buildTree(in, pre, inStrt, inIndex - 1);
    tNode.right = buildTree(in, pre, inIndex + 1, inEnd);
    return tNode;
  }

/*  This function mainly creates an unordered_map, then
  calls buildTree()*/

  public static Node buldTreeWrap(char[] in, char[] pre, int len)
  {
    for(int i = 0; i < len; i++)
    {
      mp.put(in[i], i);
    }
    return buildTree(in, pre, 0, len - 1);
  }

/* This funtcion is here just to test buildTree() */

  static void printInorder(Node node)
  {
    if(node == null)
    {
      return;
    }
    printInorder(node.left);
    System.out.print(node.data + " ");
    printInorder(node.right);
  }

/* Driver code */

  public static void main (String[] args)
  {
    char[] in = {'D', 'B', 'E', 'A', 'F', 'C'};
    char[] pre = {'A', 'B', 'D', 'E', 'C', 'F'};
    int len = in.length;
    Tree.root=buldTreeWrap(in, pre, len);

/* Let us test the built tree by printing
        Insorder traversal */

    System.out.println("Inorder traversal of the constructed tree is");
    printInorder(root);
  }
}

/*Java program to construct a tree using inorder and preorder traversal*/

import java.util.*;
public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}
class BinaryTree {
    static Set<TreeNode> set = new HashSet<>();
    static Stack<TreeNode> stack = new Stack<>();

/*    Function to build tree using given traversal*/

    public TreeNode buildTree(int[] preorder, int[] inorder)
    {
        TreeNode root = null;
        for (int pre = 0, in = 0; pre < preorder.length;) {
            TreeNode node = null;
            do {
                node = new TreeNode(preorder[pre]);
                if (root == null) {
                    root = node;
                }
                if (!stack.isEmpty()) {
                    if (set.contains(stack.peek())) {
                        set.remove(stack.peek());
                        stack.pop().right = node;
                    }
                    else {
                        stack.peek().left = node;
                    }
                }
                stack.push(node);
            } while (preorder[pre++] != inorder[in] && pre < preorder.length);
            node = null;
            while (!stack.isEmpty() && in < inorder.length &&
                    stack.peek().val == inorder[in]) {
                node = stack.pop();
                in++;
            }
            if (node != null) {
                set.add(node);
                stack.push(node);
            }
        }
        return root;
    }

/*    Function to print tree in Inorder*/

    void printInorder(TreeNode node)
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        System.out.print(node.val + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/*    driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        int in[] = new int[] { 9, 8, 4, 2, 10, 5, 10, 1, 6, 3, 13, 12, 7 };
        int pre[] = new int[] { 1, 2, 4, 8, 9, 5, 10, 10, 3, 6, 7, 12, 13 };
        int len = in.length;
        TreeNode root = tree.buildTree(pre, in);
        tree.printInorder(root);
    }
}

/*Java program to construct binary tree from
given array in level order fashion*/

public class Tree {
    Node root;

/*    Tree Node*/

    static class Node {
        int data;
        Node left, right;
        Node(int data)
        {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

/*    Function to insert nodes in level order*/

    public Node insertLevelOrder(int[] arr, Node root,
                                                int i)
    {

/*        Base case for recursion*/

        if (i < arr.length) {
            Node temp = new Node(arr[i]);
            root = temp;

/*            insert left child*/

            root.left = insertLevelOrder(arr, root.left,
                                             2 * i + 1);

/*            insert right child*/

            root.right = insertLevelOrder(arr, root.right,
                                               2 * i + 2);
        }
        return root;
    }

/*    Function to print tree nodes in InOrder fashion*/

    public void inOrder(Node root)
    {
        if (root != null) {
            inOrder(root.left);
            System.out.print(root.data + " ");
            inOrder(root.right);
        }
    }

/*    Driver program to test above function*/

    public static void main(String args[])
    {
        Tree t2 = new Tree();
        int arr[] = { 1, 2, 3, 4, 5, 6, 6, 6, 6 };
        t2.root = t2.insertLevelOrder(arr, t2.root, 0);
        t2.inOrder(t2.root);
    }
}

/*Java program for construction
of full binary tree*/

public class fullbinarytreepostpre
{
    static int preindex;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

    static class node
    {
        int data;
        node left, right;
        public node(int data)
        {
            this.data = data;
        }
    }

/*    A recursive function to construct Full
    from pre[] and post[]. preIndex is used
    to keep track of index in pre[]. l is
    low index and h is high index for the
    current subarray in post[]*/

    static node constructTreeUtil(int pre[], int post[], int l,
                                   int h, int size)
    {

/*        Base case*/

        if (preindex >= size || l > h)
            return null;

/*        The first node in preorder traversal is
        root. So take the node at preIndex from
        preorder and make it root, and increment
        preIndex*/

        node root = new node(pre[preindex]);
        preindex++;

/*        If the current subarry has only one
        element, no need to recur or
        preIndex > size after incrementing*/

        if (l == h || preindex >= size)
            return root;
        int i;

/*        Search the next element of pre[] in post[]*/

        for (i = l; i <= h; i++)
        {
            if (post[i] == pre[preindex])
                break;
        }

/*        Use the index of element found in
        postorder to divide postorder array
        in two parts. Left subtree and right subtree*/

        if (i <= h)
        {
            root.left = constructTreeUtil(pre, post, l, i, size);
            root.right = constructTreeUtil(pre, post, i + 1, h, size);
        }
        return root;
    }

/*    The main function to construct Full
    Binary Tree from given preorder and
    postorder traversals. This function
    mainly uses constructTreeUtil()*/

    static node constructTree(int pre[], int post[], int size)
    {
        preindex = 0;
        return constructTreeUtil(pre, post, 0, size - 1, size);
    }

/*A utility function to print inorder traversal of a Binary Tree*/

    static void printInorder(node root)
    {
        if (root == null)
            return;
        printInorder(root.left);
        System.out.print(root.data + " ");
        printInorder(root.right);
    }

/*Driver program to test above functions*/

    public static void main(String[] args)
    {
        int pre[] = { 1, 2, 4, 8, 9, 5, 3, 6, 7 };
        int post[] = { 8, 9, 4, 5, 2, 6, 7, 3, 1 };
        int size = pre.length;
        node root = constructTree(pre, post, size);
        System.out.println("Inorder traversal of the constructed tree:");
        printInorder(root);
    }
}

/*Java program to construct full binary tree 
using its preorder traversal and preorder 
traversal of its mirror tree */

class GFG
{

/*A Binary Tree Node */

static class Node 
{ 
