}

/*Java program to construct tree from inorder traversal*/

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

class Node 
{
    int data;
    Node left, right;
    Node(int item) 
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/* Recursive function to construct binary of size len from
       Inorder traversal inorder[]. Initial values of start and end
       should be 0 and len -1.  */

    Node buildTree(int inorder[], int start, int end, Node node) 
    {
        if (start > end)
            return null;

/* Find index of the maximum element from Binary Tree */

        int i = max(inorder, start, end);

/* Pick the maximum value and make it root */

        node = new Node(inorder[i]);

/* If this is the only element in inorder[start..end],
         then return it */

        if (start == end)
            return node;

/* Using index in Inorder traversal, construct left and
         right subtress */

        node.left = buildTree(inorder, start, i - 1, node.left);
        node.right = buildTree(inorder, i + 1, end, node.right);
        return node;
    }

/* Function to find index of the maximum value in arr[start...end] */

    int max(int arr[], int strt, int end) 
    {
        int i, max = arr[strt], maxind = strt;
        for (i = strt + 1; i <= end; i++) 
        {
            if (arr[i] > max) 
            {
                max = arr[i];
                maxind = i;
            }
        }
        return maxind;
    }

/* This funtcion is here just to test buildTree() */

    void printInorder(Node node) 
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        System.out.print(node.data + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/* Driver code*/

    public static void main(String args[]) 
    {
        BinaryTree tree = new BinaryTree();

/* Assume that inorder traversal of following tree is given
             40
            /   \
          10     30
         /         \
        5          28 */

        int inorder[] = new int[]{5, 10, 40, 30, 28};
        int len = inorder.length;
        Node mynode = tree.buildTree(inorder, 0, len - 1, tree.root);

/* Let us test the built tree by printing Inorder traversal */

        System.out.println("Inorder traversal of the constructed tree is ");
        tree.printInorder(mynode);
    }
}

/*Java program to construct a binary tree from parent array*/

/*A binary tree node*/

class Node 
{
    int key;
    Node left, right;
    public Node(int key) 
    {
        this.key = key;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/*    Creates a node with key as 'i'.  If i is root, then it changes
    root.  If parent of i is not created, then it creates parent first*/

    void createNode(int parent[], int i, Node created[]) 
    {

/*        If this node is already created*/

        if (created[i] != null)
            return;

/*        Create a new node and set created[i]*/

        created[i] = new Node(i);

/*        If 'i' is root, change root pointer and return*/

        if (parent[i] == -1) 
        {
            root = created[i];
            return;
        }

/*        If parent is not created, then create parent first*/

        if (created[parent[i]] == null)
            createNode(parent, parent[i], created);

/*        Find parent pointer*/

        Node p = created[parent[i]];

/*        If this is first child of parent*/

        if (p.left == null)
            p.left = created[i];

/*If second child*/

else 
            p.right = created[i];
    }

/* Creates tree from parent[0..n-1] and returns root of 
       the created tree */

    Node createTree(int parent[], int n) 
    {

/*        Create an array created[] to keep track
        of created nodes, initialize all entries
        as NULL*/

        Node[] created = new Node[n];
        for (int i = 0; i < n; i++) 
            created[i] = null;
        for (int i = 0; i < n; i++)
            createNode(parent, i, created);
        return root;
    }

/*    For adding new line in a program*/

    void newLine() 
    {
        System.out.println("");
    }

/*    Utility function to do inorder traversal*/

    void inorder(Node node) 
    {
        if (node != null) 
        {
            inorder(node.left);
            System.out.print(node.key + " ");
            inorder(node.right);
        }
    }

/*    Driver method*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        int parent[] = new int[]{-1, 0, 0, 1, 1, 3, 5};
        int n = parent.length;
        Node node = tree.createTree(parent, n);
        System.out.println("Inorder traversal of constructed tree ");
        tree.inorder(node);
        tree.newLine();
    }
}

/*Java program for above approach*/

import java.io.*;
import java.util.*;
class GFG {

/*    Node class*/

    static class Node {
        int data;
        Node left, right;

/*        Constructor*/

        Node(int x)
        {
            data = x;
            left = right = null;
        }
    }

/*    Tree building function*/

    static Node buildTree(int in[], int post[], int n)
    {

/*        Create Stack of type Node**/

        Stack<Node> st = new Stack<>();

/*        Create HashSet of type Node**/

        HashSet<Node> s = new HashSet<>();

/*        Initialise postIndex with n - 1*/

        int postIndex = n - 1;

/*        Initialise root with null*/

        Node root = null;
        for (int p = n - 1, i = n - 1; p >= 0 {

/*            Initialise node with NULL*/

            Node node = null;

/*            Run do-while loop*/

            do {

/*                Initialise node with
                new Node(post[p]);*/

                node = new Node(post[p]);

/*                Check is root is
                equal to NULL*/

                if (root == null) {
                    root = node;
                }

/*                If size of set
                is greater than 0*/

                if (st.size() > 0) {

/*                    If st.peek() is present in the
                    set s*/

                    if (s.contains(st.peek())) {
                        s.remove(st.peek());
                        st.peek().left = node;
                        st.pop();
                    }
                    else {
                        st.peek().right = node;
                    }
                }
                st.push(node);
            } while (post[p--] != in[i] && p >= 0);
            node = null;

/*            If the stack is not empty and
            st.top().data is equal to in[i]*/

            while (st.size() > 0 && i >= 0
                   && st.peek().data == in[i]) {
                node = st.peek();

/*                Pop elements from stack*/

                st.pop();
                i--;
            }

/*            If node not equal to NULL*/

            if (node != null) {
                s.add(node);
                st.push(node);
            }
        }

/*        Return root*/

        return root;
    }

/*    For print preOrder Traversal*/

    static void preOrder(Node node)
    {
        if (node == null)
            return;
        System.out.printf("%d ", node.data);
        preOrder(node.left);
        preOrder(node.right);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int in[] = { 4, 8, 2, 5, 1, 6, 3, 7 };
        int post[] = { 8, 4, 5, 2, 6, 7, 3, 1 };
        int n = in.length;

/*        Function Call*/

        Node root = buildTree(in, post, n);
        System.out.print(
            "Preorder of the constructed tree : \n");

/*        Function Call for preOrder*/

        preOrder(root);
    }
}

/*Java program to create a tree with left child
right sibling representation.*/

import java.util.*;
class GFG
{
  static class Node
  {
    int data;
    Node next;
    Node child;
  };

/*  Creating new Node*/

  static Node newNode(int data)
  {
    Node newNode = new Node();
    newNode.next = newNode.child = null;
    newNode.data = data;
    return newNode;
  }

/*  Adds a sibling to a list with starting with n*/

  static Node addSibling(Node n, int data)
  {
    if (n == null)
      return null;
    while (n.next != null)
      n = n.next;
    return (n.next = newNode(data));
  }

/*  Add child Node to a Node*/

  static Node addChild(Node n, int data)
  {
    if (n == null)
      return null;

/*    Check if child list is not empty.*/

    if (n.child != null)
      return addSibling(n.child, data);
    else
      return (n.child = newNode(data));
  }

/*  Traverses tree in level order*/

  static void traverseTree(Node root)
  {

/*    Corner cases*/

    if (root == null)
      return;
    System.out.print(root.data+ " ");
    if (root.child == null)
      return;

/*    Create a queue and enque root*/

    Queue<Node> q = new LinkedList<>();
    Node curr = root.child;
    q.add(curr);
    while (!q.isEmpty())
    {

/*      Take out an item from the queue*/

      curr = q.peek();
      q.remove();

/*      Print next level of taken out item and enque
      next level's children*/

      while (curr != null)
      {
        System.out.print(curr.data + " ");
        if (curr.child != null)
        {
          q.add(curr.child);
        }
        curr = curr.next;
      }
    }
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    Node root = newNode(10);
    Node n1 = addChild(root, 2);
    Node n2 = addChild(root, 3);
    Node n3 = addChild(root, 4);
    Node n4 = addChild(n3, 6);
    Node n5 = addChild(root, 5);
    Node n6 = addChild(n5, 7);
    Node n7 = addChild(n5, 8);
    Node n8 = addChild(n5, 9);
    traverseTree(root);
  }
}

/*Java program to construct tree from given Prufer Code*/

class GFG {

/*    Prints edges of tree represented by give Prufer code*/

    static void printTreeEdges(int prufer[], int m)
    {
        int vertices = m + 2;
        int vertex_set[] = new int[vertices];

/*        Initialize the array of vertices*/

        for (int i = 0; i < vertices; i++)
            vertex_set[i] = 0;

/*        Number of occurrences of vertex in code*/

        for (int i = 0; i < vertices - 2; i++)
            vertex_set[prufer[i] - 1] += 1;
        System.out.print("\nThe edge set E(G) is :\n");

/*        Find the smallest label not present in
        prufer[].*/

        int j = 0;
        for (int i = 0; i < vertices - 2; i++) {
            for (j = 0; j < vertices; j++) {

/*                If j+1 is not present in prufer set*/

                if (vertex_set[j] == 0) {

/*                    Remove from Prufer set and print
                    pair.*/

                    vertex_set[j] = -1;
                    System.out.print("(" + (j + 1) + ", "
                                     + prufer[i] + ") ");
                    vertex_set[prufer[i] - 1]--;
                    break;
                }
            }
        }
        j = 0;

/*        For the last element*/

        for (int i = 0; i < vertices; i++) {
            if (vertex_set[i] == 0 && j == 0) {
                System.out.print("(" + (i + 1) + ", ");
                j++;
            }
            else if (vertex_set[i] == 0 && j == 1)
                System.out.print((i + 1) + ")\n");
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int prufer[] = { 4, 1, 3, 4 };
        int n = prufer.length;
        printTreeEdges(prufer, n);
    }
}

/*Java program to build full k-ary tree from
its preorder traversal and to print the
postorder traversal of the tree.*/

import java.util.*;
class GFG
{

/*Structure of a node of an n-ary tree*/

static class Node 
{
    int key;
    Vector<Node> child;
};

/*Utility function to create a new tree 
node with k children*/

static Node newNode(int value)
{
    Node nNode = new Node();
    nNode.key = value;
    nNode.child= new Vector<Node>();
    return nNode;
}
static int ind;

/*Function to build full k-ary tree*/

static Node BuildKaryTree(int A[], int n, 
                          int k, int h)
{

/*    For null tree*/

    if (n <= 0)
        return null;
    Node nNode = newNode(A[ind]);
    if (nNode == null)
    {
        System.out.println("Memory error" );
        return null;
    }

/*    For adding k children to a node*/

    for (int i = 0; i < k; i++)
    {

/*        Check if ind is in range of array
        Check if height of the tree is greater than 1*/

        if (ind < n - 1 && h > 1) 
        {
            ind++;

/*            Recursively add each child*/

            nNode.child.add(BuildKaryTree(A, n, k, h - 1));
        } 
        else
        {
            nNode.child.add(null);
        }
    }
    return nNode;
}

/*Function to find the height of the tree*/

static Node BuildKaryTree_1(int[] A, int n, int k, int in)
{
    int height = (int)Math.ceil(Math.log((double)n * (k - 1) + 1) / 
                                Math.log((double)k));
    ind = in;
    return BuildKaryTree(A, n, k, height);
}

/*Function to print postorder traversal of the tree*/

static void postord(Node root, int k)
{
    if (root == null)
        return;
    for (int i = 0; i < k; i++)
        postord(root.child.get(i), k);
    System.out.print(root.key + " ");
}

/*Driver Code*/

public static void main(String args[])
{
    int ind = 0;
    int k = 3, n = 10;
    int preorder[] = { 1, 2, 5, 6, 7, 3, 8, 9, 10, 4 };
    Node root = BuildKaryTree_1(preorder, n, k, ind);
    System.out.println("Postorder traversal of " + 
                       "constructed full k-ary tree is: ");
    postord(root, k);
    System.out.println();
}
}

/* Java program to cona binary tree from
   the given String */

import java.util.*;
class GFG
{

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

  static class Node
  {
    int data;
    Node left, right;
  };

/* Helper function that allocates a new node */

  static Node newNode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
  }

/* This funtcion is here just to test  */

  static void preOrder(Node node)
  {
    if (node == null)
      return;
    System.out.printf("%d ", node.data);
    preOrder(node.left);
    preOrder(node.right);
  }

/*  function to return the index of close parenthesis*/

  static int findIndex(String str, int si, int ei)
  {
    if (si > ei)
      return -1;

/*    Inbuilt stack*/

    Stack<Character> s = new Stack<>();
    for (int i = si; i <= ei; i++)
    {

/*      if open parenthesis, push it*/

      if (str.charAt(i) == '(')
        s.add(str.charAt(i));

/*      if close parenthesis*/

      else if (str.charAt(i) == ')')
      {
        if (s.peek() == '(')
        {
          s.pop();

/*          if stack is empty, this is
          the required index*/

          if (s.isEmpty())
            return i;
        }
      }
    }

/*    if not found return -1*/

    return -1;
  }

/*  function to contree from String*/

  static Node treeFromString(String str, int si, int ei)
  {

/*    Base case*/

    if (si > ei)
      return null;

/*    new root*/

    Node root = newNode(str.charAt(si) - '0');
    int index = -1;

/*    if next char is '(' find the index of
    its complement ')'*/

    if (si + 1 <= ei && str.charAt(si+1) == '(')
      index = findIndex(str, si + 1, ei);

/*    if index found*/

    if (index != -1)
    {

/*      call for left subtree*/

      root.left = treeFromString(str, si + 2, index - 1);

/*      call for right subtree*/

      root.right
        = treeFromString(str, index + 2, ei - 1);
    }
    return root;
  }

/*  Driver Code*/

  public static void main(String[] args)
  {
    String str = "4(2(3)(1))(6(5))";
    Node root = treeFromString(str, 0, str.length() - 1);
    preOrder(root);
  }
}

/*Java program to convert binary tree to double linked list*/

/* A binary tree node has data, and left and right pointers */

class Node
{
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree
{
    Node root;

/* This is the core function to convert Tree to list. This function
       follows steps 1 and 2 of the above algorithm */

    Node bintree2listUtil(Node node)
    {

/*        Base case*/

        if (node == null)
            return node;

/*        Convert the left subtree and link to root*/

        if (node.left != null)
        {

/*            Convert the left subtree*/

            Node left = bintree2listUtil(node.left);

/*            Find inorder predecessor. After this loop, left
            will point to the inorder predecessor*/

            for (; left.right != null; left = left.right);

/*            Make root as next of the predecessor*/

            left.right = node;

/*            Make predecssor as previous of root*/

            node.left = left;
        }

/*        Convert the right subtree and link to root*/

        if (node.right != null)
        {

/*            Convert the right subtree*/

            Node right = bintree2listUtil(node.right);

/*            Find inorder successor. After this loop, right
            will point to the inorder successor*/

            for (; right.left != null; right = right.left);

/*            Make root as previous of successor*/

            right.left = node;

/*            Make successor as next of root*/

            node.right = right;
        }
        return node;
    }

/*    The main function that first calls bintree2listUtil(), then follows
    step 3 of the above algorithm*/

    Node bintree2list(Node node)
    {

/*        Base case*/

        if (node == null)
            return node;

/*        Convert to DLL using bintree2listUtil()*/

        node = bintree2listUtil(node);

/*        bintree2listUtil() returns root node of the converted
        DLL.  We need pointer to the leftmost node which is
        head of the constructed DLL, so move to the leftmost node*/

        while (node.left != null)
            node = node.left;
        return node;
    }

/* Function to print nodes in a given doubly linked list */

    void printList(Node node)
    {
        while (node != null)
        {
            System.out.print(node.data + " ");
            node = node.right;
        }
    }

/* Driver program to test above functions*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create the tree shown in above diagram*/

        tree.root = new Node(10);
        tree.root.left = new Node(12);
        tree.root.right = new Node(15);
        tree.root.left.left = new Node(25);
        tree.root.left.right = new Node(30);
        tree.root.right.left = new Node(36);

/*        Convert to DLL*/

        Node head = tree.bintree2list(tree.root);

/*        Print the converted list*/

        tree.printList(head);
    }
}

/*A Java program for in-place conversion of Binary Tree to DLL*/

/*A binary tree node has data, left pointers and right pointers*/

class Node
{
    int data;
    Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
class BinaryTree
{
    Node root;

/*    head --> Pointer to head node of created doubly linked list*/

    Node head;

/*    A simple recursive function to convert a given Binary tree
    to Doubly Linked List
    root --> Root of Binary Tree*/

    void BinaryTree2DoubleLinkedList(Node root)
    {

/*        Base case*/

        if (root == null)
            return;

/*    Initialize previously visited node as NULL. This is
    static so that the same value is accessible in all recursive
    calls*/

    static Node prev = null;

/*        Recursively convert left subtree*/

        BinaryTree2DoubleLinkedList(root.left);

/*        Now convert this node*/

        if (prev == null)
            head = root;
        else
        {
            root.left = prev;
            prev.right = root;
        }
        prev = root;

/*        Finally convert right subtree*/

        BinaryTree2DoubleLinkedList(root.right);
    }

/* Function to print nodes in a given doubly linked list */

    void printList(Node node)
    {
        while (node != null)
        {
            System.out.print(node.data + " ");
            node = node.right;
        }
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {

/*        Let us create the tree as shown in above diagram*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(12);
        tree.root.right = new Node(15);
        tree.root.left.left = new Node(25);
        tree.root.left.right = new Node(30);
        tree.root.right.left = new Node(36);

/*        convert to DLL*/

        tree.BinaryTree2DoubleLinkedList(tree.root);

/*        Print the converted List*/

        tree.printList(tree.head);
    }
}

/*    Java program to convert an arbitrary binary tree to a tree that holds
children sum property*/

/*A binary tree node*/

class Node 
{
    int data;
    Node left, right;
    Node(int item) 
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/* This function changes a tree to hold children sum
       property */

    void convertTree(Node node) 
    {
        int left_data = 0, right_data = 0, diff;

/* If tree is empty or it's a leaf node then
         return true */

        if (node == null
                || (node.left == null && node.right == null))
            return;
        else
        {

/* convert left and right subtrees  */

            convertTree(node.left);
            convertTree(node.right);

/* If left child is not present then 0 is used
             as data of left child */

            if (node.left != null)
                left_data = node.left.data;

/* If right child is not present then 0 is used
             as data of right child */

            if (node.right != null)
                right_data = node.right.data;

/* get the diff of node's data and children sum */

            diff = left_data + right_data - node.data;

/* If node's children sum is greater than the node's data */

            if (diff > 0)
                node.data = node.data + diff;

/* THIS IS TRICKY --> If node's data is greater than children
               sum, then increment subtree by diff */

            if (diff < 0)

/*                -diff is used to make diff positive*/

                increment(node, -diff);  
        }
    }

/* This function is used to increment subtree by diff */

    void increment(Node node, int diff) 
    {

/* IF left child is not NULL then increment it */

        if (node.left != null) 
        {
            node.left.data = node.left.data + diff;

/*            Recursively call to fix the descendants of node->left*/

            increment(node.left, diff);
        }

/*Else increment right child*/

else if (node.right != null) 
        {
            node.right.data = node.right.data + diff;

/*            Recursively call to fix the descendants of node->right*/

            increment(node.right, diff);
        }
    }

/* Given a binary tree, printInorder() prints out its
     inorder traversal*/

    void printInorder(Node node) 
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        System.out.print(node.data + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/*    Driver program to test above functions*/

    public static void main(String args[]) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(50);
        tree.root.left = new Node(7);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(1);
        tree.root.right.right = new Node(30);
        System.out.println("Inorder traversal before conversion is :");
        tree.printInorder(tree.root);
        tree.convertTree(tree.root);
        System.out.println("");
        System.out.println("Inorder traversal after conversion is :");
        tree.printInorder(tree.root);
    }
}

/* Java program to convert left-right to 
down-right representation of binary tree */

class GFG 
{

/*A Binary Tree Node */

static class node 
{ 
    int key; 
    node left, right; 
    node(int key)
    {
        this.key = key;
        this.left = null;
        this.right = null;
    }
}

/*An Iterative level order traversal 
based function to convert left-right 
to down-right representation. */

static void convert(node root) 
{

/*    Base Case */

    if (root == null) return;

/*    Recursively convert left 
    an right subtrees */

    convert(root.left); 
    convert(root.right);

/*    If left child is NULL, make right 
    child as left as it is the first child. */

    if (root.left == null) 
    root.left = root.right;

/*    If left child is NOT NULL, then make 
    right child as right of left child */

    else
    root.left.right = root.right;

/*    Set root's right as NULL */

    root.right = null; 
}

/*A utility function to traverse a 
tree stored in down-right form. */

static void downRightTraversal(node root) 
{ 
    if (root != null) 
    { 
        System.out.print(root.key + " "); 
        downRightTraversal(root.right); 
        downRightTraversal(root.left); 
    } 
}

/*Utility function to create
a new tree node */

static node newNode(int key) 
{ 
    node temp = new node(0); 
    temp.key = key; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/*Driver Code*/

public static void main(String[] args) 
{

/*    Let us create binary tree
    shown in above diagram */

/* 
        1 
        / \ 
        2 3 
            / \ 
            4 5 
        / / \ 
        6 7 8 
    */

    node root = new node(1);
    root.left = newNode(2); 
    root.right = newNode(3); 
    root.right.left = newNode(4); 
    root.right.right = newNode(5); 
    root.right.left.left = newNode(6); 
    root.right.right.left = newNode(7); 
    root.right.right.right = newNode(8); 
    convert(root); 
    System.out.println("Traversal of the tree " + 
                 "converted to down-right form"); 
    downRightTraversal(root); 
}
}

/* Java program to convert Binary Tree into Doubly Linked List 
   where the nodes are represented spirally */

import java.util.*;

/*A binary tree node*/

class Node 
{
    int data;
    Node left, right;
    public Node(int data) 
    {
        this.data = data;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;
    Node head;

/* Given a reference to a node,
       inserts the node on the front of the list. */

    void push(Node node) 
    {

/*        Make right of given node as head and left as
        NULL*/

        node.right = head;
        node.left = null;

/*        change left of head node to given node*/

        if (head != null) 
            head.left = node;

/*        move the head to point to the given node*/

        head = node;
    }

/*    Function to prints contents of DLL*/

    void printList(Node node) 
    {
        while (node != null) 
        {
            System.out.print(node.data + " ");
            node = node.right;
        }
    }

/* Function to print corner node at each level */

    void spiralLevelOrder(Node root) 
    {

/*        Base Case*/

        if (root == null)
            return;

/*        Create an empty deque for doing spiral
        level order traversal and enqueue root*/

        Deque<Node> q = new LinkedList<Node>();
        q.addFirst(root);

/*        create a stack to store Binary Tree nodes
        to insert into DLL later*/

        Stack<Node> stk = new Stack<Node>();
        int level = 0;
        while (!q.isEmpty()) 
        {

/*            nodeCount indicates number of Nodes
            at current level.*/

            int nodeCount = q.size();

/*            Dequeue all Nodes of current level and
            Enqueue all Nodes of next level
odd level*/

if ((level & 1) %2 != 0) 
            {
                while (nodeCount > 0) 
                {

/*                    dequeue node from front & push it to
                    stack*/

                    Node node = q.peekFirst();
                    q.pollFirst();
                    stk.push(node);

/*                    insert its left and right children
                    in the back of the deque*/

                    if (node.left != null)
                        q.addLast(node.left);
                    if (node.right != null)
                        q.addLast(node.right);
                    nodeCount--;
                }
            }

/*even level*/

else 
            {
                while (nodeCount > 0) 
                {

/*                    dequeue node from the back & push it
                    to stack*/

                    Node node = q.peekLast();
                    q.pollLast();
                    stk.push(node);

/*                    inserts its right and left children
                    in the front of the deque*/

                    if (node.right != null)
                        q.addFirst(node.right);
                    if (node.left != null)
                        q.addFirst(node.left);
                    nodeCount--;
                }
            }
            level++;
        }

/*        pop all nodes from stack and
        push them in the beginning of the list*/

        while (!stk.empty()) 
        {
            push(stk.peek());
            stk.pop();
        }
        System.out.println("Created DLL is : ");
        printList(head);
    }

