/*Java program to check children sum property*/

/* A binary tree node has data, pointer to left child 
   and a pointer to right child */

class Node 
{
    int data;
    Node left, right;
    public Node(int d) 
    {
        data = d;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/* returns 1 if children sum property holds for the given
    node and both of its children*/

    int isSumProperty(Node node) 
    {

/* left_data is left child data and right_data is for right 
           child data*/

        int left_data = 0, right_data = 0;

/* If node is NULL or it's a leaf node then
        return true */

        if (node == null
                || (node.left == null && node.right == null))
            return 1;
        else
        {

/* If left child is not present then 0 is used
               as data of left child */

            if (node.left != null) 
                left_data = node.left.data;

/* If right child is not present then 0 is used
               as data of right child */

            if (node.right != null) 
                right_data = node.right.data;

/* if the node and both of its children satisfy the
               property return 1 else 0*/

            if ((node.data == left_data + right_data)
                    && (isSumProperty(node.left)!=0)
                    && isSumProperty(node.right)!=0)
                return 1;
            else
                return 0;
        }
    }

/* driver program to test the above functions */

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(5);
        tree.root.right.right = new Node(2);
        if (tree.isSumProperty(tree.root) != 0)
            System.out.println("The given tree satisfies children"
                    + " sum property");
        else
            System.out.println("The given tree does not satisfy children"
                    + " sum property");
    }
}

/*Java program to find sum of covered and uncovered nodes
of a binary tree */

/* A binary tree node has key, pointer to left child and
   a pointer to right child */

class Node 
{
    int key;
    Node left, right;
    public Node(int key) 
    {
        this.key = key;
        left = right = null;
    }
}
class BinaryTree 
{
    Node root;

/* Utility function to calculate sum of all node of tree */

    int sum(Node t) 
    {
        if (t == null) 
            return 0;
        return t.key + sum(t.left) + sum(t.right);
    }

/* Recursive function to calculate sum of left boundary
       elements  */

    int uncoveredSumLeft(Node t) 
    {

/*  If left node, then just return its key value   */

        if (t.left == null && t.right == null)
            return t.key;

/*  If left is available then go left otherwise go right  */

        if (t.left != null) 
            return t.key + uncoveredSumLeft(t.left);
         else 
            return t.key + uncoveredSumLeft(t.right);
    }

/* Recursive function to calculate sum of right boundary
       elements  */

    int uncoveredSumRight(Node t) 
    {

/*  If left node, then just return its key value   */

        if (t.left == null && t.right == null)
            return t.key;

/*  If right is available then go right otherwise go left  */

        if (t.right != null)
            return t.key + uncoveredSumRight(t.right);
        else
            return t.key + uncoveredSumRight(t.left);
    }

/*    Returns sum of uncovered elements*/

    int uncoverSum(Node t) 
    {

/* Initializing with 0 in case we don't have
           left or right boundary  */

        int lb = 0, rb = 0;
        if (t.left != null)
            lb = uncoveredSumLeft(t.left);
        if (t.right != null)
            rb = uncoveredSumRight(t.right);

/* returning sum of root node, left boundary
           and right boundary*/

        return t.key + lb + rb;
    }

/*    Returns true if sum of covered and uncovered elements
    is same.*/

    boolean isSumSame(Node root) 
    {

/*        Sum of uncovered elements*/

        int sumUC = uncoverSum(root);

/*        Sum of all elements*/

        int sumT = sum(root);

/*        Check if sum of covered and uncovered is same*/

        return (sumUC == (sumT - sumUC));
    }

/* Helper function to print inorder traversal of
       binary tree   */

    void inorder(Node root) 
    {
        if (root != null) 
        {
            inorder(root.left);
            System.out.print(root.key + " ");
            inorder(root.right);
        }
    }

/*    Driver program to test above functions*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();

/*        Making above given diagram's binary tree*/

        tree.root = new Node(8);
        tree.root.left = new Node(3);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(6);
        tree.root.left.right.left = new Node(4);
        tree.root.left.right.right = new Node(7);
        tree.root.right = new Node(10);
        tree.root.right.right = new Node(14);
        tree.root.right.right.left = new Node(13);
        if (tree.isSumSame(tree.root)) 
            System.out.println("Sum of covered and uncovered is same");
         else 
            System.out.println("Sum of covered and uncovered is not same");
    }
}

/*Java program to check if all leaves are at same level*/

/*A binary tree node*/

class Node
{
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class Leaf
{
    int leaflevel=0;
}
class BinaryTree
{
    Node root;
    Leaf mylevel = new Leaf();

/* Recursive function which checks whether all leaves are at same
       level */

    boolean checkUtil(Node node, int level, Leaf leafLevel)
    {

/*        Base case*/

        if (node == null)
            return true;

/*        If a leaf node is encountered*/

        if (node.left == null && node.right == null)
        {

/*            When a leaf node is found first time*/

            if (leafLevel.leaflevel == 0)
            {

/*                Set first found leaf's level*/

                leafLevel.leaflevel = level;
                return true;
            }

/*            If this is not first leaf node, compare its level with
            first leaf's level*/

            return (level == leafLevel.leaflevel);
        }

/*        If this node is not leaf, recursively check left and right
        subtrees*/

        return checkUtil(node.left, level + 1, leafLevel)
                && checkUtil(node.right, level + 1, leafLevel);
    }

/* The main function to check if all leafs are at same level.
       It mainly uses checkUtil() */

    boolean check(Node node)
    {
        int level = 0;
        return checkUtil(node, level, mylevel);
    }

/*Driver Code*/

    public static void main(String args[])
    {

/*        Let us create the tree as shown in the example*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(12);
        tree.root.left = new Node(5);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(9);
        tree.root.left.left.left = new Node(1);
        tree.root.left.right.left = new Node(1);
        if (tree.check(tree.root))
            System.out.println("Leaves are at same level");
        else
            System.out.println("Leaves are not at same level");
    }
}

/*Java program to check if all leaf nodes are at 
same level of binary tree*/

import java.util.*;

/*User defined node class*/

class Node {
      int data;
      Node left, right;

/*      Constructor to create a new tree node*/

      Node(int key) {
           int data = key;
           left = right = null;
      }
}
class GFG {

/*      return true if all leaf nodes are
      at same level, else false*/

      static boolean checkLevelLeafNode(Node root)
      {
             if (root == null)
                 return true;

/*             create a queue for level order traversal*/

             Queue<Node> q = new LinkedList<>();
             q.add(root);
             int result = Integer.MAX_VALUE;
             int level = 0;

/*             traverse until the queue is empty*/

             while (q.size() != 0) {
                    int size = q.size();
                    level++;

/*                    traverse for complete level*/

                    while (size > 0) {
                         Node temp = q.remove();

/*                         check for left child*/

                         if (temp.left != null) {
                             q.add(temp.left);

/*                              if its leaf node*/

                              if (temp.left.left == null && temp.left.right == null) {

/*                                  if it's first leaf node, then update result*/

                                  if (result == Integer.MAX_VALUE)
                                      result = level;

/*                                  if it's not first leaf node, then compare 
                                  the level with level of previous leaf node.*/

                                  else if (result != level)
                                       return false;
                              }
                         }

/*                          check for right child*/

                          if (temp.right != null) {
                             q.add(temp.right);

/*                              if its leaf node*/

                             if (temp.right.left == null && temp.right.right == null) {

/*                                  if it's first leaf node, then update result*/

                                  if (result == Integer.MAX_VALUE)
                                      result = level;

/*                                  if it's not first leaf node, then compare 
                                  the level with level of previous leaf node.*/

                                  else if (result != level)
                                       return false;
                              }
                         }
                         size--;
                    }
             }
             return true;
      }

/*      Driver code*/

      public static void main(String args[])
      {

/*             construct a tree*/

             Node root = new Node(1);
             root.left = new Node(2);
             root.right = new Node(3);
             root.left.right = new Node(4);
             root.right.left = new Node(5);
             root.right.right = new Node(6);
             boolean result = checkLevelLeafNode(root);
             if (result == true)
                 System.out.println("All leaf nodes are at same level");
             else
                 System.out.println("Leaf nodes not at same level"); 
      }
}

/*Java program to check if a given tree is
Binary Heap or not*/

import java.io.*;
import java.util.*;
public class detheap
{

/*    Returns true if given level order traversal
    is Min Heap.*/

    static boolean isMinHeap(int []level)
    {
        int n = level.length - 1;

/*        First non leaf node is at index (n/2-1).
        Check whether each parent is greater than child*/

        for (int i=(n/2-1) ; i>=0 ; i--)
        {

/*            Left child will be at index 2*i+1
            Right child will be at index 2*i+2*/

            if (level[i] > level[2 * i + 1])
                return false;
            if (2*i + 2 < n)
            {

/*                If parent is greater than right child*/

                if (level[i] > level[2 * i + 2])
                   return false;
            }
        }
        return true;
    }

/*    Driver code*/

    public static void main(String[] args) 
                              throws IOException
    {
        int[] level = new int[]{10, 15, 14, 25, 30};
        if  (isMinHeap(level))
            System.out.println("True");
        else
            System.out.println("False");
    }
}

/*Java program to check if two Leaf Traversal of
Two Binary Trees is same or not*/

import java.util.*;
import java.lang.*;
import java.io.*;

/*Binary Tree node*/

class Node 
{
    int data;
    Node left, right;
    public Node(int x)
    {
        data = x;
        left = right = null;
    }

/*checks if a given node is leaf or not.*/

    public boolean isLeaf()
    {
        return (left == null && right == null);
    }
}
class LeafOrderTraversal
{

/*    Returns true of leaf traversal of two trees is
    same, else false*/

    public static boolean isSame(Node root1, Node root2)
    {

/*        Create empty stacks.  These stacks are going
        to be used for iterative traversals.*/

        Stack<Node> s1 = new Stack<Node>();
        Stack<Node> s2 = new Stack<Node>();
        s1.push(root1);
        s2.push(root2);

/*        Loop until either of two stacks is not empty*/

        while (!s1.empty() || !s2.empty())
        {

/*            If one of the stacks is empty means other
            stack has extra leaves so return false*/

            if (s1.empty() || s2.empty())
                return false;
            Node temp1 = s1.pop();
            while (temp1 != null && !temp1.isLeaf()) 
            {

/*                Push right and left children of temp1.
                Note that right child is inserted
                before left*/

                if (temp1.right != null)
                    s1.push(temp1.right);
                if (temp1.left != null)
                    s1.push(temp1.left);
                temp1 = s1.pop();
            }

/*            same for tree2*/

            Node temp2 = s2.pop();
            while (temp2 != null && !temp2.isLeaf()) 
            {
                if (temp2.right != null)
                    s2.push(temp2.right);
                if (temp2.left != null)
                    s2.push(temp2.left);
                temp2 = s2.pop();
            }

/*            If one is null and other is not, then
            return false*/

            if (temp1 == null && temp2 != null)
                return false;
            if (temp1 != null && temp2 == null)
                return false;

/*            If both are not null and data is not
            same return false*/

            if (temp1 != null && temp2 != null) 
            {
                if (temp1.data != temp2.data)
                    return false;
            }
        }

/*        If control reaches this point, all leaves
        are matched*/

        return true;
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        Let us create trees in above example 1*/

        Node root1 = new Node(1);
        root1.left = new Node(2);
        root1.right = new Node(3);
        root1.left.left = new Node(4);
        root1.right.left = new Node(6);
        root1.right.right = new Node(7);
        Node root2 = new Node(0);
        root2.left = new Node(1);
        root2.right = new Node(5);
        root2.left.right = new Node(4);
        root2.right.left = new Node(6);
        root2.right.right = new Node(7);
        if (isSame(root1, root2))
            System.out.println("Same");
        else
            System.out.println("Not Same");
    }
}

/*Java Program to check if a given Binary
Tree is balanced like a Red-Black Tree */

class GFG
{
static class Node
{
    int key;
    Node left, right;
    Node(int key)
    {
        left = null;
        right = null;
        this.key = key;
    }
}
static class INT
{
    static int d;
    INT()
    {
        d = 0;
    }
}

/*Returns returns tree if the Binary 
tree is balanced like a Red-Black
tree. This function also sets value
in maxh and minh (passed by reference).
maxh and minh are set as maximum and 
minimum heights of root.*/

static boolean isBalancedUtil(Node root,
                        INT maxh, INT minh)
{

/*    Base case*/

    if (root == null)
    {
        maxh.d = minh.d = 0;
        return true;
    }

/*    To store max and min heights of left subtree*/

    INT lmxh=new INT(), lmnh=new INT();

/*    To store max and min heights of right subtree*/

    INT rmxh=new INT(), rmnh=new INT();

/*    Check if left subtree is balanced, 
    also set lmxh and lmnh*/

    if (isBalancedUtil(root.left, lmxh, lmnh) == false)
        return false;

/*    Check if right subtree is balanced,
    also set rmxh and rmnh*/

    if (isBalancedUtil(root.right, rmxh, rmnh) == false)
        return false;

/*    Set the max and min heights 
    of this node for the parent call*/

    maxh.d = Math.max(lmxh.d, rmxh.d) + 1;
    minh.d = Math.min(lmnh.d, rmnh.d) + 1;

/*    See if this node is balanced*/

    if (maxh.d <= 2*minh.d)
        return true;
    return false;
}

/*A wrapper over isBalancedUtil()*/

static boolean isBalanced(Node root)
{
    INT maxh=new INT(), minh=new INT();
    return isBalancedUtil(root, maxh, minh);
}

/*Driver code*/

public static void main(String args[])
{
    Node root = new Node(10);
    root.left = new Node(5);
    root.right = new Node(100);
    root.right.left = new Node(50);
    root.right.right = new Node(150);
    root.right.left.left = new Node(40);
    System.out.println(isBalanced(root) ? 
            "Balanced" : "Not Balanced");
}
}

/* Iterative Java program to check if two */

import java.util.*;
class GfG {

/*A Binary Tree Node */

static class Node 
{ 
    int data; 
    Node left, right; 
}

/*Iterative method to find height of Binary Tree */

static boolean areIdentical(Node root1, Node root2) 
{

/*    Return true if both trees are empty */

    if (root1 == null && root2 == null)  return true;

/*    Return false if one is empty and other is not */

    if (root1 == null || root2 == null) return false;

/*    Create an empty queues for simultaneous traversals */

    Queue<Node > q1 = new LinkedList<Node> ();
    Queue<Node>  q2 = new LinkedList<Node> ();

/*    Enqueue Roots of trees in respective queues */

    q1.add(root1); 
    q2.add(root2); 
    while (!q1.isEmpty() && !q2.isEmpty()) 
    {

/*        Get front nodes and compare them */

        Node n1 = q1.peek(); 
        Node n2 = q2.peek(); 
        if (n1.data != n2.data) 
        return false;

/*        Remove front nodes from queues */

        q1.remove();
        q2.remove();

/* Enqueue left children of both nodes */

        if (n1.left != null && n2.left != null) 
        { 
            q1.add(n1.left); 
            q2.add(n2.left); 
        }

/*        If one left child is empty and other is not */

        else if (n1.left != null || n2.left != null) 
            return false;

/*        Right child code (Similar to left child code) */

        if (n1.right != null && n2.right != null) 
        { 
            q1.add(n1.right); 
            q2.add(n2.right); 
        } 
        else if (n1.right != null || n2.right != null) 
            return false; 
    } 
    return true; 
}

/*Utility function to create a new tree node */

static Node newNode(int data) 
{ 
    Node temp = new Node(); 
    temp.data = data; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/*Driver program to test above functions */

public static void main(String[] args) 
{ 
    Node root1 = newNode(1); 
    root1.left = newNode(2); 
    root1.right = newNode(3); 
    root1.left.left = newNode(4); 
    root1.left.right = newNode(5); 
    Node root2 = newNode(1); 
    root2.left = newNode(2); 
    root2.right = newNode(3); 
    root2.left.left = newNode(4); 
    root2.left.right = newNode(5); 
    if(areIdentical(root1, root2) == true)
    System.out.println("Yes");
    else
    System.out.println("No");
}
}

/*Java program to see if there is a root to leaf path
with given sequence.*/

import java.io.*;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node
{
    int data;
    Node left;
    Node right;
    Node(int data)
    {
        this.data = data;
        this.left = null;
        this.right = null;
    }
}
class GFG {

/*    Util function*/

    static boolean existPathUtil(Node root, int arr[], 
                        int n, int index)
    {

/*        If root is NULL or 
        reached end of the array*/

        if(root == null || index==n) 
                return false;

/*        If current node is leaf*/

        if (root.left == null && 
                        root.right == null)
        {
            if((root.data == arr[index]) && 
                                (index == n-1)) 
                return true; 
           return false;
        }

/*        If current node is equal to arr[index] this means
        that till this level path has been matched and
        remaining path can be either in left subtree or
        right subtree.*/

        return ((index < n) && (root.data == arr[index]) 
            &&  (existPathUtil(root.left, arr, n, index+1)
            || existPathUtil(root.right, arr, n, index+1) ));
    }

/*    Function to check given sequence of root 
    to leaf path exist in tree or not.
    index : current element in sequence of root to
    leaf path*/

    static boolean existPath(Node root, int arr[], 
                                    int n, int index)
    {
        if(root == null)
            return (n==0);
        return existPathUtil(root, arr, n, 0);
    }

/*    Driver code*/

    public static void main (String[] args) {

/*    arr[] : sequence of root to leaf path*/

    int arr[] = {5, 8, 6, 7};
    int n = arr.length;
    Node root = new Node(5);
    root.left = new Node(3);
    root.right = new Node(8);
    root.left.left = new Node(2);
    root.left.right = new Node(4);
    root.left.left.left = new Node(1);
    root.right.left = new Node(6);
    root.right.left.right = new Node(7);
    if(existPath(root, arr, n, 0))
        System.out.println("Path Exists");
    else
        System.out.println("Path does not Exist");
    }
}

/*Java program to print cousins of a node */

class GfG {

/*A Binary Tree Node */

static class Node 
{ 
    int data; 
    Node left, right; 
}

/*A utility function to create a new Binary 
Tree Node */

static Node newNode(int item) 
{ 
    Node temp = new Node(); 
    temp.data = item; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/* It returns level of the node if it is present 
in tree, otherwise returns 0.*/

static int getLevel(Node root, Node node, int level) 
{

/*    base cases */

    if (root == null) 
        return 0; 
    if (root == node) 
        return level;

/*    If node is present in left subtree */

    int downlevel = getLevel(root.left, node, level+1); 
    if (downlevel != 0) 
        return downlevel;

/*    If node is not present in left subtree */

    return getLevel(root.right, node, level+1); 
}

/* Print nodes at a given level such that sibling of 
node is not printed if it exists */

static void printGivenLevel(Node root, Node node, int level) 
{

/*    Base cases */

    if (root == null || level < 2) 
        return;

/*    If current node is parent of a node with 
    given level */

    if (level == 2) 
    { 
        if (root.left == node || root.right == node) 
            return; 
        if (root.left != null) 
        System.out.print(root.left.data + " "); 
        if (root.right != null) 
        System.out.print(root.right.data + " "); 
    }

/*    Recur for left and right subtrees */

    else if (level > 2) 
    { 
        printGivenLevel(root.left, node, level-1); 
        printGivenLevel(root.right, node, level-1); 
    } 
}

/*This function prints cousins of a given node */

static void printCousins(Node root, Node node) 
{

/*    Get level of given node */

    int level = getLevel(root, node, 1);

/*    Print nodes of given level. */

