/*Java program to find sum of all left leaves*/

/* A binary tree Node has key, pointer to left and right
   children */

class Node
{
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree
{
    Node root;

/*    A utility function to check if a given node is leaf or not*/

    boolean isLeaf(Node node)
    {
        if (node == null)
            return false;
        if (node.left == null && node.right == null)
            return true;
        return false;
    }

/*     This function returns sum of all left leaves in a given
     binary tree*/

    int leftLeavesSum(Node node)
    {

/*        Initialize result*/

        int res = 0;

/*        Update result if root is not NULL*/

        if (node != null)
        {

/*            If left of root is NULL, then add key of
            left child*/

            if (isLeaf(node.left))
                res += node.left.data;

/*Else recur for left child of root*/

else 
                res += leftLeavesSum(node.left);

/*            Recur for right child of root and update res*/

            res += leftLeavesSum(node.right);
        }

/*        return result*/

        return res;
    }

/*    Driver program*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(9);
        tree.root.right = new Node(49);
        tree.root.left.right = new Node(12);
        tree.root.left.left = new Node(5);
        tree.root.right.left = new Node(23);
        tree.root.right.right = new Node(52);
        tree.root.left.right.right = new Node(12);
        tree.root.right.right.left = new Node(50);
        System.out.println("The sum of leaves is " +
                                       tree.leftLeavesSum(tree.root));
    }
}

/*Java program to find sum of all left leaves*/

import java.util.*;
class GFG
{

/*A binary tree node*/

static class Node
{
    int key;
    Node left, right;

/*    A constructor to create a new Node*/

    Node(int key_)
    {
        this.key = key_;
        this.left = null;
        this.right = null;
    }
};

/*Return the sum of left leaf nodes*/

static int sumOfLeftLeaves(Node root)
{
    if(root == null)
    return 0;

/*    Using a stack_ for Depth-First
    Traversal of the tree*/

    Stack<Node> stack_ = new Stack<>();
    stack_.push(root);

/*    sum holds the sum of all the left leaves*/

    int sum = 0;
    while(stack_.size() > 0)
    {
        Node currentNode = stack_.peek();
        stack_.pop();
        if (currentNode.left != null)
        {
            stack_.add(currentNode.left);

/*            Check if currentNode's left
            child is a leaf node*/

            if(currentNode.left.left == null &&
               currentNode.left.right == null)
            {

/*                if currentNode is a leaf,
                add its data to the sum*/

                sum = sum + currentNode.left.key ;
            }
        }
        if (currentNode.right != null)
            stack_.add(currentNode.right);
    }      
    return sum;
}

/*Driver Code*/

public static void main(String[] args)
{
    Node root = new Node(20);
    root.left= new Node(9);
    root.right = new Node(49);
    root.right.left = new Node(23);
    root.right.right= new Node(52);
    root.right.right.left = new Node(50);
    root.left.left = new Node(5);
    root.left.right = new Node(12);
    root.left.right.right = new Node(12);
    System.out.print("Sum of left leaves is "
      + sumOfLeftLeaves(root) +"\n");
}
}

/*Java program to find sum of all left leaves*/

import java.util.*;
class GFG
{

/*A binary tree node*/

static class Node
{
    int key;
    Node left, right;

/*    constructor to create a new Node*/

    Node(int key_)
    {
        key = key_;
        left = null;
        right = null;
    }
};
static class pair
{
    Node first;
    boolean second;
    public pair(Node first, boolean second) 
    {
        this.first = first;
        this.second = second;
    }   
}

/*Return the sum of left leaf nodes*/

static int sumOfLeftLeaves(Node root)
{
    if (root == null)
    return 0;

/*    A queue of pairs to do bfs traversal
    and keep track if the node is a left
    or right child if boolean value
    is true then it is a left child.*/

    Queue<pair > q = new LinkedList<>();
    q.add(new pair( root, false ));
    int sum = 0;

/*    do bfs traversal*/

    while (!q.isEmpty())
    {
        Node temp = q.peek().first;
        boolean is_left_child =
                   q.peek().second;
        q.remove();

/*        if temp is a leaf node and
        left child of its parent*/

        if (is_left_child)
            sum = sum + temp.key;
        if(temp.left != null && temp.right != null && is_left_child)
            sum = sum-temp.key;

/*        if it is not leaf then
        push its children nodes
        into queue*/

        if (temp.left != null)
        {

/*            boolean value is true
            here because it is left
            child of its parent*/

            q.add(new pair( temp.left, true));
        }
        if (temp.right != null)
        {

/*            boolean value is false
            here because it is
            right child of its parent*/

            q.add(new pair( temp.right, false));
        }
    }
    return sum;
}

/*Driver Code*/

public static void main(String[] args)
{
    Node root = new Node(20);
    root.left = new Node(9);
    root.right = new Node(49);
    root.right.left = new Node(23);
    root.right.right = new Node(52);
    root.right.right.left = new Node(50);
    root.left.left = new Node(5);
    root.left.right = new Node(12);
    root.left.right.right = new Node(12);
    System.out.print("Sum of left leaves is "
         + sumOfLeftLeaves(root) +"\n");
}
}

/*Java implementation to find the sum of nodes
on the longest path from root to leaf node*/

public class GFG 
{

/*    Node of a binary tree*/

    static class Node {
        int data;
        Node left, right;
        Node(int data){
            this.data = data;
            left = null;
            right = null;
        }
    }
    static int maxLen;
    static int maxSum;

/*    function to find the sum of nodes on the
    longest path from root to leaf node*/

    static void sumOfLongRootToLeafPath(Node root, int sum,
                                         int len)
    {

/*        if true, then we have traversed a
        root to leaf path*/

        if (root == null) {

/*            update maximum length and maximum sum
            according to the given conditions*/

            if (maxLen < len) {
                maxLen = len;
                maxSum = sum;
            } else if (maxLen == len && maxSum < sum)
                maxSum = sum;
            return;
        }

/*        recur for left subtree*/

        sumOfLongRootToLeafPath(root.left, sum + root.data,
                                len + 1);

/*    recur for right subtree*/

        sumOfLongRootToLeafPath(root.right, sum + root.data,
                                len + 1);
    }

/*    utility function to find the sum of nodes on
    the longest path from root to leaf node*/

    static int sumOfLongRootToLeafPathUtil(Node root)
    {

/*        if tree is NULL, then sum is 0*/

        if (root == null)
            return 0;
        maxSum = Integer.MIN_VALUE;
        maxLen = 0;

/*        finding the maximum sum 'maxSum' for the
        maximum length root to leaf path*/

        sumOfLongRootToLeafPath(root, 0, 0);

/*        required maximum sum*/

        return maxSum;
    }

/*    Driver program to test above*/

    public static void main(String args[])
    {

/*        binary tree formation*/

        Node root = new Node(4);

/*        4        */

        root.left = new Node(2);

/*       / \       */

        root.right = new Node(5);

/*      2   5      */

        root.left.left = new Node(7);

/*     / \ / \     */

        root.left.right = new Node(1);

/*    7  1 2  3    */

        root.right.left = new Node(2);

/*     6           */
        root.right.right = new Node(3);  
        root.left.right.left = new Node(6);
        System.out.println( "Sum = "
             + sumOfLongRootToLeafPathUtil(root));
    }
}

/*Java program to implement
the above approach*/

import java.util.*; 
class GFG
{

/*A utility function to get
maximum of two integers */

static int max(int l, int r) 
{ 
    return (l > r ? l : r);
}

/*A Binary Tree Node */

static class Node 
{ 
    int data; 
    Node left, right; 
}; 
static class INT
{
    int v;
INT(int a)
{
    v = a;
}
}

/*A utility function to create 
a new Binary Tree node with
given data */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = node.right = null; 
    return node; 
}

/*print the tree in LVR 
(Inorder traversal) way. */

static void print(Node root) 
{ 
    if (root != null) 
    { 
        print(root.left); 
        System.out.print(root.data + " "); 
        print(root.right); 
    } 
}

/*Main function which
truncates the binary tree. */

static Node pruneUtil(Node root, int k, 
                      INT sum) 
{

/*    Base Case */

    if (root == null) return null;

/*    Initialize left and right 
    sums as sum from root to 
    this node (including this node) */

    INT lsum = new INT(sum.v + (root.data)); 
    INT rsum = new INT(lsum.v);

/*    Recursively prune left 
    and right subtrees */

    root.left = pruneUtil(root.left, k, lsum); 
    root.right = pruneUtil(root.right, k, rsum);

/*    Get the maximum of
    left and right sums */

    sum.v = max(lsum.v, rsum.v);

/*    If maximum is smaller 
    than k, then this node 
    must be deleted */

    if (sum.v < k) 
    { 
        root = null; 
    } 
    return root; 
}

/*A wrapper over pruneUtil() */

static Node prune(Node root, int k) 
{ 
    INT sum = new INT(0); 
    return pruneUtil(root, k, sum); 
}

/*Driver Code*/

public static void main(String args[])
{ 
    int k = 45; 
    Node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(3); 
    root.left.left = newNode(4); 
    root.left.right = newNode(5); 
    root.right.left = newNode(6); 
    root.right.right = newNode(7); 
    root.left.left.left = newNode(8); 
    root.left.left.right = newNode(9); 
    root.left.right.left = newNode(12); 
    root.right.right.left = newNode(10); 
    root.right.right.left.right = newNode(11); 
    root.left.left.right.left = newNode(13); 
    root.left.left.right.right = newNode(14); 
    root.left.left.right.right.left = newNode(15); 
    System.out.println("Tree before truncation\n"); 
    print(root);

/*k is 45 */

root = prune(root, k); 
    System.out.println("\n\nTree after truncation\n"); 
    print(root); 
} 
}

/*Java program to find maximum path sum between two leaves
of a binary tree*/

/*A binary tree node*/

class Node {
    int data;
    Node left, right;
    Node(int item) {
        data = item;
        left = right = null;
    }
}

/*An object of Res is passed around so that the
same value can be used by multiple recursive calls.*/

class Res {
    int val;
}
class BinaryTree {
    static Node root;

/*    A utility function to find the maximum sum between any
    two leaves.This function calculates two values:
    1) Maximum path sum between two leaves which is stored
        in res.
    2) The maximum root to leaf path sum which is returned.
    If one side of root is empty, then it returns INT_MIN*/

    int maxPathSumUtil(Node node, Res res) {

/*        Base cases*/

        if (node == null)
            return 0;
        if (node.left == null && node.right == null)
            return node.data;

/*        Find maximum sum in left and right subtree. Also
        find maximum root to leaf sums in left and right
        subtrees and store them in ls and rs*/

        int ls = maxPathSumUtil(node.left, res);
        int rs = maxPathSumUtil(node.right, res);

/*        If both left and right children exist*/

        if (node.left != null && node.right != null) {

/*            Update result if needed*/

            res.val = Math.max(res.val, ls + rs + node.data);

/*            Return maxium possible value for root being
            on one side*/

            return Math.max(ls, rs) + node.data;
        }

/*        If any of the two children is empty, return
        root sum for root being on one side*/

        return (node.left == null) ? rs + node.data
                : ls + node.data;
    }

/*    The main function which returns sum of the maximum
    sum path between two leaves. This function mainly
    uses maxPathSumUtil()*/

    int maxPathSum(Node node)
    {
        Res res = new Res();
        res.val = Integer.MIN_VALUE;
        maxPathSumUtil(root, res);
        return res.val;
    }

/*    Driver program to test above functions*/

    public static void main(String args[]) {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(-15);
        tree.root.left = new Node(5);
        tree.root.right = new Node(6);
        tree.root.left.left = new Node(-8);
        tree.root.left.right = new Node(1);
        tree.root.left.left.left = new Node(2);
        tree.root.left.left.right = new Node(6);
        tree.root.right.left = new Node(3);
        tree.root.right.right = new Node(9);
        tree.root.right.right.right = new Node(0);
        tree.root.right.right.right.left = new Node(4);
        tree.root.right.right.right.right = new Node(-1);
        tree.root.right.right.right.right.left = new Node(10);
        System.out.println("Max pathSum of the given binary tree is "
                + tree.maxPathSum(root));
    }
}

/*Java program to find maximum sum leaf to root
path in Binary Tree*/

/*A Binary Tree node*/

class Node {
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*A wrapper class is used so that max_no
can be updated among function calls.*/

class Maximum {
    int max_no = Integer.MIN_VALUE;
}
class BinaryTree {
    Node root;
    Maximum max = new Maximum();
    Node target_leaf = null;

/*    A utility function that prints all nodes on the
    path from root to target_leaf*/

    boolean printPath(Node node, Node target_leaf)
    {

/*        base case*/

        if (node == null)
            return false;

/*        return true if this node is the target_leaf or
        target leaf is present in one of its descendants*/

        if (node == target_leaf || printPath(node.left, target_leaf)
            || printPath(node.right, target_leaf)) {
            System.out.print(node.data + " ");
            return true;
        }
        return false;
    }

/*    This function Sets the target_leaf_ref to refer
    the leaf node of the maximum path sum. Also,
    returns the max_sum using max_sum_ref*/

    void getTargetLeaf(Node node, Maximum max_sum_ref,
                       int curr_sum)
    {
        if (node == null)
            return;

/*        Update current sum to hold sum of nodes on
        path from root to this node*/

        curr_sum = curr_sum + node.data;

/*        If this is a leaf node and path to this node
        has maximum sum so far, the n make this node
        target_leaf*/

        if (node.left == null && node.right == null) {
            if (curr_sum > max_sum_ref.max_no) {
                max_sum_ref.max_no = curr_sum;
                target_leaf = node;
            }
        }

/*        If this is not a leaf node, then recur down
        to find the target_leaf*/

        getTargetLeaf(node.left, max_sum_ref, curr_sum);
        getTargetLeaf(node.right, max_sum_ref, curr_sum);
    }

/*    Returns the maximum sum and prints the nodes on
    max sum path*/

    int maxSumPath()
    {

/*        base case*/

        if (root == null)
            return 0;

/*        find the target leaf and maximum sum*/

        getTargetLeaf(root, max, 0);

/*        print the path from root to the target leaf*/

        printPath(root, target_leaf);

/*return maximum sum*/

return max.max_no; 
    }

/*    driver function to test the above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(-2);
        tree.root.right = new Node(7);
        tree.root.left.left = new Node(8);
        tree.root.left.right = new Node(-4);
        System.out.println("Following are the nodes "
                           + "on maximum sum path");
        int sum = tree.maxSumPath();
        System.out.println("");
        System.out.println("Sum of nodes is : " + sum);
    }
}

/*Java program to find maximum sum in Binary Tree
such that no two nodes are adjacent.*/

public class FindSumOfNotAdjacentNodes {

/* A binary tree node structure */

class Node
{
    int data;
    Node left, right;
    Node(int data)
    {
        this.data=data;
        left=right=null;
    }
};

/*maxSumHelper function */

    public static Pair maxSumHelper(Node root)
    {
        if (root==null)
        {
            Pair sum=new Pair(0, 0);
            return sum;
        }
        Pair sum1 = maxSumHelper(root.left);
        Pair sum2 = maxSumHelper(root.right);
        Pair sum=new Pair(0,0);

/*        This node is included (Left and right children
        are not included)*/

        sum.first = sum1.second + sum2.second + root.data;

/*        This node is excluded (Either left or right
        child is included)*/

        sum.second = Math.max(sum1.first, sum1.second) +
                     Math.max(sum2.first, sum2.second);
        return sum;
    }

/*    Returns maximum sum from subset of nodes
    of binary tree under given constraints*/

    public static int maxSum(Node root)
    {
        Pair res=maxSumHelper(root);
        return Math.max(res.first, res.second);
    }

/*Driver code*/

    public static void main(String args[]) {
        Node root= new Node(10);
        root.left= new Node(1);
        root.left.left= new Node(2);
        root.left.left.left= new Node(1);
        root.left.right= new Node(3);
        root.left.right.left= new Node(4);
        root.left.right.right= new Node(5);
        System.out.print(maxSum(root));
    }
}

/* Pair class */

class Pair
{
    int first,second;
    Pair(int first,int second)
    {
        this.first=first;
        this.second=second;
    }
}

/*Java code for max sum with adjacent levels
not allowed*/

import java.util.*;
public class Main {

/*    Tree node class for Binary Tree
    representation*/

    static class Node {
        int data;
        Node left, right;
        Node(int item)
        {
            data = item;
            left = right = null;
        }
    }

/*    Recursive function to find the maximum
    sum returned for a root node and its
    grandchildren*/

    public static int getSumAlternate(Node root)
    {
        if (root == null)
            return 0;
        int sum = root.data;
        if (root.left != null) {
            sum += getSum(root.left.left);
            sum += getSum(root.left.right);
        }
        if (root.right != null) {
            sum += getSum(root.right.left);
            sum += getSum(root.right.right);
        }
        return sum;
    }

/*    Returns maximum sum with adjacent
    levels not allowed. This function
    mainly uses getSumAlternate()*/

    public static int getSum(Node root)
    {
        if (root == null)
            return 0;

/*        We compute sum of alternate levels
        starting first level and from second
        level.
        And return maximum of two values.*/

        return Math.max(getSumAlternate(root),
                        (getSumAlternate(root.left) +
                        getSumAlternate(root.right)));
    }

/*    Driver function*/

    public static void main(String[] args)
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.right.left = new Node(4);
        root.right.left.right = new Node(5);
        root.right.left.right.left = new Node(6);
        System.out.println(getSum(root));
    }
}

/*Java program to find sum of heights of all
nodes in a binary tree*/

class GfG {

/* A binary tree Node has data, pointer to
    left child and a pointer to right child */

static class Node {
    int data;
    Node left;
    Node right;
}

/* Compute the "maxHeight" of a particular Node*/

static int getHeight(Node Node)
{
    if (Node == null)
        return 0;
    else {

/* compute the height of each subtree */

        int lHeight = getHeight(Node.left);
        int rHeight = getHeight(Node.right);

/* use the larger one */

        if (lHeight > rHeight)
            return (lHeight + 1);
        else
            return (rHeight + 1);
    }
}

/* Helper function that allocates a new Node with the
given data and NULL left and right pointers. */

static Node newNode(int data)
{
    Node Node = new Node();
    Node.data = data;
    Node.left = null;
    Node.right = null;
    return (Node);
}

/* Function to sum of heights of individual Nodes
Uses Inorder traversal */

static int getTotalHeight( Node root)
{
    if (root == null)
        return 0;
    return getTotalHeight(root.left) + getHeight(root) + getTotalHeight(root.right);
}

/*Driver code*/

public static void main(String[] args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    System.out.println("Sum of heights of all Nodes = " + getTotalHeight(root));
}
}

/*Java program to find sum of heights of all
nodes in a binary tree*/

class GFG
{

/* A binary tree Node has data, pointer to
    left child and a pointer to right child */

    static class Node
    {
        int data;
        Node left;
        Node right;
    };
    static int sum;

/* Helper function that allocates a new Node with the
    given data and null left and right pointers. */

    static Node newNode(int data)
    {
        Node Node = new Node();
        Node.data = data;
        Node.left = null;
        Node.right = null;
        return (Node);
    }

/* Function to sum of heights of individual Nodes
    Uses Inorder traversal */

    static int getTotalHeightUtil(Node root)
    {
        if (root == null)
        {
            return 0;
        }
        int lh = getTotalHeightUtil(root.left);
        int rh = getTotalHeightUtil(root.right);
        int h = Math.max(lh, rh) + 1;
        sum = sum + h;
        return h;
    }
    static int getTotalHeight(Node root)
    {
        sum = 0;
        getTotalHeightUtil(root);
        return sum;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        Node root = newNode(1);
        root.left = newNode(2);
        root.right = newNode(3);
        root.left.left = newNode(4);
        root.left.right = newNode(5);
        System.out.printf("Sum of heights of all Nodes = %d",
                                       getTotalHeight(root));
    }
}

/*Java code to find the sum of the nodes
which are present at the maximum depth.*/

class GFG
{
static int sum = 0, max_level = Integer.MIN_VALUE;
static class Node
{
    int d;
    Node l;
    Node r;
};

/*Function to return a new node*/

static Node createNode(int d)
{
    Node node;
    node = new Node();
    node.d = d;
    node.l = null;
    node.r = null;
    return node;
}

/*Function to find the sum of the node
which are present at the maximum depth.
While traversing the nodes compare the level
of the node with max_level
(Maximum level till the current node).
If the current level exceeds the maximum level,
update the max_level as current level.
If the max level and current level are same,
add the root data to current sum.*/

static void sumOfNodesAtMaxDepth(Node ro,int level)
{
    if(ro == null)
    return;
    if(level > max_level)
    {
        sum = ro . d;
        max_level = level;
    }
    else if(level == max_level)
    {
        sum = sum + ro . d;
    }
    sumOfNodesAtMaxDepth(ro . l, level + 1);
    sumOfNodesAtMaxDepth(ro . r, level + 1);
}

/*Driver Code*/

public static void main(String[] args)
{
    Node root;
    root = createNode(1);
    root.l = createNode(2);
    root.r = createNode(3);
    root.l.l = createNode(4);
    root.l.r = createNode(5);
    root.r.l = createNode(6);
    root.r.r = createNode(7);
    sumOfNodesAtMaxDepth(root, 0);
    System.out.println(sum);
}
}

/*Java implementation to find the sum of
leaf nodes at minimum level*/

import java.util.*;
class GFG 
{

/*structure of a node of binary tree*/

static class Node 
{
    int data;
    Node left, right;
};

/*function to get a new node*/

static Node getNode(int data)
{

/*    allocate space*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.left = newNode.right = null;
    return newNode;
}

/*function to find the sum of
leaf nodes at minimum level*/

static int sumOfLeafNodesAtMinLevel(Node root)
{

/*    if tree is empty*/

    if (root == null)
        return 0;

/*    if there is only one node*/

    if (root.left == null &&
        root.right == null)
        return root.data;

/*    queue used for level order traversal*/

    Queue<Node> q = new LinkedList<>();
    int sum = 0; 
    boolean f = false;

/*    push root node in the queue 'q'*/

    q.add(root);
    while (f == false)
    {

/*        count number of nodes in the
        current level*/

        int nc = q.size();

/*        traverse the current level nodes*/

        while (nc-- >0)
        {

/*            get front element from 'q'*/

            Node top = q.peek();
            q.remove();

/*            if it is a leaf node*/

            if (top.left == null && 
                top.right == null) 
            {

/*                accumulate data to 'sum'*/

                sum += top.data;

/*                set flag 'f' to 1, to signify 
                minimum level for leaf nodes 
                has been encountered*/

                f = true;
            }
            else 
            {

/*                if top's left and right child 
                exists, then push them to 'q'*/

                if (top.left != null)
                    q.add(top.left);
                if (top.right != null)
                    q.add(top.right);
            }
        }
    }

/*    required sum*/

    return sum;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    binary tree creation*/

    Node root = getNode(1);
    root.left = getNode(2);
    root.right = getNode(3);
    root.left.left = getNode(4);
    root.left.right = getNode(5);
    root.right.left = getNode(6);
    root.right.right = getNode(7);
    root.left.right.left = getNode(8);
    root.right.left.right = getNode(9);
    System.out.println("Sum = " + 
           sumOfLeafNodesAtMinLevel(root));
    }
}

/*Java program to Merge Two Binary Trees*/

import java.util.*;
class GFG{

/* A binary tree node has data, pointer to left child
and a pointer to right child */

static class Node
{
    int data;
    Node left, right;
};

/*Structure to store node pair onto stack*/

static class snode
{
    Node l, r;
};

/* Helper function that allocates a new node with the
given data and null left and right pointers. */

static Node newNode(int data)
{
    Node new_node = new Node();
    new_node.data = data;
    new_node.left = new_node.right = null;
    return new_node;
}

/* Given a binary tree, print its nodes in inorder*/

static void inorder(Node  node)
{
    if (node == null)
        return;

/* first recur on left child */

    inorder(node.left);

/* then print the data of node */

    System.out.printf("%d ", node.data);

/* now recur on right child */

    inorder(node.right);
}

/* Function to merge given two binary trees*/

static Node MergeTrees(Node t1, Node t2)
{
    if ( t1 == null)
        return t2;
    if ( t2 == null)
        return t1;
    Stack<snode> s = new Stack<>();
    snode temp = new snode();
    temp.l = t1;
    temp.r = t2;
    s.add(temp);
    snode n;
    while (! s.isEmpty())
    {
        n = s.peek();
        s.pop();
        if (n.l == null|| n.r == null)
            continue;
        n.l.data += n.r.data;
        if (n.l.left == null)
            n.l.left = n.r.left;
        else
        {
            snode t = new snode();
            t.l = n.l.left;
            t.r = n.r.left;
            s.add(t);
        }
        if (n.l.right == null)
            n.l.right = n.r.right;
        else
        {
            snode t = new snode();
            t.l = n.l.right;
            t.r = n.r.right;
            s.add(t);
        }
    }
    return t1;
}

/*Driver code*/

public static void main(String[] args)
{

/* Let us conthe first Binary Tree
            1
          /   \
         2     3
        / \     \
       4   5     6
    */

    Node root1 = newNode(1);
    root1.left = newNode(2);
    root1.right = newNode(3);
    root1.left.left = newNode(4);
    root1.left.right = newNode(5);
    root1.right.right = newNode(6);

/* Let us conthe second Binary Tree
           4
         /   \
        1     7
       /     /  \
      3     2    6   */

    Node root2 = newNode(4);
    root2.left = newNode(1);
    root2.right = newNode(7);
    root2.left.left = newNode(3);
    root2.right.left = newNode(2);
    root2.right.right = newNode(6);
    Node root3 = MergeTrees(root1, root2);
    System.out.printf("The Merged Binary Tree is:\n");
    inorder(root3);
}
}

/*Java implementation to find lowest common ancestor of
n1 and n2 using one traversal of binary tree
It also handles cases even when n1 and n2 are not there in Tree*/

/* Class containing left and right child of current node and key */

class Node
{
    int data;
    Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{

/*    Root of the Binary Tree*/

    Node root;
    static boolean v1 = false, v2 = false;

/*    This function returns pointer to LCA of two given
    values n1 and n2.
    v1 is set as true by this function if n1 is found
    v2 is set as true by this function if n2 is found*/

    Node findLCAUtil(Node node, int n1, int n2)
    {

/*        Base case*/

        if (node == null)
            return null;

/*        Store result in temp, in case of key match so that we can search for other key also.*/

        Node temp=null;

/*        If either n1 or n2 matches with root's key, report the presence
        by setting v1 or v2 as true and return root (Note that if a key
        is ancestor of other, then the ancestor key becomes LCA)*/

        if (node.data == n1)
        {
            v1 = true;
            temp = node;
        }
        if (node.data == n2)
        {
            v2 = true;
            temp = node;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCAUtil(node.left, n1, n2);
        Node right_lca = findLCAUtil(node.right, n1, n2);
        if (temp != null)
            return temp;

/*        If both of the above calls return Non-NULL, then one key
        is present in once subtree and other is present in other,
        So this node is the LCA*/

        if (left_lca != null && right_lca != null)
            return node;

/*        Otherwise check if left subtree or right subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    Finds lca of n1 and n2 under the subtree rooted with 'node'*/

    Node findLCA(int n1, int n2)
    {

/*        Initialize n1 and n2 as not visited*/

        v1 = false;
        v2 = false;

/*        Find lca of n1 and n2 using the technique discussed above*/

        Node lca = findLCAUtil(root, n1, n2);

/*        Return LCA only if both n1 and n2 are present in tree*/

        if (v1 && v2)
            return lca;

/*        Else return NULL*/

        return null;
    }

/* Driver program to test above functions */

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        Node lca = tree.findLCA(4, 5);
        if (lca != null)
            System.out.println("LCA(4, 5) = " + lca.data);
        else
            System.out.println("Keys are not present");
        lca = tree.findLCA(4, 10);
        if (lca != null)
            System.out.println("LCA(4, 10) = " + lca.data);
        else
            System.out.println("Keys are not present");
    }
}

/*Java program to find lowest common ancestor using parent pointer*/
import java.util.HashMap;
import java.util.Map;

/*A tree node*/

class Node 
{
    int key;
    Node left, right, parent;
    Node(int key) 
    {
        this.key = key;
        left = right = parent = null;
    }
}
class BinaryTree 
{
    Node root, n1, n2, lca;

/* A utility function to insert a new node with
       given key in Binary Search Tree */

    Node insert(Node node, int key) 
    {

/* If the tree is empty, return a new node */

        if (node == null)
            return new Node(key);

/* Otherwise, recur down the tree */

        if (key < node.key) 
        {
            node.left = insert(node.left, key);
            node.left.parent = node;
        }
        else if (key > node.key) 
        {
            node.right = insert(node.right, key);
            node.right.parent = node;
        }

/* return the (unchanged) node pointer */

        return node;
    }

/*    To find LCA of nodes n1 and n2 in Binary Tree*/

    Node LCA(Node n1, Node n2) 
    {

/*        Creata a map to store ancestors of n1*/

        Map<Node, Boolean> ancestors = new HashMap<Node, Boolean>();

/*        Insert n1 and all its ancestors in map*/

        while (n1 != null) 
        {
            ancestors.put(n1, Boolean.TRUE);
            n1 = n1.parent;
        }

/*        Check if n2 or any of its ancestors is in
        map.*/

        while (n2 != null) 
        {
            if (ancestors.containsKey(n2) != ancestors.isEmpty())
                return n2;
            n2 = n2.parent;
        }
        return null;
    }

/*    Driver method to test above functions*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = tree.insert(tree.root, 20);
        tree.root = tree.insert(tree.root, 8);
        tree.root = tree.insert(tree.root, 22);
        tree.root = tree.insert(tree.root, 4);
        tree.root = tree.insert(tree.root, 12);
        tree.root = tree.insert(tree.root, 10);
        tree.root = tree.insert(tree.root, 14);
        tree.n1 = tree.root.left.right.left;
        tree.n2 = tree.root.left;
        tree.lca = tree.LCA(tree.n1, tree.n2);
        System.out.println("LCA of " + tree.n1.key + " and " + tree.n2.key
                + " is " + tree.lca.key);
    }
}

import java.util.HashMap;
import java.util.Map;

/*Java program to find lowest common ancestor using parent pointer
A tree node*/

class Node 
{
    int key;
    Node left, right, parent;
    Node(int key) 
    {
        this.key = key;
        left = right = parent = null;
    }
}
class BinaryTree 
{
    Node root, n1, n2, lca;

/* A utility function to insert a new node with
       given key in Binary Search Tree */

    Node insert(Node node, int key) 
    {

/* If the tree is empty, return a new node */

        if (node == null)
            return new Node(key);

/* Otherwise, recur down the tree */

        if (key < node.key) 
        {
            node.left = insert(node.left, key);
            node.left.parent = node;
        } 
        else if (key > node.key) 
        {
            node.right = insert(node.right, key);
            node.right.parent = node;
        }

/* return the (unchanged) node pointer */

        return node;
    }

/*    A utility function to find depth of a node
    (distance of it from root)*/

    int depth(Node node) 
    {
        int d = -1;
        while (node != null) 
        {
            ++d;
            node = node.parent;
        }
        return d;
    }

/*    To find LCA of nodes n1 and n2 in Binary Tree*/

    Node LCA(Node n1, Node n2) 
    {

/*        Find depths of two nodes and differences*/

        int d1 = depth(n1), d2 = depth(n2);
        int diff = d1 - d2;

/*        If n2 is deeper, swap n1 and n2*/

        if (diff < 0) 
        {
            Node temp = n1;
            n1 = n2;
            n2 = temp;
            diff = -diff;
        }

/*        Move n1 up until it reaches the same level as n2*/

        while (diff-- != 0)
            n1 = n1.parent;

/*        Now n1 and n2 are at same levels*/

        while (n1 != null && n2 != null) 
        {
            if (n1 == n2)
                return n1;
            n1 = n1.parent;
            n2 = n2.parent;
        }
        return null;
    }

/*    Driver method to test above functions*/

    public static void main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = tree.insert(tree.root, 20);
        tree.root = tree.insert(tree.root, 8);
        tree.root = tree.insert(tree.root, 22);
        tree.root = tree.insert(tree.root, 4);
        tree.root = tree.insert(tree.root, 12);
        tree.root = tree.insert(tree.root, 10);
        tree.root = tree.insert(tree.root, 14);
        tree.n1 = tree.root.left.right.left;
        tree.n2 = tree.root.right;
        tree.lca = tree.LCA(tree.n1, tree.n2);
        System.out.println("LCA of " + tree.n1.key + " and " + tree.n2.key
                + " is " + tree.lca.key);
    }
}

/*JAVA code to find LCA of given
two nodes in a tree*/

import java.util.*;
public class GFG
{
  static int maxn = 100005;
  static  int left(int i)
  {
    return  (2 * i + 1);
  }
  static  int right(int i) { return 2 * i + 2;}

/*  the graph*/

  static Vector<Integer> []g = new Vector[maxn];

/*  level of each node*/

  static int []level = new int[maxn];
  static Vector<Integer> e = new Vector<>();
  static Vector<Integer> l= new Vector<>();
  static int []h = new int[maxn];

/*  the segment tree*/

  static int []st = new int[5 * maxn];

/*  adding edges to the graph(tree)*/

  static void add_edge(int u, int v)
  {
    g[u].add(v);
    g[v].add(u);
  }

/*  assigning level to nodes*/

  static void levelling(int src)
  {
    for (int i = 0; i < (g[src].size()); i++)
    {
      int des = g[src].get(i);
      if (level[des] != 0)
      {
        level[des] = level[src] + 1;
        leveling(des);
      }
    }
  }
  static boolean []visited = new boolean[maxn];

/*  storing the dfs traversal
  in the array e*/

  static void dfs(int src)
  {
    e.add(src);
    visited[src] = true;
    for (int i = 0; i < (g[src]).size(); i++)
    {
      int des = g[src].get(i);
      if (!visited[des])
      {
        dfs(des);
        e.add(src);
      }
    }
  }

/*  making the array l*/

  static void setting_l(int n)
  {
    for (int i = 0; i < e.size(); i++)
      l.add(level[e.get(i)]);
  }

/*  making the array h*/

  static void setting_h(int n)
  {
    for (int i = 0; i <= n; i++)
      h[i] = -1;
    for (int i = 0; i < e.size(); i++)
    {

/*      if is already stored*/

      if (h[e.get(i)] == -1)
        h[e.get(i)] = i;
    }
  }

/*  Range minimum query to return the index
  of minimum in the subarray L[qs:qe]*/

  static int RMQ(int ss, int se, int qs, int qe, int i)
  {
    if (ss > se)
      return -1;

/*    out of range*/

    if (se < qs || qe < ss)
      return -1;

/*    in the range*/

    if (qs <= ss && se <= qe)
      return st[i];
    int mid = (ss + se)/2 ;
    int st = RMQ(ss, mid, qs, qe, left(i));
    int en = RMQ(mid + 1, se, qs, qe, right(i));
    if (st != -1 && en != -1)
    {
      if (l.get(st) < l.get(en))
        return st;
      return en;
    } else if (st != -1)
      return st-2;
    else if (en != -1)
      return en-1;
    return 0;
  }

/*  constructs the segment tree*/

  static void SegmentTreeConstruction(int ss,
                                      int se, int i)
  {
    if (ss > se)
      return;

/*leaf*/

if (ss == se) 
    {
      st[i] = ss;
      return;
    }
    int mid = (ss + se) /2;
    SegmentTreeConstruction(ss, mid, left(i));
    SegmentTreeConstruction(mid + 1, se, right(i));
    if (l.get(st[left(i)]) < l.get(st[right(i)]))
      st[i] = st[left(i)];
    else
      st[i] = st[right(i)];
  }

/*  Function to get LCA*/

  static int LCA(int x, int y)
  {
    if (h[x] > h[y])
    {
      int t = x;
      x = y;
      y = t;
    }
    return e.get(RMQ(0, l.size() - 1, h[x], h[y], 0));
  }

/*  Driver code*/

  public static void main(String[] args)
  {

/*    n=number of nodes in the tree
    q=number of queries to answer*/

    int n = 15, q = 5;
    for (int i = 0; i < g.length; i++)
      g[i] = new Vector<Integer>();

/*    making the tree*/

/*
                   1
                 / | \
                2  3  4
                   |   \
                   5    6
                 / |  \
               8   7    9 (right of 5)
                 / | \   | \
               10 11 12 13 14
                      |
                      15
  */

    add_edge(1, 2);
    add_edge(1, 3);
    add_edge(1, 4);
    add_edge(3, 5);
    add_edge(4, 6);
    add_edge(5, 7);
    add_edge(5, 8);
    add_edge(5, 9);
    add_edge(7, 10);
    add_edge(7, 11);
    add_edge(7, 12);
    add_edge(9, 13);
    add_edge(9, 14);
    add_edge(12, 15);
    level[1] = 1;
    leveling(1);
    dfs(1);
    setting_l(n);
    setting_h(n);
    SegmentTreeConstruction(0, l.size() - 1, 0);
    System.out.print(LCA(10, 15) +"\n");
    System.out.print(LCA(11, 14) +"\n");
  }
}

/*Java Program to find common nodes for given two nodes*/

import java.util.LinkedList;

/*Class to represent Tree node */

class Node 
{
    int data;
    Node left, right;
    public Node(int item) 
    {
        data = item;
        left = null;
        right = null;
    }
}

/*Class to count full nodes of Tree */

class BinaryTree 
{
    static Node root;

/*Utility function to find the LCA of two given values
n1 and n2.*/

static Node findLCA(Node root, int n1, int n2)
{

/*    Base case*/

    if (root == null)
        return null;

/*    If either n1 or n2 matches with root's key,
    report the presence by returning root (Note
    that if a key is ancestor of other, then the
    ancestor key becomes LCA*/

    if (root.data == n1 || root.data == n2)
        return root;

/*    Look for keys in left and right subtrees*/

    Node left_lca = findLCA(root.left, n1, n2);
    Node right_lca = findLCA(root.right, n1, n2);

/*    If both of the above calls return Non-NULL, then
    one key is present in once subtree and other is
    present in other, So this node is the LCA*/

    if (left_lca!=null && right_lca!=null)
        return root;

/*    Otherwise check if left subtree or right
    subtree is LCA*/

    return (left_lca != null) ? left_lca : right_lca;
}

/*Utility Function to print all ancestors of LCA*/

static boolean printAncestors(Node root, int target)
{

/* base cases */

    if (root == null)
        return false;
    if (root.data == target) {
        System.out.print(root.data+ " ");
        return true;
    }

/* If target is present in either left or right
    subtree of this node, then print this node */

    if (printAncestors(root.left, target) ||
        printAncestors(root.right, target)) {
        System.out.print(root.data+ " ");
        return true;
    }

/* Else return false */

    return false;
}

/*Function to find nodes common to given two nodes*/

static boolean findCommonNodes(Node root, int first,
                                    int second)
{
    Node LCA = findLCA(root, first, second);
    if (LCA == null)
        return false;
    printAncestors(root, LCA.data);
    return true;
}

/*Driver program to test above functions*/

    public static void main(String args[]) 
    {

/*Let us create Binary Tree shown in 
        above example */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
