        tree.root.right.left.right = new Node(10);
   if (findCommonNodes(root, 9, 7) == false)
    System.out.println("No Common nodes");
    }
}

/*Java program to find LCA of u and v by reducing problem to RMQ*/

import java.util.*;

/*A binary tree node*/

class Node
{
    Node left, right;
    int data;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class St_class
{
    int st;
    int stt[] = new int[10000];
}
class BinaryTree
{
    Node root;

/*v is the highest value of node in our tree*/

int v = 9;

/*for euler tour sequence*/

int euler[] = new int[2 * v - 1];

/*level of nodes in tour sequence*/

int level[] = new int[2 * v - 1];

/*to store 1st occurrence of nodes*/

int f_occur[] = new int[2 * v - 1];

/*variable to fill euler and level arrays*/

int fill; 
    St_class sc = new St_class();

/*    log base 2 of x*/

    int Log2(int x)
    {
        int ans = 0;
        int y = x >>= 1;
        while (y-- != 0)
            ans++;
        return ans;
    }
    int swap(int a, int b)
    {
        return a;
    }

/*  A recursive function to get the minimum value in a given range
     of array indexes. The following are parameters for this function.
     st    --> Pointer to segment tree
     index --> Index of current node in the segment tree. Initially
     0 is passed as root is always at index 0
     ss & se  --> Starting and ending indexes of the segment represented
     by current node, i.e., st[index]
     qs & qe  --> Starting and ending indexes of query range */

    int RMQUtil(int index, int ss, int se, int qs, int qe, St_class st)
    {

/*        If segment of this node is a part of given range, then return
          the min of the segment*/

        if (qs <= ss && qe >= se)
            return st.stt[index];

/*        If segment of this node is outside the given range*/

        else if (se < qs || ss > qe)
            return -1;

/*        If a part of this segment overlaps with the given range*/

        int mid = (ss + se) / 2;
        int q1 = RMQUtil(2 * index + 1, ss, mid, qs, qe, st);
        int q2 = RMQUtil(2 * index + 2, mid + 1, se, qs, qe, st);
        if (q1 == -1)
            return q2;
        else if (q2 == -1)
            return q1;
        return (level[q1] < level[q2]) ? q1 : q2;
    }

/*    Return minimum of elements in range from index qs (query start) to
    qe (query end).  It mainly uses RMQUtil()*/

    int RMQ(St_class st, int n, int qs, int qe)
    {

/*        Check for erroneous input values*/

        if (qs < 0 || qe > n - 1 || qs > qe)
        {
            System.out.println("Invalid input");
            return -1;
        }
        return RMQUtil(0, 0, n - 1, qs, qe, st);
    }

/*    A recursive function that constructs Segment Tree for array[ss..se].
    si is index of current node in segment tree st*/

    void constructSTUtil(int si, int ss, int se, int arr[], St_class st)
    {

/*        If there is one element in array, store it in current node of
        segment tree and return*/

        if (ss == se)
            st.stt[si] = ss;
        else
        {

/*            If there are more than one elements, then recur for left and
            right subtrees and store the minimum of two values in this node*/

            int mid = (ss + se) / 2;
            constructSTUtil(si * 2 + 1, ss, mid, arr, st);
            constructSTUtil(si * 2 + 2, mid + 1, se, arr, st);
            if (arr[st.stt[2 * si + 1]] < arr[st.stt[2 * si + 2]])
                st.stt[si] = st.stt[2 * si + 1];
            else
                st.stt[si] = st.stt[2 * si + 2];
        }
    }

/* Function to construct segment tree from given array. This function
     allocates memory for segment tree and calls constructSTUtil() to
     fill the allocated memory */

    int constructST(int arr[], int n)
    {

/*        Allocate memory for segment tree
        Height of segment tree*/

        int x = Log2(n) + 1;

/*        Maximum size of segment tree
  2*pow(2,x) -1*/

int max_size = 2 * (1 << x) - 1;  
        sc.stt = new int[max_size];

/*        Fill the allocated memory st*/

        constructSTUtil(0, 0, n - 1, arr, sc);

/*        Return the constructed segment tree*/

        return sc.st;
    }

/*    Recursive version of the Euler tour of T*/

    void eulerTour(Node node, int l)
    {

/* if the passed node exists */

        if (node != null)
        {

/*insert in euler array*/

euler[fill] = node.data;

/*insert l in level array*/

level[fill] = l;

/*increment index*/

fill++;

/* if unvisited, mark first occurrence */

            if (f_occur[node.data] == -1)
                f_occur[node.data] = fill - 1;

/* tour left subtree if exists, and remark euler
               and level arrays for parent on return */

            if (node.left != null)
            {
                eulerTour(node.left, l + 1);
                euler[fill] = node.data;
                level[fill] = l;
                fill++;
            }

/* tour right subtree if exists, and remark euler
               and level arrays for parent on return */

            if (node.right != null)
            {
                eulerTour(node.right, l + 1);
                euler[fill] = node.data;
                level[fill] = l;
                fill++;
            }
        }
    }

/*    returns LCA of node n1 and n2 assuming they are present in tree*/

    int findLCA(Node node, int u, int v)
    {

/* Mark all nodes unvisited.  Note that the size of
           firstOccurrence is 1 as node values which vary from
           1 to 9 are used as indexes */

        Arrays.fill(f_occur, -1);

/* To start filling euler and level arrays from index 0 */

        fill = 0;

/* Start Euler tour with root node on level 0 */

        eulerTour(root, 0);

/* construct segment tree on level array */

        sc.st = constructST(level, 2 * v - 1);

/* If v before u in Euler tour.  For RMQ to work, first
         parameter 'u' must be smaller than second 'v' */

        if (f_occur[u] > f_occur[v])
            u = swap(u, u = v);

/*        Starting and ending indexes of query range*/

        int qs = f_occur[u];
        int qe = f_occur[v];

/*        query for index of LCA in tour*/

        int index = RMQ(sc, 2 * v - 1, qs, qe);

/* return LCA node */

        return euler[index];
    }

/*    Driver program to test above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create the Binary Tree as shown in the diagram.*/

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        tree.root.left.right.left = new Node(8);
        tree.root.left.right.right = new Node(9);
        int u = 4, v = 9;
        System.out.println("The LCA of node " + u + " and " + v + " is "
                + tree.findLCA(tree.root, u, v));
    }
}

/* Java program to find maximum difference between node
   and its ancestor */

/*A binary tree node has key, pointer to left
and right child*/

class Node
{
    int key;
    Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}

/* Class Res created to implement pass by reference
   of 'res' variable */

class Res
{
    int r = Integer.MIN_VALUE;
}
public class BinaryTree
{
    Node root;

/* Recursive function to calculate maximum ancestor-node
       difference in  binary tree. It updates value at 'res'
       to store the result.  The returned value of this function
       is minimum value in subtree rooted with 't' */

    int maxDiffUtil(Node t, Res res)
    {

/* Returning Maximum int value if node is not
           there (one child case)  */

        if (t == null)
            return Integer.MAX_VALUE;

/* If leaf node then just return node's value  */

        if (t.left == null && t.right == null)
            return t.key;

/* Recursively calling left and right subtree
           for minimum value  */

        int val = Math.min(maxDiffUtil(t.left, res),
                maxDiffUtil(t.right, res));

/* Updating res if (node value - minimum value
           from subtree) is bigger than res  */

        res.r = Math.max(res.r, t.key - val);

/* Returning minimum value got so far */

        return Math.min(val, t.key);
    }

/* This function mainly calls maxDiffUtil() */

    int maxDiff(Node root)
    {

/*        Initialising result with minimum int value*/

        Res res = new Res();
        maxDiffUtil(root, res);
        return res.r;
    }

/* Helper function to print inorder traversal of
       binary tree   */

    void inorder(Node root)
    {
        if (root != null)
        {
            inorder(root.left);
            System.out.print(root.key + "");
            inorder(root.right);
        }
    }

/*    Driver program to test the above functions*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Making above given diagram's binary tree*/

        tree.root = new Node(8);
        tree.root.left = new Node(3);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(6);
        tree.root.left.right.left = new Node(4);
        tree.root.left.right.right = new Node(7);
        tree.root.right = new Node(10);
        tree.root.right.right = new Node(14);
        tree.root.right.right.left = new Node(13);
        System.out.println("Maximum difference between a node and"
                + " its ancestor is : " + tree.maxDiff(tree.root));
    }
}

/*Java implementation to print the path common to the 
two paths from the root to the two given nodes*/

import java.util.ArrayList;
public class PrintCommonPath {

/*    Initialize n1 and n2 as not visited*/

    static boolean v1 = false, v2 = false;

/* Class containing left and right child of current
 node and key value*/

class Node
{
    int data;
    Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*    This function returns pointer to LCA of two given
    values n1 and n2. This function assumes that n1 and
    n2 are present in Binary Tree*/

    static Node findLCAUtil(Node node, int n1, int n2)
    {

/*        Base case*/

        if (node == null)
            return null;

/*        Store result in temp, in case of key match so that we can search for other key also.*/

        Node temp=null;

/*        If either n1 or n2 matches with root's key, report the presence
        by setting v1 or v2 as true and return root (Note that if a key
        is ancestor of other, then the ancestor key becomes LCA)*/

        if (node.data == n1)
        {
            v1 = true;
            temp = node;
        }
        if (node.data == n2)
        {
            v2 = true;
            temp = node;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCAUtil(node.left, n1, n2);
        Node right_lca = findLCAUtil(node.right, n1, n2);
        if (temp != null)
            return temp;

/*        If both of the above calls return Non-NULL, then one key
        is present in once subtree and other is present in other,
        So this node is the LCA*/

        if (left_lca != null && right_lca != null)
            return node;

/*        Otherwise check if left subtree or right subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    Returns true if key k is present in tree rooted with root*/

    static boolean find(Node root, int k)
    {

/*        Base Case*/

        if (root == null)
            return false;

/*        If key k is present at root, or in left subtree 
        or right subtree, return true*/

        if (root.data == k || find(root.left, k) ||  find(root.right, k))
            return true;

/*        Else return false*/

        return false;
    }

/*    This function returns LCA of n1 and n2 only if both n1 and n2 
    are present in tree, otherwise returns null*/

    static Node findLCA(Node root, int n1, int n2)
    {

/*        Find lca of n1 and n2*/

        Node lca = findLCAUtil(root, n1, n2);

/*        Return LCA only if both n1 and n2 are present in tree*/

        if (v1 && v2 || v1 && find(lca, n2) || v2 && find(lca, n1))
            return lca;

/*        Else return null*/

        return null;
    }

/*    function returns true if 
    there is a path from root to 
    the given node. It also populates 
    'arr' with the given path*/

    static boolean hasPath(Node root, ArrayList<Integer> arr, int x)
    {

/*        if root is null
        there is no path*/

        if (root==null)
            return false;

/*        push the node's value in 'arr'*/

        arr.add(root.data);

/*        if it is the required node
        return true*/

        if (root.data == x)    
            return true;

/*        else check whether there    the required node lies in the
        left subtree or right subtree of the current node*/

        if (hasPath(root.left, arr, x) ||
            hasPath(root.right, arr, x))
            return true;

/*        required node does not lie either in the 
        left or right subtree of the current node
        Thus, remove current node's value from 'arr'
        and then return false;    */

        arr.remove(arr.size()-1);
        return false;            
    }

/*    function to print the path common
    to the two paths from the root 
    to the two given nodes if the nodes 
    lie in the binary tree*/

    static void printCommonPath(Node root, int n1, int n2)
    {

/*        ArrayList to store the common path*/

        ArrayList<Integer> arr=new ArrayList<>();

/*        LCA of node n1 and n2*/

        Node lca = findLCA(root, n1, n2);

/*        if LCA of both n1 and n2 exists*/

        if (lca!=null)
        {

/*            then print the path from root to
            LCA node*/

            if (hasPath(root, arr, lca.data))
            {
                for (int i=0; i<arr.size()-1; i++)    
                    System.out.print(arr.get(i)+"->");
                    System.out.print(arr.get(arr.size() - 1));    
            }    
        }

/*        LCA is not present in the binary tree 
        either n1 or n2 or both are not present*/

        else
            System.out.print("No Common Path");
    }

/*    Driver code*/

    public static void main(String args[])
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.left = new Node(6);
        root.right.right = new Node(7);
        root.left.right.left = new Node(8);
        root.right.left.right = new Node(9);
        int n1 = 4, n2 = 8;
        printCommonPath(root, n1, n2);
        }
}

/*Java program to calculate Kth ancestor of given node */

class Solution
{

/*A Binary Tree Node*/

static class Node
{
    int data;
    Node left, right;
};

/*temporary node to keep track of Node returned
from previous recursive call during backtrack*/

static Node temp = null;
static int k;

/*recursive function to calculate Kth ancestor*/

static Node kthAncestorDFS(Node root, int node )
{

/*    Base case*/

    if (root == null)
        return null;
    if (root.data == node||
    (temp = kthAncestorDFS(root.left,node)) != null ||
    (temp = kthAncestorDFS(root.right,node)) != null)
    { 
        if (k > 0)     
            k--;
        else if (k == 0)
        {

/*            print the kth ancestor*/

            System.out.print("Kth ancestor is: "+root.data);

/*            return null to stop further backtracking*/

            return null;
        }

/*        return current node to previous call*/

        return root;
    }
    return null;
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver code*/

public static void main(String args[])
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    k = 2;
    int node = 5;

/*    print kth ancestor of given node*/

    Node parent = kthAncestorDFS(root,node);

/*    check if parent is not null, it means
    there is no Kth ancestor of the node*/

    if (parent != null)
        System.out.println("-1");
}
}

/*Java program to demonstrate Succinct
Tree Encoding and decoding*/

import java.util.*;
class GFG{

/*A Binary Tree Node*/

static class Node
{
    int key;
    Node left, right;
};

/*Utility function to create new Node*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.key  = key;
    temp.left  = temp.right = null;
    return (temp);
}
static Vector<Boolean> struc;
static Vector<Integer> data;
static Node root;

/*This function fills lists 'struc' and
'data'. 'struc' list stores structure
information. 'data' list stores tree data*/

static void EncodeSuccinct(Node root)
{

/*    If root is null, put 0 in
    structure array and return*/

    if (root == null)
    {
        struc.add(false);
        return;
    }

/*    Else place 1 in structure array,
    key in 'data' array and recur
    for left and right children*/

    struc.add(true);
    data.add(root.key);
    EncodeSuccinct(root.left);
    EncodeSuccinct(root.right);
}

/*Constructs tree from 'struc' and 'data'*/

static Node DecodeSuccinct()
{
    if (struc.size() <= 0)
        return null;

/*    Remove one item from structure list*/

    boolean b = struc.get(0);
    struc.remove(0);

/*    If removed bit is 1,*/

    if (b == true)
    {

/*        Remove an item from data list*/

        int key = data.get(0);
        data.remove(0);

/*        Create a tree node with the
        removed data*/

        Node root = newNode(key);

/*        And recur to create left and
        right subtrees*/

        root.left = DecodeSuccinct();
        root.right = DecodeSuccinct();
        return root;
    }
    return null;
}

/*A utility function to print tree*/

static void preorder(Node root)
{
    if (root != null)
    {
        System.out.print("key: "+ root.key);
        if (root.left != null)
            System.out.print(" | left child: " + 
                             root.left.key);
        if (root.right != null)
            System.out.print(" | right child: " + 
                             root.right.key);
        System.out.println();
        preorder(root.left);
        preorder(root.right);
    }
}

/*Driver code*/

public static void main(String[] args)
{

/*    Let us conthe Tree shown in
    the above figure*/

    Node root = newNode(10);
    root.left = newNode(20);
    root.right = newNode(30);
    root.left.left = newNode(40);
    root.left.right = newNode(50);
    root.right.right = newNode(70);
    System.out.print("Given Tree\n");
    preorder(root);
    struc = new Vector<>();
    data = new Vector<>();
    EncodeSuccinct(root);
    System.out.print("\nEncoded Tree\n");
    System.out.print("Structure List\n");

/*Structure iterator*/

    for(boolean  si : struc)
    {
        if (si == true)
            System.out.print(1 + " ");
        else
            System.out.print(0 + " ");
    }
    System.out.print("\nData List\n");

/*Data iterator*/

    for(int di : data)
        System.out.print(di + " ");
    Node newroot = DecodeSuccinct();
    System.out.print("\n\nPreorder traversal" +
                     "of decoded tree\n");
    preorder(newroot);
}
}

/*Java program to create a custom tree from a given set of links.
The main class that represents tree and has main method*/

public class Tree {
    private TreeNode root;

/* Returns an array of trees from links input. Links are assumed to 
       be Strings of the form "<s> <e>" where <s> and <e> are starting
       and ending points for the link. The returned array is of size 26
       and has non-null values at indexes corresponding to roots of trees
       in output */

    public Tree[] buildFromLinks(String [] links) {

/*        Create two arrays for nodes and forest*/

        TreeNode[] nodes = new TreeNode[26];  
        Tree[] forest = new Tree[26];

/*        Process each link */

        for (String link : links) {

/*            Find the two ends of current link*/

            String[] ends = link.split(" ");

/*Start node*/

int start = (int) (ends[0].charAt(0) - 'a');

/*End node             */

int end   = (int) (ends[1].charAt(0) - 'a');

/*            If start of link not seen before, add it two both arrays*/

            if (nodes[start] == null) 
            {                
                nodes[start] = new TreeNode((char) (start + 'a'));

/*                Note that it may be removed later when this character is
                last character of a link. For example, let we first see
                a--->b, then c--->a.  We first add 'a' to array of trees
                and when we see link c--->a, we remove it from trees array.*/

                forest[start] = new Tree(nodes[start]);                                            
            }

/*            If end of link is not seen before, add it to the nodes array*/

            if (nodes[end] == null)                             
                nodes[end] = new TreeNode((char) (end + 'a'));

/*            If end of link is seen before, remove it from forest if 
            it exists there.*/

            else forest[end] = null;

/*            Establish Parent-Child Relationship between Start and End*/

            nodes[start].addChild(nodes[end], end);
        }        
        return forest;
    }

/*    Constructor */

    public Tree(TreeNode root) { this.root = root;  }  
    public static void printForest(String[] links)
    {
        Tree t = new Tree(new TreeNode('\0'));
        for (Tree t1 : t.buildFromLinks(links)) {
           if (t1 != null)  
           {  
              t1.root.printTreeIdented("");
              System.out.println("");
           }  
        }
    }

/*    Driver method to test*/

    public static void main(String[] args) {
        String [] links1 = {"a b", "b c", "b d", "a e"};
        System.out.println("------------ Forest 1 ----------------");
        printForest(links1);       
        String [] links2 = {"a b", "a g", "b c", "c d", "d e", "c f",
                            "z y", "y x", "x w"};
        System.out.println("------------ Forest 2 ----------------");
        printForest(links2);      
    }
}

/*Class to represent a tree node*/

class TreeNode {    
    TreeNode []children;
    char c;

/*    Adds a child 'n' to this node*/

    public void addChild(TreeNode n, int index) { this.children[index] = n;}

/*    Constructor*/

    public TreeNode(char c) { this.c = c;  this.children = new TreeNode[26];}

/*    Recursive method to print indented tree rooted with this node.*/

    public void printTreeIdented(String indent) {        
            System.out.println(indent + "-->" + c);
            for (TreeNode child : children) {
              if (child != null)  
                child.printTreeIdented(indent + "   |");
            }        
    }    
}

/*Java code to delete all leaves with given 
value. */

class GfG {

/*A binary tree node */

static class Node { 
    int data; 
    Node left, right; 
}

/*A utility function to allocate a new node */

static Node newNode(int data) 
{ 
    Node newNode = new Node(); 
    newNode.data = data; 
    newNode.left = null;
    newNode.right = null; 
    return (newNode); 
}

/*deleteleaves()*/

static Node deleteLeaves(Node root, int x) 
{ 
    if (root == null) 
        return null; 
    root.left = deleteLeaves(root.left, x); 
    root.right = deleteLeaves(root.right, x); 
    if (root.data == x && root.left == null && root.right == null) { 
        return null; 
    } 
    return root; 
}

/*inorder()*/

static void inorder(Node root) 
{ 
    if (root == null) 
        return; 
    inorder(root.left); 
    System.out.print(root.data + " "); 
    inorder(root.right); 
}

/*Driver program */

public static void main(String[] args) 
{ 
    Node root = newNode(10); 
    root.left = newNode(3); 
    root.right = newNode(10); 
    root.left.left = newNode(3); 
    root.left.right = newNode(1); 
    root.right.right = newNode(3); 
    root.right.right.left = newNode(3); 
    root.right.right.right = newNode(3); 
    deleteLeaves(root, 3); 
    System.out.print("Inorder traversal after deletion : "); 
    inorder(root); 
}
}

/*Java programn to calculate
Size of a tree*/

import java.util.LinkedList;
import java.util.Queue;

/*Node Structure*/

class Node
{
    int data;
    Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*return size of tree*/

class BinaryTree
{
    Node root;
    public int size()
    {

/*    if tree is empty it will
    return 0*/

        if (root == null)
            return 0;

/*        Using level order Traversal.*/

        Queue<Node> q = new LinkedList<Node>();
        q.offer(root);
        int count = 1; 
        while (!q.isEmpty())
        {
            Node tmp = q.poll();

/*            when the queue is empty:
            the poll() method returns null.*/

            if (tmp != null)
            {
                if (tmp.left != null)
                {

/*                    Increment count*/

                    count++;

/*                    Enqueue left child */

                    q.offer(tmp.left);
                }
                if (tmp.right != null)
                {

/*                    Increment count*/

                    count++;

/*                    Enqueue right child */

                    q.offer(tmp.right);
                }
            }
        }
        return count;
    }

/*    Driver code*/

    public static void main(String args[])
    {

/* creating a binary tree and entering 
          the nodes */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        System.out.println("The size of binary tree" + 
                         " is : " + tree.size());
    }
}

/*Java program to find height of tree*/

/*A binary tree node*/

class Node
{
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree
{
     Node root;

/* Compute the "maxDepth" of a tree -- the number of
       nodes along the longest path from the root node
       down to the farthest leaf node.*/

    int maxDepth(Node node)
    {
        if (node == null)
            return 0;
        else
        {

/* compute the depth of each subtree */

            int lDepth = maxDepth(node.left);
            int rDepth = maxDepth(node.right);

/* use the larger one */

            if (lDepth > rDepth)
                return (lDepth + 1);
             else
                return (rDepth + 1);
        }
    }

/* Driver program to test above functions */

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        System.out.println("Height of tree is : " +
                                      tree.maxDepth(tree.root));
    }
}

/* Java Program to find height of the tree considering 
only even level leaves. */

class GfG {

/* A binary tree node has data, pointer to 
left child and a pointer to right child */

static class Node { 
    int data; 
    Node left; 
 Node right; 
}
static int heightOfTreeUtil(Node root, boolean isEven) 
{

/*    Base Case */

    if (root == null) 
        return 0; 
    if (root.left == null && root.right == null) { 
        if (isEven == true) 
            return 1; 
        else
            return 0; 
    }

/*left stores the result of left subtree, 
    and right stores the result of right subtree*/

    int left = heightOfTreeUtil(root.left, !isEven); 
    int right = heightOfTreeUtil(root.right, !isEven);

/*If both left and right returns 0, it means 
    there is no valid path till leaf node*/

    if (left == 0 && right == 0) 
        return 0; 
    return (1 + Math.max(left, right)); 
}

/* Helper function that allocates a new node with the 
given data and NULL left and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return (node); 
} 
static int heightOfTree(Node root) 
{ 
    return heightOfTreeUtil(root, false); 
}

/* Driver program to test above functions*/

public static void main(String[] args) 
{

/*    Let us create binary tree shown in above diagram */

    Node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(3); 
    root.left.left = newNode(4); 
    root.left.right = newNode(5); 
    root.left.right.left = newNode(6); 
    System.out.println("Height of tree is " + heightOfTree(root)); 
}
}

/*Java program to find height using parent array*/

class BinaryTree {

/*    This function fills depth of i'th element in parent[].  The depth is
    filled in depth[i].*/

    void fillDepth(int parent[], int i, int depth[]) {

/*        If depth[i] is already filled*/

        if (depth[i] != 0) {
            return;
        }

/*        If node at index i is root*/

        if (parent[i] == -1) {
            depth[i] = 1;
            return;
        }

/*        If depth of parent is not evaluated before, then evaluate
        depth of parent first*/

        if (depth[parent[i]] == 0) {
            fillDepth(parent, parent[i], depth);
        }

/*        Depth of this node is depth of parent plus 1*/

        depth[i] = depth[parent[i]] + 1;
    }

/*    This function returns height of binary tree represented by
    parent array*/

    int findHeight(int parent[], int n) {

/*        Create an array to store depth of all nodes/ and
        initialize depth of every node as 0 (an invalid
        value). Depth of root is 1*/

        int depth[] = new int[n];
        for (int i = 0; i < n; i++) {
            depth[i] = 0;
        }

/*        fill depth of all nodes*/

        for (int i = 0; i < n; i++) {
            fillDepth(parent, i, depth);
        }

/*        The height of binary tree is maximum of all depths.
        Find the maximum value in depth[] and assign it to ht.*/

        int ht = depth[0];
        for (int i = 1; i < n; i++) {
            if (ht < depth[i]) {
                ht = depth[i];
            }
        }
        return ht;
    }

/*    Driver program to test above functions*/

    public static void main(String args[]) {
        BinaryTree tree = new BinaryTree();

/*        int parent[] = {1, 5, 5, 2, 2, -1, 3};*/

        int parent[] = new int[]{-1, 0, 0, 1, 1, 3, 5};
        int n = parent.length;
        System.out.println("Height is  " + tree.findHeight(parent, n));
    }
}

/*Recursive Java program to find the diameter of a
Binary Tree*/

/*Class containing left and right child of current
node and key value*/

class Node {
    int data;
    Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*A utility class to pass heigh object*/

class Height {
    int h;
}

/*Class to print the Diameter*/

class BinaryTree {
    Node root;

/*    define height =0 globally and  call
    diameterOpt(root,height) from main*/

    int diameterOpt(Node root, Height height)
    {

/*        lh --> Height of left subtree
        rh --> Height of right subtree*/

        Height lh = new Height(), rh = new Height();

/*    base condition- when binary tree is empty*/

        if (root == null) {
            height.h = 0;

/*diameter is also 0*/

return 0; 
        }

/*
        ldiameter  --> diameter of left subtree
        rdiameter  --> Diameter of right subtree
        Get the heights of left and right subtrees in lh and rh.
        And store the returned values in ldiameter and ldiameter*/

          int ldiameter = diameterOpt(root.left, lh);
        int rdiameter = diameterOpt(root.right, rh);

/*        Height of current node is max of heights of left
        and right subtrees plus 1*/

        height.h = Math.max(lh.h, rh.h) + 1;
        return Math.max(lh.h + rh.h + 1,
                        Math.max(ldiameter, rdiameter));
    }

/*    A wrapper over diameter(Node root)*/

    int diameter()
    {
        Height height = new Height();
        return diameterOpt(root, height);
    }

/*    The function Compute the "height" of a tree. Height
    is
      the number f nodes along the longest path from the
      root node down to the farthest leaf node.*/

    static int height(Node node)
    {

/*        base case tree is empty*/

        if (node == null)
            return 0;

/*        If tree is not empty then height = 1 + max of
        left height and right heights*/

        return (1
                + Math.max(height(node.left),
                           height(node.right)));
    }

/*    Driver Code*/

    public static void main(String args[])
    {

/*        creating a binary tree and entering the nodes*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);

/*        Function Call*/

        System.out.println(
            "The diameter of given binary tree is : "
            + tree.diameter());
    }
}

/*Java program to construct tree for given count
width and height.*/

class GfG {

/*Function to construct the tree*/

static void constructTree(int n, int d, int h)
{
    if (d == 1) {

/*        Special case when d == 2, only one edge*/

        if (n == 2 && h == 1) {
            System.out.println("1 2");
            return;
        }

/*Tree is not possible*/

System.out.println("-1"); 
        return;
    }
    if (d > 2 * h) {
        System.out.println("-1");
        return;
    }

/*    Satisfy the height condition by add
    edges up to h*/

    for (int i = 1; i <= h; i++)    
        System.out.println(i + " " + (i + 1));
    if (d > h) {

/*        Add d - h edges from 1 to
        satisfy diameter condition*/

        System.out.println("1" + " " + (h + 2));
        for (int i = h + 2; i <= d; i++) {
            System.out.println(i + " " + (i + 1));
        }
    }

/*    Remaining edges at vertex 1 or 2(d == h)*/

    for (int i = d + 1; i < n; i++)
    {
        int k = 1;
        if (d == h)
            k = 2;
        System.out.println(k + " " + (i + 1));
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int n = 5, d = 3, h = 2;
    constructTree(n, d, h);
}
}

/*Java program to find deepest right leaf
node of binary tree*/

import java.util.*;
class GFG
{

/*tree node*/

static class Node 
{
    int data;
    Node left, right;
};

/*returns a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*return the deepest right leaf node
of binary tree*/

static Node getDeepestRightLeafNode(Node root)
{
    if (root == null)
        return null;

/*    create a queue for level order traversal*/

    Queue<Node> q = new LinkedList<>();
    q.add(root);
    Node result = null;

/*    traverse until the queue is empty*/

    while (!q.isEmpty()) 
    {
        Node temp = q.peek();
        q.poll();
        if (temp.left != null)
        {
            q.add(temp.left);
        }

/*        Since we go level by level, the last 
        stored right leaf node is deepest one */

        if (temp.right != null)
        {
            q.add(temp.right);
            if (temp.right.left == null && temp.right.right == null)
                result = temp.right;
        }
    }
    return result;
}

/*Driver code*/

public static void main(String[] args) 
{

/*    construct a tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.right = newNode(4);
    root.right.left = newNode(5);
    root.right.right = newNode(6);
    root.right.left.right = newNode(7);
    root.right.right.right = newNode(8);
    root.right.left.right.left = newNode(9);
    root.right.right.right.right = newNode(10);
    Node result = getDeepestRightLeafNode(root);
    if (result != null)
        System.out.println("Deepest Right Leaf Node :: "
            + result.data);
    else
        System.out.println("No result, right leaf not found\n");
    }
}

/*Java program to find depth of the deepest
odd level leaf node of binary tree*/

import java.util.*;
class GFG 
{

/*tree node*/

static class Node 
{
    int data;
    Node left, right;
};

/*returns a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*return max odd number depth of leaf node*/

static int maxOddLevelDepth(Node root)
{
    if (root == null)
        return 0;

/*    create a queue for level order 
    traversal*/

    Queue<Node> q = new LinkedList<>();
    q.add(root);
    int result = Integer.MAX_VALUE;
    int level = 0;

/*    traverse until the queue is empty*/

    while (!q.isEmpty()) 
    {
        int size = q.size();
        level += 1;

/*        traverse for complete level*/

        while(size > 0)
        {
            Node temp = q.peek();
            q.remove();

/*            check if the node is leaf node and 
            level is odd if level is odd,
            then update result*/

            if(temp.left == null && 
               temp.right == null && (level % 2 != 0))
            {
                result = level;
            }

/*            check for left child*/

            if (temp.left != null) 
            {
                q.add(temp.left);
            }

/*            check for right child*/

            if (temp.right != null)
            {
                q.add(temp.right);
            }
            size -= 1;
        } 
    }
    return result;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    construct a tree*/

    Node root = newNode(1);
