        tree.root.right.left.right = new Node(7);
        tree.root.right.right.right = new Node(8);
        tree.root.right.left.right.left = new Node(9);
        tree.root.right.right.right.right = new Node(10);
        tree.deepestLeftLeaf(tree.root);
        if (tree.result != null)
            System.out.println("The deepest left child"+
                               " is " + tree.result.data);
        else
            System.out.println("There is no left leaf in"+
                               " the given tree");
    }
}

/*Java program to find minimum depth
of a given Binary Tree*/

import java.util.*;
class GFG
{

/*A binary Tree node*/

static class Node
{
    int data;
    Node left, right;
}

/*A queue item (Stores pointer to
node and an integer)*/

static class qItem
{
    Node node;
    int depth;
    public qItem(Node node, int depth)
    {
        this.node = node;
        this.depth = depth;
    }
}

/*Iterative method to find
minimum depth of Binary Tree*/

static int minDepth(Node root)
{

/*    Corner Case*/

    if (root == null)
        return 0;

/*    Create an empty queue for level order traversal*/

    Queue<qItem> q = new LinkedList<>();

/*    Enqueue Root and initialize depth as 1*/

    qItem qi = new qItem(root, 1);
    q.add(qi);

/*    Do level order traversal*/

    while (q.isEmpty() == false)
    {

/*        Remove the front queue item*/

        qi = q.peek();
        q.remove();

/*        Get details of the remove item*/

        Node node = qi.node;
        int depth = qi.depth;

/*        If this is the first leaf node seen so far
        Then return its depth as answer*/

        if (node.left == null && node.right == null)
            return depth;

/*        If left subtree is not null,
        add it to queue*/

        if (node.left != null)
        {
            qi.node = node.left;
            qi.depth = depth + 1;
            q.add(qi);
        }

/*        If right subtree is not null,
        add it to queue*/

        if (node.right != null)
        {
            qi.node = node.right;
            qi.depth = depth + 1;
            q.add(qi);
        }
    }
    return 0;
}

/*Utility function to create a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void main(String[] args)
{

/*    Let us create binary tree shown in above diagram*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    System.out.println(minDepth(root));
}
}

/*Java program to calculate width of binary tree*/

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

class Node {
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree {
    Node root;

/* Function to get the maximum width of a binary tree*/

    int getMaxWidth(Node node)
    {
        int maxWidth = 0;
        int width;
        int h = height(node);
        int i;

/* Get width of each level and compare
           the width with maximum width so far */

        for (i = 1; i <= h; i++) {
            width = getWidth(node, i);
            if (width > maxWidth)
                maxWidth = width;
        }
        return maxWidth;
    }

/* Get width of a given level */

    int getWidth(Node node, int level)
    {
        if (node == null)
            return 0;
        if (level == 1)
            return 1;
        else if (level > 1)
            return getWidth(node.left, level - 1)
                + getWidth(node.right, level - 1);
        return 0;
    }

/* Compute the "height" of a tree -- the number of
     nodes along the longest path from the root node
     down to the farthest leaf node.*/

    int height(Node node)
    {
        if (node == null)
            return 0;
        else {

/* compute the height of each subtree */

            int lHeight = height(node.left);
            int rHeight = height(node.right);

/* use the larger one */

            return (lHeight > rHeight) ? (lHeight + 1)
                                       : (rHeight + 1);
        }
    }

/* Driver code */

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/*
        Constructed binary tree is:
              1
            /  \
           2    3
         /  \    \
        4   5     8
                 /  \
                6   7
         */

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.right = new Node(8);
        tree.root.right.right.left = new Node(6);
        tree.root.right.right.right = new Node(7);

/*        Function call*/

        System.out.println("Maximum width is "
                           + tree.getMaxWidth(tree.root));
    }
}

/*Java program to calculate maximum width
of a binary tree using queue*/

import java.util.LinkedList;
import java.util.Queue;
public class maxwidthusingqueue 
{

/* A binary tree node has data, pointer to
       left child and a pointer to right child */

    static class node 
    {
        int data;
        node left, right;
        public node(int data) { this.data = data; }
    }

/*    Function to find the maximum width of
    the tree using level order traversal*/

    static int maxwidth(node root)
    {

/*        Base case*/

        if (root == null)
            return 0;

/*        Initialize result*/

        int maxwidth = 0;

/*        Do Level order traversal keeping
        track of number of nodes at every level*/

        Queue<node> q = new LinkedList<>();
        q.add(root);
        while (!q.isEmpty()) 
        {

/*            Get the size of queue when the level order
            traversal for one level finishes*/

            int count = q.size();

/*            Update the maximum node count value*/

            maxwidth = Math.max(maxwidth, count);

/*            Iterate for all the nodes in
            the queue currently*/

            while (count-- > 0) {

/*                Dequeue an node from queue*/

                node temp = q.remove();

/*                Enqueue left and right children
                of dequeued node*/

                if (temp.left != null)
                {
                    q.add(temp.left);
                }
                if (temp.right != null)
                {
                    q.add(temp.right);
                }
            }
        }
        return maxwidth;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        node root = new node(1);
        root.left = new node(2);
        root.right = new node(3);
        root.left.left = new node(4);
        root.left.right = new node(5);
        root.right.right = new node(8);
        root.right.right.left = new node(6);
        root.right.right.right = new node(7);

/*   Constructed Binary tree is:
        1
      /   \
    2      3
  /  \      \
 4    5      8
           /   \
          6     7    */

/*        Function call*/

        System.out.println("Maximum width = "
                           + maxwidth(root));
    }
}

/*Java program to calculate width of binary tree*/

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

class Node {
    int data;
    Node left, right;
    Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree {
    Node root;

/* Function to get the maximum width of a binary tree*/

    int getMaxWidth(Node node)
    {
        int width;
        int h = height(node);

/*        Create an array that will store count of nodes at
        each level*/

        int count[] = new int[10];
        int level = 0;

/*        Fill the count array using preorder traversal*/

        getMaxWidthRecur(node, count, level);

/*        Return the maximum value from count array*/

        return getMax(count, h);
    }

/*    A function that fills count array with count of nodes
    at every level of given binary tree*/

    void getMaxWidthRecur(Node node, int count[], int level)
    {
        if (node != null) {
            count[level]++;
            getMaxWidthRecur(node.left, count, level + 1);
            getMaxWidthRecur(node.right, count, level + 1);
        }
    }

/* Compute the "height" of a tree -- the number of
     nodes along the longest path from the root node
     down to the farthest leaf node.*/

    int height(Node node)
    {
        if (node == null)
            return 0;
        else {

/* compute the height of each subtree */

            int lHeight = height(node.left);
            int rHeight = height(node.right);

/* use the larger one */

            return (lHeight > rHeight) ? (lHeight + 1)
                                       : (rHeight + 1);
        }
    }

/*    Return the maximum value from count array*/

    int getMax(int arr[], int n)
    {
        int max = arr[0];
        int i;
        for (i = 0; i < n; i++) {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

