/*returns distance between first and last node every time
 * last node moves forwars*/

static int distance(Node first, Node last)
{

/*counts no of nodes between first and last*/

    int counter = 0;
    Node curr;
    curr = first;
    while (curr != last)
    {
        counter += 1;
        curr = curr.next;
    }
    return counter + 1;
}

/*Function to detect first node of loop
in a linked list that may contain loop*/

static boolean detectLoop(Node head)
{

/*    Create a temporary node*/

    Node temp = new Node();
    Node first, last;

/*first always points to head*/

    first = head;

/*last pointer initially points to head*/

    last = head;

/*current_length stores no of nodes between current
     * position of first and last*/

    int current_length = 0;

/*current_length stores no of nodes between previous
     * position of first and last*/

    int prev_length = -1;
    while (current_length > prev_length && last != null)
    {

/*        set prev_length to current length then update the
        current length*/

          prev_length = current_length;

/*        distance is calculated*/

        current_length = distance(first, last);

/*        last node points the next node*/

        last = last.next;
    }
    if (last == null)
    {
        return false;
    }
    else
    {
        return true;
    }
}

/* Driver program to test above function*/

public static void main(String[] args)
{
    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);

/* Create a loop for testing(5 is pointing to 3) */

    head.next.next.next.next.next = head.next.next;
    boolean found = detectLoop(head);
    if (found)
        System.out.print("Loop Found");
    else
        System.out.print("No Loop Found");
}
}

/* Java program to check if linked list is palindrome */

class LinkedList {

/* Linked list Node*/

    class Node {
        char data;
        Node next;
        Node(char d)
        {
            data = d;
            next = null;
        }
    }

/*head of list*/

Node head; 
    Node slow_ptr, fast_ptr, second_half;

/* Function to check if given linked list is
       palindrome or not */

    boolean isPalindrome(Node head)
    {
        slow_ptr = head;
        fast_ptr = head;
        Node prev_of_slow_ptr = head;

/*To handle odd size list*/

Node midnode = null;

/*initialize result*/

boolean res = true; 
        if (head != null && head.next != null) {

/* Get the middle of the list. Move slow_ptr by 1
               and fast_ptrr by 2, slow_ptr will have the middle
               node */

            while (fast_ptr != null && fast_ptr.next != null) {
                fast_ptr = fast_ptr.next.next;

/*We need previous of the slow_ptr for
                  linked lists  with odd elements */

                prev_of_slow_ptr = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/* fast_ptr would become NULL when there are even elements
               in the list and not NULL for odd elements. We need to skip 
               the middle node for odd case and store it somewhere so that
               we can restore the original list */

            if (fast_ptr != null) {
                midnode = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/*            Now reverse the second half and compare it with first half*/

            second_half = slow_ptr;

/*NULL terminate first half*/

prev_of_slow_ptr.next = null;

/*Reverse the second half*/

reverse();

/*compare*/

res = compareLists(head, second_half);

/* Construct the original list back */

/*Reverse the second half again*/

reverse(); 
            if (midnode != null) {

/*                If there was a mid node (odd size case) which
                was not part of either first half or second half.*/

                prev_of_slow_ptr.next = midnode;
                midnode.next = second_half;
            }
            else
                prev_of_slow_ptr.next = second_half;
        }
        return res;
    }

/* Function to reverse the linked list  Note that this
       function may change the head */

    void reverse()
    {
        Node prev = null;
        Node current = second_half;
        Node next;
        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        second_half = prev;
    }

/* Function to check if two input lists have same data*/

    boolean compareLists(Node head1, Node head2)
    {
        Node temp1 = head1;
        Node temp2 = head2;
        while (temp1 != null && temp2 != null) {
            if (temp1.data == temp2.data) {
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
            else
                return false;
        }

/* Both are empty reurn 1*/

        if (temp1 == null && temp2 == null)
            return true;

/* Will reach here when one is NULL
           and other is not */

        return false;
    }

/* Push a node to linked list. Note that this function
       changes the head */

    public void push(char new_data)
    {

/* Allocate the Node &
           Put in the data */

        Node new_node = new Node(new_data);

/* link the old list off the new one */

        new_node.next = head;

/* Move the head to point to new Node */

        head = new_node;
    }

/*    A utility function to print a given linked list*/

    void printList(Node ptr)
    {
        while (ptr != null) {
            System.out.print(ptr.data + "->");
            ptr = ptr.next;
        }
        System.out.println("NULL");
    }

/* Driver program to test the above functions */

    public static void main(String[] args)
    {

/* Start with the empty list */

        LinkedList llist = new LinkedList();
        char str[] = { 'a', 'b', 'a', 'c', 'a', 'b', 'a' };
        String string = new String(str);
        for (int i = 0; i < 7; i++) {
            llist.push(str[i]);
            llist.printList(llist.head);
            if (llist.isPalindrome(llist.head) != false) {
                System.out.println("Is Palindrome");
                System.out.println("");
            }
            else {
                System.out.println("Not Palindrome");
                System.out.println("");
            }
        }
    }
}

/* Recursive function to pairwise swap elements
   of a linked list */

static void pairWiseSwap(node head)
{

/* There must be at-least two nodes in the list */

    if (head != null && head.next != null) {

/* Swap the node's data with data of next node */

        swap(head.data, head.next.data);

/* Call pairWiseSwap() for rest of the list */

        pairWiseSwap(head.next.next);
    }
}

