/* Given a node as prev_node, insert a new node after the given node */

public void InsertAfter(Node prev_Node, int new_data)
{

/*1. check if the given prev_node is NULL */

    if (prev_Node == null) {
        System.out.println("The given previous node cannot be NULL ");
        return;
    }

/* 2. allocate node
    * 3. put in the data */

    Node new_node = new Node(new_data);

/* 4. Make next of new node as next of prev_node */

    new_node.next = prev_Node.next;

/* 5. Make the next of prev_node as new_node */

    prev_Node.next = new_node;

/* 6. Make prev_node as previous of new_node */

    new_node.prev = prev_Node;

/* 7. Change previous of new_node's next node */

    if (new_node.next != null)
        new_node.next.prev = new_node;
}

/*Add a node at the end of the list*/

void append(int new_data)
{

/* 1. allocate node
     * 2. put in the data */

    Node new_node = new Node(new_data);
    Node last = head;

/* 3. This new node is going to be the last node, so
     * make next of it as NULL*/

    new_node.next = null;

/* 4. If the Linked List is empty, then make the new
     * node as head */

    if (head == null) {
        new_node.prev = null;
        head = new_node;
        return;
    }

/* 5. Else traverse till the last node */

    while (last.next != null)
        last = last.next;

/* 6. Change the next of last node */

    last.next = new_node;

/* 7. Make last node as previous of new node */

    new_node.prev = last;
}

/*Java program to find a
pair with given sum x.*/

class GFG
{

/*structure of node of
doubly linked list*/

static class Node
{
    int data;
    Node next, prev;
};

/*Function to find pair whose
sum equal to given value x.*/

static void pairSum( Node head, int x)
{

/*    Set two pointers, first
    to the beginning of DLL
    and second to the end of DLL.*/

    Node first = head;
    Node second = head;
    while (second.next != null)
        second = second.next;

/*    To track if we find a pair or not*/

    boolean found = false;

/*    The loop terminates when 
    they cross each other (second.next
    == first), or they become same
    (first == second)*/

    while ( first != second && second.next != first)
    {

/*        pair found*/

        if ((first.data + second.data) == x)
        {
            found = true;
            System.out.println( "(" + first.data +
                                ", "+ second.data + ")" );

/*            move first in forward direction*/

            first = first.next;

/*            move second in backward direction*/

            second = second.prev;
        }
        else
        {
            if ((first.data + second.data) < x)
                first = first.next;
            else
                second = second.prev;
        }
    }

/*    if pair is not present*/

    if (found == false)
        System.out.println("No pair found");
}

/*A utility function to insert
a new node at the beginning
of doubly linked list*/

static Node insert(Node head, int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.next = temp.prev = null;
    if (head == null)
        (head) = temp;
    else
    {
        temp.next = head;
        (head).prev = temp;
        (head) = temp;
    }
    return temp;
}

/*Driver Code*/

public static void main(String args[])
{
    Node head = null;
    head = insert(head, 9);
    head = insert(head, 8);
    head = insert(head, 6);
    head = insert(head, 5);
    head = insert(head, 4);
    head = insert(head, 2);
    head = insert(head, 1);
    int x = 7;
    pairSum(head, x);
}
}

/*Java implementation to count triplets in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

import java.util.*;
class GFG{

/*structure of node of doubly linked list*/

static class Node {
    int data;
    Node next, prev;
};

/*function to count pairs whose sum equal to given 'value'*/

static int countPairs(Node first, Node second, int value)
{
    int count = 0;

/*    The loop terminates when either of two pointers
    become null, or they cross each other (second.next
    == first), or they become same (first == second)*/

    while (first != null && second != null &&
           first != second && second.next != first) {

/*        pair found*/

        if ((first.data + second.data) == value) {

/*            increment count*/

            count++;

/*            move first in forward direction*/

            first = first.next;

/*            move second in backward direction*/

            second = second.prev;
        }

/*        if sum is greater than 'value'
        move second in backward direction*/

        else if ((first.data + second.data) > value)
            second = second.prev;

/*        else move first in forward direction*/

        else
            first = first.next;
    }

/*    required count of pairs*/

    return count;
}

/*function to count triplets in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

static int countTriplets(Node head, int x)
{

/*    if list is empty*/

    if (head == null)
        return 0;
    Node current, first, last;
    int count = 0;

/*    get pointer to the last node of
    the doubly linked list*/

    last = head;
    while (last.next != null)
        last = last.next;

/*    traversing the doubly linked list*/

    for (current = head; current != null; current = current.next) {

/*        for each current node*/

        first = current.next;

/*        count pairs with sum(x - current.data) in the range
        first to last and add it to the 'count' of triplets*/

        count += countPairs(first, last, x - current.data);
    }

/*    required count of triplets*/

    return count;
}

/*A utility function to insert a new node at the
beginning of doubly linked list*/

static Node insert(Node head, int data)
{

/*    allocate node*/

    Node temp = new Node();

/*    put in the data*/

    temp.data = data;
    temp.next = temp.prev = null;
    if ((head) == null)
        (head) = temp;
    else {
        temp.next = head;
        (head).prev = temp;
        (head) = temp;
    }
    return head;
}

/*Driver program to test above*/

public static void main(String[] args)
{

/*    start with an empty doubly linked list*/

    Node head = null;

/*    insert values in sorted order*/

    head = insert(head, 9);
    head = insert(head, 8);
    head = insert(head, 6);
    head = insert(head, 5);
    head = insert(head, 4);
    head = insert(head, 2);
    head = insert(head, 1);
    int x = 17;
    System.out.print("Count = "
         + countTriplets(head, x));
}
}

/*Java implementation to remove duplicates
from an unsorted doubly linked list*/

class GFG
{

/*a node of the doubly linked list*/

static class Node
{
    int data;
    Node next;
    Node prev;
}

/*Function to delete a node in a Doubly Linked List.
head_ref -. pointer to head node pointer.
del -. pointer to node to be deleted.*/

static Node deleteNode(Node head_ref, Node del)
{

/*    base case*/

    if (head_ref == null || del == null)
        return head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Change next only if node to be deleted
    is NOT the last node*/

    if (del.next != null)
        del.next.prev = del.prev;

/*    Change prev only if node to be deleted
    is NOT the first node*/

    if (del.prev != null)
        del.prev.next = del.next;
    return head_ref;
}

/*function to remove duplicates from
an unsorted doubly linked list*/

static Node removeDuplicates(Node head_ref)
{

/*    if DLL is empty or if it contains only
    a single node*/

    if ((head_ref) == null ||
        (head_ref).next == null)
        return head_ref;;
    Node ptr1, ptr2;

/*    pick elements one by one*/

    for (ptr1 = head_ref;
         ptr1 != null; ptr1 = ptr1.next)
    {
        ptr2 = ptr1.next;

/*        Compare the picked element with the
        rest of the elements*/

        while (ptr2 != null)
        {

/*            if duplicate, then delete it*/

            if (ptr1.data == ptr2.data)
            {

/*                store pointer to the node next to 'ptr2'*/

                Node next = ptr2.next;

/*                delete node pointed to by 'ptr2'*/

                head_ref = deleteNode(head_ref, ptr2);

/*                update 'ptr2'*/

                ptr2 = next;
            }

/*            else simply move to the next node*/

            else
                ptr2 = ptr2.next;
        }
    }
    return head_ref;
}

/*Function to insert a node at the beginning
of the Doubly Linked List*/

static Node push(Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a
given doubly linked list*/

static void printList( Node head)
{

/*    if list is empty*/

    if (head == null)
        System.out.print("Doubly Linked list empty");
    while (head != null)
    {
        System.out.print( head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void main(String args[])
{
    Node head = null;

/*    Create the doubly linked list:
    8<.4<.4<.6<.4<.8<.4<.10<.12<.12*/

    head = push(head, 12);
    head = push(head, 12);
    head = push(head, 10);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 4);
    head = push(head, 8);
    System.out.print("Original Doubly linked list:\n");
    printList(head);

/* remove duplicate nodes */

    head=removeDuplicates(head);
    System.out.print("\nDoubly linked list after" +
                        " removing duplicates:\n");
    printList(head);
}
}

/*Java mplementation to remove duplicates
from an unsorted doubly linked list*/

import java.util.*;
class GFG
{

/*a node of the doubly linked list*/

static class Node
{
    int data;
    Node next;
    Node prev;
};

/*Function to delete a node in a Doubly Linked List.
head_ref --> pointer to head node pointer.
del --> pointer to node to be deleted.*/

static Node deleteNode(Node head_ref, Node del)
{

/*    base case*/

    if (head_ref == null || del == null)
        return null;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Change next only if node to be deleted
    is NOT the last node*/

    if (del.next != null)
        del.next.prev = del.prev;

/*    Change prev only if node to be deleted
    is NOT the first node*/

    if (del.prev != null)
        del.prev.next = del.next;
    return head_ref;
}

/*function to remove duplicates from
an unsorted doubly linked list*/

static Node removeDuplicates(Node head_ref)
{

/*    if doubly linked list is empty*/

    if ((head_ref) == null)
        return null;

/*    unordered_set 'us' implemented as hash table*/

    HashSet<Integer> us = new HashSet<>();
    Node current = head_ref, next;

/*    traverse up to the end of the list*/

    while (current != null)
    {

/*        if current data is seen before*/

        if (us.contains(current.data))
        {

/*            store pointer to the node next to
            'current' node*/

            next = current.next;

/*            delete the node pointed to by 'current'*/

            head_ref = deleteNode(head_ref, current);

/*            update 'current'*/

            current = next;
        }
        else
        {

/*            insert the current data in 'us'*/

            us.add(current.data);

/*            move to the next node*/

            current = current.next;
        }
    }
    return head_ref;
}

/*Function to insert a node at the
beginning of the Doubly Linked List*/

static Node push(Node head_ref,
                 int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a given doubly
linked list*/

static void printList(Node head)
{

/*    if list is empty*/

    if (head == null)
        System.out.print("Doubly Linked list empty");
    while (head != null)
    {
        System.out.print(head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    Node head = null;

/*    Create the doubly linked list:
    8<->4<->4<->6<->4<->8<->4<->10<->12<->12*/

    head = push(head, 12);
    head = push(head, 12);
    head = push(head, 10);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 4);
    head = push(head, 8);
    System.out.println("Original Doubly linked list:");
    printList(head);

/* remove duplicate nodes */

    head = removeDuplicates(head);
    System.out.println("\nDoubly linked list after " +
                              "removing duplicates:");
    printList(head);
}
}

/*Java implementation to sort the
biotonic doubly linked list*/

class GFG
{

/*a node of the doubly linked list*/

static class Node
{
    int data;
    Node next;
    Node prev;
}

/*Function to reverse a Doubly Linked List*/

static Node reverse( Node head_ref)
{
    Node temp = null;
    Node current = head_ref;

/*    swap next and prev for all nodes
    of doubly linked list*/

    while (current != null)
    {
        temp = current.prev;
        current.prev = current.next;
        current.next = temp;
        current = current.prev;
    }

/*    Before changing head, check for the cases
    like empty list and list with only one node*/

    if (temp != null)
        head_ref = temp.prev;
        return head_ref;
}

/*Function to merge two sorted doubly linked lists*/

static Node merge(Node first, Node second)
{

/*    If first linked list is empty*/

    if (first == null)
        return second;

/*    If second linked list is empty*/

    if (second == null)
        return first;

/*    Pick the smaller value*/

    if (first.data < second.data)
    {
        first.next = merge(first.next, second);
        first.next.prev = first;
        first.prev = null;
        return first;
    }
    else
    {
        second.next = merge(first, second.next);
        second.next.prev = second;
        second.prev = null;
        return second;
    }
}

/*function to sort a biotonic doubly linked list*/

static Node sort(Node head)
{

/*    if list is empty or if it contains
    a single node only*/

    if (head == null || head.next == null)
        return head;
    Node current = head.next;
    while (current != null)
    {

/*        if true, then 'current' is the first node
        which is smaller than its previous node*/

        if (current.data < current.prev.data)
            break;

/*        move to the next node*/

        current = current.next;
    }

/*    if true, then list is already sorted*/

    if (current == null)
        return head;

/*    spilt into two lists, one starting with 'head'
    and other starting with 'current'*/

    current.prev.next = null;
    current.prev = null;

/*    reverse the list starting with 'current'*/

    current = reverse(current);

/*    merge the two lists and return the
    final merged doubly linked list*/

    return merge(head, current);
}

/*Function to insert a node at the beginning
of the Doubly Linked List*/

static Node push( Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a given doubly
linked list*/

static void printList( Node head)
{

/*    if list is empty*/

    if (head == null)
        System.out.println("Doubly Linked list empty");
    while (head != null)
    {
        System.out.print(head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void main(String args[])
{
    Node head = null;

/*    Create the doubly linked list:
    2<.5<.7<.12<.10<.6<.4<.1*/

    head = push(head, 1);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 10);
    head = push(head, 12);
    head = push(head, 7);
    head = push(head, 5);
    head = push(head, 2);
    System.out.println("Original Doubly linked list:n");
    printList(head);

/*    sort the biotonic DLL*/

    head = sort(head);
    System.out.println("\nDoubly linked list after sorting:n");
    printList(head);
}
}

/* Java program to insetail nodes in doubly
linked list such that list remains in
ascending order on printing from left
to right */

import java.io.*;
import java.util.*;

/*A linked list node*/

class Node
{
    int info;
    Node prev, next;
}
class GFG
{
    static Node head, tail;

/*    Function to insetail new node*/

    static void nodeInsetail(int key)
    {
        Node p = new Node();
        p.info = key;
        p.next = null;

/*        If first node to be insetailed in doubly
        linked list*/

        if (head == null)
        {
            head = p;
            tail = p;
            head.prev = null;
            return;
        }

/*        If node to be insetailed has value less
        than first node*/

        if (p.info < head.info)
        {
            p.prev = null;
            head.prev = p;
            p.next = head;
            head = p;
            return;
        }

/*        If node to be insetailed has value more
        than last node*/

        if (p.info > tail.info)
        {
            p.prev = tail;
            tail.next = p;
            tail = p;
            return;
        }

/*        Find the node before which we need to
        insert p.*/

        Node temp = head.next;
        while (temp.info < p.info)
                temp = temp.next;

/*        Insert new node before temp*/

        (temp.prev).next = p;
        p.prev = temp.prev;
        temp.prev = p;
        p.next = temp;
    }

/*    Function to print nodes in from left to right*/

    static void printList(Node temp)
    {
        while (temp != null)
        {
                System.out.print(temp.info + " ");
                temp = temp.next;
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        head = tail = null;
        nodeInsetail(30);
        nodeInsetail(50);
        nodeInsetail(90);
        nodeInsetail(10);
        nodeInsetail(40);
        nodeInsetail(110);
        nodeInsetail(60);
        nodeInsetail(95);
        nodeInsetail(23);
        System.out.println("Doubly linked list on printing from left to right");
        printList(head);
    }
}

/*Function to insert at the end*/

static void insertEnd(int value)
{

/*    If the list is empty, create a single
      node circular and doubly list*/

    if (start == null)
    {
        Node new_node = new Node();
        new_node.data = value;
        new_node.next = new_node.prev = new_node;
        start = new_node;
        return;
    }

/*    If list is not empty
    Find last node*/

    Node last = (start).prev;

/*    Create Node dynamically*/

    Node new_node = new Node();
    new_node.data = value;

/*    Start is going to be
      next of new_node*/

    new_node.next = start;

/*    Make new node previous of start*/

    (start).prev = new_node;

/*    Make last preivous of new node*/

    new_node.prev = last;

/*    Make new node next of old last*/

    last.next = new_node;
}

/*Java program to illustrate inserting a Node in
a Cicular Doubly Linked list in begging, end
and middle*/

import java.util.*;
class GFG
{
static Node start;

/*Structure of a Node*/

static class Node
{
    int data;
    Node next;
    Node prev;
};

/*Function to insert at the end*/

static void insertEnd(int value)
{

/*    If the list is empty, create a single node
    circular and doubly list*/

    if (start == null)
    {
        Node new_node = new Node();
        new_node.data = value;
        new_node.next = new_node.prev = new_node;
        start = new_node;
        return;
    }

/*    If list is not empty*/

/* Find last node */

    Node last = (start).prev;

/*    Create Node dynamically*/

    Node new_node = new Node();
    new_node.data = value;

/*    Start is going to be next of new_node*/

    new_node.next = start;

/*    Make new node previous of start*/

    (start).prev = new_node;

/*    Make last preivous of new node*/

    new_node.prev = last;

/*    Make new node next of old last*/

    last.next = new_node;
}

/*Function to insert Node at the beginning
of the List,*/

static void insertBegin(int value)
{

/*    Pointer points to last Node*/

    Node last = (start).prev;
    Node new_node = new Node();

/*Inserting the data*/

new_node.data = value;

/*    setting up previous and next of new node*/

    new_node.next = start;
    new_node.prev = last;

/*    Update next and previous pointers of start
    and last.*/

    last.next = (start).prev = new_node;

/*    Update start pointer*/

    start = new_node;
}

/*Function to insert node with value as value1.
The new node is inserted after the node with
with value2*/

static void insertAfter(int value1,
                                    int value2)
{
    Node new_node = new Node();

/*Inserting the data*/

new_node.data = value1;

/*    Find node having value2 and next node of it*/

    Node temp = start;
    while (temp.data != value2)
        temp = temp.next;
    Node next = temp.next;

/*    insert new_node between temp and next.*/

    temp.next = new_node;
    new_node.prev = temp;
    new_node.next = next;
    next.prev = new_node;
}
static void display()
{
    Node temp = start;
    System.out.printf("\nTraversal in forward direction \n");
    while (temp.next != start)
    {
        System.out.printf("%d ", temp.data);
        temp = temp.next;
    }
    System.out.printf("%d ", temp.data);
    System.out.printf("\nTraversal in reverse direction \n");
    Node last = start.prev;
    temp = last;
    while (temp.prev != last)
    {
        System.out.printf("%d ", temp.data);
        temp = temp.prev;
    }
    System.out.printf("%d ", temp.data);
}

/* Driver code*/

public static void main(String[] args)
{

/* Start with the empty list */

    Node start = null;

/*    Insert 5. So linked list becomes 5.null*/

    insertEnd(5);

/*    Insert 4 at the beginning. So linked
    list becomes 4.5*/

    insertBegin(4);

/*    Insert 7 at the end. So linked list
    becomes 4.5.7*/

    insertEnd(7);

/*    Insert 8 at the end. So linked list
    becomes 4.5.7.8*/

    insertEnd(8);

/*    Insert 6, after 5. So linked list
    becomes 4.5.6.7.8*/

    insertAfter(6, 5);
    System.out.printf("Created circular doubly linked list is: ");
    display();
}
}

