/*Java program to find fractional node in
a linked list*/

public class FractionalNodell
{

/* Linked list node */

    static class Node{
        int data;
        Node next;

/*        Constructor*/

        Node (int data){
            this.data = data;
        }
    }

/* Function to find fractional node in the
       linked list */

    static Node fractionalNodes(Node head, int k)
    {

/*        Corner cases*/

        if (k <= 0 || head == null)
            return null;
        Node fractionalNode = null;

/*        Traverse the given list*/

        int i = 0;
        for (Node temp = head; temp != null;
                          temp = temp.next){

/*            For every k nodes, we move
            fractionalNode one step ahead.*/

            if (i % k == 0){

/*                First time we see a multiple of k*/

                if (fractionalNode == null)
                    fractionalNode = head;
                else
                    fractionalNode = fractionalNode.next;
            }
            i++;
        }
        return fractionalNode;
    }

/*    A utility function to print a linked list*/

    static void printList(Node node)
    {
        while (node != null)
        {
            System.out.print(node.data+" ");
            node = node.next;
        }
        System.out.println();
    }

/* Driver program to test above function */

    public static void main(String[] args) {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        head.next.next.next.next = new Node(5);
        int k =2;
        System.out.print("List is ");
        printList(head);
        Node answer = fractionalNodes(head, k);
        System.out.println("Fractional node is "+
                                      answer.data);
    }
}

/* Java program to arrange consonants and
vowels nodes in a linked list */

class GfG
{

/* A linked list node */

static class Node
{
    char data;
    Node next;
}

/* Function to add new node to the List */

static Node newNode(char key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*utility function to print linked list*/

static void printlist(Node head)
{
    if (head == null)
    {
        System.out.println("Empty List");
        return;
    }
    while (head != null)
    {
        System.out.print(head.data +" ");
        if (head.next != null)
        System.out.print("-> ");
        head = head.next;
    }
    System.out.println();
}

/*utility function for checking vowel*/

static boolean isVowel(char x)
{
    return (x == 'a' || x == 'e' || x == 'i' ||
            x == 'o' || x == 'u');
}

/* function to arrange consonants and
vowels nodes */

static Node arrange(Node head)
{
    Node newHead = head;

/*    for keep track of vowel*/

    Node latestVowel;
    Node curr = head;

/*    list is empty*/

    if (head == null)
        return null;

/*    We need to discover the first vowel
    in the list. It is going to be the
    returned head, and also the initial
    latestVowel.*/

    if (isVowel(head.data) == true)

/*        first element is a vowel. It will
        also be the new head and the initial
        latestVowel;*/

        latestVowel = head;
    else
    {

/*        First element is not a vowel. Iterate
        through the list until we find a vowel.
        Note that curr points to the element
        *before* the element with the vowel.*/

        while (curr.next != null &&
            !isVowel(curr.next.data))
            curr = curr.next;

/*        This is an edge case where there are
        only consonants in the list.*/

        if (curr.next == null)
            return head;

/*        Set the initial latestVowel and the
        new head to the vowel item that we found.
        Relink the chain of consonants after
        that vowel item:
        old_head_consonant->consonant1->consonant2->
        vowel->rest_of_list becomes
        vowel->old_head_consonant->consonant1->
        consonant2->rest_of_list*/

        latestVowel = newHead = curr.next;
        curr.next = curr.next.next;
        latestVowel.next = head;
    }

/*    Now traverse the list. Curr is always the item
    *before* the one we are checking, so that we
    can use it to re-link.*/

    while (curr != null && curr.next != null)
    {
        if (isVowel(curr.next.data) == true)
        {

/*            The next discovered item is a vowel*/

            if (curr == latestVowel)
            {

/*                If it comes directly after the
                previous vowel, we don't need to
                move items around, just mark the
                new latestVowel and advance curr.*/

                latestVowel = curr = curr.next;
            }
            else
            {

/*                But if it comes after an intervening
                chain of consonants, we need to chain
                the newly discovered vowel right after
                the old vowel. Curr is not changed as
                after the re-linking it will have a
                new next, that has not been checked yet,
                and we always keep curr at one before
                the next to check.*/

                Node temp = latestVowel.next;

/*                Chain in new vowel*/

                latestVowel.next = curr.next;

/*                Advance latestVowel*/

                latestVowel = latestVowel.next;

/*                Remove found vowel from previous place*/

                curr.next = curr.next.next;

/*                Re-link chain of consonants after latestVowel*/

                latestVowel.next = temp;
            }
        }
        else
        {

/*            No vowel in the next element, advance curr.*/

            curr = curr.next;
        }
    }
    return newHead;
}

/*Driver code*/

public static void main(String[] args)
{
    Node head = newNode('a');
    head.next = newNode('b');
    head.next.next = newNode('c');
    head.next.next.next = newNode('e');
    head.next.next.next.next = newNode('d');
    head.next.next.next.next.next = newNode('o');
    head.next.next.next.next.next.next = newNode('x');
    head.next.next.next.next.next.next.next = newNode('i');
    System.out.println("Linked list before : ");
    printlist(head);
    head = arrange(head);
    System.out.println("Linked list after :");
    printlist(head);
}
}

/*Java implementation to modify the contents
of the linked list*/

class GFG
{

/* Linked list node */

static class Node
{
    int data;
    Node next;
};

/* Function to insert a node at the beginning
of the linked list */

static Node push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node =new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list at the end
    of the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    return head_ref;
}
static Node front,back;

/* Split the nodes of the given list
into front and back halves,
and return the two lists
using the reference parameters.
Uses the fast/slow pointer strategy. */

static void frontAndBackSplit( Node head)
{
    Node slow, fast;
    slow = head;
    fast = head.next;

/* Advance 'fast' two nodes, and
    advance 'slow' one node */

    while (fast != null)
    {
        fast = fast.next;
        if (fast != null)
        {
            slow = slow.next;
            fast = fast.next;
        }
    }

/* 'slow' is before the midpoint in the list,
        so split it in two at that point. */

    front = head;
    back = slow.next;
    slow.next = null;
}

/* Function to reverse the linked list */

static Node reverseList( Node head_ref)
{
    Node current, prev, next;
    current = head_ref;
    prev = null;
    while (current != null)
    {
        next = current.next;
        current.next = prev;
        prev = current;
        current = next;
    }
    head_ref = prev;
    return head_ref;
}

/*perfrom the required subtraction operation
on the 1st half of the linked list*/

static void modifyTheContentsOf1stHalf()
{
    Node front1 = front, back1 = back;

/*    traversing both the lists simultaneously*/

    while (back1 != null)
    {

/*        subtraction operation and node data
        modification*/

        front1.data = front1.data - back1.data;
        front1 = front1.next;
        back1 = back1.next;
    }
}

/*function to concatenate the 2nd(back) list
at the end of the 1st(front) list and
returns the head of the new list*/

static Node concatFrontAndBackList(Node front,
                                   Node back)
{
    Node head = front;
    if(front == null)return back;
    while (front.next != null)
        front = front.next;
    front.next = back;
    return head;
}

/*function to modify the contents of the linked list*/

static Node modifyTheList( Node head)
{

/*    if list is empty or contains only single node*/

    if (head == null || head.next == null)
        return head;
    front = null; back = null;

/*    split the list into two halves
    front and back lists*/

    frontAndBackSplit(head);

/*    reverse the 2nd(back) list*/

    back = reverseList(back);

/*    modify the contents of 1st half*/

    modifyTheContentsOf1stHalf();

/*    agains reverse the 2nd(back) list*/

    back = reverseList(back);

/*    concatenating the 2nd list back to the
    end of the 1st list*/

    head = concatFrontAndBackList(front, back);

/*    pointer to the modified list*/

    return head;
}

/*function to print the linked list*/

static void printList( Node head)
{
    if (head == null)
        return;
    while (head.next != null)
    {
        System.out.print(head.data + " -> ");
        head = head.next;
    }
    System.out.println(head.data );
}

/*Driver Code*/

public static void main(String args[])
{
    Node head = null;

/*    creating the linked list*/

    head = push(head, 10);
    head = push(head, 7);
    head = push(head, 12);
    head = push(head, 8);
    head = push(head, 9);
    head = push(head, 2);

/*    modify the linked list*/

    head = modifyTheList(head);

/*    print the modified linked list*/

    System.out.println( "Modified List:" );
    printList(head);
}
}

/*Java implementation to modify the
contents of the linked list*/

import java.util.*;
class GFG
{

/*    Linked list node*/

    static class Node
    {
        int data;
        Node next;
    };

/*    Function to insert a node at the
    beginning of the linked list*/

    static Node push(Node head_ref, int new_data)
    {

/*        allocate node*/

        Node new_node = new Node();

/*        put in the data*/

        new_node.data = new_data;

/*        link the old list at the end of the new node*/

        new_node.next = head_ref;

/*        move the head to point to the new node*/

        head_ref = new_node;
        return head_ref;
    }

/*    function to print the linked list*/

    static void printList(Node head)
    {
        if (head == null)
        {
            return;
        }
        while (head.next != null)
        {
            System.out.print(head.data + "->");
            head = head.next;
        }
        System.out.print(head.data + "\n");
    }

/*    Function to middle node of list.*/

    static Node find_mid(Node head)
    {
        Node temp = head, slow = head, fast = head;
        while (fast != null && fast.next != null)
        {

/*            Advance 'fast' two nodes, and
            advance 'slow' one node*/

            slow = slow.next;
            fast = fast.next.next;
        }

/*        If number of nodes are odd then update slow
        by slow.next;*/

        if (fast != null)
        {
            slow = slow.next;
        }
        return slow;
    }

/*    function to modify the contents of the linked list.*/

    static void modifyTheList(Node head, Node slow)
    {

/*        Create Stack.*/

        Stack<Integer> s = new Stack<Integer>();
        Node temp = head;
        while (slow != null)
        {
            s.add(slow.data);
            slow = slow.next;
        }

/*    Traverse the list by using temp until stack is empty.*/

        while (!s.empty())
        {
            temp.data = temp.data - s.peek();
            temp = temp.next;
            s.pop();
        }
    }

/*    Driver program to test above*/

    public static void main(String[] args)
    {
        Node head = null, mid;

/*        creating the linked list*/

        head = push(head, 10);
        head = push(head, 7);
        head = push(head, 12);
        head = push(head, 8);
        head = push(head, 9);
        head = push(head, 2);

/*        Call Function to Find the starting
        point of second half of list.*/

        mid = find_mid(head);

/*        Call function to modify
        the contents of the linked list.*/

        modifyTheList(head, mid);

/*        print the modified linked list*/

        System.out.print("Modified List:" + "\n");
        printList(head);
    }
}

/*Construct a BST from given pre-order traversal
for example if the given traversal is {10, 5, 1, 7, 40, 50},
then the output should be the root of the following tree.
     10
   /   \
  5     40
 /  \      \
1    7      50 */

class Node {
    int data;
    Node left, right;
    Node(int data)
    {
        this.data = data;
        this.left = this.right = null;
    }
}
class CreateBSTFromPreorder {
    private static Node node;

/*    This will create the BST*/

    public static Node createNode(Node node, int data)
    {
        if (node == null)
            node = new Node(data);
        if (node.data > data)
            node.left = createNode(node.left, data);
        if (node.data < data)
            node.right = createNode(node.right, data);
        return node;
    }

/*    A wrapper function of createNode*/

    public static void create(int data)
    {
        node = createNode(node, data);
    }

/*    A function to print BST in inorder*/

    public static void inorderRec(Node root)
    {
        if (root != null) {
            inorderRec(root.left);
            System.out.println(root.data);
            inorderRec(root.right);
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] nodeData = { 10, 5, 1, 7, 40, 50 };
        for (int i = 0; i < nodeData.length; i++) {
            create(nodeData[i]);
        }
        inorderRec(node);
    }
}

/*Java implementation to construct a BST
from its level order traversal*/

class GFG
{

/*node of a BST*/

static class Node
{
    int data;
    Node left, right;
};

/*function to get a new node*/

static Node getNode(int data)
{

/*    Allocate memory*/

    Node newNode = new Node();

/*    put in the data */

    newNode.data = data;
    newNode.left = newNode.right = null; 
    return newNode;
}

/*function to construct a BST from
its level order traversal*/

static Node LevelOrder(Node root , int data) 
{
    if(root == null)
    { 
        root = getNode(data);
        return root;
    }
    if(data <= root.data)
    root.left = LevelOrder(root.left, data);
    else
    root.right = LevelOrder(root.right, data);
    return root;     
}
static Node constructBst(int arr[], int n)
{
    if(n == 0)return null;
    Node root = null;
    for(int i = 0; i < n; i++)
    root = LevelOrder(root , arr[i]);
    return root;
}

/*function to print the inorder traversal*/

static void inorderTraversal(Node root)
{
    if (root == null)
        return;
    inorderTraversal(root.left);
    System.out.print( root.data + " ");
    inorderTraversal(root.right); 
}

/*Driver code*/

public static void main(String args[])
{
    int arr[] = {7, 4, 12, 3, 6, 8, 1, 5, 10};
    int n = arr.length;
    Node root = constructBst(arr, n);
    System.out.print( "Inorder Traversal: ");
    inorderTraversal(root);
}
}

/*Java program to Check given array
can represent BST or not*/

class GFG 
{

/*    structure for Binary Node*/

    static class Node 
    {
        int key;
        Node right, left;
    };
    static Node newNode(int num) 
    {
        Node temp = new Node();
        temp.key = num;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    To create a Tree with n levels. We always
    insert new node to left if it is less than
    previous value.*/

    static Node createNLevelTree(int arr[], int n) 
    {
        Node root = newNode(arr[0]);
        Node temp = root;
        for (int i = 1; i < n; i++)
        {
            if (temp.key > arr[i]) 
            {
                temp.left = newNode(arr[i]);
                temp = temp.left;
            } 
            else 
            {
                temp.right = newNode(arr[i]);
                temp = temp.right;
            }
        }
        return root;
    }

/*    Please refer below post for details of this
    function.
www.geeksforgeeks.org/a-program-to-check-if-a-binary-tree-is-bst-or-not/
https:*/

    static boolean isBST(Node root, int min, int max) 
    {
        if (root == null) 
        {
            return true;
        }
        if (root.key < min || root.key > max) 
        {
            return false;
        }

/*        Allow only distinct values*/

        return (isBST(root.left, min,
                (root.key) - 1)
                && isBST(root.right,
                        (root.key) + 1, max));
    }

/*    Returns tree if given array of size n can
    represent a BST of n levels.*/

    static boolean canRepresentNLevelBST(int arr[], int n) 
    {
        Node root = createNLevelTree(arr, n);
        return isBST(root, Integer.MIN_VALUE, Integer.MAX_VALUE);
    }

/*    Driver code*/

    public static void main(String[] args) 
    {
        int arr[] = {512, 330, 78, 11, 8};
        int n = arr.length;
        if (canRepresentNLevelBST(arr, n)) 
        {
            System.out.println("Yes");
        } 
        else 
        {
            System.out.println("No");
        }
    }
}

/*Java program to Check given array 
can represent BST or not */

class Solution
{

/*Driver code */

public static void main(String args[]) 
{ 
    int arr[] = { 5123, 3300, 783, 1111, 890 }; 
    int n = arr.length; 
    int max = Integer.MAX_VALUE; 
    int min = Integer.MIN_VALUE; 
    boolean flag = true; 
    for (int i = 1; i < n; i++) {

/*        This element can be inserted to the right 
        of the previous element, only if it is greater 
        than the previous element and in the range. */

        if (arr[i] > arr[i - 1] && arr[i] > min && arr[i] < max) {

/*            max remains same, update min */

            min = arr[i - 1]; 
        }

/*        This element can be inserted to the left 
        of the previous element, only if it is lesser 
        than the previous element and in the range. */

        else if (arr[i] < arr[i - 1] && arr[i] > min && arr[i] < max) {

/*            min remains same, update max */

            max = arr[i - 1]; 
        } 
        else { 
            flag = false; 
            break; 
        } 
    } 
    if (flag) { 
        System.out.println("Yes"); 
    } 
    else {

/*        if the loop completed successfully without encountering else condition */

        System.out.println("No"); 
    } 
} 
}

/*Java program to find minimum value node in Binary Search Tree*/

/*A binary tree node*/

class Node {
    int data;
    Node left, right;
    Node(int d) {
        data = d;
        left = right = null;
    }
}
class BinaryTree {
    static Node head;

/* Given a binary search tree and a number, 
     inserts a new node with the given number in 
     the correct place in the tree. Returns the new 
     root pointer which the caller should then use 
     (the standard trick to avoid using reference 
     parameters). */

    Node insert(Node node, int data) {

/* 1. If the tree is empty, return a new,     
         single node */

        if (node == null) {
            return (new Node(data));
        } else {

/* 2. Otherwise, recur down the tree */

            if (data <= node.data) {
                node.left = insert(node.left, data);
            } else {
                node.right = insert(node.right, data);
            }

/* return the (unchanged) node pointer */

            return node;
        }
    }

/* Given a non-empty binary search tree,  
     return the minimum data value found in that 
     tree. Note that the entire tree does not need 
     to be searched. */

    int minvalue(Node node) {
        Node current = node;

/* loop down to find the leftmost leaf */

        while (current.left != null) {
            current = current.left;
        }
        return (current.data);
    }

/*    Driver program to test above functions*/

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        Node root = null;
        root = tree.insert(root, 4);
        tree.insert(root, 2);
        tree.insert(root, 1);
        tree.insert(root, 3);
        tree.insert(root, 6);
        tree.insert(root, 5);
        System.out.println("Minimum value of BST is " + tree.minvalue(root));
    }
}

/*A simple inorder traversal based Java program
to find k-th smallest element in a BST.*/

import java.io.*;
import java.util.*;

/*A BST node*/

class Node {
    int data;
    Node left, right;
    int lCount;
    Node(int x)
    {
        data = x;
        left = right = null;
        lCount = 0;
    }
}
class Gfg
{

/*    Recursive function to insert an key into BST*/

    public static Node insert(Node root, int x)
    {
        if (root == null)
            return new Node(x);

/*        If a node is inserted in left subtree, then
        lCount of this node is increased. For simplicity,
        we are assuming that all keys (tried to be
        inserted) are distinct.*/

        if (x < root.data) {
            root.left = insert(root.left, x);
            root.lCount++;
        }
        else if (x > root.data)
            root.right = insert(root.right, x);
        return root;
    }

/*    Function to find k'th largest element in BST
    Here count denotes the number of
    nodes processed so far*/

    public static Node kthSmallest(Node root, int k)
    {

/*        base case*/

        if (root == null)
            return null;
        int count = root.lCount + 1;
        if (count == k)
            return root;
        if (count > k)
            return kthSmallest(root.left, k);

/*        else search in right subtree*/

        return kthSmallest(root.right, k - count);
    }

/*    main function*/

    public static void main(String args[])
    {
        Node root = null;
        int keys[] = { 20, 8, 22, 4, 12, 10, 14 };
        for (int x : keys)
            root = insert(root, x);
        int k = 4;
        Node res = kthSmallest(root, k);
        if (res == null)
            System.out.println("There are less "
                           + "than k nodes in the BST");
        else
            System.out.println("K-th Smallest"
                    + " Element is " + res.data);
    }
}

/*Check if each internal node of BST has only one child*/

class BinaryTree {
    boolean hasOnlyOneChild(int pre[], int size) {
        int nextDiff, lastDiff;
        for (int i = 0; i < size - 1; i++) {
            nextDiff = pre[i] - pre[i + 1];
            lastDiff = pre[i] - pre[size - 1];
            if (nextDiff * lastDiff < 0) {
                return false;
            };
        }
        return true;
    }

/*  Driver code*/

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        int pre[] = new int[]{8, 3, 5, 7, 6};
        int size = pre.length;
        if (tree.hasOnlyOneChild(pre, size) == true) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Check if each internal node of BST has only one child*/

class BinaryTree {
    boolean hasOnlyOneChild(int pre[], int size) {

/*        Initialize min and max using last two elements*/

        int min, max;
        if (pre[size - 1] > pre[size - 2]) {
            max = pre[size - 1];
            min = pre[size - 2];
        } else {
            max = pre[size - 2];
            min = pre[size - 1];
        }

/*        Every element must be either smaller than min or
        greater than max*/

        for (int i = size - 3; i >= 0; i--) {
            if (pre[i] < min) {
                min = pre[i];
            } else if (pre[i] > max) {
                max = pre[i];
            } else {
                return false;
            }
        }
        return true;
    }

/*Driver program to test above function*/

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        int pre[] = new int[]{8, 3, 5, 7, 6};
        int size = pre.length;
        if (tree.hasOnlyOneChild(pre, size) == true) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Java Program for finding K-th largest Node using O(1)
extra memory and reverse Morris traversal.*/

class GfG
{

/*Node structure*/

static class Node
{
    int data;
    Node left, right;
}

/*helper function to create a new Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.right = null;
    temp.left = null;
    return temp;
}
static Node KthLargestUsingMorrisTraversal(Node root, int k)
{
    Node curr = root;
    Node Klargest = null;

/*    count variable to keep count of visited Nodes*/

    int count = 0;
    while (curr != null)
    {

/*        if right child is NULL*/

        if (curr.right == null)
        {

/*            first increment count and check if count = k*/

            if (++count == k)
                Klargest = curr;

/*            otherwise move to the left child*/

            curr = curr.left;
        }
        else
        {

/*            find inorder successor of current Node*/

            Node succ = curr.right;
            while (succ.left != null && succ.left != curr)
                succ = succ.left;
            if (succ.left == null)
            {

/*                set left child of successor to the
                current Node*/

                succ.left = curr;

/*                move current to its right*/

                curr = curr.right;
            }

/*            restoring the tree back to original binary
            search tree removing threaded links*/

            else
            {
                succ.left = null;
                if (++count == k)
                    Klargest = curr;

/*                move current to its left child*/

                curr = curr.left;
            }
        }
    }
    return Klargest;
}

/*Driver code*/

public static void main(String[] args)
{

/* Constructed binary tree is
        4
        / \
    2 7
    / \ / \
    1 3 6 10 */

    Node root = newNode(4);
    root.left = newNode(2);
    root.right = newNode(7);
    root.left.left = newNode(1);
    root.left.right = newNode(3);
    root.right.left = newNode(6);
    root.right.right = newNode(10);
    System.out.println("Finding K-th largest Node in BST : " +
                    KthLargestUsingMorrisTraversal(root, 2).data);
}
}

/*Java program to find k'th largest element in BST*/

import java.util.*;
class GfG {

/*A BST node*/

static class Node
{
    int key;
    Node left, right;
}

/*A function to find*/

static int KSmallestUsingMorris(Node root, int k)
{

/*    Count to iterate over elements till we
    get the kth smallest number*/

    int count = 0;

/*store the Kth smallest*/

int ksmall = Integer.MIN_VALUE;

/*to store the current node*/

Node curr = root; 
    while (curr != null)
    {

/*        Like Morris traversal if current does
        not have left child rather than printing
        as we did in inorder, we will just
        increment the count as the number will
        be in an increasing order*/

        if (curr.left == null)
        {
            count++;

/*            if count is equal to K then we found the
            kth smallest, so store it in ksmall*/

            if (count==k)
                ksmall = curr.key;

/*            go to current's right child*/

            curr = curr.right;
        }
        else
        {

/*            we create links to Inorder Successor and
            count using these links*/

            Node pre = curr.left;
            while (pre.right != null && pre.right != curr)
                pre = pre.right;

/*            building links*/

            if (pre.right== null)
            {

/*                link made to Inorder Successor*/

                pre.right = curr;
                curr = curr.left;
            }

/*            While breaking the links in so made temporary
            threaded tree we will check for the K smallest
            condition*/

            else
            {

/*                Revert the changes made in if part (break link
                from the Inorder Successor)*/

                pre.right = null;
                count++;

/*                If count is equal to K then we found
                the kth smallest and so store it in ksmall*/

                if (count==k)
                    ksmall = curr.key;
                curr = curr.right;
            }
        }
    }

/*return the found value*/

return ksmall; 
}

/*A utility function to create a new BST node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    return temp;
}

/* A utility function to insert a new node with given key in BST */

static Node insert(Node node, int key)
{

/* If the tree is empty, return a new node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else if (key > node.key)
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/*Driver Program to test above functions*/

public static void main(String[] args)
{

/* Let us create following BST
            50
        /     \
        30     70
        / \ / \
    20 40 60 80 */

    Node root = null;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);
    for (int k=1; k<=7; k++)
    System.out.print(KSmallestUsingMorris(root, k) + " ");
}
}

/*Java program to check if a given array is sorted
or not.*/

class GFG {

/*Function that returns true if array is Inorder
traversal of any Binary Search Tree or not.*/

    static boolean isInorder(int[] arr, int n) {

/*        Array has one or no element*/

        if (n == 0 || n == 1) {
            return true;
        }

/*Unsorted pair found*/

for (int i = 1; i < n; i++) 
        {
            if (arr[i - 1] > arr[i]) {
                return false;
            }
        }

/*        No unsorted pair found*/

        return true;
    }

