        } else {
            System.out.println("Non");
        }
    }
}

/*Java code to find the largest value smaller
than or equal to N*/

class GfG {

/*Node structure*/

static class Node {
    int key;
    Node left, right;
}

/*To create new BST Node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*To insert a new node in BST*/

static Node insert(Node node, int key)
{

/*    if tree is empty return new node*/

    if (node == null)
        return newNode(key);

/*    if key is less then or greater then
    node value then recur down the tree*/

    if (key < node.key)
        node.left = insert(node.left, key);
    else if (key > node.key)
        node.right = insert(node.right, key);

/*    return the (unchanged) node pointer*/

    return node;
}

/*function to find max value less then N*/

static int findMaxforN(Node root, int N)
{

/*    Base cases*/

    if (root == null)
        return -1;
    if (root.key == N)
        return N;

/*    If root's value is smaller, try in right
    subtree*/

    else if (root.key < N) {
        int k = findMaxforN(root.right, N);
        if (k == -1)
            return root.key;
        else
            return k;
    }

/*    If root's key is greater, return value
    from left subtree.*/

    else if (root.key > N)
        return findMaxforN(root.left, N);
    return -1;
}

/*Driver code*/

public static void main(String[] args)
{
    int N = 4;

/*creating following BST
                5
            / \
            2     12
        / \ / \
        1 3 9 21
                    / \
                    19 25 */

    Node root = null;
    root = insert(root, 25);
    insert(root, 2);
    insert(root, 1);
    insert(root, 3);
    insert(root, 12);
    insert(root, 9);
    insert(root, 21);
    insert(root, 19);
    insert(root, 25);
    System.out.println(findMaxforN(root, N));
}
}

/*Java program to find distance between
two nodes in BST*/

class GfG {
static class Node {
    Node left, right;
    int key;
}
static Node newNode(int key)
{
    Node ptr = new Node();
    ptr.key = key;
    ptr.left = null;
    ptr.right = null;
    return ptr;
}

/*Standard BST insert function*/

static Node insert(Node root, int key)
{
    if (root == null)
        root = newNode(key);
    else if (root.key > key)
        root.left = insert(root.left, key);
    else if (root.key < key)
        root.right = insert(root.right, key);
    return root;
}

/*This function returns distance of x from
root. This function assumes that x exists
in BST and BST is not NULL.*/

static int distanceFromRoot(Node root, int x)
{
    if (root.key == x)
        return 0;
    else if (root.key > x)
        return 1 + distanceFromRoot(root.left, x);
    return 1 + distanceFromRoot(root.right, x);
}

/*Returns minimum distance beween a and b.
This function assumes that a and b exist
in BST.*/

static int distanceBetween2(Node root, int a, int b)
{
    if (root == null)
        return 0;

/*    Both keys lie in left*/

    if (root.key > a && root.key > b)
        return distanceBetween2(root.left, a, b);

/*    Both keys lie in right
same path*/

if (root.key < a && root.key < b) 
        return distanceBetween2(root.right, a, b);

/*    Lie in opposite directions (Root is
    LCA of two nodes)*/

    if (root.key >= a && root.key <= b)
        return distanceFromRoot(root, a) + distanceFromRoot(root, b);
    return 0;
}

/*This function make sure that a is smaller
than b before making a call to findDistWrapper()*/

static int findDistWrapper(Node root, int a, int b)
{
    int temp = 0;
if (a > b)
    {
    temp = a;
    a = b;
    b = temp;
    }
return distanceBetween2(root, a, b);
}

/*Driver code*/

public static void main(String[] args)
{
    Node root = null;
    root = insert(root, 20);
    insert(root, 10);
    insert(root, 5);
    insert(root, 15);
    insert(root, 30);
    insert(root, 25);
    insert(root, 35);
    System.out.println(findDistWrapper(root, 5, 35));
}
}

/*Java code to print BST keys in given Range in
constant space using Morris traversal.*/

class GfG {
static class node {
    int data;
    node left, right;
}

/*Function to print the keys in range*/

static void RangeTraversal(node root, int n1, int n2)
{
    if (root == null)
        return;
    node curr = root;
    while (curr != null) {
        if (curr.left == null)
        {

/*            check if current node
            lies between n1 and n2*/

            if (curr.data <= n2 && curr.data >= n1)
            {
                System.out.print(curr.data + " ");
            }
            curr = curr.right;
        }
        else {
            node pre = curr.left;

/*            finding the inorder predecessor-
            inorder predecessor is the right
            most in left subtree or the left
            child, i.e in BST it is the
            maximum(right most) in left subtree.*/

            while (pre.right != null && pre.right != curr)
                pre = pre.right;
            if (pre.right == null)
            {
                pre.right = curr;
                curr = curr.left;
            }
            else {
                pre.right = null;

/*                check if current node lies
                between n1 and n2*/

                if (curr.data <= n2 && curr.data >= n1)
                {
                    System.out.print(curr.data + " ");
                }
                curr = curr.right;
            }
        }
    }
}

/*Helper function to create a new node*/

static node newNode(int data)
{
    node temp = new node();
    temp.data = data;
    temp.right = null;
    temp.left = null;
    return temp;
}

/*Driver Code*/

public static void main(String[] args)
{

/* Constructed binary tree is
        4
        / \
    2     7
    / \ / \
    1 3 6 10
*/

    node root = newNode(4);
    root.left = newNode(2);
    root.right = newNode(7);
    root.left.left = newNode(1);
    root.left.right = newNode(3);
    root.right.left = newNode(6);
    root.right.right = newNode(10);
    RangeTraversal(root, 4, 12);
}
}

/*Java program to delete leaf Node from
binary search tree.*/

class GfG {
    static class Node {
        int data;
        Node left;
        Node right;
    }

/*    Create a newNode in binary search tree.*/

    static Node newNode(int data)
    {
        Node temp = new Node();
        temp.data = data;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    Insert a Node in binary search tree.*/

    static Node insert(Node root, int data)
    {
        if (root == null)
            return newNode(data);
        if (data < root.data)
            root.left = insert(root.left, data);
        else if (data > root.data)
            root.right = insert(root.right, data);
        return root;
    }

/*    Function for inorder traversal in a BST.*/

    static void inorder(Node root)
    {
        if (root != null) {
            inorder(root.left);
            System.out.print(root.data + " ");
            inorder(root.right);
        }
    }

/*    Delete leaf nodes from binary search tree.*/

    static Node leafDelete(Node root)
    {
        if (root == null) {
            return null;
        }
        if (root.left == null && root.right == null) {
            return null;
        }

/*        Else recursively delete in left and right
        subtrees.*/

        root.left = leafDelete(root.left);
        root.right = leafDelete(root.right);
        return root;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        Node root = null;
        root = insert(root, 20);
        insert(root, 10);
        insert(root, 5);
        insert(root, 15);
        insert(root, 30);
        insert(root, 25);
        insert(root, 35);
        System.out.println("Inorder before Deleting the leaf Node. ");
        inorder(root);
        System.out.println();
        leafDelete(root);
        System.out.println("INorder after Deleting the leaf Node. ");
        inorder(root);
    }
}

/*Java program to find Sum Of All Elements smaller
than or equal t Kth Smallest Element In BST*/

import java.util.*;
class GFG{

/* Binary tree Node */

static class Node
{
    int data;
    int lCount;
    int Sum ;
    Node left;
    Node right;
};

/*utility function new Node of BST*/

static Node createNode(int data)
{
    Node  new_Node = new Node();
    new_Node.left = null;
    new_Node.right = null;
    new_Node.data = data;
    new_Node.lCount = 0 ;
    new_Node.Sum = 0;
    return new_Node;
}

/*A utility function to insert a new Node with
given key in BST and also maintain lcount ,Sum*/

static Node  insert(Node root, int key)
{

/*    If the tree is empty, return a new Node*/

    if (root == null)
        return createNode(key);

/*    Otherwise, recur down the tree*/

    if (root.data > key)
    {

/*        increment lCount of current Node*/

        root.lCount++;

/*        increment current Node sum by adding
        key into it*/

        root.Sum += key;
        root.left= insert(root.left , key);
    }
    else if (root.data < key )
        root.right= insert (root.right , key );

/*    return the (unchanged) Node pointer*/

    return root;
}
static int temp_sum;

/*function return sum of all element smaller than and equal
to Kth smallest element*/

static void ksmallestElementSumRec(Node root, int k )
{
    if (root == null)
        return ;

/*    if we fount k smallest element then break the function*/

    if ((root.lCount + 1) == k)
    {
        temp_sum += root.data + root.Sum ;
        return ;
    }
    else if (k > root.lCount)
    {

/*        store sum of all element smaller than current root ;*/

        temp_sum += root.data + root.Sum;

/*        decremented k and call right sub-tree*/

        k = k -( root.lCount + 1);
        ksmallestElementSumRec(root.right , k );
    }

/*call left sub-tree*/

else 
        ksmallestElementSumRec(root.left , k );
}

/*Wrapper over ksmallestElementSumRec()*/

static void ksmallestElementSum(Node root, int k)
{
    temp_sum = 0;
    ksmallestElementSumRec(root, k);
}

/* Driver program to test above functions */

public static void main(String[] args)
{

/*    20
        /    \
       8     22
     /   \
    4     12
         /   \
        10    14
          */

    Node root = null;
    root = insert(root, 20);
    root = insert(root, 8);
    root = insert(root, 4);
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 14);
    root = insert(root, 22);
    int k = 3;
     ksmallestElementSum(root, k);
     System.out.println(temp_sum);
}
}

/*Java program to find minimum
value node in Binary Search Tree*/

/*A binary tree node*/

class Node {
    int data;
    Node left, right, parent;
    Node(int d)
    {
        data = d;
        left = right = parent = null;
    }
}
class BinaryTree {
    static Node head;

/* Given a binary search tree and a number,
     inserts a new node with the given number in
     the correct place in the tree. Returns the new
     root pointer which the caller should then use
     (the standard trick to avoid using reference
     parameters). */

    Node insert(Node node, int data)
    {

/* 1. If the tree is empty, return a new,    
         single node */

        if (node == null) {
            return (new Node(data));
        }
        else {
            Node temp = null;

/* 2. Otherwise, recur down the tree */

            if (data <= node.data) {
                temp = insert(node.left, data);
                node.left = temp;
                temp.parent = node;
            }
            else {
                temp = insert(node.right, data);
                node.right = temp;
                temp.parent = node;
            }

/* return the (unchanged) node pointer */

            return node;
        }
    }
    Node inOrderSuccessor(Node root, Node n)
    {

/*        step 1 of the above algorithm*/

        if (n.right != null) {
            return minValue(n.right);
        }

/*        step 2 of the above algorithm*/

        Node p = n.parent;
        while (p != null && n == p.right) {
            n = p;
            p = p.parent;
        }
        return p;
    }

/* Given a non-empty binary search
       tree, return the minimum data 
       value found in that tree. Note that
       the entire tree does not need
       to be searched. */

    Node minValue(Node node)
    {
        Node current = node;

/* loop down to find the leftmost leaf */

        while (current.left != null) {
            current = current.left;
        }
        return current;
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        Node root = null, temp = null, suc = null, min = null;
        root = tree.insert(root, 20);
        root = tree.insert(root, 8);
        root = tree.insert(root, 22);
        root = tree.insert(root, 4);
        root = tree.insert(root, 12);
        root = tree.insert(root, 10);
        root = tree.insert(root, 14);
        temp = root.left.right.right;
        suc = tree.inOrderSuccessor(root, temp);
        if (suc != null) {
            System.out.println(
                "Inorder successor of "
                + temp.data + " is " + suc.data);
        }
        else {
            System.out.println(
                "Inorder successor does not exist");
        }
    }
}

/*Java program to find predecessor
and successor in a BST*/

import java.util.*;
class GFG
{

/*BST Node*/

static class Node
{
    int key;
    Node left, right;
};
static Node pre;
static Node suc;

/*Function that finds predecessor
and successor of key in BST.*/

static void findPreSuc(Node root, int key)
{
    if (root == null)
        return;

/*    Search for given key in BST.*/

    while (root != null)
    {

/*        If root is given key.*/

        if (root.key == key)
        {

/*            the minimum value in right subtree
            is successor.*/

            if (root.right != null)
            {
                suc = root.right;
                while (suc.left != null)
                    suc = suc.left;
            }

/*            the maximum value in left subtree
            is predecessor.*/

            if (root.left != null)
            {
                pre = root.left;
                while (pre.right != null)
                    pre = pre.right;
            }
            return;
        }

/*        If key is greater than root, then
        key lies in right subtree. Root
        could be predecessor if left
        subtree of key is null.*/

        else if (root.key < key)
        {
            pre = root;
            root = root.right;
        }

/*        If key is smaller than root, then
        key lies in left subtree. Root
        could be successor if right
        subtree of key is null.*/

        else
        {
            suc = root;
            root = root.left;
        }
    }
}

/*A utility function to create a new BST node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = temp.right = null;
    return temp;
}

/*A utility function to insert
a new node with given key in BST*/

static Node insert(Node node, int key)
{
    if (node == null)
        return newNode(key);
    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);
    return node;
}

/*Driver Code*/

public static void main(String[] args)
{

/*Key to be searched in BST*/

int key = 65;

/* Let us create following BST
                50
                / \
            / \
            30     70
            / \     / \
            / \ / \
        20 40 60 80
    */

    Node root = null;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);
    findPreSuc(root, key);
    if (pre != null)
        System.out.println("Predecessor is " +
                                     pre.key);
    else
        System.out.print("-1");
    if (suc != null)
        System.out.print("Successor is " + suc.key);
    else
        System.out.print("-1");
    }
}

/*Java code to find a pair with given sum
in a Balanced BST*/

import java.util.ArrayList;

/*A binary tree node*/

class Node {
    int data;
    Node left, right;
    Node(int d)
    {
        data = d;
        left = right = null;
    }
}
class BinarySearchTree {

/*    Root of BST*/

    Node root;

/*    Constructor*/

    BinarySearchTree()
    {
        root = null;
    }

/*    Inorder traversal of the tree*/

    void inorder()
    {
        inorderUtil(this.root);
    }

/*    Utility function for inorder traversal of the tree*/

    void inorderUtil(Node node)
    {
        if (node == null)
            return;
        inorderUtil(node.left);
        System.out.print(node.data + " ");
        inorderUtil(node.right);
    }

/*    This method mainly calls insertRec()*/

    void insert(int key)
    {
        root = insertRec(root, key);
    }

/* A recursive function to insert a new key in BST */

    Node insertRec(Node root, int data)
    {

/* If the tree is empty, return a new node */

        if (root == null) {
            root = new Node(data);
            return root;
        }

/* Otherwise, recur down the tree */

        if (data < root.data)
            root.left = insertRec(root.left, data);
        else if (data > root.data)
            root.right = insertRec(root.right, data);
        return root;
    }

/*    Method that adds values of given BST into ArrayList
    and hence returns the ArrayList*/

    ArrayList<Integer> treeToList(Node node, ArrayList<Integer>
                                                 list)
    {

/*        Base Case*/

        if (node == null)
            return list;
        treeToList(node.left, list);
        list.add(node.data);
        treeToList(node.right, list);
        return list;
    }

/*    method that checks if there is a pair present*/

    boolean isPairPresent(Node node, int target)
    {

/*        This list a1 is passed as an argument
        in treeToList method
        which is later on filled by the values of BST*/

        ArrayList<Integer> a1 = new ArrayList<>();

/*        a2 list contains all the values of BST
        returned by treeToList method*/

        ArrayList<Integer> a2 = treeToList(node, a1);

/*Starting index of a2*/

int start = 0;

/*Ending index of a2*/

int end = a2.size() - 1; 
        while (start < end) {

/*Target Found!*/

if (a2.get(start) + a2.get(end) == target) 
            {
                System.out.println("Pair Found: " + a2.get(start) + " + " + a2.get(end) + " "
                                   + "= " + target);
                return true;
            }

/*decrements end*/

if (a2.get(start) + a2.get(end) > target) 
            {
                end--;
            }

/*increments start*/

if (a2.get(start) + a2.get(end) < target) 
            {
                start++;
            }
        }
        System.out.println("No such values are found!");
        return false;
    }

/*    Driver function*/

    public static void main(String[] args)
    {
        BinarySearchTree tree = new BinarySearchTree();

/*
                   15
                /     \
              10      20
             / \     /  \
            8  12   16  25    */

        tree.insert(15);
        tree.insert(10);
        tree.insert(20);
        tree.insert(8);
        tree.insert(12);
        tree.insert(16);
        tree.insert(25);
        tree.isPairPresent(tree.root, 33);
    }
}

/* In a balanced binary search tree
isPairPresent two element which sums to
a given value time O(n) space O(logn) */

import java.util.*;
class GFG
{
static final int MAX_SIZE= 100;

/*A BST node*/

static class node
{
    int val;
    node left, right;
};

/*Stack type*/

static class Stack
{
    int size;
    int top;
    node []array;
};

/*A utility function to create a stack of given size*/

static Stack createStack(int size)
{
    Stack stack = new Stack();
    stack.size = size;
    stack.top = -1;
    stack.array = new node[stack.size];
    return stack;
}

/*BASIC OPERATIONS OF STACK*/

static int isFull(Stack stack)
{
    return (stack.top - 1 == stack.size)?1:0 ;
}
static int isEmpty(Stack stack)
{
    return stack.top == -1?1:0;
}
static void push(Stack stack, node node)
{
    if (isFull(stack)==1)
        return;
    stack.array[++stack.top] = node;
}
static node pop(Stack stack)
{
    if (isEmpty(stack) == 1)
        return null;
    return stack.array[stack.top--];
}

/*Returns true if a pair with target
sum exists in BST, otherwise false*/

static boolean isPairPresent(node root, int target)
{

/*    Create two stacks. s1 is used for
    normal inorder traversal and s2 is
    used for reverse inorder traversal*/

    Stack s1 = createStack(MAX_SIZE);
    Stack s2 = createStack(MAX_SIZE);

/*    Note the sizes of stacks is MAX_SIZE,
    we can find the tree size and fix stack size
    as O(Logn) for balanced trees like AVL and Red Black
    tree. We have used MAX_SIZE to keep the code simple
    done1, val1 and curr1 are used for
    normal inorder traversal using s1
    done2, val2 and curr2 are used for
    reverse inorder traversal using s2*/

    boolean done1 = false, done2 = false;
    int val1 = 0, val2 = 0;
    node curr1 = root, curr2 = root;

/*    The loop will break when we either
  find a pair or one of the two
    traversals is complete*/

    while (true)
    {

/*        Find next node in normal Inorder
        traversal. See following post
www.geeksforgeeks.org/inorder-tree-traversal-without-recursion/
https:*/

        while (done1 == false)
        {
            if (curr1 != null)
            {
                push(s1, curr1);
                curr1 = curr1.left;
            }
            else
            {
                if (isEmpty(s1) == 1)
                    done1 = true;
                else
                {
                    curr1 = pop(s1);
                    val1 = curr1.val;
                    curr1 = curr1.right;
                    done1 = true;
                }
            }
        }

/*        Find next node in REVERSE Inorder traversal. The only
        difference between above and below loop is, in below loop
        right subtree is traversed before left subtree*/

        while (done2 == false)
        {
            if (curr2 != null)
            {
                push(s2, curr2);
                curr2 = curr2.right;
            }
            else {
                if (isEmpty(s2) == 1)
                    done2 = true;
                else {
                    curr2 = pop(s2);
                    val2 = curr2.val;
                    curr2 = curr2.left;
                    done2 = true;
                }
            }
        }

/*        If we find a pair, then print the pair and return. The first
        condition makes sure that two same values are not added*/

        if ((val1 != val2) && (val1 + val2) == target)
        {
            System.out.print("Pair Found: " +
                             val1+ "+ " +
                             val2+ " = " + 
                             target +"\n");
            return true;
        }

/*        If sum of current values is smaller,
        then move to next node in
        normal inorder traversal*/

        else if ((val1 + val2) < target)
            done1 = false;

/*        If sum of current values is greater,
        then move to next node in
        reverse inorder traversal*/

        else if ((val1 + val2) > target)
            done2 = false;

/*        If any of the inorder traversals is
        over, then there is no pair
        so return false*/

        if (val1 >= val2)
            return false;
    }
}

/*A utility function to create BST node*/

static node NewNode(int val)
{
    node tmp = new node();
    tmp.val = val;
    tmp.right = tmp.left = null;
    return tmp;
}

/*Driver program to test above functions*/

public static void main(String[] args)
{

/*
                15
                / \
            10 20
            / \ / \
            8 12 16 25 */

    node root = NewNode(15);
    root.left = NewNode(10);
    root.right = NewNode(20);
    root.left.left = NewNode(8);
    root.left.right = NewNode(12);
    root.right.left = NewNode(16);
    root.right.right = NewNode(25);
    int target = 33;
    if (isPairPresent(root, target) == false)
        System.out.print("\nNo such values are found\n");
}
}

/*Java program to find maximum element in the path
between two Nodes of Binary Search Tree.*/

class Solution
{
static class Node
{
     Node left, right;
    int data;
}

/*Create and return a pointer of new Node.*/

static Node createNode(int x)
{
    Node p = new Node();
    p . data = x;
    p . left = p . right = null;
    return p;
}

/*Insert a new Node in Binary Search Tree.*/

static void insertNode( Node root, int x)
{
    Node p = root, q = null;
    while (p != null)
    {
        q = p;
        if (p . data < x)
            p = p . right;
        else
            p = p . left;
    }
    if (q == null)
        p = createNode(x);
    else
    {
        if (q . data < x)
            q . right = createNode(x);
        else
            q . left = createNode(x);
    }
}

/*Return the maximum element between a Node
and its given ancestor.*/

static int maxelpath(Node q, int x)
{
    Node p = q;
    int mx = -1;

/*    Traversing the path between ansector and
    Node and finding maximum element.*/

    while (p . data != x)
    {
        if (p . data > x)
        {
            mx = Math.max(mx, p . data);
            p = p . left;
        }
        else
        {
            mx = Math.max(mx, p . data);
            p = p . right;
        }
    }
    return Math.max(mx, x);
}

/*Return maximum element in the path between
two given Node of BST.*/

static int maximumElement( Node root, int x, int y)
{
    Node p = root;

/*    Finding the LCA of Node x and Node y*/

    while ((x < p . data && y < p . data) ||
        (x > p . data && y > p . data))
    {

/*        Checking if both the Node lie on the
        left side of the parent p.*/

        if (x < p . data && y < p . data)
            p = p . left;

/*        Checking if both the Node lie on the
        right side of the parent p.*/

        else if (x > p . data && y > p . data)
            p = p . right;
    }

/*    Return the maximum of maximum elements occur
    in path from ancestor to both Node.*/

    return Math.max(maxelpath(p, x), maxelpath(p, y));
}

/*Driver Code*/

public static void main(String args[])
{
    int arr[] = { 18, 36, 9, 6, 12, 10, 1, 8 };
    int a = 1, b = 10;
    int n =arr.length;

/*    Creating the root of Binary Search Tree*/

     Node root = createNode(arr[0]);

/*    Inserting Nodes in Binary Search Tree*/

    for (int i = 1; i < n; i++)
        insertNode(root, arr[i]);
    System.out.println( maximumElement(root, a, b) );
}
}

/*Recursive Java program to find key closest to k
in given Binary Search Tree.*/

 class solution
 {
     static int min_diff, min_diff_key;

/*  A binary tree node has key, pointer to left child
and a pointer to right child */

static class Node
{
    int key;
     Node  left,  right;
};

/*  Utility that allocates a new node with the
  given key and null left and right pointers.  */

 static Node  newnode(int key)
{
     Node  node = new Node();
    node.key = key;
    node.left = node.right  = null;
    return (node);
}

/*Function to find node with minimum absolute
difference with given K
min_diff   -. minimum difference till now
min_diff_key  -. node having minimum absolute
                   difference with K*/

static void maxDiffUtil(Node  ptr, int k)
{
    if (ptr == null)
        return ;

/*    If k itself is present*/

    if (ptr.key == k)
    {
        min_diff_key = k;
        return;
    }

/*    update min_diff and min_diff_key by checking
    current node value*/

    if (min_diff > Math.abs(ptr.key - k))
    {
        min_diff = Math.abs(ptr.key - k);
        min_diff_key = ptr.key;
    }

/*    if k is less than ptr.key then move in
    left subtree else in right subtree*/

    if (k < ptr.key)
        maxDiffUtil(ptr.left, k);
    else
        maxDiffUtil(ptr.right, k);
}

/*Wrapper over maxDiffUtil()*/

static int maxDiff(Node  root, int k)
{

/*    Initialize minimum difference*/

    min_diff = 999999999; min_diff_key = -1;

/*    Find value of min_diff_key (Closest key
    in tree with k)*/

    maxDiffUtil(root, k);
    return min_diff_key;
}

/*Driver program to run the case*/

public static void main(String args[])
{
     Node  root = newnode(9);
    root.left    = newnode(4);
    root.right   = newnode(17);
    root.left.left = newnode(3);
    root.left.right = newnode(6);
    root.left.right.left = newnode(5);
    root.left.right.right = newnode(7);
    root.right.right = newnode(22);
    root.right.right.left = newnode(20);
    int k = 18;
    System.out.println( maxDiff(root, k));
}
}

/*Java program to implement insert operation
in Red Black Tree.*/

class node
{
    node left, right;
    int data;

/*    red ==> true, black ==> false*/

    boolean color; 
    node(int data)
    {
        this.data = data;
        left = null;
        right = null;

/*        New Node which is created is
        always red in color.*/

        color = true;
    }
}
public class LLRBTREE {
    private static node root = null;

/*    utility function to rotate node anticlockwise.*/

    node rotateLeft(node myNode)
    {
        System.out.printf("left rotation!!\n");
        node child = myNode.right;
        node childLeft = child.left;
        child.left = myNode;
        myNode.right = childLeft;
        return child;
    }

/*    utility function to rotate node clockwise.*/

    node rotateRight(node myNode)
    {
        System.out.printf("right rotation\n");
        node child = myNode.left;
        node childRight = child.right;
        child.right = myNode;
        myNode.left = childRight;
        return child; 
    }

/*    utility function to check whether
    node is red in color or not.*/

    boolean isRed(node myNode)
    {
        if (myNode == null) 
            return false;
        return (myNode.color == true);
    }

/*    utility function to swap color of two 
    nodes.*/

    void swapColors(node node1, node node2)
    {
        boolean temp = node1.color;
        node1.color = node2.color;
        node2.color = temp;
    }

/*    insertion into Left Leaning Red Black Tree.*/

    node insert(node myNode, int data)
    {

/*        Normal insertion code for any Binary
        Search tree. */

        if (myNode == null) 
            return new node(data); 
        if (data < myNode.data) 
            myNode.left = insert(myNode.left, data);
        else if (data > myNode.data) 
            myNode.right = insert(myNode.right, data);
        else
            return myNode;

/*        case 1.
        when right child is Red but left child is
        Black or doesn't exist.*/

        if (isRed(myNode.right) && !isRed(myNode.left))
        {

/*            left rotate the node to make it into
            valid structure.*/

            myNode = rotateLeft(myNode);

/*            swap the colors as the child node 
            should always be red*/

            swapColors(myNode, myNode.left);
        }

/*        case 2
        when left child as well as left grand child in Red*/

        if (isRed(myNode.left) && isRed(myNode.left.left))
        {

/*            right rotate the current node to make 
            it into a valid structure.*/

            myNode = rotateRight(myNode);
            swapColors(myNode, myNode.right);
        }

/*        case 3
        when both left and right child are Red in color.*/

        if (isRed(myNode.left) && isRed(myNode.right))
        {

/*            invert the color of node as well 
            it's left and right child.*/

            myNode.color = !myNode.color;

/*            change the color to black.*/

            myNode.left.color = false;
            myNode.right.color = false; 
        }
        return myNode;
    }

/*    Inorder traversal*/

    void inorder(node node)
    {
        if (node != null)
        {
            inorder(node.left);
            System.out.print(node.data + " ");
            inorder(node.right); 
        }
    }

/*Driver Code*/

    public static void main(String[] args) {

/* LLRB tree made after all insertions are made.

    1. Nodes which have double INCOMING edge means
       that they are RED in color.
    2. Nodes which have single INCOMING edge means
       that they are BLACK in color.

        root
         |
         40
       //  \
      20    50
     /  \
   10    30
        //
       25    */

    LLRBTREE node = new LLRBTREE();
    root = node.insert(root, 10);

/*    to make sure that root remains
    black is color*/

    root.color = false;
    root = node.insert(root, 20);
    root.color = false;
    root = node.insert(root, 30);
    root.color = false;
    root = node.insert(root, 40);
    root.color = false;
    root = node.insert(root, 50);
    root.color = false; 
    root = node.insert(root, 25);
    root.color = false;

/*    display the tree through inorder traversal.*/

    node.inorder(root);
    }
}

/*Java program Insertion in Threaded Binary Search Tree.*/

import java.util.*;
class solution
{
static class Node
{
     Node left, right;
    int info;

/*    True if left pointer points to predecessor
    in Inorder Traversal*/

    boolean lthread;

/*    True if right pointer points to successor
    in Inorder Traversal*/

    boolean rthread;
};

/*Insert a Node in Binary Threaded Tree*/

static Node insert( Node root, int ikey)
{

/*    Searching for a Node with given value*/

    Node ptr = root;

/*Parent of key to be inserted*/

Node par = null; 
    while (ptr != null)
    {

/*        If key already exists, return*/

        if (ikey == (ptr.info))
        {
            System.out.printf("Duplicate Key !\n");
            return root;
        }

/*Update parent pointer*/

par = ptr;

/*        Moving on left subtree.*/

        if (ikey < ptr.info)
        {
            if (ptr . lthread == false)
                ptr = ptr . left;
            else
                break;
        }

/*        Moving on right subtree.*/

        else
        {
            if (ptr.rthread == false)
                ptr = ptr . right;
            else
                break;
        }
    }

/*    Create a new node*/

    Node tmp = new Node();
    tmp . info = ikey;
    tmp . lthread = true;
    tmp . rthread = true;
    if (par == null)
    {
        root = tmp;
        tmp . left = null;
        tmp . right = null;
    }
    else if (ikey < (par . info))
    {
        tmp . left = par . left;
        tmp . right = par;
        par . lthread = false;
        par . left = tmp;
    }
    else
    {
        tmp . left = par;
        tmp . right = par . right;
        par . rthread = false;
        par . right = tmp;
    }
    return root;
}

/*Returns inorder successor using rthread*/

static  Node inorderSuccessor( Node ptr)
{

/*    If rthread is set, we can quickly find*/

    if (ptr . rthread == true)
        return ptr.right;

/*    Else return leftmost child of right subtree*/

    ptr = ptr . right;
    while (ptr . lthread == false)
        ptr = ptr . left;
    return ptr;
}

/*Printing the threaded tree*/

static void inorder( Node root)
{
    if (root == null)
        System.out.printf("Tree is empty");

/*    Reach leftmost node*/

     Node ptr = root;
    while (ptr . lthread == false)
        ptr = ptr . left;

/*    One by one print successors*/

    while (ptr != null)
    {
        System.out.printf("%d ",ptr . info);
        ptr = inorderSuccessor(ptr);
    }
}

/*Driver Program*/

public static void main(String[] args)
{
     Node root = null;
    root = insert(root, 20);
    root = insert(root, 10);
    root = insert(root, 30);
    root = insert(root, 5);
    root = insert(root, 16);
    root = insert(root, 14);
    root = insert(root, 17);
    root = insert(root, 13);
    inorder(root);
} 
}

/*Here 'par' is pointer to parent Node and 'ptr' is
pointer to current Node.*/

Node caseA(Node root, Node par,
                   Node ptr)
{

/*    If Node to be deleted is root*/

    if (par == null)
        root = null;

/*    If Node to be deleted is left
    of its parent*/

    else if (ptr == par.left) {
        par.lthread = true;
        par.left = ptr.left;
    }
    else {
        par.rthread = true;
        par.right = ptr.right;
    }
    return root;
}

/*Here 'par' is pointer to parent Node and 'ptr' is
pointer to current Node.*/

static Node caseB(Node root, Node par,
                   Node ptr)
{
    Node child;

/*    Initialize child Node to be deleted has
    left child.*/

    if (ptr.lthread == false)
        child = ptr.left;

/*    Node to be deleted has right child.*/

    else
        child = ptr.right;

/*    Node to be deleted is root Node.*/

    if (par == null)
        root = child;

/*    Node is left child of its parent.*/

    else if (ptr == par.left)
        par.left = child;
    else
        par.right = child;

/*    Find successor and predecessor*/

    Node s = inSucc(ptr);
    Node p = inPred(ptr);

/*    If ptr has left subtree.*/

    if (ptr.lthread == false)
        p.right = s;

/*    If ptr has right subtree.*/

    else {
        if (ptr.rthread == false)
            s.left = p;
    }
    return root;
}

/*Complete Java program to demonstrate deletion
in threaded BST*/

import java.util.*;
class solution {
    static class Node {
        Node left, right;
        int info;

/*        True if left pointer points to predecessor
        in Inorder Traversal*/

        boolean lthread;

/*        True if right pointer points to predecessor
        in Inorder Traversal*/

        boolean rthread;
    };

/*    Insert a Node in Binary Threaded Tree*/

    static Node insert(Node root, int ikey)
    {

/*        Searching for a Node with given value*/

        Node ptr = root;

/*Parent of key to be inserted*/

Node par = null; 
        while (ptr != null) {

/*            If key already exists, return*/

            if (ikey == (ptr.info)) {
                System.out.printf("Duplicate Key !\n");
                return root;
            }

/*Update parent pointer*/

par = ptr;

/*            Moving on left subtree.*/

            if (ikey < ptr.info) {
                if (ptr.lthread == false)
                    ptr = ptr.left;
                else
                    break;
            }

/*            Moving on right subtree.*/

            else {
                if (ptr.rthread == false)
                    ptr = ptr.right;
                else
                    break;
            }
        }

/*        Create a new Node*/

        Node tmp = new Node();
        tmp.info = ikey;
        tmp.lthread = true;
        tmp.rthread = true;
        if (par == null) {
            root = tmp;
            tmp.left = null;
            tmp.right = null;
        }
        else if (ikey < (par.info)) {
            tmp.left = par.left;
            tmp.right = par;
            par.lthread = false;
            par.left = tmp;
        }
        else {
            tmp.left = par;
            tmp.right = par.right;
            par.rthread = false;
            par.right = tmp;
        }
        return root;
    }

/*    Returns inorder successor using left
    and right children (Used in deletion)*/

    static Node inSucc(Node ptr)
    {
        if (ptr.rthread == true)
            return ptr.right;
        ptr = ptr.right;
        while (ptr.lthread == false)
            ptr = ptr.left;
        return ptr;
    }

/*    Returns inorder successor using rthread
    (Used in inorder)*/

    static Node inorderSuccessor(Node ptr)
    {

/*        If rthread is set, we can quickly find*/

        if (ptr.rthread == true)
            return ptr.right;

/*        Else return leftmost child of right subtree*/

        ptr = ptr.right;
        while (ptr.lthread == false)
            ptr = ptr.left;
        return ptr;
    }

/*    Printing the threaded tree*/

    static void inorder(Node root)
    {
        if (root == null)
            System.out.printf("Tree is empty");

/*        Reach leftmost Node*/

        Node ptr = root;
        while (ptr.lthread == false)
            ptr = ptr.left;

/*        One by one print successors*/

        while (ptr != null) {
            System.out.printf("%d ", ptr.info);
            ptr = inorderSuccessor(ptr);
        }
    }
    static Node inPred(Node ptr)
    {
        if (ptr.lthread == true)
            return ptr.left;
        ptr = ptr.left;
        while (ptr.rthread == false)
            ptr = ptr.right;
        return ptr;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseA(Node root, Node par,
                      Node ptr)
    {

/*        If Node to be deleted is root*/

        if (par == null)
            root = null;

/*        If Node to be deleted is left
        of its parent*/

        else if (ptr == par.left) {
            par.lthread = true;
            par.left = ptr.left;
        }
        else {
            par.rthread = true;
            par.right = ptr.right;
        }
        return root;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseB(Node root, Node par,
                      Node ptr)
    {
        Node child;

/*        Initialize child Node to be deleted has
        left child.*/

        if (ptr.lthread == false)
            child = ptr.left;

/*        Node to be deleted has right child.*/

        else
            child = ptr.right;

/*        Node to be deleted is root Node.*/

        if (par == null)
            root = child;

/*        Node is left child of its parent.*/

        else if (ptr == par.left)
            par.left = child;
        else
            par.right = child;

/*        Find successor and predecessor*/

        Node s = inSucc(ptr);
        Node p = inPred(ptr);

/*        If ptr has left subtree.*/

        if (ptr.lthread == false)
            p.right = s;

/*        If ptr has right subtree.*/

        else {
            if (ptr.rthread == false)
                s.left = p;
        }
        return root;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseC(Node root, Node par,
                      Node ptr)
    {

/*        Find inorder successor and its parent.*/

        Node parsucc = ptr;
        Node succ = ptr.right;

/*        Find leftmost child of successor*/

        while (succ.lthread == false) {
            parsucc = succ;
            succ = succ.left;
        }
        ptr.info = succ.info;
        if (succ.lthread == true && succ.rthread == true)
            root = caseA(root, parsucc, succ);
        else
            root = caseB(root, parsucc, succ);
        return root;
    }

/*    Deletes a key from threaded BST with given root and
    returns new root of BST.*/

    static Node delThreadedBST(Node root, int dkey)
    {

/*        Initialize parent as null and ptrent
        Node as root.*/

        Node par = null, ptr = root;

/*        Set true if key is found*/

        int found = 0;

/*        Search key in BST : find Node and its
        parent.*/

        while (ptr != null) {
            if (dkey == ptr.info) {
                found = 1;
                break;
            }
            par = ptr;
            if (dkey < ptr.info) {
                if (ptr.lthread == false)
                    ptr = ptr.left;
                else
                    break;
            }
            else {
                if (ptr.rthread == false)
                    ptr = ptr.right;
                else
                    break;
            }
        }
        if (found == 0)
            System.out.printf("dkey not present in tree\n");

/*        Two Children*/

        else if (ptr.lthread == false && ptr.rthread == false)
            root = caseC(root, par, ptr);

/*        Only Left Child*/

        else if (ptr.lthread == false)
            root = caseB(root, par, ptr);

/*        Only Right Child*/

        else if (ptr.rthread == false)
            root = caseB(root, par, ptr);

/*        No child*/

        else
            root = caseA(root, par, ptr);
        return root;
    }

/*    Driver Program*/

    public static void main(String args[])
    {
        Node root = null;
        root = insert(root, 20);
        root = insert(root, 10);
        root = insert(root, 30);
        root = insert(root, 5);
        root = insert(root, 16);
        root = insert(root, 14);
        root = insert(root, 17);
        root = insert(root, 13);
        root = delThreadedBST(root, 20);
        inorder(root);
    }
}

/* Java program to convert a Binary Tree to
    Threaded Tree */

import java.util.*;
class solution
{

/* structure of a node in threaded binary tree */

static class Node
{
    int key;
    Node left, right;

/*    Used to indicate whether the right pointer
    is a normal right pointer or a pointer
    to inorder successor.*/

    boolean isThreaded;
};

/*Converts tree with given root to threaded
binary tree.
This function returns rightmost child of
root.*/

static Node createThreaded(Node root)
{

/*    Base cases : Tree is empty or has single
                  node*/

    if (root == null)
        return null;
    if (root.left == null &&
        root.right == null)
        return root;

/*    Find predecessor if it exists*/

    if (root.left != null)
    {

/*        Find predecessor of root (Rightmost
        child in left subtree)*/

        Node l = createThreaded(root.left);

/*        Link a thread from predecessor to
        root.*/

        l.right = root;
        l.isThreaded = true;
    }

/*    If current node is rightmost child*/

    if (root.right == null)
        return root;

/*    Recur for right subtree.*/

    return createThreaded(root.right);
}

/*A utility function to find leftmost node
in a binary tree rooted with 'root'.
This function is used in inOrder()*/

static Node leftMost(Node root)
{
    while (root != null && root.left != null)
        root = root.left;
    return root;
}

/*Function to do inorder traversal of a threadded
binary tree*/

static void inOrder(Node root)
{
    if (root == null) return;

/*    Find the leftmost node in Binary Tree*/

    Node cur = leftMost(root);
    while (cur != null)
    {
        System.out.print(cur.key + " ");

/*        If this Node is a thread Node, then go to
        inorder successor*/

        if (cur.isThreaded)
            cur = cur.right;

/*Else go to the leftmost child in right subtree*/

else 
            cur = leftMost(cur.right);
    }
}

/*A utility function to create a new node*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.left = temp.right = null;
    temp.key = key;
    return temp;
}

/*Driver program to test above functions*/

public static void main(String args[])
{

/*       1
            / \
           2   3
          / \ / \
         4  5 6  7   */

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(6);
    root.right.right = newNode(7);
    createThreaded(root);
    System.out.println("Inorder traversal of created "+"threaded tree is\n");
    inOrder(root); 
}
}

/* Java program to print inorder traversal of a Binary Search Tree
   without recursion and stack */

/*BST node*/

class Node
{
    int key;
    Node left, right, parent;
    public Node(int key)
    {
        this.key = key;
        left = right = parent = null;
    }
}
class BinaryTree
{
    Node root;

/* A utility function to insert a new node with
       given key in BST */

    Node insert(Node node, int key)
    {

/* If the tree is empty, return a new node */

        if (node == null)
            return new Node(key);

/* Otherwise, recur down the tree */

        if (key < node.key)
        {
            node.left = insert(node.left, key);
            node.left.parent = node;
        }
        else if (key > node.key)
        {
            node.right = insert(node.right, key);
            node.right.parent = node;
        }

/* return the (unchanged) node pointer */

        return node;
    }

/*    Function to print inorder traversal using parent
    pointer*/

    void inorder(Node root)
    {
        boolean leftdone = false;

/*        Start traversal from root*/

        while (root != null)
        {

/*            If left child is not traversed, find the
            leftmost child*/

            if (!leftdone)
            {
                while (root.left != null)
                {
                    root = root.left;
                }
            }

/*            Print root's data*/

            System.out.print(root.key + " ");

/*            Mark left as done*/

            leftdone = true;

/*            If right child exists*/

            if (root.right != null)
            {
                leftdone = false;
                root = root.right;
            }

/*            If right child doesn't exist, move to parent*/

            else if (root.parent != null)
            {

/*                If this node is right child of its parent,
                visit parent's parent first*/

                while (root.parent != null
                        && root == root.parent.right)
                    root = root.parent;
                if (root.parent == null)
                    break;
                root = root.parent;
            }
            else
                break;
        }
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = tree.insert(tree.root, 24);
        tree.root = tree.insert(tree.root, 27);
        tree.root = tree.insert(tree.root, 29);
        tree.root = tree.insert(tree.root, 34);
        tree.root = tree.insert(tree.root, 14);
        tree.root = tree.insert(tree.root, 4);
        tree.root = tree.insert(tree.root, 10);
        tree.root = tree.insert(tree.root, 22);
        tree.root = tree.insert(tree.root, 13);
        tree.root = tree.insert(tree.root, 3);
        tree.root = tree.insert(tree.root, 2);
        tree.root = tree.insert(tree.root, 6);
        System.out.println("Inorder traversal is ");
        tree.inorder(tree.root);
    }
}

/*Java program to find ceil of a given value in BST*/

/* A binary tree node has key, left child and right child */

class Node {
    int data;
    Node left, right;
    Node(int d)
    {
        data = d;
        left = right = null;
    }
}
class BinaryTree {
    Node root;

/*    Function to find ceil of a given input in BST.
    If input is more than the max key in BST,
    return -1*/

    int Ceil(Node node, int input)
    {

/*        Base case*/

        if (node == null) {
            return -1;
        }

/*        We found equal key*/

        if (node.data == input) {
            return node.data;
        }

/*        If root's key is smaller,
        ceil must be in right subtree*/

        if (node.data < input) {
            return Ceil(node.right, input);
        }

/*        Else, either left subtree or root
        has the ceil value*/

        int ceil = Ceil(node.left, input);
        return (ceil >= input) ? ceil : node.data;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(8);
        tree.root.left = new Node(4);
        tree.root.right = new Node(12);
        tree.root.left.left = new Node(2);
        tree.root.left.right = new Node(6);
        tree.root.right.left = new Node(10);
        tree.root.right.right = new Node(14);
        for (int i = 0; i < 16; i++) {
            System.out.println(i + " " + tree.Ceil(tree.root, i));
        }
    }
}

/*Java program to find floor and ceil
of a given key in BST*/

import java.io.*;

/*A binary tree node has key,
left child and right child*/

class Node
{
    int data;
    Node left, right;
    Node(int d)
    {
        data = d;
        left = right = null;
    }
}
class BinaryTree{
Node root;
int floor;
int ceil;

/*Helper function to find floor and
ceil of a given key in BST*/

public void floorCeilBSTHelper(Node root,
                               int key)
{
    while (root != null)
    {
        if (root.data == key)
        {
            ceil = root.data;
            floor = root.data;
            return;
        }
        if (key > root.data)
        {
            floor = root.data;
            root = root.right;
        }
        else
        {
            ceil = root.data;
            root = root.left;
        }
    }
    return;
}

/*Display the floor and ceil of a
given key in BST. If key is less
than the min key in BST, floor
will be -1; If key is more than
the max key in BST, ceil will be -1;*/

public void floorCeilBST(Node root, int key)
{

/*    Variables 'floor' and 'ceil'
    are passed by reference*/

    floor = -1;
    ceil = -1;
    floorCeilBSTHelper(root, key);
    System.out.println(key + " " +
                     floor + " " + ceil);
}

/*Driver code*/

public static void main(String[] args)
{
    BinaryTree tree = new BinaryTree();
    tree.root = new Node(8);
    tree.root.left = new Node(4);
    tree.root.right = new Node(12);
    tree.root.left.left = new Node(2);
    tree.root.left.right = new Node(6);
    tree.root.right.left = new Node(10);
    tree.root.right.right = new Node(14);
    for(int i = 0; i < 16; i++)
    {
        tree.floorCeilBST(tree.root, i);
    }
}
}

/*Java program to implement basic operations
(search, insert and delete) on a BST that
handles duplicates by storing count with
every node*/

class GFG
{
static class node
{
    int key;
    int count;
    node left, right;
};

/*A utility function to create a new BST node*/

static node newNode(int item)
{
    node temp = new node();
    temp.key = item;
    temp.left = temp.right = null;
    temp.count = 1;
    return temp;
}

/*A utility function to do inorder traversal of BST*/

static void inorder(node root)
{
    if (root != null)
    {
        inorder(root.left);
        System.out.print(root.key + "(" +
                         root.count + ") ");
        inorder(root.right);
    }
}

/* A utility function to insert a new
node with given key in BST */

static node insert(node node, int key)
{

/* If the tree is empty, return a new node */

    if (node == null) return newNode(key);

/*    If key already exists in BST,
    increment count and return*/

    if (key == node.key)
    {
    (node.count)++;
        return node;
    }

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/* Given a non-empty binary search tree, return
the node with minimum key value found in that
tree. Note that the entire tree does not need
to be searched. */

static node minValueNode(node node)
{
    node current = node;

/* loop down to find the leftmost leaf */

    while (current.left != null)
        current = current.left;
    return current;
}

/* Given a binary search tree and a key,
this function deletes a given key and
returns root of modified tree */

static node deleteNode(node root, int key)
{

/*    base case*/

    if (root == null) return root;

/*    If the key to be deleted is smaller than the
    root's key, then it lies in left subtree*/

    if (key < root.key)
        root.left = deleteNode(root.left, key);

/*    If the key to be deleted is greater than
    the root's key, then it lies in right subtree*/

    else if (key > root.key)
        root.right = deleteNode(root.right, key);

/*    if key is same as root's key*/

    else
    {

/*        If key is present more than once,
        simply decrement count and return*/

        if (root.count > 1)
        {
            (root.count)--;
            return root;
        }

/*        ElSE, delete the node
        node with only one child or no child*/

        if (root.left == null)
        {
            node temp = root.right;
            root=null;
            return temp;
        }
        else if (root.right == null)
        {
            node temp = root.left;
            root = null;
            return temp;
        }

/*        node with two children: Get the inorder
        successor (smallest in the right subtree)*/

        node temp = minValueNode(root.right);

/*        Copy the inorder successor's
        content to this node*/

        root.key = temp.key;

/*        Delete the inorder successor*/

        root.right = deleteNode(root.right,
                                temp.key);
    }
    return root;
}

/*Driver Code*/

public static void main(String[] args)
{

/* Let us create following BST
            12(3)
        /     \
    10(2)     20(1)
    / \
    9(1) 11(1) */

    node root = null;
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 20);
    root = insert(root, 9);
    root = insert(root, 11);
    root = insert(root, 10);
    root = insert(root, 12);
    root = insert(root, 12);
    System.out.print("Inorder traversal of " +
                     "the given tree " + "\n");
    inorder(root);
    System.out.print("\nDelete 20\n");
    root = deleteNode(root, 20);
    System.out.print("Inorder traversal of " +
                     "the modified tree \n");
    inorder(root);
    System.out.print("\nDelete 12\n");
    root = deleteNode(root, 12);
    System.out.print("Inorder traversal of " +
                     "the modified tree \n");
    inorder(root);
    System.out.print("\nDelete 9\n");
    root = deleteNode(root, 9);
    System.out.print("Inorder traversal of " +
                     "the modified tree \n");
    inorder(root);
}
}

/*Java program to demonstrate decrease
key operation on binary search tree*/

class GfG
{
static class node
{
    int key;
    node left, right;
}
static node root = null;

/*A utility function to
create a new BST node*/

static node newNode(int item)
{
    node temp = new node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*A utility function to
do inorder traversal of BST*/

static void inorder(node root)
{
    if (root != null)
    {
        inorder(root.left);
        System.out.print(root.key + " ");
        inorder(root.right);
    }
}

/* A utility function to insert
a new node with given key in BST */

static node insert(node node, int key)
{

/* If the tree is empty, return a new node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/* Given a non-empty binary search tree,
return the node with minimum key value
found in that tree. Note that the entire
tree does not need to be searched. */

static node minValueNode(node Node)
{
    node current = Node;

/* loop down to find the leftmost leaf */

    while (current.left != null)
        current = current.left;
    return current;
}

/* Given a binary search tree and
a key, this function deletes the key
and returns the new root */

static node deleteNode(node root, int key)
{

/*    base case*/

    if (root == null) return root;

/*    If the key to be deleted is
    smaller than the root's key,
    then it lies in left subtree*/

    if (key < root.key)
        root.left = deleteNode(root.left, key);

/*    If the key to be deleted is
    greater than the root's key,
    then it lies in right subtree*/

    else if (key > root.key)
        root.right = deleteNode(root.right, key);

/*    if key is same as root's
    key, then This is the node
    to be deleted*/

    else
    {

/*        node with only one child or no child*/

        if (root.left == null)
        {
            node temp = root.right;
            return temp;
        }
        else if (root.right == null)
        {
            node temp = root.left;
            return temp;
        }

/*        node with two children: Get
        the inorder successor (smallest
        in the right subtree)*/

        node temp = minValueNode(root.right);

/*        Copy the inorder successor's
        content to this node*/

        root.key = temp.key;

/*        Delete the inorder successor*/

        root.right = deleteNode(root.right, temp.key);
    }
    return root;
}

/*Function to decrease a key
value in Binary Search Tree*/

static node changeKey(node root, int oldVal, int newVal)
{

/*    First delete old key value*/

    root = deleteNode(root, oldVal);

/*    Then insert new key value*/

    root = insert(root, newVal);

/*    Return new root*/

    return root;
}

/*Driver code*/

public static void main(String[] args)
{

/* Let us create following BST
            50
        / \
        30 70
        / \ / \
    20 40 60 80 */

    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 70);
    root = insert(root, 60);
    root = insert(root, 80);
    System.out.println("Inorder traversal of the given tree");
    inorder(root);
    root = changeKey(root, 40, 10);

/* BST is modified to
            50
        / \
        30 70
        / / \
    20 60 80
    /
    10 */

    System.out.println("\nInorder traversal of the modified tree ");
    inorder(root);
}
}

/*Java program of iterative traversal based method to 
find common elements in two BSTs.*/

import java.util.*;
class GfG {

/*A BST node */

static class Node 
{ 
    int key; 
    Node left, right; 
}

/*A utility function to create a new node */

static Node newNode(int ele) 
{ 
    Node temp = new Node(); 
    temp.key = ele; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/*Function two print common elements in given two trees */

static void printCommon(Node root1, Node root2) 
{

/*    Create two stacks for two inorder traversals*/

    Stack<Node> s1 = new Stack<Node> (); 
    Stack<Node> s2 = new Stack<Node> ();
    while (true) 
    {

/*        push the Nodes of first tree in stack s1 */

        if (root1 != null) 
        { 
            s1.push(root1); 
            root1 = root1.left; 
        }

/*        push the Nodes of second tree in stack s2 */

        else if (root2 != null) 
        { 
            s2.push(root2); 
            root2 = root2.left; 
        }

/*        Both root1 and root2 are NULL here */

        else if (!s1.isEmpty() && !s2.isEmpty()) 
        { 
            root1 = s1.peek(); 
            root2 = s2.peek();

/*            If current keys in two trees are same */

            if (root1.key == root2.key) 
            { 
                System.out.print(root1.key + " "); 
                s1.pop(); 
                s2.pop();

/*                move to the inorder successor */

                root1 = root1.right; 
                root2 = root2.right; 
            } 
            else if (root1.key < root2.key) 
            {

/*                If Node of first tree is smaller, than that of 
                second tree, then its obvious that the inorder 
                successors of current Node can have same value 
                as that of the second tree Node. Thus, we pop 
                from s2 */

                s1.pop(); 
                root1 = root1.right;

/*                root2 is set to NULL, because we need 
                new Nodes of tree 1 */

                root2 = null; 
            } 
            else if (root1.key > root2.key) 
            { 
                s2.pop(); 
                root2 = root2.right; 
                root1 = null; 
            } 
        }

/*        Both roots and both stacks are empty */

        else break; 
    } 
}

/*A utility function to do inorder traversal */

static void inorder(Node root) 
{ 
    if (root != null) 
    { 
        inorder(root.left); 
        System.out.print(root.key + " "); 
        inorder(root.right); 
    } 
}

/* A utility function to insert a new Node with given key in BST */

static Node insert(Node node, int key) 
{

/* If the tree is empty, return a new Node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key) 
        node.left = insert(node.left, key); 
    else if (key > node.key) 
        node.right = insert(node.right, key);

/* return the (unchanged) Node pointer */

    return node; 
}

/*Driver program */

public static void main(String[] args) 
{

/*    Create first tree as shown in example */

    Node root1 = null; 
    root1 = insert(root1, 5); 
    root1 = insert(root1, 1); 
    root1 = insert(root1, 10); 
    root1 = insert(root1, 0); 
    root1 = insert(root1, 4); 
    root1 = insert(root1, 7); 
    root1 = insert(root1, 9);

/*    Create second tree as shown in example */

    Node root2 = null; 
    root2 = insert(root2, 10); 
    root2 = insert(root2, 7); 
    root2 = insert(root2, 20); 
    root2 = insert(root2, 4); 
    root2 = insert(root2, 9); 
    System.out.print("Tree 1 : " + "\n"); 
    inorder(root1); 
    System.out.println();
    System.out.print("Tree 2 : " + "\n"); 
    inorder(root2); 
    System.out.println();
    System.out.println("Common Nodes: ");
    printCommon(root1, root2); 
}
}

/*Java program to print leaf node from
preorder of binary search tree.*/

import java.util.*;
class GFG
{

/*Binary Search*/

static int binarySearch(int inorder[], int l, 
                        int r, int d)
{
    int mid = (l + r) >> 1;
    if (inorder[mid] == d)
        return mid;
    else if (inorder[mid] > d)
        return binarySearch(inorder, l,
                            mid - 1, d);
    else
        return binarySearch(inorder, 
                            mid + 1, r, d);
}

/*Point to the index in preorder.*/

static int ind;

/*Function to print Leaf Nodes by 
doing preorder traversal of tree
using preorder and inorder arrays.*/

static void leafNodesRec(int preorder[], 
                         int inorder[],
                         int l, int r, int n)
{

/*    If l == r, therefore no right or left subtree.
    So, it must be leaf Node, print it.*/

    if(l == r)
    {
        System.out.printf("%d ", inorder[l]);
        ind = ind + 1;
        return;
    }

/*    If array is out of bound, return.*/

    if (l < 0 || l > r || r >= n)
        return;

/*    Finding the index of preorder element
    in inorder array using binary search.*/

    int loc = binarySearch(inorder, l, r, 
                           preorder[ind]);

/*    Incrementing the index.*/

    ind = ind + 1;

/*    Finding on the left subtree.*/

    leafNodesRec(preorder, inorder,
                    l, loc - 1, n);

/*    Finding on the right subtree.*/

    leafNodesRec(preorder, inorder, 
                    loc + 1, r, n);
}

/*Finds leaf nodes from given preorder traversal.*/

static void leafNodes(int preorder[], int n)
{

/*    To store inorder traversal*/

    int inorder[] = new int[n];

/*    Copy the preorder into another array.*/

    for (int i = 0; i < n; i++)
        inorder[i] = preorder[i];

/*    Finding the inorder by sorting the array.*/

    Arrays.sort(inorder);

/*    Print the Leaf Nodes.*/

    leafNodesRec(preorder, inorder, 0, n - 1, n);
}

/*Driver Code*/

public static void main(String args[])
{
    int preorder[] = { 890, 325, 290, 530, 965 };
    int n = preorder.length;
    leafNodes(preorder, n);
}
}

/*Stack based Java program to print leaf nodes 
from preorder traversal.*/

import java.util.*;
class GfG {

/*Print the leaf node from the given preorder of BST. */

static void leafNode(int preorder[], int n) 
{ 
    Stack<Integer> s = new Stack<Integer> (); 
    for (int i = 0, j = 1; j < n; i++, j++) 
    { 
        boolean found = false; 
        if (preorder[i] > preorder[j]) 
            s.push(preorder[i]); 
        else
        { 
            while (!s.isEmpty()) 
            { 
                if (preorder[j] > s.peek()) 
                { 
                    s.pop(); 
                    found = true; 
                } 
                else
                    break; 
            } 
        } 
        if (found) 
            System.out.print(preorder[i] + " "); 
    }

/*    Since rightmost element is always leaf node. */

    System.out.println(preorder[n - 1]); 
}

/*Driver code */

public static void main(String[] args) 
{ 
    int preorder[] = { 890, 325, 290, 530, 965 }; 
    int n = preorder.length; 
    leafNode(preorder, n); 
} 
}

/*Recursive Java program to find leaf
nodes from given preorder traversal*/

class GFG
{
    static int i = 0;

/*    Print the leaf node from
    the given preorder of BST.*/

    static boolean isLeaf(int pre[], int n,
            int min, int max)
    {
        if (i >= n)
        {
            return false;
        }
        if (pre[i] > min && pre[i] < max)
        {
            i++;
            boolean left = isLeaf(pre, n, min, pre[i - 1]);
            boolean right = isLeaf(pre, n, pre[i - 1], max);
            if (!left && !right)
            {
                System.out.print(pre[i - 1] + " ");
            }
            return true;
        }
        return false;
    }
    static void printLeaves(int preorder[], int n)
    {
        isLeaf(preorder, n, Integer.MIN_VALUE,
                            Integer.MAX_VALUE);
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int preorder[] = {890, 325, 290, 530, 965};
        int n = preorder.length;
        printLeaves(preorder, n);
    }
}

/*Java program to demonstrate insert operation
in binary search tree with parent pointer*/

class GfG {

/*Node structure*/

static class Node
{
    int key;
    Node left, right, parent;
}

/*A utility function to create a new BST Node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    temp.parent = null;
    return temp;
}

/*A utility function to do inorder traversal of BST*/

static void inorder(Node root)
{
    if (root != null)
    {
        inorder(root.left);
        System.out.print("Node : "+ root.key + " , ");
        if (root.parent == null)
        System.out.println("Parent : NULL");
        else
        System.out.println("Parent : " + root.parent.key);
        inorder(root.right);
    }
}

/* A utility function to insert a new Node with
given key in BST */

static Node insert(Node node, int key)
{

/* If the tree is empty, return a new Node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
    {
        Node lchild = insert(node.left, key);
        node.left = lchild;

/*        Set parent of root of left subtree*/

        lchild.parent = node;
    }
    else if (key > node.key)
    {
        Node rchild = insert(node.right, key);
        node.right = rchild;

/*        Set parent of root of right subtree*/

        rchild.parent = node;
    }

/* return the (unchanged) Node pointer */

    return node;
}

/*Driver Program to test above functions*/

public static void main(String[] args)
{

/* Let us create following BST
            50
        /     \
        30     70
        / \ / \
    20 40 60 80 */

    Node root = null;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);

/*    print iNoder traversal of the BST*/

    inorder(root);
}
}

/*Java program to find rank of an
element in a stream.*/

class GfG {
static class Node {
    int data;
    Node left, right;
    int leftSize;
}
static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = null;
    temp.right = null;
    temp.leftSize = 0;
    return temp;
}

/*Inserting a new Node.*/

static Node insert(Node root, int data)
{
    if (root == null)
        return newNode(data);

/*    Updating size of left subtree.*/

    if (data <= root.data) {
        root.left = insert(root.left, data);
        root.leftSize++;
    }
    else
        root.right = insert(root.right, data);
    return root;
}

/*Function to get Rank of a Node x.*/

static int getRank(Node root, int x)
{

/*    Step 1.*/

    if (root.data == x)
        return root.leftSize;

/*    Step 2.*/

    if (x < root.data) {
        if (root.left == null)
            return -1;
        else
            return getRank(root.left, x);
    }

/*    Step 3.*/

    else {
        if (root.right == null)
            return -1;
        else {
            int rightSize = getRank(root.right, x);
          if(rightSize == -1) return -1;
            return root.leftSize + 1 + rightSize;
        }
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 5, 1, 4, 4, 5, 9, 7, 13, 3 };
    int n = arr.length;
    int x = 4;
    Node root = null;
    for (int i = 0; i < n; i++)
        root = insert(root, arr[i]);
    System.out.println("Rank of " + x + " in stream is : "+getRank(root, x));
    x = 13;
    System.out.println("Rank of " + x + " in stream is : "+getRank(root, x));
}
}

/*Java program to find rank of an
element in a stream.*/

class GFG
