/*Java program to count number of nodes in
BST containing two digit special number*/

/*A binary tree node*/

class Node
{
    int info;
    Node left, right;
    Node(int d)
    {
        info = d;
        left = right = null;
    }
}
class BinaryTree{
static Node head;
static int count;

/*Function to create a new node*/

Node insert(Node node, int info)
{

/*    If the tree is empty, return a new,
    single node*/

    if (node == null)
    {
        return (new Node(info));
    }
    else
    {

/*        Otherwise, recur down the tree*/

        if (info <= node.info)
        {
            node.left = insert(node.left, info);
        }
        else
        {
            node.right = insert(node.right, info);
        }

/*        return the (unchanged) node pointer*/

        return node;
    }
}

/*Function to find if number
is special or not*/

static int check(int num)
{
    int sum = 0, i = num,
        sum_of_digits,
        prod_of_digits;

/*    Check if number is two digit or not*/

    if (num < 10 || num > 99)
        return 0;
    else
    {
        sum_of_digits = (i % 10) + (i / 10);
        prod_of_digits = (i % 10) * (i / 10);
        sum = sum_of_digits + prod_of_digits;
    }
    if (sum == num)
        return 1;
    else
        return 0;
}

/*Function to count number of special
two digit number*/

static void countSpecialDigit(Node rt)
{
    int x;
    if (rt == null)
        return;
    else
    {
        x = check(rt.info);
        if (x == 1)
            count = count + 1;
        countSpecialDigit(rt.left);
        countSpecialDigit(rt.right);
    }
}

/*Driver code*/

public static void main(String[] args)
{
    BinaryTree tree = new BinaryTree();
    Node root = null;
    root = tree.insert(root, 50);
    tree.insert(root, 29);
    tree.insert(root, 59);
    tree.insert(root, 19);
    tree.insert(root, 53);
    tree.insert(root, 556);
    tree.insert(root, 56);
    tree.insert(root, 94);
    tree.insert(root, 13);

/*    Function call*/

    countSpecialDigit(root);
    System.out.println(count);
}
}

/*Java code to sort 2D matrix row-wise*/

import java.io.*;
public class Sort2DMatrix {
    static int sortRowWise(int m[][])
    {

/*        loop for rows of matrix*/

        for (int i = 0; i < m.length; i++) {

/*            loop for column of matrix*/

            for (int j = 0; j < m[i].length; j++) {

/*                loop for comparison and swapping*/

                for (int k = 0; k < m[i].length - j - 1; k++) {
                    if (m[i][k] > m[i][k + 1]) {

/*                        swapping of elements*/

                        int t = m[i][k];
                        m[i][k] = m[i][k + 1];
                        m[i][k + 1] = t;
                    }
                }
            }
        }

/*        printing the sorted matrix*/

        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m[i].length; j++)
                System.out.print(m[i][j] + " ");
            System.out.println();
        }
        return 0;
    }

/*    driver code*/

    public static void main(String args[])
    {
        int m[][] = { { 9, 8, 7, 1 },
                      { 7, 3, 0, 2 },
                      { 9, 5, 3, 2 },
                      { 6, 3, 1, 2 } };
        sortRowWise(m);
    }
}

/*Java program to print given
number of 1's, 2's, 3's ....k's
in zig-zag way.*/

import java.util.*;
import java.lang.*;
public class GfG{

/*    function that prints given number of 1's,
    2's, 3's ....k's in zig-zag way.*/

    public static void ZigZag(int rows,
                              int columns,
                              int numbers[])
    {
        int k = 0;

/*        two-dimensional array to store numbers.*/

        int[][] arr = new int[rows][columns];
        for (int i=0; i<rows; i++)
        {

/*            for even row.*/

            if (i%2==0)
            {

/*                for each column.*/

                for (int j=0; j<columns &&
                        numbers[k]>0; j++)
                {

/*                    storing element.*/

                    arr[i][j] = k+1;

/*                    decrement element at
                    kth index.*/

                    numbers[k]--;

/*                    if array contains zero
                    then increment index to
                    make this next index*/

                    if (numbers[k] == 0)
                        k++;
                }
            }

/*            for odd row.*/

            else
            {

/*                for each column.*/

                for (int j=columns-1; j>=0 &&
                    numbers[k]>0; j--)
                {

/*                    storing element.*/

                    arr[i][j] = k+1;

/*                    decrement element
                    at kth index.*/

                    numbers[k]--;

/*                    if array contains zero then
                    increment index to make this
                    next index.*/

                    if (numbers[k]==0)
                        k++;
                }
            }
        }

/*        printing the stored elements.*/

        for (int i=0;i<rows;i++)
        {
            for (int j=0;j<columns;j++)
                System.out.print(arr[i][j] + " ");
            System.out.println();
        }
    }

/*    Driver function*/

    public static void main(String argc[])
    {
        int rows = 4;
        int columns = 5;
        int[] Numbers = new int[]{3, 4, 2,
                                  2, 3, 1, 5};
        ZigZag(rows, columns, Numbers);
    }
}

/*Java program to find maximum elements
that can be made equal with k updates*/

import java.util.Arrays;
public class GFG {
    static int MAX = 100;

/*    Function to Check center element
    is equal to the individual
    sum of all the half diagonals*/

    static boolean HalfDiagonalSums(int mat[][],
                                          int n)
    {

/*        Find sums of half diagonals*/

        int diag1_left = 0, diag1_right = 0;
        int diag2_left = 0, diag2_right = 0;
        for (int i = 0, j = n - 1; i < n;
                                    i++, j--)
        {
            if (i < n/2) {
                diag1_left += mat[i][i];
                diag2_left += mat[j][i];        
            }
            else if (i > n/2) {
                diag1_right += mat[i][i];
                diag2_right += mat[j][i];        
            }
        }
        return (diag1_left == diag2_right &&
                diag2_right == diag2_left &&
                diag1_right == diag2_left &&
                diag2_right == mat[n/2][n/2]);
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[][] = { { 2, 9, 1, 4, -2},
                      { 6, 7, 2, 11, 4},
                      { 4, 2, 9, 2, 4},
                      { 1, 9, 2, 4, 4},
                      { 0, 2, 4, 2, 5} };
        System.out.print ( HalfDiagonalSums(a, 5)
                                ? "Yes" : "No" );
    }
}

