}

/*Java program to find length of the longest valid
substring*/

import java.util.Stack;
class Test
{

/*    method to get length of the longest valid*/

    static int findMaxLen(String str)
    {
        int n = str.length();

/*        Create a stack and push -1
        as initial index to it.*/

        Stack<Integer> stk = new Stack<>();
        stk.push(-1);

/*        Initialize result*/

        int result = 0;

/*        Traverse all characters of given string*/

        for (int i = 0; i < n; i++)
        {

/*            If opening bracket, push index of it*/

            if (str.charAt(i) == '(')
                stk.push(i);

/*If closing bracket, i.e.,str[i] = ')'
*/

            else
            {

/*                Pop the previous
                opening bracket's index*/

                if(!stk.empty())
                    stk.pop();

/*                Check if this length
                formed with base of
                current valid substring
                is more than max
                so far*/

                if (!stk.empty())
                    result
                        = Math.max(result,
                                   i - stk.peek());

/*                If stack is empty. push
                current index as base
                for next valid substring (if any)*/

                else
                    stk.push(i);
            }
        }
        return result;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        String str = "((()()";

/*        Function call*/

        System.out.println(findMaxLen(str));
        str = "()(()))))";

/*        Function call*/

        System.out.println(findMaxLen(str));
    }
}

/*Java Code to count minimum reversal for
making an expression balanced.*/

import java.util.*;
public class GFG {

/*    Method count minimum reversal for
    making an expression balanced.
    Returns -1 if expression cannot be balanced*/

    static int countMinReversals(String expr)
    {
        int len = expr.length();
        int ans;

/*        Expressions of odd lengths
        cannot be balanced*/

        if (len % 2 != 0) {
            return -1;
        }
        int left_brace = 0, right_brace = 0;
        for (int i = 0; i < len; i++) {
            char ch = expr.charAt(i);

/*            If we find a left bracket then we simply
            increment the left bracket*/

            if (ch == '{') {
                left_brace++;
            }

/*            Else if left bracket is 0 then we find
            unbalanced right bracket and increment
            right bracket or if the expression
            is balanced then we decrement left*/

            else {
                if (left_brace == 0) {
                    right_brace++;
                }
                else {
                    left_brace--;
                }
            }
        }
        ans = (int)(Math.ceil((0.0 + left_brace) / 2)
                    + Math.ceil((0.0 + right_brace) / 2));
        return ans;
    }

/*    Driver method*/

    public static void main(String[] args)
    {
        String expr = "}}{{";
        System.out.println(countMinReversals(expr));
    }
}

/* Java Program to check whether valid
expression is redundant or not*/

import java.util.Stack;
public class GFG {

/*Function to check redundant brackets in a
balanced expression*/

    static boolean checkRedundancy(String s) {

/*        create a stack of characters*/

        Stack<Character> st = new Stack<>();
        char[] str = s.toCharArray();

/*        Iterate through the given expression*/

        for (char ch : str) {

/*            if current character is close parenthesis ')'*/

            if (ch == ')') {
                char top = st.peek();
                st.pop();

/*                If immediate pop have open parenthesis '('
                duplicate brackets found*/

                boolean flag = true;
                while (top != '(') {

/*                    Check for operators in expression*/

                    if (top == '+' || top == '-'
                            || top == '*' || top == '/') {
                        flag = false;
                    }

/*                    Fetch top element of stack*/

                    top = st.peek();
                    st.pop();
                }

/*                If operators not found*/

                if (flag == true) {
                    return true;
                }
            } else {

/*push open parenthesis '(',*/

st.push(ch);

/*operators and operands to stack*/

}                
        }
        return false;
    }

/*Function to check redundant brackets*/

    static void findRedundant(String str) {
        boolean ans = checkRedundancy(str);
        if (ans == true) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

/*Driver code*/

    public static void main(String[] args) {
        String str = "((a+b))";
        findRedundant(str);
        str = "(a+(b)/c)";
        findRedundant(str);
        str = "(a+b*(c-d))";
        findRedundant(str);
    }
}

/*Java program to check if two expressions
evaluate to same.*/

import java.io.*;
import java.util.*;
class GFG
{
    static final int MAX_CHAR = 26;

/*    Return local sign of the operand. For example,
    in the expr a-b-(c), local signs of the operands
    are +a, -b, +c*/

    static boolean adjSign(String s, int i)
    {
        if (i == 0)
            return true;
        if (s.charAt(i - 1) == '-')
            return false;
        return true;
    };

/*    Evaluate expressions into the count vector of
    the 26 alphabets.If add is true, then add count
    to the count vector of the alphabets, else remove
    count from the count vector.*/

    static void eval(String s, int[] v, boolean add)
    {

/*        stack stores the global sign
        for operands.*/

        Stack<Boolean> stk = new Stack<>();
        stk.push(true);

/*        + means true
        global sign is positive initially*/

        int i = 0;
        while (i < s.length())
        {
            if (s.charAt(i) == '+' || s.charAt(i) == '-')
            {
                i++;
                continue;
            }
            if (s.charAt(i) == '(')
            {

/*                global sign for the bracket is
                pushed to the stack*/

                if (adjSign(s, i))
                    stk.push(stk.peek());
                else
                    stk.push(!stk.peek());
            }

/*            global sign is popped out which
            was pushed in for the last bracket*/

            else if (s.charAt(i) == ')')
                stk.pop();
            else
            {

/*                global sign is positive (we use different
                values in two calls of functions so that
                we finally check if all vector elements
                are 0.*/

                if (stk.peek())
                    v[s.charAt(i) - 'a'] += (adjSign(s, i) ?
                               add ? 1 : -1 : add ? -1 : 1);

/*                global sign is negative here*/

                else
                    v[s.charAt(i) - 'a'] += (adjSign(s, i) ?
                                add ? -1 : 1 : add ? 1 : -1);
            }
            i++;
        }
    };

/*    Returns true if expr1 and expr2 represent
    same expressions*/

    static boolean areSame(String expr1, String expr2)
    {

/*        Create a vector for all operands and
        initialize the vector as 0.*/

        int[] v = new int[MAX_CHAR];

/*        Put signs of all operands in expr1*/

        eval(expr1, v, true);

/*        Subtract signs of operands in expr2*/

        eval(expr2, v, false);

/*        If expressions are same, vector must
        be 0.*/

        for (int i = 0; i < MAX_CHAR; i++)
            if (v[i] != 0)
                return false;
        return true;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        String expr1 = "-(a+b+c)", expr2 = "-a-b-c";
        if (areSame(expr1, expr2))
            System.out.println("Yes");
        else
            System.out.println("No");
    }
}

/*Java program to print minimum number that can be formed
from a given sequence of Is and Ds*/

class GFG
{

/*    Prints the minimum number that can be formed from
    input sequence of I's and D's*/

    static void PrintMinNumberForPattern(String arr)
    {

/*        Initialize current_max (to make sure that
        we don't use repeated character*/

        int curr_max = 0;

/*        Initialize last_entry (Keeps track for
        last printed digit)*/

        int last_entry = 0;
        int j;

/*        Iterate over input array*/

        for (int i = 0; i < arr.length(); i++)
        {

/*            Initialize 'noOfNextD' to get count of
            next D's available*/

            int noOfNextD = 0;
            switch (arr.charAt(i))
            {
                case 'I':

/*                    If letter is 'I'
                    Calculate number of next consecutive D's
                    available*/

                    j = i + 1;
                    while (j < arr.length() && arr.charAt(j) == 'D')
                    {
                        noOfNextD++;
                        j++;
                    }
                    if (i == 0)
                    {
                        curr_max = noOfNextD + 2;

/*                        If 'I' is first letter, print incremented
                        sequence from 1*/

                        System.out.print(" " + ++last_entry);
                        System.out.print(" " + curr_max);

/*                        Set max digit reached*/

                        last_entry = curr_max;
                    }
                    else
                    {

/*                        If not first letter
                        Get next digit to print*/

                        curr_max = curr_max + noOfNextD + 1;

/*                        Print digit for I*/

                        last_entry = curr_max;
                        System.out.print(" " + last_entry);
                    }

/*                    For all next consecutive 'D' print
                    decremented sequence*/

                    for (int k = 0; k < noOfNextD; k++)
                    {
                        System.out.print(" " + --last_entry);
                        i++;
                    }
                    break;

/*                If letter is 'D'*/

                case 'D':
                    if (i == 0)
                    {

/*                        If 'D' is first letter in sequence
                        Find number of Next D's available*/

                        j = i + 1;
                        while (j < arr.length()&&arr.charAt(j) == 'D')
                        {
                            noOfNextD++;
                            j++;
                        }

/*                        Calculate first digit to print based on
                        number of consecutive D's*/

                        curr_max = noOfNextD + 2;

/*                        Print twice for the first time*/

                        System.out.print(" " + curr_max + " " + (curr_max - 1));

/*                        Store last entry*/

                        last_entry = curr_max - 1;
                    }
                    else
                    {

/*                        If current 'D' is not first letter
                        Decrement last_entry*/

                        System.out.print(" " + (last_entry - 1));
                        last_entry--;
                    }
                    break;
            }
        }
        System.out.println();
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        PrintMinNumberForPattern("IDID");
        PrintMinNumberForPattern("I");
        PrintMinNumberForPattern("DD");
        PrintMinNumberForPattern("II");
        PrintMinNumberForPattern("DIDI");
        PrintMinNumberForPattern("IIDDD");
        PrintMinNumberForPattern("DDIDDIID");
    }
}

/*Java program to print minimum number that can be formed
from a given sequence of Is and Ds*/

import java.io.*;
import java.util.*;
public class GFG {
       static void printLeast(String arr)
       {

/*              min_avail represents the minimum number which is
              still available for inserting in the output vector.
              pos_of_I keeps track of the most recent index
              where 'I' was encountered w.r.t the output vector*/

              int min_avail = 1, pos_of_I = 0;

/*              vector to store the output*/

              ArrayList<Integer> al = new ArrayList<>();

/*              cover the base cases*/

              if (arr.charAt(0) == 'I')
              {
                  al.add(1);
                  al.add(2);
                  min_avail = 3;
                  pos_of_I = 1;
              }
              else
              {
                  al.add(2);
                  al.add(1);
                  min_avail = 3;
                  pos_of_I = 0;
              }

/*              Traverse rest of the input*/

              for (int i = 1; i < arr.length(); i++)
              {
                   if (arr.charAt(i) == 'I')
                   {
                       al.add(min_avail);
                       min_avail++;
                       pos_of_I = i + 1;
                   }
                   else
                   {
                       al.add(al.get(i));
                       for (int j = pos_of_I; j <= i; j++)
                            al.set(j, al.get(j) + 1);
                       min_avail++;
                   }
              }

/*              print the number*/

              for (int i = 0; i < al.size(); i++)
                   System.out.print(al.get(i) + " ");
              System.out.println();
       }

/*       Driver code*/

       public static void main(String args[])
       {
              printLeast("IDID");
              printLeast("I");
              printLeast("DD");
              printLeast("II");
              printLeast("DIDI");
              printLeast("IIDDD");
              printLeast("DDIDDIID");
       }
}

/*Java program to find duplicate parenthesis in a 
balanced expression */
import java.util.Stack;
public class GFG {

/*Function to find duplicate parenthesis in a 
balanced expression */

    static boolean findDuplicateparenthesis(String s) {

/*        create a stack of characters */

        Stack<Character> Stack = new Stack<>();

/*        Iterate through the given expression */

        char[] str = s.toCharArray();
        for (char ch : str) {

/*            if current character is close parenthesis ')' */

            if (ch == ')') {

/*                pop character from the stack */

                char top = Stack.peek();
                Stack.pop();

/*                stores the number of characters between a 
                closing and opening parenthesis 
                if this count is less than or equal to 1 
                then the brackets are redundant else not */

                int elementsInside = 0;
                while (top != '(') {
                    elementsInside++;
                    top = Stack.peek();
                    Stack.pop();
                }
                if (elementsInside < 1) {
                    return true;
                }
}

/*push open parenthesis '(', operators and  operands to stack */

            else {
                Stack.push(ch);
            }
        }

/*        No duplicates found */

        return false;
    }

/*Driver code */

public static void main(String[] args) {

/*        input balanced expression */

        String str = "(((a+(b))+(c+d)))";
        if (findDuplicateparenthesis(str)) {
            System.out.println("Duplicate Found ");
        } else {
            System.out.println("No Duplicates Found ");
        }
    }
}

/*Java program to count the number less than N,
whose all permutation is greater
than or equal to the number.*/

import java.util.Stack;
class GFG
{

/*    Return the count of the number having all
    permutation greater than or equal to the number.*/

    static int countNumber(int n)
    {
        int result = 0;

/*        Pushing 1 to 9 because all number from 1
        to 9 have this property.*/

        Stack<Integer> s = new Stack<>();
        for (int i = 1; i <= 9; i++)
        {
            if (i <= n)
            {
                s.push(i);
                result++;
            }

/*            take a number from stack and add
            a digit smaller than last digit
            of it.*/

            while (!s.empty())
            {
                int tp = s.peek();
                s.pop();
                for (int j = tp % 10; j <= 9; j++)
                {
                    int x = tp * 10 + j;
                    if (x <= n) {
                        s.push(x);
                        result++;
                    }
                }
            }
        }
        return result;
    }

/*    Driven Code*/

    public static void main(String[] args)
    {
        int n = 15;
        System.out.println(countNumber(n));
    }
}

/*  Java implementation of above method*/

import java.util.Stack;
import java.util.Vector;
class Test
{

/*    Method to find the size of manipulated sequence*/

    static int removeConsecutiveSame(Vector <String> v)
    {
        Stack<String> st = new Stack<>();

/*        Start traversing the sequence*/

        for (int i=0; i<v.size(); i++)
        {

/*            Push the current string if the stack
            is empty*/

            if (st.empty())
                st.push(v.get(i));
            else
            {
                String str = st.peek();

/*                compare the current string with stack top
                if equal, pop the top*/

                if (str.equals(v.get(i)))    
                    st.pop();

/*                Otherwise push the current string*/

                else
                    st.push(v.get(i));
            }
        }

/*        Return stack size*/

        return st.size();
    }

/*    Driver method*/

    public static void main(String[] args) 
    {
        Vector<String> v = new Vector<>();
        v.addElement("ab"); v.addElement("aa");
        v.addElement("aa");v.addElement("bcd");
        v.addElement("ab");
        System.out.println(removeConsecutiveSame(v));
    }
}

/*Java program to decode a string recursively
encoded as count followed substring*/

import java.util.Stack;
class Test
{

/*    Returns decoded string for 'str'*/

    static String decode(String str)
    {
        Stack<Integer> integerstack = new Stack<>();
        Stack<Character> stringstack = new Stack<>();
        String temp = "", result = "";

/*        Traversing the string*/

        for (int i = 0; i < str.length(); i++)
        {
            int count = 0;

/*            If number, convert it into number
            and push it into integerstack.*/

            if (Character.isDigit(str.charAt(i)))
            {
                while (Character.isDigit(str.charAt(i)))
                {
                    count = count * 10 + str.charAt(i) - '0';
                    i++;
                }
                i--;
                integerstack.push(count);
            }

/*            If closing bracket ']', pop elemment until
            '[' opening bracket is not found in the
            character stack.*/

            else if (str.charAt(i) == ']')
            {
                temp = "";
                count = 0;
                if (!integerstack.isEmpty())
                {
                    count = integerstack.peek();
                    integerstack.pop();
                }
                while (!stringstack.isEmpty() && stringstack.peek()!='[' )
                {
                    temp = stringstack.peek() + temp;
                    stringstack.pop();
                }
                if (!stringstack.empty() && stringstack.peek() == '[')
                    stringstack.pop();

/*                Repeating the popped string 'temo' count
                number of times.*/

                for (int j = 0; j < count; j++)
                    result = result + temp;

/*                Push it in the character stack.*/

                for (int j = 0; j < result.length(); j++)
                    stringstack.push(result.charAt(j));
                result = "";
            }

/*            If '[' opening bracket, push it into character stack.*/

            else if (str.charAt(i) == '[')
            {
                if (Character.isDigit(str.charAt(i-1)))
                    stringstack.push(str.charAt(i));
                else
                {
                    stringstack.push(str.charAt(i));
                    integerstack.push(1);
                }
            }
            else
                stringstack.push(str.charAt(i));
        }

/*        Pop all the elmenet, make a string and return.*/

        while (!stringstack.isEmpty())
        {
            result = stringstack.peek() + result;
            stringstack.pop();
        }
        return result;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        String str = "3[b2[ca]]";
        System.out.println(decode(str));
    }
}

/*Java Program to implement growable array based stack
using tight strategy*/

class GFG
{

/*constant amount at which stack is increased*/

static final int BOUND = 4;

/*top of the stack*/

static int top = -1;

/*length of stack*/

static int length = 0;

/*function to create new stack*/

static int[] create_new(int[] a)
{

/*    allocate memory for new stack*/

    int[] new_a = new int[length + BOUND];

/*    copying the content of old stack*/

    for (int i = 0; i < length; i++)
        new_a[i] = a[i];

/*    re-sizing the length*/

    length += BOUND;
    return new_a;
}

/*function to push new element*/

static int[] push(int[] a, int element)
{

/*    if stack is full, create new one*/

    if (top == length - 1)
        a = create_new(a);

/*    insert element at top of the stack*/

    a[++top] = element;
    return a;
}

/*function to pop an element*/

static void pop(int[] a)
{
    top--;
}

/*function to display*/

static void display(int[] a)
{

/*    if top is -1, that means stack is empty*/

    if (top == -1)
        System.out.println("Stack is Empty");
    else
    {
        System.out.print("Stack: ");
        for (int i = 0; i <= top; i++)
            System.out.print(a[i] + " ");
        System.out.println();
    }
}

/*Driver Code*/

public static void main(String args[])
{

/*    creating initial stack*/

    int []a = create_new(new int[length + BOUND]);

/*    pushing element to top of stack*/

    a = push(a, 1);
    a = push(a, 2);
    a = push(a, 3);
    a = push(a, 4);
    display(a);

/*    pushing more element when stack is full*/

    a = push(a, 5);
    a = push(a, 6);
    display(a);
    a = push(a, 7);
    a = push(a, 8);
    display(a);

/*    pushing more element so that stack can grow*/

    a = push(a, 9);
    display(a);
}
}

/*Java code to answer the query in constant time*/

import java.util.*;
class GFG{

/*
BOP[] stands for "Balanced open parentheses"
BCP[] stands for "Balanced close parentheses"
*/

/*Function for precomputation*/

static void constructBlanceArray(int BOP[], int BCP[],
                                String str, int n)
{

/*    Create a stack and push -1
    as initial index to it.*/

    Stack<Integer> stk = new Stack<>();;

/*    Traverse all characters of given String*/

    for(int i = 0; i < n; i++)
    {

/*        If opening bracket, push index of it*/

        if (str.charAt(i) == '(')
            stk.add(i);

/*        If closing bracket, i.e., str[i] = ')'*/

        else
        {

/*            If closing bracket, i.e., str[i] = ')'
            && stack is not empty then mark both
            "open & close" bracket indexs as 1 .
            Pop the previous opening bracket's index*/

            if (!stk.isEmpty())
            {
                BCP[i] = 1;
                BOP[stk.peek()] = 1;
                stk.pop();
            }

/*            If stack is empty.*/

            else
                BCP[i] = 0;
        }
    }
    for(int i = 1; i < n; i++)
    {
        BCP[i] += BCP[i - 1];
        BOP[i] += BOP[i - 1];
    }
}

/*Function return output of each query in O(1)*/

static int query(int BOP[], int BCP[],
                 int s, int e)
{
    if (BOP[s - 1] == BOP[s])
    {
        return (BCP[e] - BOP[s]) * 2;
    }
    else
    {
        return (BCP[e] - BOP[s] + 1) * 2;
    }
}

/*Driver code*/

public static void main(String[] args)
{
    String str = "())(())(())(";
    int n = str.length();
    int BCP[] = new int[n + 1];
    int BOP[] = new int[n + 1];
    constructBlanceArray(BOP, BCP, str, n);
    int startIndex = 5, endIndex = 11;
    System.out.print("Maximum Length Correct " +
                     "Bracket Subsequence between " +
                     startIndex + " and " + endIndex +
                     " = " + query(BOP, BCP, startIndex,
                                   endIndex) + "\n");
    startIndex = 4;
    endIndex = 5;
    System.out.print("Maximum Length Correct " + 
                     "Bracket Subsequence between " +
                     startIndex + " and " + endIndex +
                     " = " + query(BOP, BCP, startIndex,
                                   endIndex) + "\n");
    startIndex = 1;
    endIndex = 5;
    System.out.print("Maximum Length Correct " +
                     "Bracket Subsequence between " +
                     startIndex + " and " + endIndex +
                     " = " + query(BOP, BCP, startIndex,
                                   endIndex) + "\n");
}
}

/*Java program for implementation of Heap Sort*/

public class HeapSort {

/*    To heapify a subtree rooted with node i which is
    an index in arr[]. n is size of heap*/

    void heapify(int arr[], int n, int i)
    {

/*Initialize largest as root*/

int largest = i;

/*left = 2*i + 1*/

int l = 2 * i + 1;

/*right = 2*i + 2*/

int r = 2 * i + 2;

/*        If left child is larger than root*/

        if (l < n && arr[l] > arr[largest])
            largest = l;

/*        If right child is larger than largest so far*/

        if (r < n && arr[r] > arr[largest])
            largest = r;

/*        If largest is not root*/

        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;

/*            Recursively heapify the affected sub-tree*/

            heapify(arr, n, largest);
        }
    }

/*The main function to sort an array of given size*/

    public void sort(int arr[])
    {
        int n = arr.length;

/*        Build heap (rearrange array)*/

        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(arr, n, i);

/*        One by one extract an element from heap*/

        for (int i = n - 1; i > 0; i--) {

/*            Move current root to end*/

            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;

/*            call max heapify on the reduced heap*/

            heapify(arr, i, 0);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int arr[])
    {
        int n = arr.length;
        for (int i = 0; i < n; ++i)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 12, 11, 13, 5, 6, 7 };
        int n = arr.length;
        HeapSort ob = new HeapSort();
        ob.sort(arr);
        System.out.println("Sorted array is");
        printArray(arr);
    }
}

/*Java program to checks if a
binary tree is max heap or not*/

import java.util.*;
class GFG
{

/*  Tree node structure*/

  static class Node
  {
    int data;
    Node left;
    Node right;
  };

/*  To add a new node*/

  static Node newNode(int k)
  {
    Node node = new Node();
    node.data = k;
    node.right = node.left = null;
    return node;
  }
  static boolean isHeap(Node root)
  {
    Queue<Node> q = new LinkedList<>();
    q.add(root);
    boolean nullish = false;
    while (!q.isEmpty())
    {
      Node temp = q.peek();
      q.remove();
      if (temp.left != null)
      {
        if (nullish
            || temp.left.data
            >= temp.data)
        {
          return false;
        }
        q.add(temp.left);
      }
      else {
        nullish = true;
      }
      if (temp.right != null)
      {
        if (nullish
            || temp.right.data
            >= temp.data)
        {
          return false;
        }
        q.add(temp.right);
      }
      else
      {
        nullish = true;
      }
    }
    return true;
  }

/*  Driver code*/

  public static void main(String[] args)
  {
    Node root = null;
    root = newNode(10);
    root.left = newNode(9);
    root.right = newNode(8);
    root.left.left = newNode(7);
    root.left.right = newNode(6);
    root.right.left = newNode(5);
    root.right.right = newNode(4);
    root.left.left.left = newNode(3);
    root.left.left.right = newNode(2);
    root.left.right.left = newNode(1);

/*    Function call*/

    if (isHeap(root))
      System.out.print("Given binary tree is a Heap\n");
    else
      System.out.print("Given binary tree is not a Heap\n");
  }
}

/*Java program to check whether a given array
represents a max-heap or not*/

class GFG
{

/*    Returns true if arr[i..n-1]
    represents a max-heap*/

    static boolean isHeap(int arr[],
                          int i, int n)
    {

/*        If a leaf node*/

        if (i >= (n - 2) / 2)
        {
            return true;
        }

/*        If an internal node and
        is greater than its
        children, and same is
        recursively true for the
        children*/

        if (arr[i] >= arr[2 * i + 1]
            && arr[i] >= arr[2 * i + 2]
            && isHeap(arr, 2 * i + 1, n)
            && isHeap(arr, 2 * i + 2, n))
        {
            return true;
        }
        return false;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int arr[] = { 90, 15, 10, 7, 12, 2, 7, 3 };
        int n = arr.length - 1;
        if (isHeap(arr, 0, n)) {
            System.out.println("Yes");
        }
        else {
            System.out.println("No");
        }
    }
}

/*Java program to check whether a given array
represents a max-heap or not*/

class GFG {

/*Returns true if arr[i..n-1] represents a
max-heap*/

    static boolean isHeap(int arr[], int n) {

/*        Start from root and go till the last internal
        node*/

        for (int i = 0; i <= (n - 2) / 2; i++) {

/*            If left child is greater, return false*/

            if (arr[2 * i + 1] > arr[i]) {
                return false;
            }

/*            If right child is greater, return false*/

            if (2 * i + 2 < n && arr[2 * i + 2] > arr[i]) {
                return false;
            }
        }
        return true;
    }

/*Driver program*/

    public static void main(String[] args) {
        int arr[] = {90, 15, 10, 7, 12, 2, 7, 3};
        int n = arr.length;
        if (isHeap(arr, n)) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Java program to connect n
ropes with minimum cost*/

/*A class for Min Heap*/

class MinHeap {

/*Array of elements in heap*/

int[] harr;

/*Current number of elements in min heap*/

int heap_size;

/*maximum possible size of min heap*/

int capacity;

/*    Constructor: Builds a heap from
    a given array a[] of given size*/

    public MinHeap(int a[], int size)
    {
        heap_size = size;
        capacity = size;
        harr = a;
        int i = (heap_size - 1) / 2;
        while (i >= 0) {
            MinHeapify(i);
            i--;
        }
    }

/*    A recursive method to heapify a subtree
    with the root at given index
    This method assumes that the subtrees
    are already heapified*/

    void MinHeapify(int i)
    {
        int l = left(i);
        int r = right(i);
        int smallest = i;
        if (l < heap_size && harr[l] < harr[i])
            smallest = l;
        if (r < heap_size && harr[r] < harr[smallest])
            smallest = r;
        if (smallest != i) {
            swap(i, smallest);
            MinHeapify(smallest);
        }
    }
    int parent(int i) { return (i - 1) / 2; }

/*    to get index of left child of node at index i*/

    int left(int i) { return (2 * i + 1); }

/*    to get index of right child of node at index i*/

    int right(int i) { return (2 * i + 2); }

/*    Method to remove minimum element (or root) from min heap*/

    int extractMin()
    {
        if (heap_size <= 0)
            return Integer.MAX_VALUE;
        if (heap_size == 1) {
            heap_size--;
            return harr[0];
        }

/*        Store the minimum value, and remove it from heap*/

        int root = harr[0];
        harr[0] = harr[heap_size - 1];
        heap_size--;
        MinHeapify(0);
        return root;
    }

/*    Inserts a new key 'k'*/

    void insertKey(int k)
    {
        if (heap_size == capacity) {
            System.out.println("Overflow: Could not insertKey");
            return;
        }

/*        First insert the new key at the end*/

        heap_size++;
        int i = heap_size - 1;
        harr[i] = k;

/*        Fix the min heap property if it is violated*/

        while (i != 0 && harr[parent(i)] > harr[i]) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

/*    A utility function to check
    if size of heap is 1 or not*/

    boolean isSizeOne()
    {
        return (heap_size == 1);
    }

/*    A utility function to swap two elements*/

    void swap(int x, int y)
    {
        int temp = harr[x];
        harr[x] = harr[y];
        harr[y] = temp;
    }

/*    The main function that returns the
    minimum cost to connect n ropes of
    lengths stored in len[0..n-1]*/

    static int minCost(int len[], int n)
    {

/*Initialize result*/

int cost = 0;

/*        Create a min heap of capacity equal
        to n and put all ropes in it*/

        MinHeap minHeap = new MinHeap(len, n);

/*        Iterate while size of heap doesn't become 1*/

        while (!minHeap.isSizeOne()) {

/*            Extract two minimum length ropes from min heap*/

            int min = minHeap.extractMin();
            int sec_min = minHeap.extractMin();

/*Update total cost*/

cost += (min + sec_min);

/*            Insert a new rope in min heap with length equal to sum
            of two extracted minimum lengths*/

            minHeap.insertKey(min + sec_min);
        }

/*        Finally return total minimum
        cost for connecting all ropes*/

        return cost;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int len[] = { 4, 3, 2, 6 };
        int size = len.length;
        System.out.println("Total cost for connecting ropes is " + minCost(len, size));
    }
};

/*Java program to merge k sorted arrays of size n each.*/

import java.util.*;
class GFG{
  static final int n = 4;

/*  Merge arr1[0..n1-1] and arr2[0..n2-1] into
  arr3[0..n1+n2-1]*/

  static void mergeArrays(int arr1[], int arr2[], int n1,
                          int n2, int arr3[])
  {
    int i = 0, j = 0, k = 0;

/*    Traverse both array*/

    while (i<n1 && j <n2)
    {

/*      Check if current element of first
      array is smaller than current element
      of second array. If yes, store first
      array element and increment first array
      index. Otherwise do same with second array*/

      if (arr1[i] < arr2[j])
        arr3[k++] = arr1[i++];
      else
        arr3[k++] = arr2[j++];
    }

/*    Store remaining elements of first array*/

    while (i < n1)
      arr3[k++] = arr1[i++];

/*    Store remaining elements of second array*/

    while (j < n2)
      arr3[k++] = arr2[j++];
  }

/*  A utility function to print array elements*/

  static void printArray(int arr[], int size)
  {
    for (int i = 0; i < size; i++)
      System.out.print(arr[i]+  " ");
  }

/*  This function takes an array of arrays as an argument and
  All arrays are assumed to be sorted. It merges them together
  and prints the final sorted output.*/

  static void mergeKArrays(int arr[][], int i, int j, int output[])
  {

/*    if one array is in range*/

    if(i == j)
    {
      for(int p = 0; p < n; p++)
        output[p] = arr[i][p];
      return;
    }

/*    if only two arrays are left them merge them*/

    if(j - i == 1)
    {
      mergeArrays(arr[i], arr[j], n, n, output);
      return;
    }

/*    output arrays*/

    int []out1 = new int[n*(((i + j) / 2) - i + 1)];
    int []out2 = new int[n*(j - ((i + j) / 2))];

/*    divide the array into halves*/

    mergeKArrays(arr, i, (i + j) / 2, out1);
    mergeKArrays(arr, (i + j) / 2 + 1, j, out2);

/*    merge the output array*/

    mergeArrays(out1, out2, n * (((i + j) / 2) - i + 1), n * (j - ((i + j) / 2)), output);
  }

/*  Driver program to test above functions*/

  public static void main(String[] args)
  {

/*    Change n at the top to change number of elements
    in an array*/

    int arr[][] =  {{2, 6, 12, 34},
                    {1, 9, 20, 1000},
                    {23, 34, 90, 2000}};
    int k = arr.length;
    int []output = new int[n*k];
    mergeKArrays(arr,0,2, output);
    System.out.print("Merged array is " +"\n");
    printArray(output, n*k);
  }
}

/*Java program to generate
smallest derangement
using priority queue.*/

import java.util.*;
class GFG{
static void generate_derangement(int N)
{

/*  Generate Sequence and insert
  into a priority queue.*/

  int []S = new int[N + 1];
  PriorityQueue<Integer> PQ =
                new PriorityQueue <>();
  for (int i = 1; i <= N; i++)
  {
    S[i] = i;
    PQ.add(S[i]);
  }

/*  Generate Least Derangement*/

  int []D = new int[N + 1];
  for (int i = 1; i <= N; i++)
  {
    int d = PQ.peek();
    PQ.remove();
    if (d != S[i] || i == N)
    {
      D[i] = d;
    }
    else
    {
      D[i] = PQ.peek();
      PQ.remove();
      PQ.add(d);
    }
  }
  if (D[N] == S[N])
  {
    int t = D[N - 1];
    D[N - 1] = D[N];
    D[N] = t;
  }

/*  Print Derangement*/

  for (int i = 1; i <= N; i++)
    System.out.printf("%d ", D[i]);   
  System.out.printf("\n");
}

/*Driver code*/

public static void main(String[] args)
{
  generate_derangement(10);
}
}

/*Efficient Java program to find
smallest derangement.*/

class GFG
{
static void generate_derangement(int N)
{

/*    Generate Sequence S*/

    int S[] = new int[N + 1];
    for (int i = 1; i <= N; i++)
        S[i] = i;

/*    Generate Derangement*/

    int D[] = new int[N + 1];
    for (int i = 1; i <= N; i += 2)
    {
        if (i == N)
        {

/*            Only if i is odd
            Swap S[N-1] and S[N]*/

            D[N] = S[N - 1];
            D[N - 1] = S[N];
        }
        else
        {
            D[i] = i + 1;
            D[i + 1] = i;
        }
    }

/*    Print Derangement*/

    for (int i = 1; i <= N; i++)
        System.out.print(D[i] + " ");
    System.out.println();
}

/*Driver Program*/

public static void main(String[] args)
{
    generate_derangement(10);
}
}

/*Java program to find the largest derangement*/

import java.io.*;
import java.util.Collections;
import java.util.PriorityQueue;
class GFG{
public static void printLargest(int a[],int n)
{
     PriorityQueue<Integer> pq = new PriorityQueue<>(
         Collections.reverseOrder());

/*    Stores result*/

      int res[] = new int[n];

/*      Insert all elements into a priority queue*/

      for(int i = 0; i < n; i++)
    {
        pq.add(a[i]);
    }

/*      Fill Up res[] from left to right*/

    for(int i = 0; i < n; i++)
    {
        int p = pq.peek();
        pq.remove();
        if (p != a[i] || i == n - 1)
        {
            res[i] = p;
        }
        else
        {

/*            New Element poped equals the element
            in original sequence. Get the next
            largest element*/

            res[i] = pq.peek();
            pq.remove();
            pq.add(p);
        }
    }

/*      If given sequence is in descending
      order then we need to swap last two
      elements again*/

      if (res[n - 1] == a[n - 1])
    {
        res[n - 1] = res[n - 2];
        res[n - 2] = a[n - 1];
    }
      System.out.println("Largest Derangement");
    for(int i = 0; i < n; i++)
    {
        System.out.print(res[i] + " ");
    }
}

/*Driver code*/

public static void main(String[] args)
{
      int n = 7;
    int seq[] = { 92, 3, 52, 13, 2, 31, 1 };
      printLargest(seq, n);
}
}

/*Java program for implementation of Heap Sort*/

import java.io.*;
class GFG {

/*    To heapify a subtree rooted with node i which is
    an index in arr[]. n is size of heap*/

    static void heapify(int arr[], int n, int i)
    {

/*Initialize smalles as root*/

int smallest = i;

/*left = 2*i + 1*/

int l = 2 * i + 1;

/*right = 2*i + 2*/

int r = 2 * i + 2;

/*        If left child is smaller than root*/

        if (l < n && arr[l] < arr[smallest])
            smallest = l;

/*        If right child is smaller than smallest so far*/

        if (r < n && arr[r] < arr[smallest])
            smallest = r;

/*        If smallest is not root*/

        if (smallest != i) {
            int temp = arr[i];
            arr[i] = arr[smallest];
            arr[smallest] = temp;

/*            Recursively heapify the affected sub-tree*/

            heapify(arr, n, smallest);
        }
    }

/*    main function to do heap sort*/

    static void heapSort(int arr[], int n)
    {

/*        Build heap (rearrange array)*/

        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(arr, n, i);

/*        One by one extract an element from heap*/

        for (int i = n - 1; i >= 0; i--) {

/*            Move current root to end*/

            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;

/*            call max heapify on the reduced heap*/

            heapify(arr, i, 0);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int arr[], int n)
    {
        for (int i = 0; i < n; ++i)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int arr[] = { 4, 6, 3, 2, 9 };
        int n = arr.length;
        heapSort(arr, n);
        System.out.println("Sorted array is ");
        printArray(arr, n);
    }
}

/*Java implementation of above approach*/

class GFG
{
static int n = 7;
static void minheapify(int []a, int index)
{
    int small = index;
    int l = 2 * index + 1;
    int r = 2 * index + 2;
    if (l < n && a[l] < a[small])
        small = l;
    if (r < n && a[r] < a[small])
        small = r;
    if (small != index)
    {
        int t = a[small];
        a[small] = a[index];
        a[index] = t;
        minheapify(a, small);
    }
}

/*Driver code*/

public static void main (String[] args)
{
    int i = 0;
    int k1 = 3;
    int k2 = 6;
    int []a = { 20, 8, 22, 4, 12, 10, 14 };
    int ans = 0;
    for (i = (n / 2) - 1; i >= 0; i--)
    {
        minheapify(a, i);
    }

/*    decreasing value by 1 because we want
    min heapifying k times and it starts
    from 0 so we have to decrease it 1 time*/

    k1--;
    k2--;

/*    Step 1: Do extract minimum k1 times
    (This step takes O(K1 Log n) time)*/

    for (i = 0; i <= k1; i++)
    {
        a[0] = a[n - 1];
        n--;
        minheapify(a, 0);
    }

/*Step 2: Do extract minimum k2 – k1 – 1 times and sum all
   extracted elements. (This step takes O ((K2 – k1) * Log n) time)*/

    for (i = k1 + 1; i < k2; i++)
    {
        ans += a[0];
        a[0] = a[n - 1];
        n--;
        minheapify(a, 0);
    }
    System.out.println(ans);
}
}

/*Java implementation of Deque using
doubly linked list*/

import java.util.*;
class GFG
{

/*  Node of a doubly linked list*/

  static class Node
  {
    int data;
    Node prev, next;

/*    Function to get a new node*/

    static Node getnode(int data)
    {
      Node newNode = new Node();
      newNode.data = data;
      newNode.prev = newNode.next = null;
      return newNode;
    }
  };

/*  A structure to represent a deque*/

  static class Deque {
    Node front;
    Node rear;
    int Size;
    Deque()
    {
      front = rear = null;
      Size = 0;
    }

/*    Function to check whether deque
    is empty or not*/

    boolean isEmpty() { return (front == null); }

/*    Function to return the number of
    elements in the deque*/

    int size() { return Size; }

/*    Function to insert an element
    at the front end*/

    void insertFront(int data)
    {
      Node newNode = Node.getnode(data);

/*      If true then new element cannot be added
      and it is an 'Overflow' condition*/

      if (newNode == null)
        System.out.print("OverFlow\n");
      else {

/*        If deque is empty*/

        if (front == null)
          rear = front = newNode;

/*        Inserts node at the front end*/

        else {
          newNode.next = front;
          front.prev = newNode;
          front = newNode;
        }

/*        Increments count of elements by 1*/

        Size++;
      }
    }

/*    Function to insert an element
    at the rear end*/

    void insertRear(int data)
    {
      Node newNode = Node.getnode(data);

/*      If true then new element cannot be added
      and it is an 'Overflow' condition*/

      if (newNode == null)
        System.out.print("OverFlow\n");
      else {

/*        If deque is empty*/

        if (rear == null)
          front = rear = newNode;

/*        Inserts node at the rear end*/

        else {
          newNode.prev = rear;
          rear.next = newNode;
          rear = newNode;
        }
        Size++;
      }
    }

/*    Function to delete the element
    from the front end*/

    void deleteFront()
    {

/*      If deque is empty then
      'Underflow' condition*/

      if (isEmpty())
        System.out.print("UnderFlow\n");

/*      Deletes the node from the front end and makes
      the adjustment in the links*/

      else {
        Node temp = front;
        front = front.next;

/*        If only one element was present*/

        if (front == null)
          rear = null;
        else
          front.prev = null;

/*        Decrements count of elements by 1*/

        Size--;
      }
    }

/*    Function to delete the element
    from the rear end*/

    void deleteRear()
    {

/*      If deque is empty then
      'Underflow' condition*/

      if (isEmpty())
        System.out.print("UnderFlow\n");

/*      Deletes the node from the rear end and makes
      the adjustment in the links*/

      else {
        Node temp = rear;
        rear = rear.prev;

/*        If only one element was present*/

        if (rear == null)
          front = null;
        else
          rear.next = null;

/*        Decrements count of elements by 1*/

        Size--;
      }
    }

/*    Function to return the element
    at the front end*/

    int getFront()
    {

/*      If deque is empty, then returns
      garbage value*/

      if (isEmpty())
        return -1;
      return front.data;
    }

/*    Function to return the element
    at the rear end*/

    int getRear()
    {

/*      If deque is empty, then returns
      garbage value*/

      if (isEmpty())
        return -1;
      return rear.data;
    }

/*    Function to delete all the elements
    from Deque*/

    void erase()
    {
      rear = null;
      while (front != null) {
        Node temp = front;
        front = front.next;
      }
      Size = 0;
    }
  }

/*  Driver program to test above*/

  public static void main(String[] args)
  {
    Deque dq = new Deque();
    System.out.print(
      "Insert element '5' at rear end\n");
    dq.insertRear(5);
    System.out.print(
      "Insert element '10' at rear end\n");
    dq.insertRear(10);
    System.out.print("Rear end element: " + dq.getRear()
                     + "\n");
    dq.deleteRear();
    System.out.print(
      "After deleting rear element new rear"
      + " is: " + dq.getRear() + "\n");
    System.out.print(
      "Inserting element '15' at front end \n");
    dq.insertFront(15);
    System.out.print(
      "Front end element: " + dq.getFront() + "\n");
    System.out.print("Number of elements in Deque: "
                     + dq.size() + "\n");
    dq.deleteFront();
    System.out.print("After deleting front element new "
                     + "front is: " + dq.getFront()
                     + "\n");
  }
}

/*Java program to implement sorting a
queue data structure*/

import java.util.LinkedList;
import java.util.Queue;
class GFG
{

/*    Queue elements after sortIndex are 
    already sorted. This function returns
    index of minimum element from front to
    sortIndex*/

    public static int minIndex(Queue<Integer> list,
                                     int sortIndex)
    {
    int min_index = -1;
    int min_value = Integer.MAX_VALUE;
    int s = list.size();
    for (int i = 0; i < s; i++)
    {
        int current = list.peek();

/*        This is dequeue() in Java STL*/

        list.poll();

/*        we add the condition i <= sortIndex
        because we don't want to traverse
        on the sorted part of the queue,
        which is the right part.*/

        if (current <= min_value && i <= sortIndex)
        {
            min_index = i;
            min_value = current;
        }

/*This is enqueue() in C++ STL*/

        list.add(current); 
    }
    return min_index;
}

/*    Moves given minimum element 
    to rear of queue*/

    public static void insertMinToRear(Queue<Integer> list,
                                             int min_index)
     {
        int min_value = 0; 
        int s = list.size();
        for (int i = 0; i < s; i++)
        {
        int current = list.peek();
        list.poll();
        if (i != min_index)
            list.add(current);
        else
            min_value = current;
        }
        list.add(min_value);
    }

/*    SortQueue Function*/

    public static void sortQueue(Queue<Integer> list)
    {
        for(int i = 1; i <= list.size(); i++)
        {
            int min_index = minIndex(list,list.size() - i);
            insertMinToRear(list, min_index);
        }
    }

/*    Driver function*/

    public static void main (String[] args) 
    {
        Queue<Integer> list = new LinkedList<Integer>();
        list.add(30);
        list.add(11);
        list.add(15);
        list.add(4);

/*        Sort Queue*/

        sortQueue(list);

/*        print sorted Queue*/

        while(list.isEmpty()== false)
        {
            System.out.print(list.peek() + " ");
            list.poll();
        }
    }
}

/*Java implementation to find the first negative
integer in every window of size k*/

import java.util.*;
class solution
{

/*function to find the first negative
integer in every window of size k*/

static void printFirstNegativeInteger(int arr[], int n, int k)
{

/*    flag to check whether window contains
    a negative integer or not*/

    boolean flag;

/*    Loop for each subarray(window) of size k*/

    for (int i = 0; i<(n-k+1); i++)        
    {
        flag = false;

/*        traverse through the current window*/

        for (int j = 0; j<k; j++)
        {

/*            if a negative integer is found, then
            it is the first negative integer for
            current window. Print it, set the flag
            and break*/

            if (arr[i+j] < 0)
            {
                System.out.print((arr[i+j])+" ");
                flag = true;
                break;
            }
        }

/*        if the current window does not
        contain a negative integer*/

        if (!flag)
            System.out.print("0"+" ");
    }
}

/*Driver program to test above functions*/

public static void main(String args[])
{
    int arr[] = {12, -1, -7, 8, -15, 30, 16, 28};
    int n = arr.length;
    int k = 3;
    printFirstNegativeInteger(arr, n, k);
}
}

/*Java code for First negative integer
in every window of size k*/

import java.util.*;
class GFG{
static void printFirstNegativeInteger(int arr[],
                                      int k, int n)
{
    int firstNegativeIndex = 0;
    int firstNegativeElement;
    for(int i = k - 1; i < n; i++)
    {

/*        Skip out of window and positive elements*/

        while ((firstNegativeIndex < i ) &&
               (firstNegativeIndex <= i - k ||
            arr[firstNegativeIndex] > 0))
        {
            firstNegativeIndex ++;
        }

/*        Check if a negative element is
        found, otherwise use 0*/

        if (arr[firstNegativeIndex] < 0)
        {
            firstNegativeElement = arr[firstNegativeIndex];
        }
        else
        {
            firstNegativeElement = 0;
        }
        System.out.print(firstNegativeElement + " ");
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 12, -1, -7, 8, -15, 30, 16, 28 };
    int n = arr.length;
    int k = 3;
    printFirstNegativeInteger(arr, k, n);   
}
}

/*Java program to check
whether X can give
change to every person
in the Queue*/

import java.io.*;
class GFG
{

/*Function to check if
every person will
get the change from X*/

static int isChangeable(int notes[],
                        int n)
{

/*    To count the 5$
    and 10& notes*/

    int fiveCount = 0;
    int tenCount = 0;

/*    Serve the customer
    in order*/

    for (int i = 0; i < n; i++)
    {

/*        Increase the number
        of 5$ note by one*/

        if (notes[i] == 5)
            fiveCount++;
        else if (notes[i] == 10)
        {

/*            decrease the number
            of note 5$ and
            increase 10$ note by one*/

            if (fiveCount > 0)
            {
                fiveCount--;
                tenCount++;
            }
            else
                return 0;
        }
        else
        {

/*            decrease 5$ and
            10$ note by one*/

            if (fiveCount > 0 &&
                tenCount > 0)
            {
                fiveCount--;
                tenCount--;
            }

/*            decrease 5$
            note by three*/

            else if (fiveCount >= 3)
            {
                fiveCount -= 3;
            }
            else
                return 0;
        }
    }
    return 1;
}

/*Driver Code*/

public static void main (String[] args)
{

/*queue of customers
with available notes.*/

int a[] = {5, 5, 5, 10, 20};
int n = a.length;

/*Calling function*/

if (isChangeable(a, n) > 0)
    System.out.print("YES");
else
    System.out.print("NO");
}
}

/*Java program to implement direct index 
mapping with negative values allowed. */

class GFG
{
final static int MAX = 1000;

/*Since array is global, it 
is initialized as 0. */

static boolean[][] has = new boolean[MAX + 1][2];

/*searching if X is Present in 
the given array or not. */

static boolean search(int X) 
{
    if (X >= 0) 
    {
        if (has[X][0] == true) 
        {
            return true;
        } 
        else 
        {
            return false;
        }
    }

/*    if X is negative take the 
    absolute value of X. */

    X = Math.abs(X);
    if (has[X][1] == true) 
    {
        return true;
    }
    return false;
}
static void insert(int a[], int n) 
{
    for (int i = 0; i < n; i++) 
    {
        if (a[i] >= 0) 
        {
            has[a[i]][0] = true;
        } 
        else 
        {
            has[Math.abs(a[i])][1] = true;
        }
    }
}

/*Driver code */

public static void main(String args[]) 
{
    int a[] = {-1, 9, -5, -8, -5, -2};
    int n = a.length;
    insert(a, n);
    int X = -5;
    if (search(X) == true)
    {
        System.out.println("Present");
    } 
    else 
    {
        System.out.println("Not Present");
    }
}
}

/*Java implementation of the
above approach*/

import java.util.ArrayList;
public class GFG {

/*    Function to find the Duplicates,
    if duplicate occurs 2 times or
    more than 2 times in
    array so, it will print duplicate
    value only once at output*/

    static void findDuplicates(
      int arr[], int len)
    {

/*        initialize ifPresent as false*/

        boolean ifPresent = false;

/*        ArrayList to store the output*/

        ArrayList<Integer> al = new ArrayList<Integer>();
        for (int i = 0; i < len - 1; i++) {
            for (int j = i + 1; j < len; j++) {
                if (arr[i] == arr[j]) {

/*                    checking if element is
                    present in the ArrayList
                    or not if present then break*/

                    if (al.contains(arr[i])) {
                        break;
                    }

/*                    if element is not present in the
                    ArrayList then add it to ArrayList
                    and make ifPresent at true*/

                    else {
                        al.add(arr[i]);
                        ifPresent = true;
                    }
                }
            }
        }

/*        if duplicates is present
        then print ArrayList*/

        if (ifPresent == true) {
            System.out.print(al + " ");
        }
        else {
            System.out.print(
                "No duplicates present in arrays");
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int arr[] = { 12, 11, 40, 12, 5, 6, 5, 12, 11 };
        int n = arr.length;
        findDuplicates(arr, n);
    }
}

/*Java program to find the most frequent element
in an array*/

import java.util.*;
class GFG {
    static int mostFrequent(int arr[], int n)
    {

/*        Sort the array*/

        Arrays.sort(arr);

/*        find the max frequency using linear
        traversal*/

        int max_count = 1, res = arr[0];
        int curr_count = 1;
        for (int i = 1; i < n; i++)
        {
            if (arr[i] == arr[i - 1])
                curr_count++;
            else
            {
                if (curr_count > max_count)
                {
                    max_count = curr_count;
                    res = arr[i - 1];
                }
                curr_count = 1;
            }
        }

/*        If last element is most frequent*/

        if (curr_count > max_count)
        {
            max_count = curr_count;
            res = arr[n - 1];
        }
        return res;
    }

/*    Driver program*/

    public static void main (String[] args) {
        int arr[] = {1, 5, 2, 1, 3, 2, 1};
        int n = arr.length;
        System.out.println(mostFrequent(arr,n));
    }
}

/*Java program to find the most frequent element
in an array*/

import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
class GFG {
    static int mostFrequent(int arr[], int n)
    {

/*        Insert all elements in hash*/

        Map<Integer, Integer> hp =
               new HashMap<Integer, Integer>();
        for(int i = 0; i < n; i++)
        {
            int key = arr[i];
            if(hp.containsKey(key))
            {
                int freq = hp.get(key);
                freq++;
                hp.put(key, freq);
            }
            else
            {
                hp.put(key, 1);
            }
        }

/*        find max frequency.*/

        int max_count = 0, res = -1;
        for(Entry<Integer, Integer> val : hp.entrySet())
        {
            if (max_count < val.getValue())
            {
                res = val.getKey();
                max_count = val.getValue();
            }
        }
        return res;
    }

/*    Driver code*/

    public static void main (String[] args) {
        int arr[] = {1, 5, 2, 1, 3, 2, 1};
        int n = arr.length;
        System.out.println(mostFrequent(arr, n));
    }
}

/*Java program to find one of the repeating 
elements in a read only array */

import java.io.*;
import java.util.*;
class GFG
{

/*    Function to find one of the repeating 
    elements */

    static int findRepeatingNumber(int[] arr, int n)
    {

/*        Size of blocks except the 
        last block is sq */

        int sq = (int) Math.sqrt(n);

/*        Number of blocks to incorporate 1 to 
        n values blocks are numbered from 0 
        to range-1 (both included) */

        int range = (n / sq) + 1;

/*        Count array maintains the count for 
        all blocks */

        int[] count = new int[range];

/*        Traversing the read only array and 
        updating count */

        for (int i = 0; i <= n; i++)
        {

/*            arr[i] belongs to block number 
            (arr[i]-1)/sq i is considered 
            to start from 0 */

            count[(arr[i] - 1) / sq]++;
        }

/*        The selected_block is set to last 
        block by default. Rest of the blocks 
        are checked */

        int selected_block = range - 1;
        for (int i = 0; i < range - 1; i++) 
        { 
            if (count[i] > sq) 
            { 
                selected_block = i; 
                break; 
            } 
        }

/*        after finding block with size > sq 
        method of hashing is used to find 
        the element repeating in this block */

        HashMap<Integer, Integer> m = new HashMap<>();
        for (int i = 0; i <= n; i++)
        {

/*            checks if the element belongs to the 
            selected_block */

            if ( ((selected_block * sq) < arr[i]) && 
                    (arr[i] <= ((selected_block + 1) * sq))) 
            { 
                m.put(arr[i], 1);

/*                repeating element found*/

                if (m.get(arr[i]) == 1) 
                    return arr[i]; 
            } 
        }

/*        return -1 if no repeating element exists */

        return -1; 
}

/*Driver code*/

public static void main(String args[])
{

/*    read only array, not to be modified */

    int[] arr = { 1, 1, 2, 3, 5, 4 };

/*    array of size 6(n + 1) having 
    elements between 1 and 5 */

    int n = 5;
    System.out.println("One of the numbers repeated in the array is: " + 
                                    findRepeatingNumber(arr, n));
}
}

/*Java Program to Find the top three repeated numbers*/

import java.io.*;
import java.util.*;

/*User defined Pair class*/

class Pair {
    int first, second;
}
class GFG {

/*    Function to print top three repeated numbers*/

    static void top3Repeated(int[] arr, int n)
    {

/*        There should be atleast two elements*/

        if (n < 3) {
            System.out.print("Invalid Input");
            return;
        }

/*        Count Frequency of each element*/

        TreeMap<Integer, Integer> freq = new TreeMap<>();
        for (int i = 0; i < n; i++)
            if (freq.containsKey(arr[i]))
                freq.put(arr[i], 1 + freq.get(arr[i]));
            else
                freq.put(arr[i], 1);

/*        Initialize first value of each variable
        of Pair type is INT_MIN*/

        Pair x = new Pair();
        Pair y = new Pair();
        Pair z = new Pair();
        x.first = y.first = z.first = Integer.MIN_VALUE;
        for (Map.Entry curr : freq.entrySet()) {

/*            If frequency of current element
            is not zero and greater than
            frequency of first largest element*/

            if (Integer.parseInt(String.valueOf(curr.getValue())) > x.first) {

/*                Update second and third largest*/

                z.first = y.first;
                z.second = y.second;
                y.first = x.first;
                y.second = x.second;

/*                Modify values of x Number*/

                x.first = Integer.parseInt(String.valueOf(curr.getValue()));
                x.second = Integer.parseInt(String.valueOf(curr.getKey()));
            }

/*            If frequency of current element is
            not zero and frequency of current
            element is less than frequency of
            first largest element, but greater
            than y element*/

            else if (Integer.parseInt(String.valueOf(curr.getValue())) > y.first) {

/*                Modify values of third largest*/

                z.first = y.first;
                z.second = y.second;

/*                Modify values of second largest*/

                y.first = Integer.parseInt(String.valueOf(curr.getValue()));
                y.second = Integer.parseInt(String.valueOf(curr.getKey()));
            }

/*            If frequency of current element
            is not zero and frequency of
            current element is less than
            frequency of first element and
            second largest, but greater than
            third largest.*/

            else if (Integer.parseInt(String.valueOf(curr.getValue())) > z.first) {

/*                Modify values of z Number*/

                z.first = Integer.parseInt(String.valueOf(curr.getValue()));
                z.second = Integer.parseInt(String.valueOf(curr.getKey()));
            }
        }
        System.out.print("Three largest elements are " + x.second + " "
                         + y.second + " " + z.second);
    }

/*    Driver's Code*/

    public static void main(String args[])
    {
        int[] arr = { 3, 4, 2, 3, 16, 3, 15,
                      16, 15, 15, 16, 2, 3 };
        int n = arr.length;
        top3Repeated(arr, n);
    }
}

/*A simple Java program to group
multiple occurrences of individual
array elements*/

class GFG
{

/*    A simple method to group all occurrences
    of individual elements*/

    static void groupElements(int arr[], int n)
    {

/*        Initialize all elements as not visited*/

        boolean visited[] = new boolean[n];
        for (int i = 0; i < n; i++)
        {
            visited[i] = false;
        }

/*        Traverse all elements*/

        for (int i = 0; i < n; i++)
        {

/*            Check if this is first occurrence*/

            if (!visited[i])
            {

/*                If yes, print it and all
                subsequent occurrences*/

                System.out.print(arr[i] + " ");
                for (int j = i + 1; j < n; j++)
                {
                    if (arr[i] == arr[j])
                    {
                        System.out.print(arr[i] + " ");
                        visited[j] = true;
                    }
                }
            }
        }
    }

/* Driver code */

    public static void main(String[] args)
    {
        int arr[] = {4, 6, 9, 2, 3, 4,
                        9, 6, 10, 4};
        int n = arr.length;
        groupElements(arr, n);
    }
}

/* Java program to group multiple occurrences of individual array elements */

import java.util.HashMap;
class Main
{

/*    A hashing based method to group all occurrences of individual elements*/

    static void orderedGroup(int arr[])
    {

/*        Creates an empty hashmap*/

        HashMap<Integer, Integer> hM = new HashMap<Integer, Integer>();

/*        Traverse the array elements, and store count for every element
        in HashMap*/

        for (int i=0; i<arr.length; i++)
        {

/*           Check if element is already in HashMap*/

           Integer prevCount = hM.get(arr[i]);
           if (prevCount == null)
                prevCount = 0;

/*           Increment count of element element in HashMap*/

           hM.put(arr[i], prevCount + 1);
        }

/*        Traverse array again*/

        for (int i=0; i<arr.length; i++)
        {

/*            Check if this is first occurrence*/

            Integer count =  hM.get(arr[i]);    
            if (count != null)
            {

/*                If yes, then print the element 'count' times*/

                for (int j=0; j<count; j++)
                   System.out.print(arr[i] + " ");

/*                And remove the element from HashMap.*/

                hM.remove(arr[i]);
            }
        }
    }

/*    Driver method to test above method*/

    public static void main (String[] args)
    {
        int arr[] = {10, 5, 3, 10, 10, 4, 1, 3};
        orderedGroup(arr);
    }
}

/*Java code to find maximum shortest distance
from endpoints*/

import java.util.*;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    HashMap<Integer,
            Integer> count = new HashMap<Integer,
                                         Integer>();
    for (int i = 0; i < n; i++)
    {
        if(count.containsKey(a[i]))
        {
            count.put(a[i], count.get(a[i]) + 1);
        }
        else
        {
            count.put(a[i], 1);
        }
    }
}

/*function to find maximum shortest distance*/

static int find_maximum(int a[], int n, int k)
{

/*    stores the shortest distance of every
    element in original array.*/

    HashMap<Integer,
            Integer> b = new HashMap<Integer,
                                     Integer>();
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        shortest distance from ends*/

        int d = Math.min(1 + i, n - i);
        if (!b.containsKey(x))
            b.put(x, d);
        else
        {

/* if duplicates are found, b[x]
            is replaced with minimum of the
            previous and current position's
            shortest distance*/

            b. put(x, Math.min(d, b.get(x)));
        }
    }
    int ans = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        similar elements ignore them
        cause we need distinct elements*/

        if (x != k - x && b.containsKey(k - x))        
            ans = Math.min(Math.max(b.get(x),
                                    b.get(k - x)), ans);    
    }
    return ans;
}

/*Driver Code*/

public static void main(String[] args)
{
    int a[] = { 3, 5, 8, 6, 7 };
    int K = 11;
    int n = a.length;
    System.out.println(find_maximum(a, n, K));
}
}

/*Java program if there exists a pair for given product*/

import java.util.HashSet;
class GFG
{

/*    Returns true if there is a pair in arr[0..n-1]
    with product equal to x.*/

    static boolean isProduct(int arr[], int n, int x)
    {

/*        Create an empty set and insert first
        element into it*/

        HashSet<Integer> hset = new HashSet<>();
        if(n < 2)
            return false;

/*        Traverse remaining elements*/

        for(int i = 0; i < n; i++)
        {

/*            0 case must be handles explicitly as
            x % 0 is undefined*/

            if(arr[i] == 0)
            {
                if(x == 0)
                    return true;
                else
                    continue;
            }

/*            x/arr[i] exists in hash, then we
            found a pair*/

            if(x % arr[i] == 0)
            {
                if(hset.contains(x / arr[i]))
                    return true;

/*            Insert arr[i]*/

            hset.add(arr[i]);
            }
        }
        return false;
    }

/*    driver code*/

    public static void main(String[] args)
    {
        int arr[] = {10, 20, 9, 40};
        int x = 400;
        int n = arr.length;
        if(isProduct(arr, arr.length, x))
        System.out.println("Yes");
        else
        System.out.println("No");
        x = 190;
        if(isProduct(arr, arr.length, x))
        System.out.println("Yes");
        else
        System.out.println("No");
    }
}

/*A sorting based Java program to find missing
elements from an array*/

import java.util.Arrays;
public class PrintMissing {

/*    Print all elements of range [low, high] that
    are not present in arr[0..n-1]*/

    static void printMissing(int ar[], int low, int high)
    {
        Arrays.sort(ar);

/*        Do binary search for 'low' in sorted
        array and find index of first element
        which either equal to or greater than
        low.*/

        int index = ceilindex(ar, low, 0, ar.length - 1);
        int x = low;

/*        Start from the found index and linearly
        search every range element x after this
        index in arr[]*/

        while (index < ar.length && x <= high) {

/*            If x doesn't math with current element
            print it*/

            if (ar[index] != x) {
                System.out.print(x + " ");
            }

/*            If x matches, move to next element in arr[]*/

            else
                index++;

/*            Move to next element in range [low, high]*/

            x++;
        }

/*        Print range elements thar are greater than the
        last element of sorted array.*/

        while (x <= high) {
            System.out.print(x + " ");
            x++;
        }
    }

/*    Utility function to find ceil index of given element*/

    static int ceilindex(int ar[], int val, int low, int high)
    {
        if (val < ar[0])
            return 0;
        if (val > ar[ar.length - 1])
            return ar.length;
        int mid = (low + high) / 2;
        if (ar[mid] == val)
            return mid;
        if (ar[mid] < val) {
            if (mid + 1 < high && ar[mid + 1] >= val)
                return mid + 1;
            return ceilindex(ar, val, mid + 1, high);
        }
        else {
            if (mid - 1 >= low && ar[mid - 1] < val)
                return mid;
            return ceilindex(ar, val, low, mid - 1);
        }
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 3, 5, 4 };
        int low = 1, high = 10;
        printMissing(arr, low, high);
    }
}

/*Java program to find the largest product number*/

import java.util.*;
class GFG
{

/*    Function to find greatest number*/

    static int findGreatest(int arr[], int n)
    {

/*        Store occurrences of all
        elements in hash array*/

        Map<Integer, Integer> m = new HashMap<>();
        for (int i = 0; i < n; i++)
        {
            if (m.containsKey(arr[i]))
            {
                m.put(arr[i], m.get(arr[i]) + 1);
            }
            else
            {
                m.put(arr[i], m.get(arr[i]));
            }
        }

/*        m[arr[i]]++;
        Sort the array and traverse
        all elements from end.*/

        Arrays.sort(arr);
        for (int i = n - 1; i > 1; i--)
        {

/*            For every element, check if there is another
            element which divides it.*/

            for (int j = 0; j < i &&
                arr[j] <= Math.sqrt(arr[i]); j++)
            {
                if (arr[i] % arr[j] == 0)
                {
                    int result = arr[i] / arr[j];

/*                    Check if the result value exists in array
                    or not if yes the return arr[i]*/

                    if (result != arr[j] &&
                        m.get(result) == null|| m.get(result) > 0)
                    {
                        return arr[i];
                    }

/*                    To handle the case like arr[i] = 4
                    and arr[j] = 2*/

                    else if (result == arr[j] && m.get(result) > 1)
                    {
                        return arr[i];
                    }
                }
            }
        }
        return -1;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = {17, 2, 1, 15, 30};
        int n = arr.length;
        System.out.println(findGreatest(arr, n));
    }
}

/*Hashing based Java program to find common elements
with minimum index sum.*/

import java.util.*;
class GFG
{

/*    Function to print common Strings with minimum index sum*/

    static void find(Vector<String> list1, Vector<String> list2)
    {

/*        mapping Strings to their indices*/

        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < list1.size(); i++)
            map.put(list1.get(i), i);

/*resultant list*/

Vector<String> res = new Vector<String>(); 
        int minsum = Integer.MAX_VALUE;
        for (int j = 0; j < list2.size(); j++)
        {
            if (map.containsKey(list2.get(j)))
            {

/*                If current sum is smaller than minsum*/

                int sum = j + map.get(list2.get(j));
                if (sum < minsum)
                {
                    minsum = sum;
                    res.clear();
                    res.add(list2.get(j));
                }

/*                if index sum is same then put this
                String in resultant list as well*/

                else if (sum == minsum)
                    res.add(list2.get(j));
            }
        }

/*        Print result*/

        for (int i = 0; i < res.size(); i++)
            System.out.print(res.get(i) + " ");
    }

/*    Driver code*/

    public static void main(String[] args)
    {

/*        Creating list1*/

        Vector<String> list1 = new Vector<String>();
        list1.add("GeeksforGeeks");
        list1.add("Udemy");
        list1.add("Coursera");
        list1.add("edX");

/*        Creating list2*/

        Vector<String> list2 = new Vector<String>();
        list2.add("Codecademy");
        list2.add("Khan Academy");
        list2.add("GeeksforGeeks");
        find(list1, list2);
    }
}

/*Java program to make a permutation of numbers
from 1 to n using minimum changes.*/

import java.util.*;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    HashMap<Integer,
            Integer> count = new HashMap<Integer,
                                         Integer>();
    for (int i = 0; i < n; i++)
    {
        if(count.containsKey(a[i]))
        {
            count.put(a[i], count.get(a[i]) + 1);
        }
        else
        {
            count.put(a[i], 1);
        }
    }
    int next_missing = 1;
    for (int i = 0; i < n; i++)
    {
        if (count.containsKey(a[i]) &&
            count.get(a[i]) != 1 ||
            a[i] > n || a[i] < 1)
        {
            count.put(a[i], count.get(a[i]) - 1);

/*            Find next missing element to put
            in place of current element.*/

            while (count.containsKey(next_missing))
                next_missing++;

/*            Replace with next missing and insert
            the missing element in hash.*/

            a[i] = next_missing;
            count. put(next_missing, 1);
        }
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int A[] = { 2, 2, 3, 3 };
    int n = A.length;
    makePermutation(A, n);
    for (int i = 0; i < n; i++)
        System.out.print(A[i] + " ");
    }
}

/*Java implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

class GFG {

/*count pairs from the two sorted array whose sum
is equal to the given 'value'*/

static int countPairs(int arr1[], int arr2[], int n, int value)
{
    int count = 0;
    int l = 0, r = n - 1;

/*    traverse 'arr1[]' from left to right
    traverse 'arr2[]' from right to left*/

    while (l < n & r >= 0) {
        int sum = arr1[l] + arr2[r];

/*        if the 'sum' is equal to 'value', then
        increment 'l', decrement 'r' and
        increment 'count'*/

        if (sum == value) {
            l++; r--;
            count++;
        }

/*        if the 'sum' is greater than 'value', then
        decrement r*/

        else if (sum > value)
            r--;

/*        else increment l*/

        else
            l++;
    }

/*    required count of pairs*/

    return count;
}

/*function to count all quadruples from four sorted arrays
whose sum is equal to a given value x*/

static int countQuadruples(int arr1[], int arr2[], int arr3[],
                    int arr4[], int n, int x)
{
    int count = 0;

/*    generate all pairs from arr1[] and arr2[]*/

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) {

/*            calculate the sum of elements in
            the pair so generated*/

            int p_sum = arr1[i] + arr2[j];

/*            count pairs in the 3rd and 4th array
            having value 'x-p_sum' and then
            accumulate it to 'count'*/

            count += countPairs(arr3, arr4, n, x - p_sum);
        }

/*    required count of quadruples*/

    return count;
}

/*Driver program to test above*/

    static public void main(String[] args) {

/*        four sorted arrays each of size 'n'*/

        int arr1[] = {1, 4, 5, 6};
        int arr2[] = {2, 3, 7, 8};
        int arr3[] = {1, 4, 6, 10};
        int arr4[] = {2, 4, 7, 8};
        int n = arr1.length;
        int x = 30;
        System.out.println("Count = "
                + countQuadruples(arr1, arr2, arr3, arr4, n, x));
    }
}

/*Java program to count pairs
