/*JAVA program to check if arr[0..n-1] can be divided
in pairs such that every pair is divisible by k.*/

import java.util.HashMap;
public class Divisiblepair {

/*    Returns true if arr[0..n-1] can be divided into pairs
    with sum divisible by k.*/

    static boolean canPairs(int ar[], int k)
    {

/*        An odd length array cannot be divided into pairs*/

        if (ar.length % 2 == 1)
            return false;

/*        Create a frequency array to count occurrences
        of all remainders when divided by k.*/

        HashMap<Integer, Integer> hm = new HashMap<>();

/*        Count occurrences of all remainders*/

        for (int i = 0; i < ar.length; i++) {
            int rem = ((ar[i] % k) + k) % k;
            if (!hm.containsKey(rem)) {
                hm.put(rem, 0);
            }
            hm.put(rem, hm.get(rem) + 1);
        }

/*        Traverse input array and use freq[] to decide
        if given array can be divided in pairs*/

        for (int i = 0; i < ar.length; i++) {

/*            Remainder of current element*/

            int rem = ((ar[i] % k) + k) % k;

/*            If remainder with current element divides
            k into two halves.*/

            if (2 * rem == k) {

/*                Then there must be even occurrences of
                such remainder*/

                if (hm.get(rem) % 2 == 1)
                    return false;
            }

/*            If remainder is 0, then there must be two
            elements with 0 remainder*/

            else if (rem == 0) {

/*                Then there must be even occurrences of
                such remainder*/

                if (hm.get(rem) % 2 == 1)
                    return false;
            }

/*            Else number of occurrences of remainder
            must be equal to number of occurrences of
            k - remainder*/

            else {
                if (hm.get(k - rem) != hm.get(rem))
                    return false;
            }
        }
        return true;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 92, 75, 65, 48, 45, 35 };
        int k = 10;

/*        Function call*/

        boolean ans = canPairs(arr, k);
        if (ans)
            System.out.println("True");
        else
            System.out.println("False");
    }
}

/*Java program to find three element
from different three arrays such
that a + b + c is equal to
given sum*/

import java.util.*;
class GFG
{

/*    Function to check if there is
    an element from each array such
    that sum of the three elements is
    equal to given sum.*/

    static boolean findTriplet(int a1[], int a2[], int a3[],
                                int n1, int n2, int n3,
                                int sum)
    {

/*        Store elements of
        first array in hash*/

        HashSet<Integer> s = new HashSet<Integer>();
        for (int i = 0; i < n1; i++)
        {
            s.add(a1[i]);
        }

/*        sum last two arrays
        element one by one*/

        ArrayList<Integer> al = new ArrayList<>(s);
        for (int i = 0; i < n2; i++)
        {
            for (int j = 0; j < n3; j++)
            {

/*                Consider current pair and
                find if there is an element
                in a1[] such that these three
                form a required triplet*/

                if (al.contains(sum - a2[i] - a3[j]) &
                            al.indexOf(sum - a2[i] - a3[j])
                            != al.get(al.size() - 1))
                {
                    return true;
                }
            }
        }
        return false;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int a1[] = {1, 2, 3, 4, 5};
        int a2[] = {2, 3, 6, 1, 2};
        int a3[] = {3, 2, 4, 5, 6};
        int sum = 9;
        int n1 = a1.length;
        int n2 = a2.length;
        int n3 = a3.length;
        if (findTriplet(a1, a2, a3, n1, n2, n3, sum))
        {
            System.out.println("Yes");
        }
        else
        {
            System.out.println("No");
        }
    }
}

/*Java Program to find four different elements a,b,c and d of
array such that a+b = c+d*/

import java.io.*;
import java.util.*;
class ArrayElements
{

/*    Class to represent a pair*/

    class pair
    {
        int first, second;
        pair(int f,int s)
        {
            first = f; second = s;
        }
    };

/*function to find a, b, c, d such that
(a + b) = (c + d)*/

    boolean findPairs(int arr[])
    {

/*        Create an empty Hash to store mapping from sum to
        pair indexes*/

        HashMap<Integer,pair> map = new HashMap<Integer,pair>();
        int n=arr.length;

/*        Traverse through all possible pairs of arr[]*/

        for (int i=0; i<n; ++i)
        {
            for (int j=i+1; j<n; ++j)
            {

/*                If sum of current pair is not in hash,
                then store it and continue to next pair*/

                int sum = arr[i]+arr[j];
                if (!map.containsKey(sum))
                    map.put(sum,new pair(i,j));
else 
                {
                    pair p = map.get(sum);
                    System.out.println("("+arr[p.first]+", "+arr[p.second]+
                                      ") and ("+arr[i]+", "+arr[j]+")");
                    return true;
                }
            }
        }
        return false;
    }

/*    Testing program*/

    public static void main(String args[])
    {
        int arr[] = {3, 4, 7, 1, 2, 9, 8};
        ArrayElements a = new ArrayElements();
        a.findPairs(arr);
    }
}

/*Java program to find length of the
longest increasing subsequence
whose adjacent element differ by 1*/

import java.util.*;
class lics {

/*function that returns the length of the
longest increasing subsequence
whose adjacent element differ by 1*/

    static int LongIncrConseqSubseq(int arr[], int n)
    {

/*        create hashmap to save latest consequent
        number as "key" and its length as "value"*/

        HashMap<Integer, Integer> map = new HashMap<>();

/*        put first element as "key" and its length as "value"*/

        map.put(arr[0], 1);

/*    iterate for all element*/

        for (int i = 1; i < n; i++) {

/*            check if last consequent of arr[i] exist or not*/

            if (map.containsKey(arr[i] - 1)) {

/*                put the updated consequent number
                and increment its value(length)*/

                map.put(arr[i], map.get(arr[i] - 1) + 1);
                map.remove(arr[i] - 1);
            }
            else {
                map.put(arr[i], 1);
            }
        }
        return Collections.max(map.values());
    }

/*    driver code*/

    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int arr[] = new int[n];
        for (int i = 0; i < n; i++)
            arr[i] = sc.nextInt();
        System.out.println(LongIncrConseqSubseq(arr, n));
    }
}

/*Java Program to find longest consecutive
subsequence This Program uses Priority Queue*/

import java.io.*;
import java.util.PriorityQueue;
public class Longset_Sub
{

/*    return the length of the longest
    subsequence of consecutive integers*/

    static int findLongestConseqSubseq(int arr[], int N)
    {
        PriorityQueue<Integer> pq
            = new PriorityQueue<Integer>();
        for (int i = 0; i < N; i++)
        {

/*            adding element from
            array to PriorityQueue*/

            pq.add(arr[i]);
        }

/*        Storing the first element
        of the Priority Queue
        This first element is also
        the smallest element*/

        int prev = pq.poll();

/*        Taking a counter variable with value 1*/

        int c = 1;

/*        Storing value of max as 1
        as there will always be
        one element*/

        int max = 1;
        for (int i = 1; i < N; i++)
        {

/*            check if current peek
            element minus previous
            element is greater then
            1 This is done because
            if it's greater than 1
            then the sequence
            doesn't start or is broken here*/

            if (pq.peek() - prev > 1)
            {

/*                Store the value of counter to 1
                As new sequence may begin*/

                c = 1;

/*                Update the previous position with the
                current peek And remove it*/

                prev = pq.poll();
            }

/*            Check if the previous
              element and peek are same*/

            else if (pq.peek() - prev == 0)
            {

/*                Update the previous position with the
                current peek And remove it*/

                prev = pq.poll();
            }

/*            if the difference
            between previous element and peek is 1*/

            else
            {

/*                Update the counter
                These are consecutive elements*/

                c++;

/*                Update the previous position
                  with the current peek And remove it*/

                prev = pq.poll();
            }

/*            Check if current longest
            subsequence is the greatest*/

            if (max < c)
            {

/*                Store the current subsequence count as
                max*/

                max = c;
            }
        }
        return max;
    }

/*    Driver Code*/

    public static void main(String args[])
        throws IOException
    {
        int arr[] = { 1, 9, 3, 10, 4, 20, 2 };
        int n = arr.length;
        System.out.println(
            "Length of the Longest consecutive subsequence is "
            + findLongestConseqSubseq(arr, n));
    }
}

/*Java program to print subarray with sum as given sum*/

import java.util.*;
class GFG {

/*Function to print subarray with sum as given sum*/

    public static void subArraySum(int[] arr, int n, int sum) {

/*        cur_sum to keep track of cummulative sum till that point*/

        int cur_sum = 0;
        int start = 0;
        int end = -1;
        HashMap<Integer, Integer> hashMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            cur_sum = cur_sum + arr[i];

/*            check whether cur_sum - sum = 0, if 0 it means
            the sub array is starting from index 0- so stop*/

            if (cur_sum - sum == 0) {
                start = 0;
                end = i;
                break;
            }

/*            if hashMap already has the value, means we already
            have subarray with the sum - so stop*/

            if (hashMap.containsKey(cur_sum - sum)) {
                start = hashMap.get(cur_sum - sum) + 1;
                end = i;
                break;
            }

/*            if value is not present then add to hashmap*/

            hashMap.put(cur_sum, i);
        }

/*        if end is -1 : means we have reached end without the sum*/

        if (end == -1) {
            System.out.println("No subarray with given sum exists");
        } else {
            System.out.println("Sum found between indexes "
                            + start + " to " + end);
        }
    }

/*    Driver code*/

    public static void main(String[] args) {
        int[] arr = {10, 2, -2, -20, 10};
        int n = arr.length;
        int sum = -10;
        subArraySum(arr, n, sum);
    }
}

/*JAVA Code for Difference between
highest and least frequencies
in an array*/

import java.util.*;
class GFG {
    static int findDiff(int arr[], int n)
    {

/*        sort the array*/

        Arrays.sort(arr);
        int count = 0, max_count = 0,
            min_count = n;
        for (int i = 0; i < (n - 1); i++) {

/*            checking consecutive elements*/

            if (arr[i] == arr[i + 1]) {
                count += 1;
                continue;
            }
            else {
                max_count = Math.max(max_count,
                                     count);
                min_count = Math.min(min_count,
                                     count);
                count = 0;
            }
        }
        return (max_count - min_count);
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[] = { 7, 8, 4, 5, 4, 1,
                      1, 7, 7, 2, 5 };
        int n = arr.length;
        System.out.println(findDiff(arr, n));
    }
}

/*Java code to find the difference between highest
and least frequencies*/

import java.util.*;
class GFG
{
static int findDiff(int arr[], int n)
{

/*    Put all elements in a hash map*/

    Map<Integer,Integer> mp = new HashMap<>();
    for (int i = 0 ; i < n; i++)
    {
        if(mp.containsKey(arr[i]))
        {
            mp.put(arr[i], mp.get(arr[i])+1);
        }
        else
        {
            mp.put(arr[i], 1);
        }
    }

/*    Find counts of maximum and minimum
    frequent elements*/

    int max_count = 0, min_count = n;
    for (Map.Entry<Integer,Integer> x : mp.entrySet())
    {
        max_count = Math.max(max_count, x.getValue());
        min_count = Math.min(min_count, x.getValue());
    }
    return (max_count - min_count);
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 7, 8, 4, 5, 4, 1, 1, 7, 7, 2, 5 };
    int n = arr.length;
    System.out.println(findDiff(arr, n));
}
}

/*java find maximum difference
of subset sum*/

import java .io.*;
public class GFG {

/*    function for maximum subset diff*/

    static int maxDiff(int []arr, int n)
    {
        int SubsetSum_1 = 0, SubsetSum_2 = 0;
        for (int i = 0; i <= n - 1; i++)
        {
            boolean isSingleOccurance = true;
            for (int j = i + 1; j <= n - 1; j++)
            {

/*                if frequency of any element
                is two make both equal to
                zero*/

                if (arr[i] == arr[j])
                {
                    isSingleOccurance = false;
                    arr[i] = arr[j] = 0;
                    break;
                }
            }
            if (isSingleOccurance)
            {
                if (arr[i] > 0)
                    SubsetSum_1 += arr[i];
                else
                    SubsetSum_2 += arr[i];
            }
        }
        return Math.abs(SubsetSum_1 - SubsetSum_2);
    }

/*    driver program*/

    static public void main (String[] args)
    {
        int []arr = { 4, 2, -3, 3, -2, -2, 8 };
        int n = arr.length;
        System.out.println("Maximum Difference = "
                               + maxDiff(arr, n));
    }
}

/*Java find maximum
difference of subset sum*/

import java.util.*;
class GFG{

/*Function for maximum subset diff*/

public static int maxDiff(int arr[],
                          int n)
{
  HashMap<Integer,
          Integer> hashPositive = new HashMap<>();
  HashMap<Integer,
          Integer> hashNegative = new HashMap<>();
  int SubsetSum_1 = 0,
      SubsetSum_2 = 0;

/*  Construct hash for
  positive elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] > 0)
    {
      if(hashPositive.containsKey(arr[i]))
      {
        hashPositive.replace(arr[i],
        hashPositive.get(arr[i]) + 1);
      }
      else
      {
        hashPositive.put(arr[i], 1);
      }
    }
  }

/*  Calculate subset sum
  for positive elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if(arr[i] > 0 &&
       hashPositive.containsKey(arr[i]))
    {
      if(hashPositive.get(arr[i]) == 1)
      {
        SubsetSum_1 += arr[i];
      }
    }
  }

/*  Construct hash for
  negative elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] < 0)
    {
      if(hashNegative.containsKey(Math.abs(arr[i])))
      {
        hashNegative.replace(Math.abs(arr[i]),
        hashNegative.get(Math.abs(arr[i])) + 1);
      }
      else
      {
        hashNegative.put(Math.abs(arr[i]), 1);
      }
    }
  }

/*  Calculate subset sum for
  negative elements*/

  for (int i = 0; i <= n - 1; i++)
  {
    if (arr[i] < 0 &&
        hashNegative.containsKey(Math.abs(arr[i])))
    {
      if(hashNegative.get(Math.abs(arr[i])) == 1)
      {
        SubsetSum_2 += arr[i];
      }
    }
  }
  return Math.abs(SubsetSum_1 - SubsetSum_2);
}

/*Driver code*/

public static void main(String[] args)
{
  int arr[] = {4, 2, -3, 3,
               -2, -2, 8};
  int n = arr.length;
  System.out.print("Maximum Difference = " +
                    maxDiff(arr, n));
}
}

/*Java program to find longest subarray with
k or less distinct elements.*/

import java.util.*;
class GFG
{

/*function to print the longest sub-array*/

static void longest(int a[], int n, int k)
{
    int[] freq = new int[7];
    int start = 0, end = 0, now = 0, l = 0;
    for (int i = 0; i < n; i++)
    {

/*        mark the element visited*/

        freq[a[i]]++;

/*        if its visited first time, then increase
        the counter of distinct elements by 1*/

        if (freq[a[i]] == 1)
            now++;

/*        When the counter of distinct elements
        increases from k, then reduce it to k*/

        while (now > k)
        {

/*            from the left, reduce the number of
            time of visit*/

            freq[a[l]]--;

/*            if the reduced visited time element
            is not present in further segment
            then decrease the count of distinct
            elements*/

            if (freq[a[l]] == 0)
                now--;

/*            increase the subsegment mark*/

            l++;
        }

/*        check length of longest sub-segment
        when greater then previous best
        then change it*/

        if (i - l + 1 >= end - start + 1)
        {
            end = i;
            start = l;
        }
    }

/*    print the longest sub-segment*/

    for (int i = start; i <= end; i++)
        System.out.print(a[i]+" ");
}

/*Driver code*/

public static void main(String args[])
{
    int a[] = { 6, 5, 1, 2, 3, 2, 1, 4, 5 };
    int n = a.length;
    int k = 3;
    longest(a, n, k);
}
}

/*Java program to calculate 
the sum of f(a[i], aj])*/

import java.util.*;
public class GfG {

/*    Function to calculate the sum*/

    public static int sum(int a[], int n)
    {

/*        Map to keep a count of occurrences*/

        Map<Integer,Integer> cnt = new HashMap<Integer,Integer>();

/*        Traverse in the list from start to end
        number of times a[i] can be in a pair and
        to get the difference we subtract pre_sum*/

        int ans = 0, pre_sum = 0;
        for (int i = 0; i < n; i++) {
            ans += (i * a[i]) - pre_sum;
            pre_sum += a[i];

/*            If the (a[i]-1) is present then subtract
            that value as f(a[i], a[i]-1) = 0*/

            if (cnt.containsKey(a[i] - 1))
                ans -= cnt.get(a[i] - 1);

/*            If the (a[i]+1) is present then
            add that value as f(a[i], a[i]-1)=0
            here we add as a[i]-(a[i]-1)<0 which would
            have been added as negative sum, so we add
            to remove this pair from the sum value*/

            if (cnt.containsKey(a[i] + 1))
                ans += cnt.get(a[i] + 1);

/*            keeping a counter for every element*/

            if(cnt.containsKey(a[i])) {
                cnt.put(a[i], cnt.get(a[i]) + 1);
            }
            else {
                cnt.put(a[i], 1);
            }
        }
        return ans;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 1, 2, 3, 1, 3 };
        int n = a.length;
        System.out.println(sum(a, n));
    }
}

/*Java program to find number
of pairs in an array such
that their XOR is 0*/

import java.util.*;
class GFG
{

/*    Function to calculate
    the count*/

    static int calculate(int a[], int n)
    {

/*        Sorting the list using
        built in function*/

        Arrays.sort(a);
        int count = 1;
        int answer = 0;

/*        Traversing through the
        elements*/

        for (int i = 1; i < n; i++)
        {
            if (a[i] == a[i - 1])
            {

/*                Counting frequency of each
                elements*/

                count += 1;
            }
            else
            {

/*                Adding the contribution of
                the frequency to the answer*/

                answer = answer + (count * (count - 1)) / 2;
                count = 1;
            }
        }
        answer = answer + (count * (count - 1)) / 2;
        return answer;
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int a[] = { 1, 2, 1, 2, 4 };
        int n = a.length;

/*        Print the count*/

        System.out.println(calculate(a, n));
    }
}

class LargestSubArray {

/*    This function Prints the starting and ending
    indexes of the largest subarray with equal
    number of 0s and 1s. Also returns the size
    of such subarray.*/

    int findSubArray(int arr[], int n)
    {
        int sum = 0;
        int maxsize = -1, startindex = 0;
        int endindex = 0;

/*        Pick a starting point as i*/

        for (int i = 0; i < n - 1; i++) {
            sum = (arr[i] == 0) ? -1 : 1;

/*            Consider all subarrays starting from i*/

            for (int j = i + 1; j < n; j++) {
                if (arr[j] == 0)
                    sum += -1;
                else
                    sum += 1;

/*                If this is a 0 sum subarray, then
                compare it with maximum size subarray
                calculated so far*/

                if (sum == 0 && maxsize < j - i + 1) {
                    maxsize = j - i + 1;
                    startindex = i;
                }
            }
        }
        endindex = startindex + maxsize - 1;
        if (maxsize == -1)
            System.out.println("No such subarray");
        else
            System.out.println(startindex + " to " + endindex);
        return maxsize;
    }

/* Driver program to test the above functions */

    public static void main(String[] args)
    {
        LargestSubArray sub;
        sub = new LargestSubArray();
        int arr[] = { 1, 0, 0, 1, 0, 1, 1 };
        int size = arr.length;
        sub.findSubArray(arr, size);
    }
}

/*Java implementation to print
all the triplets in given array
that form Arithmetic Progression*/

import java.io.*;
class GFG
{

/*    Function to print all triplets in
    given sorted array that forms AP*/

    static void findAllTriplets(int arr[], int n)
    {
        for (int i = 1; i < n - 1; i++)
        {

/*            Search other two elements
            of AP with arr[i] as middle.*/

            for (int j = i - 1, k = i + 1; j >= 0 && k < n;)
            {

/*                if a triplet is found*/

                if (arr[j] + arr[k] == 2 * arr[i])
                {
                    System.out.println(arr[j] +" " +
                                       arr[i]+ " " + arr[k]);

/*                    Since elements are distinct,
                    arr[k] and arr[j] cannot form
                    any more triplets with arr[i]*/

                    k++;
                    j--;
                }

/*                If middle element is more move to
                higher side, else move lower side.*/

                else if (arr[j] + arr[k] < 2 * arr[i])
                    k++;        
                else
                    j--;        
            }
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int arr[] = { 2, 6, 9, 12, 17,
                      22, 31, 32, 35, 42 };
        int n = arr.length;
        findAllTriplets(arr, n);
    }
}

/*Java program to find all unique triplets
without using any extra space.*/

import java.util.*;
public class Main
{

/*    Function to all find unique triplets
    without using extra space*/

    public static void findTriplets(int a[], int n, int sum)
    {
        int i;

/*        Sort the input array*/

        Arrays.sort(a);

/*        For handling the cases when no such
        triplets exits.*/

        boolean flag = false;

/*        Iterate over the array from start to n-2.*/

        for (i = 0; i < n - 2; i++)
        {
            if (i == 0 || a[i] > a[i - 1])
            {

/*                Index of the first element in
                remaining range.*/

                int start = i + 1;

/*                Index of the last element*/

                int end = n - 1;

/*                Setting our new target*/

                int target = sum - a[i];
                while (start < end)
                {

/*                    Checking if current element
                    is same as previous*/

                    if (start > i + 1
                        && a[start] == a[start - 1])
                    {
                        start++;
                        continue;
                    }

/*                    Checking if current element is
                    same as previous*/

                    if (end < n - 1
                        && a[end] == a[end + 1])
                    {
                        end--;
                        continue;
                    }

/*                    If we found the triplets then print it
                    and set the flag*/

                    if (target == a[start] + a[end])
                    {
                        System.out.print("[" + a[i]
                             + "," + a[start]
                             + "," + a[end] + "] ");
                        flag = true;
                        start++;
                        end--;
                    }

/*                    If target is greater then
                      increment the start index*/

                    else if (target > (a[start] + a[end]))
                    {
                        start++;
                    }

/*                    If target is smaller than
                    decrement the end index*/

                    else {
                        end--;
                    }
                }
            }
        }

/*        If no such triplets found*/

        if (flag == false) {
            System.out.print("No Such Triplets Exist");
        }
    }

/*Driver code*/

    public static void main(String[] args) {
        int a[] = { 12, 3, 6, 1, 6, 9 };
        int n = a.length;
        int sum = 24;

/*        Function call*/

        findTriplets(a, n, sum);
    }
}

/* A Java program to answer queries to check whether 
the substrings are palindrome or not efficiently */

public class GFG {
    static int p = 101;
    static int MOD = 1000000007;

/*    Structure to represent a query. A query consists
    of (L, R) and we have to answer whether the substring
    from index-L to R is a palindrome or not*/

    static class Query {
        int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    A function to check if a string str is palindrome
    in the ranfe L to R*/

    static boolean isPalindrome(String str, int L, int R)
    {

/*        Keep comparing characters while they are same*/

        while (R > L) {
            if (str.charAt(L++) != str.charAt(R--)) {
                return (false);
            }
        }
        return (true);
    }

/*    A Function to find pow (base, exponent) % MOD
    in log (exponent) time*/

    static int modPow(int base, int exponent)
    {
        if (exponent == 0) {
            return 1;
        }
        if (exponent == 1) {
            return base;
        }
        int temp = modPow(base, exponent / 2);
        if (exponent % 2 == 0) {
            return (temp % MOD * temp % MOD) % MOD;
        }
        else {
            return (((temp % MOD * temp % MOD) % MOD)
                    * base % MOD)
                % MOD;
        }
    }

/*    A Function to calculate
    Modulo Multiplicative Inverse of 'n'*/

    static int findMMI(int n)
    {
        return modPow(n, MOD - 2);
    }

/*    A Function to calculate the prefix hash*/

    static void computePrefixHash(String str, int n,
                                  int prefix[], int power[])
    {
        prefix[0] = 0;
        prefix[1] = str.charAt(0);
        for (int i = 2; i <= n; i++) {
            prefix[i] = (prefix[i - 1] % MOD
                         + (str.charAt(i - 1) % MOD
                            * power[i - 1] % MOD)
                               % MOD)
                        % MOD;
        }
        return;
    }

/*    A Function to calculate the suffix hash
    Suffix hash is nothing but the prefix hash of
    the reversed string*/

    static void computeSuffixHash(String str, int n,
                                  int suffix[], int power[])
    {
        suffix[0] = 0;
        suffix[1] = str.charAt(n - 1);
        for (int i = n - 2, j = 2; i >= 0 && j <= n; i--, j++) {
            suffix[j] = (suffix[j - 1] % MOD
                         + (str.charAt(i) % MOD
                            * power[j - 1] % MOD)
                               % MOD)
                        % MOD;
        }
        return;
    }

/*    A Function to answer the Queries*/

    static void queryResults(
        String str, Query q[], int m, int n,
        int prefix[], int suffix[], int power[])
    {
        for (int i = 0; i <= m - 1; i++) {
            int L = q[i].L;
            int R = q[i].R;

/*            Hash Value of Substring [L, R]*/

            long hash_LR
                = ((prefix[R + 1] - prefix[L] + MOD) % MOD
                   * findMMI(power[L]) % MOD)
                  % MOD;

/*            Reverse Hash Value of Substring [L, R]*/

            long reverse_hash_LR
                = ((suffix[n - L] - suffix[n - R - 1] + MOD) % MOD
                   * findMMI(power[n - R - 1]) % MOD)
                  % MOD;

/*            If both are equal then the substring is a palindrome*/

            if (hash_LR == reverse_hash_LR) {
                if (isPalindrome(str, L, R) == true) {
                    System.out.printf("The Substring [%d %d] is a "
                                          + "palindrome\n",
                                      L, R);
                }
                else {
                    System.out.printf("The Substring [%d %d] is not a "
                                          + "palindrome\n",
                                      L, R);
                }
            }
            else {
                System.out.printf("The Substring [%d %d] is not a "
                                      + "palindrome\n",
                                  L, R);
            }
        }
        return;
    }

/*    A Dynamic Programming Based Approach to compute the
    powers of 101*/

    static void computePowers(int power[], int n)
    {

/*        101^0 = 1*/

        power[0] = 1;
        for (int i = 1; i <= n; i++) {
            power[i] = (power[i - 1] % MOD * p % MOD) % MOD;
        }
        return;
    }

/* Driver code */

    public static void main(String[] args)
    {
        String str = "abaaabaaaba";
        int n = str.length();

/*        A Table to store the powers of 101*/

        int[] power = new int[n + 1];
        computePowers(power, n);

/*        Arrays to hold prefix and suffix hash values*/

        int[] prefix = new int[n + 1];
        int[] suffix = new int[n + 1];

/*        Compute Prefix Hash and Suffix Hash Arrays*/

        computePrefixHash(str, n, prefix, power);
        computeSuffixHash(str, n, suffix, power);
        Query q[] = { new Query(0, 10), new Query(5, 8),
                      new Query(2, 5), new Query(5, 9) };
        int m = q.length;
        queryResults(str, q, m, n, prefix, suffix, power);
    }
}

/*Java program to finds out smallest range that includes
elements from each of the given sorted lists.*/

class GFG {
    static final int N = 5;

/*    array for storing the current index of list i*/

    static int ptr[] = new int[501];

/*    This function takes an k sorted lists in the form of
    2D array as an argument. It finds out smallest range
    that includes elements from each of the k lists.*/

    static void findSmallestRange(int arr[][], int n, int k)
    {
        int i, minval, maxval, minrange, minel = 0, maxel = 0, flag, minind;

/*        initializing to 0 index;*/

        for (i = 0; i <= k; i++) {
            ptr[i] = 0;
        }
        minrange = Integer.MAX_VALUE;
        while (true) {

/*            for maintaining the index of list containing the minimum element*/

            minind = -1;
            minval = Integer.MAX_VALUE;
            maxval = Integer.MIN_VALUE;
            flag = 0;

/*            iterating over all the list*/

            for (i = 0; i < k; i++) {

/*                if every element of list[i] is traversed then break the loop*/

                if (ptr[i] == n) {
                    flag = 1;
                    break;
                }

/*                find minimum value among all the list elements pointing by the ptr[] array*/

                if (ptr[i] < n && arr[i][ptr[i]] < minval) {

/*update the index of the list*/

minind = i; 
                    minval = arr[i][ptr[i]];
                }

/*                find maximum value among all the list elements pointing by the ptr[] array*/

                if (ptr[i] < n && arr[i][ptr[i]] > maxval) {
                    maxval = arr[i][ptr[i]];
                }
            }

/*            if any list exhaust we will not get any better answer, so break the while loop*/

            if (flag == 1) {
                break;
            }
            ptr[minind]++;

/*            updating the minrange*/

            if ((maxval - minval) < minrange) {
                minel = minval;
                maxel = maxval;
                minrange = maxel - minel;
            }
        }
        System.out.printf("The smallest range is [%d, %d]\n", minel, maxel);
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[][] = {
            { 4, 7, 9, 12, 15 },
            { 0, 8, 10, 14, 20 },
            { 6, 12, 16, 30, 50 }
        };
        int k = arr.length;
        findSmallestRange(arr, N, k);
    }
}

/*Java program to demonstrate working of
Cuckoo hashing.*/

import java.util.*;
class GFG
{

/*upper bound on number of elements in our set*/

static int MAXN = 11;

/*choices for position*/

static int ver = 2;

/*Auxiliary space bounded by a small multiple
of MAXN, minimizing wastage*/

static int [][]hashtable = new int[ver][MAXN];

/*Array to store possible positions for a key*/

static int []pos = new int[ver];

/* function to fill hash table with dummy value
* dummy value: INT_MIN
* number of hashtables: ver */

static void initTable()
{
    for (int j = 0; j < MAXN; j++)
        for (int i = 0; i < ver; i++)
            hashtable[i][j] = Integer.MIN_VALUE;
}

/* return hashed value for a key
* function: ID of hash function according to which
    key has to hashed
* key: item to be hashed */

static int hash(int function, int key)
{
    switch (function)
    {
        case 1: return key % MAXN;
        case 2: return (key / MAXN) % MAXN;
    }
    return Integer.MIN_VALUE;
}

/* function to place a key in one of its possible positions
* tableID: table in which key has to be placed, also equal
  to function according to which key must be hashed
* cnt: number of times function has already been called
  in order to place the first input key
* n: maximum number of times function can be recursively
  called before stopping and declaring presence of cycle */

static void place(int key, int tableID, int cnt, int n)
{

/* if function has been recursively called max number
    of times, stop and declare cycle. Rehash. */

    if (cnt == n)
    {
        System.out.printf("%d unpositioned\n", key);
        System.out.printf("Cycle present. REHASH.\n");
        return;
    }

/* calculate and store possible positions for the key.
    * check if key already present at any of the positions.
    If YES, return. */

    for (int i = 0; i < ver; i++)
    {
        pos[i] = hash(i + 1, key);
        if (hashtable[i][pos[i]] == key)
        return;
    }

/* check if another key is already present at the
       position for the new key in the table
    * If YES: place the new key in its position
    * and place the older key in an alternate position
    for it in the next table */

    if (hashtable[tableID][pos[tableID]] != Integer.MIN_VALUE)
    {
        int dis = hashtable[tableID][pos[tableID]];
        hashtable[tableID][pos[tableID]] = key;
        place(dis, (tableID + 1) % ver, cnt + 1, n);
    }

/*else: place the new key in its position*/

else 
    hashtable[tableID][pos[tableID]] = key;
}

/* function to print hash table contents */

static void printTable()
{
    System.out.printf("Final hash tables:\n");
    for (int i = 0; i < ver; i++, System.out.printf("\n"))
        for (int j = 0; j < MAXN; j++)
            if(hashtable[i][j] == Integer.MIN_VALUE)
                System.out.printf("- ");
            else
                System.out.printf("%d ", hashtable[i][j]);
    System.out.printf("\n");
}

/* function for Cuckoo-hashing keys
* keys[]: input array of keys
* n: size of input array */

static void cuckoo(int keys[], int n)
{

/*    initialize hash tables to a dummy value
    (INT-MIN) indicating empty position*/

    initTable();

/*    start with placing every key at its position in
    the first hash table according to first hash
    function*/

    for (int i = 0, cnt = 0; i < n; i++, cnt = 0)
        place(keys[i], 0, cnt, n);

/*    print the final hash tables*/

    printTable();
}

/*Driver Code*/

public static void main(String[] args)
{

/* following array doesn't have any cycles and
    hence all keys will be inserted without any
    rehashing */

    int keys_1[] = {20, 50, 53, 75, 100,
                    67, 105, 3, 36, 39};
    int n = keys_1.length;
    cuckoo(keys_1, n);

/* following array has a cycle and hence we will
    have to rehash to position every key */

    int keys_2[] = {20, 50, 53, 75, 100,
                    67, 105, 3, 36, 39, 6};
    int m = keys_2.length;
    cuckoo(keys_2, m);
}
}

/*Java program to find total
number of even-odd subarrays
present in given array*/

class GFG {

/*    function that returns the
    count of subarrays that
    contain equal number of
    odd as well as even numbers*/

    static int countSubarrays(int[] arr,
            int n) {

/*        initialize difference
        and answer with 0*/

        int difference = 0;
        int ans = 0;

/*        create two auxiliary hash
        arrays to count frequency
        of difference, one array
        for non-negative difference
        and other array for negative
        difference. Size of these
        two auxiliary arrays is 'n+1'
        because difference can
        reach maximum value 'n' as
        well as minimum value '-n'*/

/*        initialize these
        auxiliary arrays with 0*/

        int[] hash_positive = new int[n + 1];
        int[] hash_negative = new int[n + 1];

/*        since the difference is
        initially 0, we have to
        initialize hash_positive[0] with 1*/

        hash_positive[0] = 1;

/*        for loop to iterate
        through whole array
        (zero-based indexing is used)*/

        for (int i = 0; i < n; i++) {

/*            incrementing or decrementing
            difference based on
            arr[i] being even or odd,
            check if arr[i] is odd*/

            if ((arr[i] & 1) == 1) {
                difference++;
            } else {
                difference--;
            }

/*            adding hash value of 'difference'
            to our answer as all the previous
            occurrences of the same difference
            value will make even-odd subarray
            ending at index 'i'. After that,
            we will increment hash array for
            that 'difference' value for its
            occurrence at index 'i'. if
            difference is negative then use
            hash_negative*/

            if (difference < 0) {
                ans += hash_negative[-difference];
                hash_negative[-difference]++;

/*else use hash_positive*/

} 
            else {
                ans += hash_positive[difference];
                hash_positive[difference]++;
            }
        }

/*        return total number
        of even-odd subarrays*/

        return ans;
    }

/*    Driver code*/

    public static void main(String[] args) {
        int[] arr = new int[]{3, 4, 6, 8,
            1, 10, 5, 7};
        int n = arr.length;

/*        Printing total number
        of even-odd subarrays*/

        System.out.println("Total Number of Even-Odd"
                + " subarrays are "
                + countSubarrays(arr, n));
    }
}

/*Java Program to find the largest
such that d = a + b + c*/

import java.io.*;
import java.util.Arrays;
class GFG
{

/*function to find largest d*/

static int findLargestd(int []S, int n)
{
    boolean found = false;

/*    sort the array in
    ascending order*/

    Arrays.sort(S);

/*    iterating from backwards to
    find the required largest d*/

    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = 0; j < n; j++)
        {

/*            since all four a, b, c,
            d should be distinct*/

            if (i == j)
                continue;
            for (int k = j + 1; k < n; k++)
            {
                if (i == k)
                    continue;
                for (int l = k + 1; l < n; l++)
                {
                    if (i == l)
                        continue;

/*                    if the current combination 
                    of j, k, l in the set is
                    equal to S[i] return this
                    value as this would be the
                    largest d since we are 
                    iterating in descending order*/

                    if (S[i] == S[j] + S[k] + S[l])
                    {
                        found = true;
                        return S[i];
                    }
                }
            }
        }
    }
    if (found == false)
        return Integer.MAX_VALUE;
    return -1;
}

/*Driver Code*/

public static void main(String []args)
{
    int []S = new int[]{ 2, 3, 5, 7, 12 };
    int n = S.length;
    int ans = findLargestd(S, n);
    if (ans == Integer.MAX_VALUE)
        System.out.println("No Solution");
    else
        System.out.println("Largest d such that " +
                         "a + " + "b + c = d is " +
                                             ans );
}
}

/*Java for finding sum of all
unique subarray sum*/

import java.util.*;
class GFG
{

/*function for finding grandSum*/

static int findSubarraySum(int []arr, int n)
{
    int res = 0;

/*    Go through all subarrays, compute sums
    and count occurrences of sums.*/

    HashMap<Integer,
            Integer> m = new HashMap<Integer,
                                     Integer>();
    for (int i = 0; i < n; i++)
    {
        int sum = 0;
        for (int j = i; j < n; j++)
        {
            sum += arr[j];
            if (m.containsKey(sum))
            {
                m.put(sum, m.get(sum) + 1);
            }
            else
            {
                m.put(sum, 1);
            }
        }
    }

/*    Print all those sums that appear
    once.*/

    for (Map.Entry<Integer,
                   Integer> x : m.entrySet())
        if (x.getValue() == 1)
            res += x.getKey();
    return res;
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 3, 2, 3, 1, 4 };
    int n = arr.length;
    System.out.println(findSubarraySum(arr, n));
}
}

/*Efficient Java program to count
Amicable pairs in an array.*/

import java.util.*;
class GFG
{

/*Calculate the sum
of proper divisors*/

static int sumOfDiv(int x)
{

/*    1 is a proper divisor*/

    int sum = 1;
    for (int i = 2; i <= Math.sqrt(x); i++)
    {
        if (x % i == 0)
        {
            sum += i;

/*            To handle perfect squares*/

            if (x / i != i)
                sum += x / i;
        }
    }
    return sum;
}

/*Check if pair is amicable*/

static boolean isAmicable(int a, int b)
{
    return (sumOfDiv(a) == b &&
            sumOfDiv(b) == a);
}

/*This function prints count
of amicable pairs present
in the input array*/

static int countPairs(int arr[], int n)
{

/*    Map to store the numbers*/

    HashSet<Integer> s = new HashSet<Integer>();
    int count = 0;
    for (int i = 0; i < n; i++)
        s.add(arr[i]);

/*    Iterate through each number,
    and find the sum of proper
    divisors and check if it's
    also present in the array*/

    for (int i = 0; i < n; i++)
    {
        if (s.contains(sumOfDiv(arr[i])))
        {

/*            It's sum of proper divisors*/

            int sum = sumOfDiv(arr[i]);
            if (isAmicable(arr[i], sum))
                count++;
        }
    }

/*    As the pairs are counted
    twice, thus divide by 2*/

    return count / 2;
}

/*Driver code*/

public static void main(String[] args)
{
    int arr1[] = { 220, 284, 1184,
                   1210, 2, 5 };
    int n1 = arr1.length;
    System.out.println(countPairs(arr1, n1));
    int arr2[] = { 2620, 2924, 5020,
                   5564, 6232, 6368 };
    int n2 = arr2.length;
    System.out.println(countPairs(arr2, n2));
}
}

/*Java program for finding maximum
area possible of a rectangle*/

import java.util.HashSet;
import java.util.Set;
public class GFG
{

/*    function for finding max area*/

    static int findArea(int arr[], int n)
    {
        Set<Integer> s = new HashSet<>();

/*        traverse through array*/

        int first = 0, second = 0;
        for (int i = 0; i < n; i++) {

/*            If this is first occurrence of
            arr[i], simply insert and continue*/

            if (!s.contains(arr[i])) {
                s.add(arr[i]);
                continue;
            }

/*            If this is second (or more)
            occurrence, update first and
            second maximum values.*/

            if (arr[i] > first) {
                second = first;
                first = arr[i];
            } else if (arr[i] > second)
                second = arr[i];
        }

/*        return the product of dimensions*/

        return (first * second);
    }

/*    driver function*/

    public static void main(String args[])
    {
        int arr[] = { 4, 2, 1, 4, 6, 6, 2, 5 };
        int n = arr.length;
        System.out.println(findArea(arr, n));
    }
}

import java.util.*;
class GFG
{

/*    Wrapper over the recursive function leftRotateRec()
    It left rotates arr[] by d.*/

    public static void leftRotate(int arr[], int d,
                                                int n)
    {
        leftRotateRec(arr, 0, d, n);
    }
    public static void leftRotateRec(int arr[], int i,
                                  int d, int n)
    {

/* Return If number of elements to be rotated
        is zero or equal to array size */

        if(d == 0 || d == n)
            return;

/*If number of elements to be rotated
        is exactly half of array size */

        if(n - d == d)
        {
            swap(arr, i, n - d + i, d);
            return;
        }

/* If A is shorter*/

        if(d < n - d)
        {
            swap(arr, i, n - d + i, d);
            leftRotateRec(arr, i, d, n - d);    
        }

/* If B is shorter*/
 else   
        {
            swap(arr, i, d, n - d);
            leftRotateRec(arr, n - d + i, 2 * d - n, d); 
        }
    }

/* function to print an array */

public static void printArray(int arr[], int size)
{
    int i;
    for(i = 0; i < size; i++)
        System.out.print(arr[i] + " ");
    System.out.println();
}

/*This function swaps d elements
starting at index fi with d elements
starting at index si */

public static void swap(int arr[], int fi,
                        int si, int d)
{
    int i, temp;
    for(i = 0; i < d; i++)
    {
        temp = arr[fi + i];
        arr[fi + i] = arr[si + i];
        arr[si + i] = temp;
    }
}

/*Driver Code*/

public static void main (String[] args)
{
    int arr[] = {1, 2, 3, 4, 5, 6, 7};
    leftRotate(arr, 2, 7);
    printArray(arr, 7);    
}
}

/*Java code for above implementation*/

static void leftRotate(int arr[], int d, int n)
{
int i, j;
if(d == 0 || d == n)
    return;
i = d;
j = n - d;
while (i != j)
{

/*A is shorter*/
    if(i < j) 
    {
    swap(arr, d-i, d+j-i, i);
    j -= i;
    }

/*B is shorter*/
    else 
    {
    swap(arr, d-i, d, j);
    i -= j;
    }
}

/*Finally, block swap A and B*/

swap(arr, d-i, d, i);
}

/* Java program to search an element in
   sorted and rotated array using
   single pass of Binary Search*/

class Main {

/*    Returns index of key in arr[l..h]
    if key is present, otherwise returns -1*/

    static int search(int arr[], int l, int h, int key)
    {
        if (l > h)
            return -1;
        int mid = (l + h) / 2;
        if (arr[mid] == key)
            return mid;

/* If arr[l...mid] first subarray is sorted */

        if (arr[l] <= arr[mid]) {

/* As this subarray is sorted, we
               can quickly check if key lies in
               half or other half */

            if (key >= arr[l] && key <= arr[mid])
                return search(arr, l, mid - 1, key);

/*If key not lies in first half subarray,
           Divide other half  into two subarrays,
           such that we can quickly check if key lies
           in other half */

            return search(arr, mid + 1, h, key);
        }

/* If arr[l..mid] first subarray is not sorted,
           then arr[mid... h] must be sorted subarry*/

        if (key >= arr[mid] && key <= arr[h])
            return search(arr, mid + 1, h, key);
        return search(arr, l, mid - 1, key);
    }

/*    main function*/

    public static void main(String args[])
    {
        int arr[] = { 4, 5, 6, 7, 8, 9, 1, 2, 3 };
        int n = arr.length;
        int key = 6;
        int i = search(arr, 0, n - 1, key);
        if (i != -1)
            System.out.println("Index: " + i);
        else
            System.out.println("Key not found");
    }
}

/*Java program to find
number of pairs with
a given sum in a sorted
and rotated array.*/

import java.io.*;
class GFG
{

/*This function returns
count of number of pairs
with sum equals to x.*/

static int pairsInSortedRotated(int arr[],
                                int n, int x)
{

/*    Find the pivot element.
    Pivot element is largest
    element of array.*/

    int i;
    for (i = 0; i < n - 1; i++)
        if (arr[i] > arr[i + 1])
            break;

/*    l is index of
    smallest element.*/

    int l = (i + 1) % n;

/*    r is index of
    largest element.*/

    int r = i;

/*    Variable to store
    count of number
    of pairs.*/

    int cnt = 0;

/*    Find sum of pair
    formed by arr[l]
    and arr[r] and
    update l, r and
    cnt accordingly.*/

    while (l != r)
    {

/*        If we find a pair with
        sum x, then increment
        cnt, move l and r to
        next element.*/

        if (arr[l] + arr[r] == x)
        {
            cnt++;

/*            This condition is required
            to be checked, otherwise
            l and r will cross each
            other and loop will never
            terminate.*/

            if(l == (r - 1 + n) % n)
            {
                return cnt;
            }
            l = (l + 1) % n;
            r = (r - 1 + n) % n;
        }

/*        If current pair sum
        is less, move to
        the higher sum side.*/

        else if (arr[l] + arr[r] < x)
            l = (l + 1) % n;

/*        If current pair sum
        is greater, move
        to the lower sum side.*/

        else
            r = (n + r - 1) % n;
    }
    return cnt;
}

/*Driver Code*/

public static void main (String[] args)
{
    int arr[] = {11, 15, 6, 7, 9, 10};
    int sum = 16;
    int n = arr.length;
    System.out.println(
            pairsInSortedRotated(arr, n, sum));
}
}

/*Java program to find number of
rotations in a sorted and rotated
array.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class LinearSearch
{

/*    Returns count of rotations for an
    array which is first sorted in
    ascending order, then rotated*/

    static int countRotations(int arr[], int n)
    {

/*        We basically find index of minimum
        element*/

        int min = arr[0], min_index = -1;
        for (int i = 0; i < n; i++)
        {
            if (min > arr[i])
            {
                min = arr[i];
                min_index = i;
            }
        }
        return min_index;
    }

/*    Driver program to test above functions*/

    public static void main (String[] args)
    {
        int arr[] = {15, 18, 2, 3, 6, 12};
        int n = arr.length;
        System.out.println(countRotations(arr, n));
    }
}

/*Java code to rotate an array
and answer the index query*/

import java.util.*;
class GFG
{

/*    Function to compute the element at
    given index*/

    static int findElement(int[] arr, int[][] ranges,
                            int rotations, int index)
    {
        for (int i = rotations - 1; i >= 0; i--) {

/*            Range[left...right]*/

            int left = ranges[i][0];
            int right = ranges[i][1];

/*            Rotation will not have any effect*/

            if (left <= index && right >= index) {
                if (index == left)
                    index = right;
                else
                    index--;
            }
        }

/*        Returning new element*/

        return arr[index];
    }

/*    Driver*/

    public static void main (String[] args) {
        int[] arr = { 1, 2, 3, 4, 5 };

/*        No. of rotations*/

        int rotations = 2;

/*        Ranges according to 0-based indexing*/

        int[][] ranges = { { 0, 2 }, { 0, 3 } };
        int index = 1;
        System.out.println(findElement(arr, ranges,
                                 rotations, index));
    }
}

/*Java program for above approach*/

class GFG{

/*Function to tranform the array*/

public static void fixArray(int ar[], int n)
{
    int i, j, temp;

/*    Iterate over the array*/

    for(i = 0; i < n; i++)
    {
        for(j = 0; j < n; j++)
        {

/*            Checf is any ar[j]
            exists such that
            ar[j] is equal to i*/

            if (ar[j] == i)
            {
                temp = ar[j];
                ar[j] = ar[i];
                ar[i] = temp;
                break;
            }
        }
    }

/*    Iterate over array*/

    for(i = 0; i < n; i++)
    {

/*        If not present*/

        if (ar[i] != i)
        {
            ar[i] = -1;
        }
    }

/*    Print the output*/

    System.out.println("Array after Rearranging");
    for(i = 0; i < n; i++)
    {
        System.out.print(ar[i] + " ");
    }
}

/*Driver Code*/

public static void main(String[] args)
{
    int n, ar[] = { -1, -1, 6, 1, 9,
                     3, 2, -1, 4, -1 };
    n = ar.length;

/*    Function Call*/

    fixArray(ar, n);
}
}

/*Java program to implement the
above approach*/

import java.io.*;
class GFG{
static void printArray(int[] array, int length)
{
  System.out.print("[");
  for (int i = 0; i < length; i++)
  {
    System.out.print(array[i]);
    if (i < (length - 1))
      System.out.print(",");
    else
      System.out.print("]\n");
  }
}
static void reverse(int[] array,
                    int start,
                    int end)
{
  while (start < end)
  {
    int temp = array[start];
    array[start] = array[end];
    array[end] = temp;
    start++;
    end--;
  }
}

/*Rearrange the array with
all negative integers on left
and positive integers on right
use recursion to split the
array with first element
as one half and the rest
array as another and then
merge it with head of
the array in each step*/

static void rearrange(int[] array,
                      int start,
                      int end)
{

/*  exit condition*/

  if (start == end)
    return;

/*  rearrange the array
  except the first element
  in each recursive call*/

  rearrange(array,
            (start + 1), end);

/*  If the first element of
  the array is positive,
  then right-rotate the
  array by one place first
  and then reverse the merged array.*/

  if (array[start] >= 0)
  {
    reverse(array,
            (start + 1), end);
    reverse(array,
            start, end);
  }
}

/*Driver code*/

public static void main(String[] args)
{
  int[] array = {-12, -11, -13,
                 -5, -6, 7, 5, 3, 6};
  int length = array.length;
  int countNegative = 0;
  for (int i = 0; i < length; i++)
  {
    if (array[i] < 0)
      countNegative++;
  }
  System.out.print("array: ");
  printArray(array, length);
  rearrange(array, 0,
           (length - 1));
  reverse(array, countNegative,
         (length - 1));
  System.out.print("rearranged array: ");
  printArray(array, length);
}
}

class GFG {

/*    Function For Swaping Two Element Of An Array*/

    public static void swap(int[] A, int i, int j)
    {
        int temp = A[i];
        A[i] = A[j];
        A[j] = temp;
    }

/*    shift all zero to left side of an array*/

    static void shiftAllZeroToLeft(int array[], int n)
    {

/*        Maintain last index with positive value*/

        int lastSeenNonZero = 0;
        for (int index = 0; index < n; index++) {

/*            If Element is non-zero*/

            if (array[index] != 0) {

/*                swap current index, with lastSeen
                non-zero*/

                swap(array, array[index],
                     array[lastSeenNonZero]);

/*                next element will be last seen non-zero*/

                lastSeenNonZero++;
            }
        }
    }
}

/*Java code to reorder an array
according to given indices*/

class GFG{
static int heapSize;
public static void heapify(int arr[],
                           int index[], int i)
{
    int largest = i;

/*    left child in 0 based indexing*/

    int left = 2 * i + 1;

/*    right child in 1 based indexing*/

    int right = 2 * i + 2;

/*    Find largest index from root,
    left and right child*/

    if (left < heapSize &&
        index[left] > index[largest] )
    {
        largest = left;
    }
    if (right < heapSize &&
        index[right] > index[largest] )
    {
        largest = right;
    }
    if (largest != i)
    {

/*        swap arr whenever index is swapped*/

        int temp = arr[largest];
        arr[largest] = arr[i];
        arr[i] = temp;
        temp = index[largest];
        index[largest] = index[i];
        index[i] = temp;
        heapify(arr, index, largest);
    }
}
public static void heapSort(int arr[],
                            int index[], int n)
{

/*    Build heap*/

    for(int i = (n - 1) / 2 ; i >= 0 ; i--)
    {
        heapify(arr, index, i);
    }

/*    Swap the largest element of
    index(first element)
    with the last element*/

    for(int i = n - 1 ; i > 0 ; i--)
    {
        int temp = index[0];
        index[0] = index[i];
        index[i] = temp;

/*        swap arr whenever index is swapped*/

        temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;
        heapSize--;
        heapify(arr, index, 0);
    }
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 50, 40, 70, 60, 90 };
    int index[] = { 3, 0, 4, 1, 2 };
    int n = arr.length;
    heapSize = n;
    heapSort(arr, index, n);
    System.out.println("Reordered array is: ");
    for(int i = 0 ; i < n ; i++)
        System.out.print(arr[i] + " ");
    System.out.println();  
    System.out.println("Modified Index array is: ");
    for(int i = 0; i < n; i++)
        System.out.print(index[i] + " ");
}
}

/*Java program to Rearrange positive and negative
numbers in a array*/

class GFG {

/* Function to print an array */

    static void printArray(int A[], int size)
    {
        for (int i = 0; i < size; i++)
            System.out.print(A[i] + " ");
        System.out.println("");
        ;
    }

/* Function to reverse an array. An array can be
reversed in O(n) time and O(1) space. */

    static void reverse(int arr[], int l, int r)
    {
        if (l < r) {
            arr = swap(arr, l, r);
            reverse(arr, ++l, --r);
        }
    }

/*    Merges two subarrays of arr[].
    First subarray is arr[l..m]
    Second subarray is arr[m+1..r]*/

    static void merge(int arr[], int l, int m, int r)
    {

/*Initial index of 1st subarray*/

int i = l;

/*Initial index of IInd*/

int j = m + 1; 
        while (i <= m && arr[i] < 0)
            i++;

/*        arr[i..m] is positive*/

        while (j <= r && arr[j] < 0)
            j++;

/*        arr[j..r] is positive
        reverse positive part of
        left sub-array (arr[i..m])*/

        reverse(arr, i, m);

/*        reverse negative part of
        right sub-array (arr[m+1..j-1])*/

        reverse(arr, m + 1, j - 1);

/*        reverse arr[i..j-1]*/

        reverse(arr, i, j - 1);
    }

/*    Function to Rearrange positive and negative
    numbers in a array*/

    static void RearrangePosNeg(int arr[], int l, int r)
    {
        if (l < r) {

/*            Same as (l+r)/2, but avoids overflow for
            large l and h*/

            int m = l + (r - l) / 2;

/*            Sort first and second halves*/

            RearrangePosNeg(arr, l, m);
            RearrangePosNeg(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }
    static int[] swap(int[] arr, int i, int j)
    {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        return arr;
    }

/* Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { -12, 11, -13, -5, 6, -7, 5, -3, -6 };
        int arr_size = arr.length;
        RearrangePosNeg(arr, 0, arr_size - 1);
        printArray(arr, arr_size);
    }
}

/*Java implementation of the above approach*/

import java.io.*;
class GFG
{
      public static void RearrangePosNeg(int arr[])
    {
          int i=0;
          int j=arr.length-1;
          while(true)
        {

/*            Loop until arr[i] < 0 and
            still inside the array*/

            while(arr[i]<0 && i<arr.length)
              i++;

/*            Loop until arr[j] > 0 and
            still inside the array*/

              while(arr[j]>0 && j>=0)
              j--;

/*            if i is less than j*/

              if(i<j)
            {
                int temp = arr[i];
                  arr[i] = arr[j];
                  arr[j] = temp;
            }
              else
              break;
        }
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        int arr[] = {-12, 11, -13, -5, 6, -7, 5, -3, -6};
          RearrangePosNeg(arr);
          for(int i=0;i<arr.length;i++)
          System.out.print(arr[i]+" ");
    }
}

/*Java program to rearrange an
array in minimum maximum form*/

public class Main {

/*    Prints max at first position, min at second
    position second max at third position, second
    min at fourth position and so on.*/

    public static void rearrange(int arr[], int n)
    {

/*        initialize index of first minimum and first
        maximum element*/

        int max_idx = n - 1, min_idx = 0;

/*        store maximum element of array*/

        int max_elem = arr[n - 1] + 1;

/*        traverse array elements*/

        for (int i = 0; i < n; i++) {

/*            at even index : we have to put
            maximum element*/

            if (i % 2 == 0) {
                arr[i] += (arr[max_idx] % max_elem) * max_elem;
                max_idx--;
            }

/*            at odd index : we have to put minimum element*/

            else {
                arr[i] += (arr[min_idx] % max_elem) * max_elem;
                min_idx++;
            }
        }

/*        array elements back to it's original form*/

        for (int i = 0; i < n; i++)
            arr[i] = arr[i] / max_elem;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int n = arr.length;
        System.out.println("Original Array");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        rearrange(arr, n);
        System.out.print("\nModified Array\n");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java program to rearrange an
array in minimum maximum form*/

public class Main {

/*    Prints max at first position, min at second
    position second max at third position, second
    min at fourth position and so on.*/

    public static void rearrange(int arr[], int n)
    {

/*        initialize index of first minimum and first
        maximum element*/

        int max_ele = arr[n - 1];
        int min_ele = arr[0];

/*        traverse array elements*/

        for (int i = 0; i < n; i++) {

/*            at even index : we have to put maximum element*/

            if (i % 2 == 0) {
                arr[i] = max_ele;
                max_ele -= 1;
            }

/*            at odd index : we have to put minimum element*/

            else {
                arr[i] = min_ele;
                min_ele += 1;
            }
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int n = arr.length;
        System.out.println("Original Array");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        rearrange(arr, n);
        System.out.print("\nModified Array\n");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java program to put all negative
numbers before positive numbers*/

import java.io.*;
class GFG {
    static void rearrange(int arr[], int n)
    {
        int j = 0, temp;
        for (int i = 0; i < n; i++) {
            if (arr[i] < 0) {
                if (i != j) {
                    temp = arr[i];
                    arr[i] = arr[j];
                    arr[j] = temp;
                }
                j++;
            }
        }
    }

