}

/*Java code to rearrange an array such
that even index elements are smaller
and odd index elements are greater
than their next.*/

class GFG {

/*Rearrange*/

    static void rearrange(int arr[], int n)
    {
        int temp;
        for (int i = 0; i < n - 1; i++) {
            if (i % 2 == 0 && arr[i] > arr[i + 1]) {
                temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
            if (i % 2 != 0 && arr[i] < arr[i + 1]) {
                temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
            }
        }
    }

/* Utility that prints out an array in
    a line */

    static void printArray(int arr[], int size)
    {
        for (int i = 0; i < size; i++)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 6, 4, 2, 1, 8, 3 };
        int n = arr.length;
        System.out.print("Before rearranging: \n");
        printArray(arr, n);
        rearrange(arr, n);
        System.out.print("After rearranging: \n");
        printArray(arr, n);
    }
}

/*Java program to rearrange positive
and negative numbers*/

import java.io.*;
class GFG {
static void rearrange(int a[], int size)
{
  int positive = 0, negative = 1, temp;
    while (true) {

/* Move forward the positive pointer till
    negative number number not encountered */

    while (positive < size && a[positive] >= 0)
        positive += 2;

/* Move forward the negative pointer till
        positive number number not encountered */

    while (negative < size && a[negative] <= 0)
        negative += 2;

/*    Swap array elements to fix their position.*/

    if (positive < size && negative < size) {
        temp = a[positive];
        a[positive] = a[negative];
        a[negative] = temp;
    }

/* Break from the while loop when any index
    exceeds the size of the array */

    else
        break;
    }
}

/*Driver code*/

public static void main(String args[]) {
    int arr[] = {1, -3, 5, 6, -3, 6, 7, -4, 9, 10};
    int n = arr.length;
    rearrange(arr, n);
