/*Java for printing smallest k numbers in order*/

import java.util.*;
import java.lang.*;
public class GfG {

/*    Function to print smallest k numbers
    in arr[0..n-1]*/

    public static void printSmall(int arr[], int n, int k)
    {

/*        For each arr[i] find whether
        it is a part of n-smallest
        with insertion sort concept*/

        for (int i = k; i < n; ++i) {

/*            Find largest from top n-element*/

            int max_var = arr[k - 1];
            int pos = k - 1;
            for (int j = k - 2; j >= 0; j--) {
                if (arr[j] > max_var) {
                    max_var = arr[j];
                    pos = j;
                }
            }

/*            If largest is greater than arr[i]
            shift all element one place left*/

            if (max_var > arr[i]) {
                int j = pos;
                while (j < k - 1) {
                    arr[j] = arr[j + 1];
                    j++;
                }

/*                make arr[k-1] = arr[i]*/

                arr[k - 1] = arr[i];
            }
        }

/*        print result*/

        for (int i = 0; i < k; i++)
            System.out.print(arr[i] + " ");
    }

/*    Driver function*/

    public static void main(String argc[])
    {
        int[] arr = { 1, 5, 8, 9, 6, 7, 3, 4, 2, 0 };
        int n = 10;
        int k = 5;
        printSmall(arr, n, k);
    }
}

/*Java code to print first k pairs with least
sum from two arrays.*/

import java.io.*;
class KSmallestPair
{

/*    Function to find k pairs with least sum such
    that one elemennt of a pair is from arr1[] and
    other element is from arr2[]*/

    static void kSmallestPair(int arr1[], int n1, int arr2[],
                                            int n2, int k)
    {
        if (k > n1*n2)
        {
            System.out.print("k pairs don't exist");
            return ;
        }

/*        Stores current index in arr2[] for
        every element of arr1[]. Initially
        all values are considered 0.
        Here current index is the index before
        which all elements are considered as
        part of output.*/

        int index2[] = new int[n1];
        while (k > 0)
        {

/*            Initialize current pair sum as infinite*/

            int min_sum = Integer.MAX_VALUE;
            int min_index = 0;

/*            To pick next pair, traverse for all
            elements of arr1[], for every element, find
            corresponding current element in arr2[] and
            pick minimum of all formed pairs.*/

            for (int i1 = 0; i1 < n1; i1++)
            {

/*                Check if current element of arr1[] plus
                element of array2 to be used gives
                minimum sum*/

                if (index2[i1] < n2 &&
                    arr1[i1] + arr2[index2[i1]] < min_sum)
                {

/*                    Update index that gives minimum*/

                    min_index = i1;

/*                    update minimum sum*/

                    min_sum = arr1[i1] + arr2[index2[i1]];
                }
            }
            System.out.print("(" + arr1[min_index] + ", " +
                            arr2[index2[min_index]]+ ") ");
            index2[min_index]++;
            k--;
        }
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int arr1[] = {1, 3, 11};
        int n1 = arr1.length;
        int arr2[] = {2, 4, 8};
        int n2 = arr2.length;
        int k = 4;
        kSmallestPair( arr1, n1, arr2, n2, k);
    }
}

