        Arrays.sort(a);
        Arrays.sort(b);

/*        Function call*/

        intersection(a, b, n, m);
    }
}

/*Java program to find union and intersection
using similar Hashing Technique
without using any predefined Java Collections
Time Complexity best case & avg case = O(m+n)
Worst case = O(nlogn)
package com.arrays.math;*/

public class UnsortedIntersectionUnion {

/*    Prints intersection of arr1[0..n1-1] and
    arr2[0..n2-1]*/

    public void findPosition(int a[], int b[])
    {
        int v = (a.length + b.length);
        int ans[] = new int[v];
        int zero1 = 0;
        int zero2 = 0;
        System.out.print("Intersection : ");

/*        Iterate first array*/

        for (int i = 0; i < a.length; i++)
            zero1 = iterateArray(a, v, ans, i);

/*        Iterate second array*/

        for (int j = 0; j < b.length; j++)
            zero2 = iterateArray(b, v, ans, j);
        int zero = zero1 + zero2;
        placeZeros(v, ans, zero);
        printUnion(v, ans, zero);
    }

/*    Prints union of arr1[0..n1-1] and arr2[0..n2-1]*/

    private void printUnion(int v, int[] ans, int zero)
    {
        int zero1 = 0;
        System.out.print("\nUnion : ");
        for (int i = 0; i < v; i++) {
            if ((zero == 0 && ans[i] == 0)
                || (ans[i] == 0 && zero1 > 0))
                continue;
            if (ans[i] == 0)
                zero1++;
            System.out.print(ans[i] + ",");
        }
    }

/*placeZeroes function*/

    private void placeZeros(int v, int[] ans, int zero)
    {
        if (zero == 2) {
            System.out.println("0");
            int d[] = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
        if (zero == 1) {
            int d[] = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
    }

/*    Function to itreate array*/

    private int iterateArray(int[] a, int v, int[] ans,
                             int i)
    {
        if (a[i] != 0) {
            int p = a[i] % v;
            placeValue(a, ans, i, p, v);
        }
        else
            return 1;
        return 0;
    }

/*placeValue function*/

    private void placeValue(int[] a, int[] ans, int i,
                            int p, int v)
    {
        p = p % v;
        if (ans[p] == 0)
            ans[p] = a[i];
        else {
            if (ans[p] == a[i])
                System.out.print(a[i] + ",");
            else {

/*                Hashing collision happened increment
                position and do recursive call*/

                p = p + 1;
                placeValue(a, ans, i, p, v);
            }
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int a[] = { 7, 1, 5, 2, 3, 6 };
        int b[] = { 3, 8, 6, 20, 7 };
        UnsortedIntersectionUnion uiu
            = new UnsortedIntersectionUnion();
        uiu.findPosition(a, b);
    }
}

/*Java program to find the Minimum length Unsorted Subarray,
sorting which makes the complete array sorted*/

class Main
{
    static void printUnsorted(int arr[], int n)
    {
      int s = 0, e = n-1, i, max, min;

/*      step 1(a) of above algo*/

      for (s = 0; s < n-1; s++)
      {
        if (arr[s] > arr[s+1])
          break;
      }
      if (s == n-1)
      {
        System.out.println("The complete array is sorted");
        return;
      }

/*      step 1(b) of above algo*/

      for(e = n - 1; e > 0; e--)
      {
        if(arr[e] < arr[e-1])
          break;
      }

/*      step 2(a) of above algo*/

      max = arr[s]; min = arr[s];
      for(i = s + 1; i <= e; i++)
      {
        if(arr[i] > max)
          max = arr[i];
        if(arr[i] < min)
          min = arr[i];
      }

/*      step 2(b) of above algo*/

      for( i = 0; i < s; i++)
      {
        if(arr[i] > min)
        { 
          s = i;
          break;
        }     
      }

/*      step 2(c) of above algo*/

      for( i = n -1; i >= e+1; i--)
      {
        if(arr[i] < max)
        {
          e = i;
          break;
        }
      }

/*      step 3 of above algo*/

      System.out.println(" The unsorted subarray which"+
                         " makes the given array sorted lies"+
                       "  between the indices "+s+" and "+e);
      return;
    }
    public static void main(String args[])
    {
      int arr[] = {10, 12, 20, 30, 25, 40, 32, 31, 35, 50, 60};
      int arr_size = arr.length;
      printUnsorted(arr, arr_size);
    }
}

/*Java implementation of the above approach*/

import java.util.*;
class GFG {

/*CountTriangles function*/

    static void CountTriangles(int[] A)
    {
        int n = A.length;
        Arrays.sort(A);
        int count = 0;
        for (int i = n - 1; i >= 1; i--) {
            int l = 0, r = i - 1;
            while (l < r) {
                if (A[l] + A[r] > A[i]) {

/*                    If it is possible with a[l], a[r]
                    and a[i] then it is also possible
                    with a[l+1]..a[r-1], a[r] and a[i]*/

                    count += r - l;

/*                    checking for more possible solutions*/

                    r--;
                }

/*if not possible check for higher values of arr[l]*/

else 
                {
                    l++;
                }
            }
        }
        System.out.print("No of possible solutions: " + count);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int[] A = { 4, 3, 5, 7, 6 };
        CountTriangles(A);
    }
}

/*Java program to finds number of pairs (x, y)
in an array such that x^y > y^x*/

import java.util.Arrays;
class Test {

/*    Function to return count of pairs with x as one
    element of the pair. It mainly looks for all values
    in Y[] where x ^ Y[i] > Y[i] ^ x*/

    static int count(int x, int Y[], int n, int NoOfY[])
    {

/*        If x is 0, then there cannot be any value in Y
        such that x^Y[i] > Y[i]^x*/

        if (x == 0)
            return 0;

/*        If x is 1, then the number of pais is equal to
        number of zeroes in Y[]*/

        if (x == 1)
            return NoOfY[0];

/*        Find number of elements in Y[] with values
        greater than x getting upperbound of x with
        binary search*/

        int idx = Arrays.binarySearch(Y, x);
        int ans;
        if (idx < 0) {
            idx = Math.abs(idx + 1);
            ans = Y.length - idx;
        }
        else {
            while (idx < n && Y[idx] == x) {
                idx++;
            }
            ans = Y.length - idx;
        }

/*        If we have reached here, then x must be greater
        than 1, increase number of pairs for y=0 and y=1*/

        ans += (NoOfY[0] + NoOfY[1]);

/*        Decrease number of pairs for x=2 and (y=4 or y=3)*/

        if (x == 2)
            ans -= (NoOfY[3] + NoOfY[4]);

/*        Increase number of pairs for x=3 and y=2*/

        if (x == 3)
            ans += NoOfY[2];
        return ans;
    }

/*    Function to returns count of pairs (x, y) such that
    x belongs to X[], y belongs to Y[] and x^y > y^x*/

    static long countPairs(int X[], int Y[], int m, int n)
    {

/*        To store counts of 0, 1, 2, 3 and 4 in array Y*/

        int NoOfY[] = new int[5];
        for (int i = 0; i < n; i++)
            if (Y[i] < 5)
                NoOfY[Y[i]]++;

/*        Sort Y[] so that we can do binary search in it*/

        Arrays.sort(Y);

/*Initialize result*/

long total_pairs = 0;

/*        Take every element of X and count pairs with it*/

        for (int i = 0; i < m; i++)
            total_pairs += count(X[i], Y, n, NoOfY);
        return total_pairs;
    }

/*    Driver method*/

    public static void main(String args[])
    {
        int X[] = { 2, 1, 6 };
        int Y[] = { 1, 5 };
        System.out.println(
            "Total pairs = "
            + countPairs(X, Y, X.length, Y.length));
    }
}

/*A sorting base java program to
count pairs with difference k*/

import java.util.*;
import java.io.*;
class GFG {

/*
Standard binary search function */

    static int binarySearch(int arr[], int low,
                               int high, int x)
    {
        if (high >= low)
        {
            int mid = low + (high - low) / 2;
            if (x == arr[mid])
                return mid;
            if (x > arr[mid])
                return binarySearch(arr, (mid + 1),
                                          high, x);
            else
                return binarySearch(arr, low,
                                    (mid - 1), x);
        }
        return -1;
    }

/*    Returns count of pairs with
    difference k in arr[] of size n.*/

    static int countPairsWithDiffK(int arr[], int n, int k)
    {
        int count = 0, i;

/*        Sort array elements*/

        Arrays.sort(arr);

/*        code to remove duplicates from arr[]*/

/*        Pick a first element point*/

        for (i = 0; i < n - 1; i++)
            if (binarySearch(arr, i + 1, n - 1,
                             arr[i] + k) != -1)
                count++;
        return count;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 5, 3, 4, 2 };
        int n = arr.length;
        int k = 3;
        System.out.println("Count of pairs with given diff is "
                            + countPairsWithDiffK(arr, n, k));
    }
}

/*A sorting based Java program to
count pairs with difference k*/

import java.util.*;
class GFG {

/* Returns count of pairs with
difference k in arr[] of size n. */

static int countPairsWithDiffK(int arr[], int n,
                                          int k)
{
    int count = 0;

/*Sort array elements*/

Arrays.sort(arr); 
    int l = 0;
    int r = 0;
    while(r < n)
    {
        if(arr[r] - arr[l] == k)
        {
            count++;
            l++;
            r++;
        }
        else if(arr[r] - arr[l] > k)
            l++;

/*arr[r] - arr[l] < sum*/

else 
            r++;
    }
    return count;
}

/*Driver program to test above function*/

public static void main(String[] args)
{
    int arr[] = {1, 5, 3, 4, 2};
    int n = arr.length;
