    System.out.println("Count of pairs with given diff is " +
                        countPairsWithDiffK(arr, n, k));
}
}

import java.io.*;
class GFG {

static int BS(int[] arr, int X, int low)  {
        int high = arr.length - 1;
        int ans = arr.length;
        while(low <= high) {
            int mid = low + (high - low) / 2;
            if(arr[mid] >= X) {
                ans = mid;
                high = mid - 1;
            }
            else low = mid + 1;
        }
        return ans;
    }

static int countPairsWithDiffK(int[] arr, int N, int k) {
        int count = 0;
        Arrays.sort(arr);
        for(int i = 0 ; i < N ; ++i) {
            int X = BS(arr, arr[i] + k, i + 1);
            if(X != N) {
                int Y = BS(arr, arr[i] + k + 1, i + 1);
                count += Y - X;
            }
        }
        return count;
    }

public static void main (String[] args) {
        int arr[] = {1, 3, 5, 8, 6, 4, 6};
        int n = arr.length;
        int k = 2;
        System.out.println("Count of pairs with given diff is " +
                            countPairsWithDiffK(arr, n, k));
        }
}

/*Java program program to merge two
sorted arrays with O(1) extra space.*/

import java.util.Arrays;
class Test
{

/*Merge ar1[] and ar2[] with O(1) extra space*/

    static int arr1[] = new int[]{1, 5, 9, 10, 15, 20};
    static int arr2[] = new int[]{2, 3, 8, 13};
    static void merge(int m, int n)
    {

/*        Iterate through all elements of ar2[] starting from
        the last element*/

        for (int i=n-1; i>=0; i--)
        {

/* Find the smallest element greater than ar2[i]. Move all
               elements one position ahead till the smallest greater
               element is not found */

            int j, last = arr1[m-1];
            for (j=m-2; j >= 0 && arr1[j] > arr2[i]; j--)
                arr1[j+1] = arr1[j];

/*            If there was a greater element*/

            if (j != m-2 || last > arr2[i])
            {
                arr1[j+1] = arr2[i];
                arr2[i] = last;
            }
        }
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        merge(arr1.length,arr2.length);
        System.out.print("After Merging nFirst Array: ");
        System.out.println(Arrays.toString(arr1));
        System.out.print("Second Array:  ");
        System.out.println(Arrays.toString(arr2));
    }
}

/*Java program for the above approach*/

import java.util.Arrays;
import java.util.Collections;
class GFG {

/*    Function to merge two arrays*/

    static void merge(int m, int n)
    {
        int i = 0, j = 0, k = n - 1;

/*    Untill i less than equal to k
    or j is less tha m*/

        while (i <= k and j < m) {
            if (arr1[i] < arr2[j])
                i++;
            else {
                int temp = arr2[j];
                arr2[j] = arr1[k];
                arr1[k] = temp;
                j++;
                k--;
            }
        }

/*    Sort first array*/

        Arrays.sort(arr1);

/*    Sort second array*/

        Arrays.sort(arr2);
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        int arr1[] = new int[] { 1, 5, 9, 10, 15, 20 };
        int arr2[] = new int[] { 2, 3, 8, 13 };
        merge(arr1.length, arr2.length);
        System.out.print("After Merging \nFirst Array: ");
        System.out.println(Arrays.toString(arr1));
        System.out.print("Second Array:  ");
        System.out.println(Arrays.toString(arr2));
    }
}

/*Java program to implement delete
operation in an unsorted array*/

class Main
{

/*    function to search a key to
    be deleted*/

    static int findElement(int arr[], int n, int key)
    {
        int i;
        for (i = 0; i < n; i++)
            if (arr[i] == key)
                return i;
        return -1;
    }

/*    Function to delete an element*/

    static int deleteElement(int arr[], int n, int key)
    {

/*        Find position of element to be
        deleted*/

        int pos = findElement(arr, n, key);
        if (pos == -1)
        {
            System.out.println("Element not found");
            return n;
        }

/*        Deleting element*/

        int i;
        for (i = pos; i< n - 1; i++)
            arr[i] = arr[i + 1];
        return n - 1;
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int i;
        int arr[] = {10, 50, 30, 40, 20};
        int n = arr.length;
        int key = 30;
        System.out.println("Array before deletion");
        for (i=0; i<n; i++)
          System.out.print(arr[i] + " ");
        n = deleteElement(arr, n, key);
        System.out.println("\n\nArray after deletion");
        for (i=0; i<n; i++)
          System.out.print(arr[i]+" ");
    }
}

/*Java program to delete an
element from a sorted array*/

class Main {

/*    binary search*/

    static int binarySearch(int arr[], int low, int high, int key)
    {
        if (high < low)
            return -1;
        int mid = (low + high) / 2;
        if (key == arr[mid])
            return mid;
        if (key > arr[mid])
            return binarySearch(arr, (mid + 1), high, key);
        return binarySearch(arr, low, (mid - 1), key);
    }

/* Function to delete an element */

    static int deleteElement(int arr[], int n, int key)
    {

/*        Find position of element to be deleted*/

        int pos = binarySearch(arr, 0, n - 1, key);
        if (pos == -1) {
            System.out.println("Element not found");
            return n;
        }

/*        Deleting element*/

        int i;
        for (i = pos; i < n - 1; i++)
            arr[i] = arr[i + 1];
        return n - 1;
    }

/* Driver Code */

    public static void main(String[] args)
    {
        int i;
        int arr[] = { 10, 20, 30, 40, 50 };
        int n = arr.length;
        int key = 30;
        System.out.print("Array before deletion:\n");
        for (i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
        n = deleteElement(arr, n, key);
        System.out.print("\n\nArray after deletion:\n");
        for (i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java program to find common elements in three arrays*/

class FindCommon
{

/*    This function prints common elements in ar1*/

    void findCommon(int ar1[], int ar2[], int ar3[])
    {

/*        Initialize starting indexes for ar1[], ar2[] and ar3[]*/

        int i = 0, j = 0, k = 0;

/*        Iterate through three arrays while all arrays have elements*/

        while (i < ar1.length && j < ar2.length && k < ar3.length)
        {

/*             If x = y and y = z, print any of them and move ahead
             in all arrays*/

             if (ar1[i] == ar2[j] && ar2[j] == ar3[k])
             {   System.out.print(ar1[i]+" ");   i++; j++; k++; }

/*             x < y*/

             else if (ar1[i] < ar2[j])
                 i++;

/*             y < z*/

             else if (ar2[j] < ar3[k])
                 j++;

/*             We reach here when x > y and z < y, i.e., z is smallest*/

             else
                 k++;
        }
    }

/*    Driver code to test above*/

    public static void main(String args[])
    {
        FindCommon ob = new FindCommon();
        int ar1[] = {1, 5, 10, 20, 40, 80};
        int ar2[] = {6, 7, 20, 80, 100};
        int ar3[] = {3, 4, 15, 20, 30, 70, 80, 120};
        System.out.print("Common elements are ");
        ob.findCommon(ar1, ar2, ar3);
    }
}

/*Java program to demonstrate working of
an algorithm that finds an element in an
array of infinite size*/

class Test
{

/*    Simple binary search algorithm*/

    static int binarySearch(int arr[], int l, int r, int x)
    {
        if (r>=l)
        {
            int mid = l + (r - l)/2;
            if (arr[mid] == x)
                return mid;
            if (arr[mid] > x)
                return binarySearch(arr, l, mid-1, x);
            return binarySearch(arr, mid+1, r, x);
        }
        return -1;
    }

/*    Method takes an infinite size array and a key to be
    searched and returns its position if found else -1.
    We don't know size of arr[] and we can assume size to be
    infinite in this function.
    NOTE THAT THIS FUNCTION ASSUMES arr[] TO BE OF INFINITE SIZE
    THEREFORE, THERE IS NO INDEX OUT OF BOUND CHECKING*/

    static int findPos(int arr[],int key)
    {
        int l = 0, h = 1;
        int val = arr[0];

/*        Find h to do binary search*/

        while (val < key)
        {

/*store previous high*/

l = h;

/*            check that 2*h doesn't exceeds array
            length to prevent ArrayOutOfBoundException*/

            if(2*h < arr.length-1)
               h = 2*h;            
            else
               h = arr.length-1;

/*update new val*/

val = arr[h]; 
        }

/*        at this point we have updated low
        and high indices, thus use binary
        search between them*/

        return binarySearch(arr, l, h, key);
    }

/*    Driver method to test the above function*/

    public static void main(String[] args)
    {
        int arr[] = new int[]{3, 5, 7, 9, 10, 90,
                            100, 130, 140, 160, 170};
        int ans = findPos(arr,10);
        if (ans==-1)
            System.out.println("Element not found");
        else
            System.out.println("Element found at index " + ans);
    }
}

/*Java Program to find max subarray
sum excluding some elements*/

import java.io.*;
class GFG {

/*    Function to check the element
    present in array B*/

    static boolean isPresent(int B[], int m, int x)
    {
        for (int i = 0; i < m; i++)
            if (B[i] == x)
                return true;
        return false;
    }

/*    Utility function for findMaxSubarraySum()
    with the following parameters
    A => Array A,
    B => Array B,
    n => Number of elements in Array A,
    m => Number of elements in Array B*/

    static int findMaxSubarraySumUtil(int A[], int B[],
                                      int n, int m)
    {

/*        set max_so_far to INT_MIN*/

        int max_so_far = -2147483648, curr_max = 0;
        for (int i = 0; i < n; i++)
        {

/*            if the element is present in B,
            set current max to 0 and move to
            the next element*/

            if (isPresent(B, m, A[i]))
            {
                curr_max = 0;
                continue;
            }

/*            Proceed as in Kadane's Algorithm*/

            curr_max = Math.max(A[i], curr_max + A[i]);
            max_so_far = Math.max(max_so_far, curr_max);
        }
        return max_so_far;
    }

/*    Wrapper for findMaxSubarraySumUtil()*/

    static void findMaxSubarraySum(int A[], int B[], int n,
                                   int m)
    {
        int maxSubarraySum
            = findMaxSubarraySumUtil(A, B, n, m);

/*        This case will occour when all
        elements of A are present
        in B, thus no subarray can be formed*/

        if (maxSubarraySum == -2147483648)
        {
            System.out.println("Maximum Subarray Sum"
                               + " "
                               + "can't be found");
        }
        else {
            System.out.println("The Maximum Subarray Sum = "
                               + maxSubarraySum);
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int A[] = { 3, 4, 5, -4, 6 };
        int B[] = { 1, 8, 5 };
        int n = A.length;
        int m = B.length;

/*        Function call*/

        findMaxSubarraySum(A, B, n, m);
    }
}

