        Arrays.sort(B);
        int maxSubarraySum
            = findMaxSubarraySumUtil(A, B, n, m);

/*        This case will occour when all elements
        of A are present in B, thus no subarray
        can be formed*/

        if (maxSubarraySum == Integer.MIN_VALUE)
        {
