/*Java program to find Majority 
element in an array*/

import java.io.*;
import java.util.*;
class GFG{

/*Function to find Majority element
in an array it returns -1 if there
is no majority element  */

public static int majorityElement(int[] arr, int n)
{

/*    Sort the array in O(nlogn)*/

    Arrays.sort(arr);
    int count = 1, max_ele = -1,
         temp = arr[0], ele = 0,
            f = 0;
    for(int i = 1; i < n; i++)
    {

/*        Increases the count if the
        same element occurs otherwise
        starts counting new element*/

        if (temp == arr[i])
        {
            count++;
        }
        else
        {
            count = 1;
            temp = arr[i];
        }

/*        Sets maximum count and stores
        maximum occured element so far
        if maximum count becomes greater
        than n/2 it breaks out setting
        the flag*/

        if (max_ele < count)
        {
            max_ele = count;
            ele = arr[i];
            if (max_ele > (n / 2))
            {
                f = 1;
                break;
            }
        }
    }

/*    Returns maximum occured element
    if there is no such element, returns -1*/

    return (f == 1 ? ele : -1);
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 1, 1, 2, 1, 3, 5, 1 };
    int n = 7;

/*    Function calling*/

    System.out.println(majorityElement(arr, n));
}
}

/* Java Program to check for majority element in a sorted array */

import java.io.*;
class Majority {

/* If x is present in arr[low...high] then returns the index of
        first occurrence of x, otherwise returns -1 */

    static int  _binarySearch(int arr[], int low, int high, int x)
    {
        if (high >= low)
        {
            int mid = (low + high)/2;

/* Check if arr[mid] is the first occurrence of x.
                arr[mid] is first occurrence if x is one of the following
                is true:
                (i)  mid == 0 and arr[mid] == x
                (ii) arr[mid-1] < x and arr[mid] == x
            */

            if ( (mid == 0 || x > arr[mid-1]) && (arr[mid] == x) )
                return mid;
            else if (x > arr[mid])
                return _binarySearch(arr, (mid + 1), high, x);
            else
                return _binarySearch(arr, low, (mid -1), x);
        }
        return -1;
    }

/* This function returns true if the x is present more than n/2
        times in arr[] of size n */

    static boolean isMajority(int arr[], int n, int x)
    {

/* Find the index of first occurrence of x in arr[] */

        int i = _binarySearch(arr, 0, n-1, x);

/* If element is not present at all, return false*/

        if (i == -1)
            return false;

/* check if the element is present more than n/2 times */

        if (((i + n/2) <= (n -1)) && arr[i + n/2] == x)
            return true;
        else
            return false;
    }

/*Driver function to check for above functions*/

    public static void main (String[] args)  {
        int arr[] = {1, 2, 3, 3, 3, 3, 10};
        int n = arr.length;
        int x = 3;
        if (isMajority(arr, n, x)==true)
            System.out.println(x + " appears more than "+
                              n/2 + " times in arr[]");
        else
            System.out.println(x + " does not appear more than " +
                              n/2 + " times in arr[]");
    }
}

/*Java program to check fixed point
in an array using binary search*/

class Main
{
    static int binarySearch(int arr[], int low, int high)
    {
        if(high >= low)
        {

/* low + (high - low)/2; */

            int mid = (low + high)/2; 
            if(mid == arr[mid])
                return mid;
            if(mid > arr[mid])
                return binarySearch(arr, (mid + 1), high);
            else
                return binarySearch(arr, low, (mid -1));
        }

/* Return -1 if there is
           no Fixed Point */

        return -1;
    }

/*    main function*/

    public static void main(String args[])
    {
        int arr[] = {-10, -1, 0, 3 , 10, 11, 30, 50, 100};
        int n = arr.length;
        System.out.println("Fixed Point is "
                   + binarySearch(arr,0, n-1));       
    }
}

class SubarraySum {

/* Returns true if the there is a
subarray of arr[] with a sum equal to
       'sum' otherwise returns false. 
Also, prints the result */

    int subArraySum(int arr[], int n, int sum)
    {
        int curr_sum, i, j;

/*        Pick a starting point*/

        for (i = 0; i < n; i++) {
            curr_sum = arr[i];

/*            try all subarrays starting with 'i'*/

            for (j = i + 1; j <= n; j++) {
                if (curr_sum == sum) {
                    int p = j - 1;
                    System.out.println(
                        "Sum found between indexes " + i
                        + " and " + p);
                    return 1;
                }
                if (curr_sum > sum || j == n)
                    break;
                curr_sum = curr_sum + arr[j];
            }
        }
        System.out.println("No subarray found");
        return 0;
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        SubarraySum arraysum = new SubarraySum();
        int arr[] = { 15, 2, 4, 8, 9, 5, 10, 23 };
        int n = arr.length;
        int sum = 23;
        arraysum.subArraySum(arr, n, sum);
    }
}

class SubarraySum {

/* Returns true if the there is
a subarray of arr[] with sum equal to
       'sum' otherwise returns false. 
Also, prints the result */

    int subArraySum(int arr[], int n, int sum)
    {

/* Initialize curr_sum as
    value of first element
    and starting point as 0 */

        int curr_sum = arr[0], start = 0, i;

/*        Pick a starting point*/

        for (i = 1; i <= n; i++) {

/*            If curr_sum exceeds the sum,
            then remove the starting elements*/

            while (curr_sum > sum && start < i - 1) {
                curr_sum = curr_sum - arr[start];
                start++;
            }

/*            If curr_sum becomes equal to sum,
            then return true*/

            if (curr_sum == sum) {
                int p = i - 1;
                System.out.println(
                    "Sum found between indexes " + start
                    + " and " + p);
                return 1;
            }

/*            Add this element to curr_sum*/

            if (i < n)
                curr_sum = curr_sum + arr[i];
        }

/*    If we reach here, then no subarray*/

        System.out.println("No subarray found");
        return 0;
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        SubarraySum arraysum = new SubarraySum();
        int arr[] = { 15, 2, 4, 8, 9, 5, 10, 23 };
        int n = arr.length;
        int sum = 23;
        arraysum.subArraySum(arr, n, sum);
    }
}

/*Java code to find maximum triplet sum*/

import java.io.*;
import java.util.*;
class GFG {

/*    This function assumes that there
    are at least  three elements in arr[].*/

    static int maxTripletSum(int arr[], int n)
    {

/*        Initialize Maximum, second maximum and third
        maximum element*/

        int maxA = -100000000, maxB = -100000000;
        int maxC = -100000000;
        for (int i = 0; i < n; i++) {

/*            Update Maximum, second maximum
            and third maximum element*/

            if (arr[i] > maxA)
            {
                maxC = maxB;
                maxB = maxA;
                maxA = arr[i];
            }

/*            Update second maximum and third maximum
            element*/

            else if (arr[i] > maxB)
            {
                maxC = maxB;
                maxB = arr[i];
            }

/*            Update third maximum element*/

            else if (arr[i] > maxC)
                maxC = arr[i];
        }
        return (maxA + maxB + maxC);
    }

/*    Driven code*/

    public static void main(String args[])
    {
        int arr[] = { 1, 0, 8, 6, 4, 2 };
        int n = arr.length;
        System.out.println(maxTripletSum(arr, n));
    }
}

/*Java program to find a triplet*/

class FindTriplet {

/*    returns true if there is triplet with sum equal
    to 'sum' present in A[]. Also, prints the triplet*/

    boolean find3Numbers(int A[], int arr_size, int sum)
    {
        int l, r;

/*        Fix the first element as A[i]*/

        for (int i = 0; i < arr_size - 2; i++) {

/*            Fix the second element as A[j]*/

            for (int j = i + 1; j < arr_size - 1; j++) {

/*                Now look for the third number*/

                for (int k = j + 1; k < arr_size; k++) {
                    if (A[i] + A[j] + A[k] == sum) {
                        System.out.print("Triplet is " + A[i] + ", " + A[j] + ", " + A[k]);
                        return true;
                    }
                }
            }
        }

/*        If we reach here, then no triplet was found*/

        return false;
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        FindTriplet triplet = new FindTriplet();
        int A[] = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.length;
        triplet.find3Numbers(A, arr_size, sum);
    }
}

/*Java program to find a triplet*/

class FindTriplet {

/*    returns true if there is triplet with sum equal
    to 'sum' present in A[]. Also, prints the triplet*/

    boolean find3Numbers(int A[], int arr_size, int sum)
    {
        int l, r;

/* Sort the elements */

        quickSort(A, 0, arr_size - 1);

/* Now fix the first element one by one and find the
           other two elements */

        for (int i = 0; i < arr_size - 2; i++) {

/*            To find the other two elements, start two index variables
            from two corners of the array and move them toward each
            other
index of the first element in the remaining elements*/

l = i + 1;

/*index of the last element*/

r = arr_size - 1; 
            while (l < r) {
                if (A[i] + A[l] + A[r] == sum) {
                    System.out.print("Triplet is " + A[i] + ", " + A[l] + ", " + A[r]);
                    return true;
                }
                else if (A[i] + A[l] + A[r] < sum)
                    l++;

/*A[i] + A[l] + A[r] > sum*/

else 
                    r--;
            }
        }

/*        If we reach here, then no triplet was found*/

        return false;
    }

/*partition function*/

    int partition(int A[], int si, int ei)
    {
        int x = A[ei];
        int i = (si - 1);
        int j;
        for (j = si; j <= ei - 1; j++) {
            if (A[j] <= x) {
                i++;
                int temp = A[i];
                A[i] = A[j];
                A[j] = temp;
            }
        }
        int temp = A[i + 1];
        A[i + 1] = A[ei];
        A[ei] = temp;
        return (i + 1);
    }

/* Implementation of Quick Sort
    A[] --> Array to be sorted
    si  --> Starting index
    ei  --> Ending index
     */

    void quickSort(int A[], int si, int ei)
    {
        int pi;

/* Partitioning index */

        if (si < ei) {
            pi = partition(A, si, ei);
            quickSort(A, si, pi - 1);
            quickSort(A, pi + 1, ei);
        }
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        FindTriplet triplet = new FindTriplet();
        int A[] = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.length;
        triplet.find3Numbers(A, arr_size, sum);
    }
}

class ProductArray {

/* Function to print product array
for a given array arr[] of size n */

    void productArray(int arr[], int n)
    {

/*        Base case*/

        if (n == 1) {
            System.out.print("0");
            return;
        }
        int i, temp = 1;

/* Allocate memory for the product array */

        int prod[] = new int[n];

/* Initialize the product array as 1 */

        for (int j = 0; j < n; j++)
            prod[j] = 1;

/* In this loop, temp variable contains product of
           elements on left side excluding arr[i] */

        for (i = 0; i < n; i++) {
            prod[i] = temp;
            temp *= arr[i];
        }

/* Initialize temp to 1 for product on right side */

        temp = 1;

/* In this loop, temp variable contains product of
           elements on right side excluding arr[i] */

        for (i = n - 1; i >= 0; i--) {
            prod[i] *= temp;
            temp *= arr[i];
        }

/* print the constructed prod array */

        for (i = 0; i < n; i++)
            System.out.print(prod[i] + " ");
        return;
    }

/* Driver program to test above functions */

    public static void main(String[] args)
    {
        ProductArray pa = new ProductArray();
        int arr[] = { 10, 3, 5, 6, 2 };
        int n = arr.length;
        System.out.println("The product array is : ");
        pa.productArray(arr, n);
    }
}

/*Java program for the above approach*/

import java.io.*;
import java.util.*;
class Solution {
    public static long[] productExceptSelf(int a[], int n)
    {
        long prod = 1;
        long flag = 0;

/*        product of all elements*/

        for (int i = 0; i < n; i++) {

/*            counting number of elements
            which have value
            0*/

            if (a[i] == 0)
                flag++;
            else
                prod *= a[i];
        }

/*        creating a new array of size n*/

        long arr[] = new long[n];
        for (int i = 0; i < n; i++) {

/*            if number of elements in
            array with value 0
            is more than 1 than each
            value in new array
            will be equal to 0*/

            if (flag > 1) {
                arr[i] = 0;
            }

/*            if no element having value
            0 than we will
            insert product/a[i] in new array*/

            else if (flag == 0)
                arr[i] = (prod / a[i]);

/*            if 1 element of array having
            value 0 than all
            the elements except that index
            value , will be
            equal to 0*/

            else if (flag == 1 && a[i] != 0) {
                arr[i] = 0;
            }

/*            if(flag == 1 && a[i] == 0)*/

            else
                arr[i] = prod;
        }
        return arr;
    }

/*    Driver Code*/

    public static void main(String args[])
        throws IOException
    {
        int n = 5;
        int[] array = { 10, 3, 5, 6, 2 };
        Solution ob = new Solution();
        long[] ans = new long[n];
        ans = ob.productExceptSelf(array, n);
        for (int i = 0; i < n; i++) {
            System.out.print(ans[i] + " ");
        }
    }
}

class AreConsecutive
{

/* The function checks if the array elements are consecutive
       If elements are consecutive, then returns true, else returns
       false */

    boolean areConsecutive(int arr[], int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in array */

        int max = getMax(arr, n);

/* 3) max - min + 1 is equal to n,  then only check all elements */

        if (max - min + 1 == n)
        {

/* Create a temp array to hold visited flag of all elements.
               Note that, calloc is used here so that all values are initialized
               as false */

            boolean visited[] = new boolean[n];
            int i;
            for (i = 0; i < n; i++)
            {

/* If we see an element again, then return false */

                if (visited[arr[i] - min] != false)
                    return false;

/* If visited first time, then mark the element as visited */

                visited[arr[i] - min] = true;
            }

/* If all elements occur once, then return true */

            return true;
        }

/*if (max - min  + 1 != n)*/

return false; 
    }

/* UTILITY FUNCTIONS */

    int getMin(int arr[], int n)
    {
        int min = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] < min)
                min = arr[i];
        }
        return min;
    }
    int getMax(int arr[], int n)
    {
        int max = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

/* Driver program to test above functions */

    public static void main(String[] args)
    {
        AreConsecutive consecutive = new AreConsecutive();
        int arr[] = {5, 4, 2, 3, 1, 6};
        int n = arr.length;
        if (consecutive.areConsecutive(arr, n) == true)
            System.out.println("Array elements are consecutive");
        else
            System.out.println("Array elements are not consecutive");
    }
}

class AreConsecutive
{

/* The function checks if the array elements are consecutive
       If elements are consecutive, then returns true, else returns
       false */

    boolean areConsecutive(int arr[], int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in array */

        int max = getMax(arr, n);

/* 3) max-min+1 is equal to n then only check all elements */

        if (max - min + 1 == n)
        {
            int i;
            for (i = 0; i < n; i++)
            {
                int j;
                if (arr[i] < 0)
                    j = -arr[i] - min;
                else
                    j = arr[i] - min;

/*                if the value at index j is negative then
                there is repitition*/

                if (arr[j] > 0)
                    arr[j] = -arr[j];
                else
                    return false;
            }

/* If we do not see a negative value then all elements
               are distinct */

            return true;
        }

/*if (max-min+1 != n)*/

return false; 
