/*Java program for linear search*/

import java.io.*;
class GFG
{
    public static void search(int arr[], int search_Element)
    {
        int left = 0;
        int length = arr.length;
        int right = length - 1;
        int position = -1;

/*        run loop from 0 to right*/

        for (left = 0; left <= right;)
        {

/*            if search_element is found with left variable*/

            if (arr[left] == search_Element)
            {
                position = left;
                System.out.println(
                    "Element found in Array at "
                    + (position + 1) + " Position with "
                    + (left + 1) + " Attempt");
                break;
            }

/*            if search_element is found with right variable*/

            if (arr[right] == search_Element)
            {
                position = right;
                System.out.println(
                    "Element found in Array at "
                    + (position + 1) + " Position with "
                    + (length - right) + " Attempt");
                break;
            }
            left++;
            right--;
        }

/*        if element not found*/

        if (position == -1)
            System.out.println("Not found in Array with "
                               + left + " Attempt");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 3, 4, 5 };
        int search_element = 5;

/*        Function call*/

        search(arr,search_element);
    }
}

/*Java implementation of recursive Binary Search*/

class BinarySearch {

/*    Returns index of x if it is present in arr[l..
    r], else return -1*/

    int binarySearch(int arr[], int l, int r, int x)
    {
        if (r >= l) {
            int mid = l + (r - l) / 2;

/*            If the element is present at the
            middle itself*/

            if (arr[mid] == x)
                return mid;

/*            If element is smaller than mid, then
            it can only be present in left subarray*/

            if (arr[mid] > x)
                return binarySearch(arr, l, mid - 1, x);

/*            Else the element can only be present
            in right subarray*/

            return binarySearch(arr, mid + 1, r, x);
        }

/*        We reach here when element is not present
        in array*/

        return -1;
    }

/*    Driver method to test above*/

    public static void main(String args[])
    {
        BinarySearch ob = new BinarySearch();
        int arr[] = { 2, 3, 4, 10, 40 };
        int n = arr.length;
        int x = 10;
        int result = ob.binarySearch(arr, 0, n - 1, x);
        if (result == -1)
            System.out.println("Element not present");
        else
            System.out.println("Element found at index " + result);
    }
}

/*Java program to implement interpolation
search with recursion*/

import java.util.*;
class GFG {

/*    If x is present in arr[0..n-1], then returns
    index of it, else returns -1.*/

    public static int interpolationSearch(int arr[], int lo,
                                          int hi, int x)
    {
        int pos;

/*        Since array is sorted, an element
        present in array must be in range
        defined by corner*/

        if (lo <= hi && x >= arr[lo] && x <= arr[hi]) {

/*            Probing the position with keeping
            uniform distribution in mind.*/

            pos = lo
                  + (((hi - lo) / (arr[hi] - arr[lo]))
                     * (x - arr[lo]));

/*            Condition of target found*/

            if (arr[pos] == x)
                return pos;

/*            If x is larger, x is in right sub array*/

            if (arr[pos] < x)
                return interpolationSearch(arr, pos + 1, hi,
                                           x);

/*            If x is smaller, x is in left sub array*/

            if (arr[pos] > x)
                return interpolationSearch(arr, lo, pos - 1,
                                           x);
        }
        return -1;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {

/*        Array of items on which search will
        be conducted.*/

        int arr[] = { 10, 12, 13, 16, 18, 19, 20, 21,
                      22, 23, 24, 33, 35, 42, 47 };
        int n = arr.length;

/*        Element to be searched*/

        int x = 18;
        int index = interpolationSearch(arr, 0, n - 1, x);

/*        If element was found*/

        if (index != -1)
            System.out.println("Element found at index "
                               + index);
        else
            System.out.println("Element not found.");
    }
}

/*Optimized java implementation
of Bubble sort*/

import java.io.*;
class GFG
{

/*    An optimized version of Bubble Sort*/

    static void bubbleSort(int arr[], int n)
    {
        int i, j, temp;
        boolean swapped;
        for (i = 0; i < n - 1; i++)
        {
            swapped = false;
            for (j = 0; j < n - i - 1; j++)
            {
                if (arr[j] > arr[j + 1])
                {

/*                    swap arr[j] and arr[j+1]*/

                    temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    swapped = true;
                }
            }

/*            IF no two elements were
            swapped by inner loop, then break*/

            if (swapped == false)
                break;
        }
    }

/*    Function to print an array*/

    static void printArray(int arr[], int size)
    {
        int i;
        for (i = 0; i < size; i++)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver program*/

    public static void main(String args[])
    {
        int arr[] = { 64, 34, 25, 12, 22, 11, 90 };
        int n = arr.length;
        bubbleSort(arr, n);
        System.out.println("Sorted array: ");
        printArray(arr, n);
    }
}

/* Java program for Merge Sort */

class MergeSort
{

/*    Merges two subarrays of arr[].
    First subarray is arr[l..m]
    Second subarray is arr[m+1..r]*/

    void merge(int arr[], int l, int m, int r)
    {

/*        Find sizes of two subarrays to be merged*/

        int n1 = m - l + 1;
        int n2 = r - m;

/* Create temp arrays */

        int L[] = new int[n1];
        int R[] = new int[n2];

/*Copy data to temp arrays*/

        for (int i = 0; i < n1; ++i)
            L[i] = arr[l + i];
        for (int j = 0; j < n2; ++j)
            R[j] = arr[m + 1 + j];

/*        Merge the temp arrays
        Initial indexes of first
        and second subarrays*/

        int i = 0, j = 0;

/*        Initial index of merged subarry array*/

        int k = l;
        while (i < n1 && j < n2) {
            if (L[i] <= R[j]) {
                arr[k] = L[i];
                i++;
            }
            else {
                arr[k] = R[j];
                j++;
            }
            k++;
        }

/* Copy remaining elements of L[] if any */

        while (i < n1) {
            arr[k] = L[i];
            i++;
            k++;
        }

/* Copy remaining elements of R[] if any */

        while (j < n2) {
            arr[k] = R[j];
            j++;
            k++;
        }
    }

/*    Main function that sorts arr[l..r] using
    merge()*/

    void sort(int arr[], int l, int r)
    {
        if (l < r) {

/*            Find the middle point*/

            int m =l+ (r-l)/2;

/*            Sort first and second halves*/

            sort(arr, l, m);
            sort(arr, m + 1, r);

/*            Merge the sorted halves*/

            merge(arr, l, m, r);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int arr[])
    {
        int n = arr.length;
        for (int i = 0; i < n; ++i)
            System.out.print(arr[i] + " ");
        System.out.println();
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 12, 11, 13, 5, 6, 7 };
        System.out.println("Given Array");
        printArray(arr);
        MergeSort ob = new MergeSort();
        ob.sort(arr, 0, arr.length - 1);
        System.out.println("\nSorted array");
        printArray(arr);
    }
}

/*Java implementation of QuickSort*/

import java.io.*;
class GFG{

/*A utility function to swap two elements*/

static void swap(int[] arr, int i, int j)
{
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

/* This function takes last element as pivot, places
   the pivot element at its correct position in sorted
   array, and places all smaller (smaller than pivot)
   to left of pivot and all greater elements to right
   of pivot */

static int partition(int[] arr, int low, int high)
{

/*    pivot*/

    int pivot = arr[high];

/*    Index of smaller element and
    indicates the right position
    of pivot found so far*/

    int i = (low - 1);
    for(int j = low; j <= high - 1; j++)
    {

/*        If current element is smaller
        than the pivot*/

        if (arr[j] < pivot)
        {

/*            Increment index of
            smaller element*/

            i++;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, high);
    return (i + 1);
}

/* The main function that implements QuickSort
          arr[] --> Array to be sorted,
          low --> Starting index,
          high --> Ending index
 */

static void quickSort(int[] arr, int low, int high)
{
    if (low < high)
    {

/*        pi is partitioning index, arr[p]
        is now at right place*/

        int pi = partition(arr, low, high);

/*        Separately sort elements before
        partition and after partition*/

        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

/*Function to print an array*/

static void printArray(int[] arr, int size)
{
    for(int i = 0; i < size; i++)
        System.out.print(arr[i] + " ");
    System.out.println();
}

/*Driver Code*/

public static void main(String[] args)
{
    int[] arr = { 10, 7, 8, 9, 1, 5 };
    int n = arr.length;
    quickSort(arr, 0, n - 1);
    System.out.println("Sorted array: ");
    printArray(arr, n);
}
}

/*Java program for implementation of Comb Sort*/

class CombSort
{

/*    To find gap between elements*/

    int getNextGap(int gap)
    {

/*        Shrink gap by Shrink factor*/

        gap = (gap*10)/13;
        if (gap < 1)
            return 1;
        return gap;
    }

/*    Function to sort arr[] using Comb Sort*/

    void sort(int arr[])
    {
        int n = arr.length;

/*        initialize gap*/

        int gap = n;

/*        Initialize swapped as true to make sure that
        loop runs*/

        boolean swapped = true;

/*        Keep running while gap is more than 1 and last
        iteration caused a swap*/

        while (gap != 1 || swapped == true)
        {

/*            Find next gap*/

            gap = getNextGap(gap);

/*            Initialize swapped as false so that we can
            check if swap happened or not*/

            swapped = false;

/*            Compare all elements with current gap*/

            for (int i=0; i<n-gap; i++)
            {
                if (arr[i] > arr[i+gap])
                {

/*                    Swap arr[i] and arr[i+gap]*/

                    int temp = arr[i];
                    arr[i] = arr[i+gap];
                    arr[i+gap] = temp;

/*                    Set swapped*/

                    swapped = true;
                }
            }
        }
    }

/*    Driver method*/

    public static void main(String args[])
    {
        CombSort ob = new CombSort();
        int arr[] = {8, 4, 1, 56, 3, -44, 23, -6, 28, 0};
        ob.sort(arr);
        System.out.println("sorted array");
        for (int i=0; i<arr.length; ++i)
            System.out.print(arr[i] + " ");
    }
}

/*Java program to implement cycle sort*/

import java.util.*;
import java.lang.*;
class GFG {

/*    Function sort the array using Cycle sort*/

    public static void cycleSort(int arr[], int n)
    {

/*        count number of memory writes*/

        int writes = 0;

/*        traverse array elements and put it to on
        the right place*/

        for (int cycle_start = 0; cycle_start <= n - 2; cycle_start++) {

/*            initialize item as starting point*/

            int item = arr[cycle_start];

/*            Find position where we put the item. We basically
            count all smaller elements on right side of item.*/

            int pos = cycle_start;
            for (int i = cycle_start + 1; i < n; i++)
                if (arr[i] < item)
                    pos++;

/*            If item is already in correct position*/

            if (pos == cycle_start)
                continue;

/*            ignore all duplicate elements*/

            while (item == arr[pos])
                pos += 1;

/*            put the item to it's right position*/

            if (pos != cycle_start) {
                int temp = item;
                item = arr[pos];
                arr[pos] = temp;
                writes++;
            }

/*            Rotate rest of the cycle*/

            while (pos != cycle_start) {
                pos = cycle_start;

/*                Find position where we put the element*/

                for (int i = cycle_start + 1; i < n; i++)
                    if (arr[i] < item)
                        pos += 1;

/*                ignore all duplicate elements*/

                while (item == arr[pos])
                    pos += 1;

/*                put the item to it's right position*/

                if (item != arr[pos]) {
                    int temp = item;
                    item = arr[pos];
                    arr[pos] = temp;
                    writes++;
                }
            }
        }
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 8, 3, 9, 10, 10, 2, 4 };
        int n = arr.length;
        cycleSort(arr, n);
        System.out.println("After sort : ");
        for (int i = 0; i < n; i++)
            System.out.print(arr[i] + " ");
    }
}

/*Java program for the above approach*/

import java.io.*;
import java.lang.*;
import java.util.*;

/*Node Class*/

class Node {
    int data;
    Node next;
    Node(int key)
    {
        this.data = key;
        next = null;
    }
}
class GFG {

/*    Function to merge sort*/

    static Node mergeSort(Node head)
    {
        if (head.next == null)
            return head;
        Node mid = findMid(head);
        Node head2 = mid.next;
        mid.next = null;
        Node newHead1 = mergeSort(head);
        Node newHead2 = mergeSort(head2);
        Node finalHead = merge(newHead1, newHead2);
        return finalHead;
    }

/*    Function to merge two linked lists*/

    static Node merge(Node head1, Node head2)
    {
        Node merged = new Node(-1);
        Node temp = merged;

/*        While head1 is not null and head2
        is not null*/

        while (head1 != null && head2 != null) {
            if (head1.data < head2.data) {
                temp.next = head1;
                head1 = head1.next;
            }
            else {
                temp.next = head2;
                head2 = head2.next;
            }
            temp = temp.next;
        }

/*        While head1 is not null*/

        while (head1 != null) {
            temp.next = head1;
            head1 = head1.next;
            temp = temp.next;
        }

/*        While head2 is not null*/

        while (head2 != null) {
            temp.next = head2;
            head2 = head2.next;
            temp = temp.next;
        }
        return merged.next;
    }

/*    Find mid using The Tortoise and The Hare approach*/

    static Node findMid(Node head)
    {
        Node slow = head, fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        return slow;
    }

/*    Function to print list*/

    static void printList(Node head)
    {
        while (head != null) {
            System.out.print(head.data + " ");
            head = head.next;
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        Node head = new Node(7);
        Node temp = head;
        temp.next = new Node(10);
        temp = temp.next;
        temp.next = new Node(5);
        temp = temp.next;
        temp.next = new Node(20);
        temp = temp.next;
        temp.next = new Node(3);
        temp = temp.next;
        temp.next = new Node(2);
        temp = temp.next;

/*        Apply merge Sort*/

        head = mergeSort(head);
        System.out.print("\nSorted Linked List is: \n");
        printList(head);
    }
}

/*Java program for implementation of QuickSort*/

import java.util.*;
class QuickSort {

/* This function takes last element as pivot,
    places the pivot element at its correct
    position in sorted array, and places all
    smaller (smaller than pivot) to left of
    pivot and all greater elements to right
    of pivot */

    static int partition(int arr[], int low, int high)
    {
        int pivot = arr[high];
        int i = (low - 1); 
        for (int j = low; j <= high - 1; j++) {
            if (arr[j] <= pivot) {
                i++;
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        int temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;
        return i + 1;
    }

/* The main function that implements QuickSort()
    arr[] --> Array to be sorted,
    low --> Starting index,
    high --> Ending index */

    static void qSort(int arr[], int low, int high)
    {
        if (low < high) {

/* pi is partitioning index, arr[pi] is
            now at right place */

            int pi = partition(arr, low, high);
            qSort(arr, low, pi - 1);
            qSort(arr, pi + 1, high);
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int n = 5;
        int arr[] = { 4, 2, 6, 9, 2 };
        qSort(arr, 0, n - 1);
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

/*Java program for implementation of QuickSort*/

import java.util.*;
class QuickSort {

/* This function takes last element as pivot,
    places the pivot element at its correct
    position in sorted array, and places all
    smaller (smaller than pivot) to left of
    pivot and all greater elements to right
    of pivot */

    static int partition(int arr[], int low, int high)
    {
        int pivot = arr[high];

        int i = (low - 1);
        for (int j = low; j <= high - 1; j++) {
            if (arr[j] <= pivot) {
                i++;
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
        int temp = arr[i + 1];
        arr[i + 1] = arr[high];
        arr[high] = temp;
        return i + 1;
    }

/* A[] --> Array to be sorted, 
   l  --> Starting index, 
   h  --> Ending index */

    static void quickSortIterative(int arr[], int l, int h)
    {

/*        Create an auxiliary stack*/

        int[] stack = new int[h - l + 1];

/*        initialize top of stack*/

        int top = -1;

/*        push initial values of l and h to stack*/

        stack[++top] = l;
        stack[++top] = h;

/*        Keep popping from stack while is not empty*/

        while (top >= 0) {

/*            Pop h and l*/

            h = stack[top--];
            l = stack[top--];

/*            Set pivot element at its correct position
            in sorted array*/

            int p = partition(arr, l, h);

/*            If there are elements on left side of pivot,
            then push left side to stack*/

            if (p - 1 > l) {
                stack[++top] = l;
                stack[++top] = p - 1;
            }

/*            If there are elements on right side of pivot,
            then push right side to stack*/

            if (p + 1 < h) {
                stack[++top] = p + 1;
                stack[++top] = h;
            }
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        int arr[] = { 4, 3, 5, 2, 1, 3, 2, 3 };
        int n = 8;

/*        Function calling*/

        quickSortIterative(arr, 0, n - 1);
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}

/*Java program to find an element 
in an almost sorted array*/

class GFG
{

/*    A recursive binary search based function. 
    It returns index of x in given array 
    arr[l..r] is present, otherwise -1*/

    int binarySearch(int arr[], int l, int r, int x)
    {
        if (r >= l)
        {
            int mid = l + (r - l) / 2;

/*            If the element is present at 
            one of the middle 3 positions*/

            if (arr[mid] == x) 
                return mid;
            if (mid > l && arr[mid - 1] == x)
                return (mid - 1);
            if (mid < r && arr[mid + 1] == x)
                return (mid + 1);

/*            If element is smaller than mid, then
            it can only be present in left subarray*/

            if (arr[mid] > x) 
                return binarySearch(arr, l, mid - 2, x);

/*            Else the element can only be present 
            in right subarray*/

            return binarySearch(arr, mid + 2, r, x);
        }

/*        We reach here when element is 
        not present in array*/

        return -1;
    }

/*    Driver code*/

    public static void main(String args[])
    {
        GFG ob = new GFG();
        int arr[] = {3, 2, 10, 4, 40};
        int n = arr.length;
        int x = 4;
        int result = ob.binarySearch(arr, 0, n - 1, x);
        if(result == -1)
            System.out.println("Element is not present in array");
        else
            System.out.println("Element is present at index " +
                                result);
    }
}

/*Java program to count 1's in a sorted array*/

class CountOnes
{

/* Returns counts of 1's in arr[low..high].  The
       array is assumed to be sorted in non-increasing
       order */

    int countOnes(int arr[], int low, int high)
    {
        if (high >= low)
        {

/*            get the middle index*/

            int mid = low + (high - low) / 2;

/*            check if the element at middle index is last
            1*/

            if ((mid == high || arr[mid + 1] == 0)
                && (arr[mid] == 1))
                return mid + 1;

/*            If element is not last 1, recur for right
            side*/

            if (arr[mid] == 1)
                return countOnes(arr, (mid + 1), high);

/*            else recur for left side*/

            return countOnes(arr, low, (mid - 1));
        }
        return 0;
    }

/* Driver code */

    public static void main(String args[])
    {
        CountOnes ob = new CountOnes();
        int arr[] = { 1, 1, 1, 1, 0, 0, 0 };
        int n = arr.length;
        System.out.println("Count of 1's in given array is "
                           + ob.countOnes(arr, 0, n - 1));
    }
}

/*Java program to sort link list
using insertion sort*/

public class LinkedlistIS
{
    node head;
    node sorted;
    class node
    {
        int val;
        node next;
        public node(int val)
        {
            this.val = val;
        }
    }

/*A utility function to insert a node
at the beginning of linked list*/

    void push(int val)
    {

/* allocate node */

        node newnode = new node(val);

/* link the old list off the new node */

        newnode.next = head;

/* move the head to point to the new node */

        head = newnode;
    }

/*    function to sort a singly linked list using insertion sort*/

    void insertionSort(node headref)
    {

/*        Initialize sorted linked list*/

        sorted = null;
        node current = headref;

/*        Traverse the given linked list and insert every
        node to sorted*/

        while (current != null)
        {

/*            Store next for next iteration*/

            node next = current.next;

/*            insert current in sorted linked list*/

            sortedInsert(current);

/*            Update current*/

            current = next;
        }

/*        Update head_ref to point to sorted linked list*/

        head = sorted;
    }

/*
     * function to insert a new_node in a list. Note that
     * this function expects a pointer to head_ref as this
     * can modify the head of the input linked list
     * (similar to push())
     */

    void sortedInsert(node newnode)
    {

/* Special case for the head end */

        if (sorted == null || sorted.val >= newnode.val)
        {
            newnode.next = sorted;
            sorted = newnode;
        }
        else
        {
            node current = sorted;

/* Locate the node before the point of insertion */

            while (current.next != null && current.next.val < newnode.val)
            {
                current = current.next;
            }
            newnode.next = current.next;
            current.next = newnode;
        }
    }

/* Function to print linked list */

    void printlist(node head)
    {
        while (head != null)
        {
            System.out.print(head.val + " ");
            head = head.next;
        }
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        LinkedlistIS list = new LinkedlistIS();
        list.push(5);
        list.push(20);
        list.push(4);
        list.push(3);
        list.push(30);
        System.out.println("Linked List before Sorting..");
        list.printlist(list.head);
        list.insertionSort(list.head);
        System.out.println("\nLinkedList After sorting");
        list.printlist(list.head);
    }
}

/*Java program to count Minimum number
of swaps so that the largest element
is at beginning and the
smallest element is at last*/

import java.io.*;
class GFG {

/*    Function performing calculations*/

    public static void minimumSwaps(int a[], int n)
    {
        int maxx = -1, minn = a[0], l = 0, r = 0;
        for (int i = 0; i < n; i++) {

/*            Index of leftmost largest element*/

            if (a[i] > maxx) {
                maxx = a[i];
                l = i;
            }

/*            Index of rightmost smallest element*/

            if (a[i] <= minn) {
                minn = a[i];
                r = i;
            }
        }
        if (r < l)
            System.out.println(l + (n - r - 2));
        else
            System.out.println(l + (n - r - 1));
    }

/*    Driver Code*/

    public static void main(String args[]) throws IOException
    {
        int a[] = { 5, 6, 1, 3 };
        int n = a.length;
        minimumSwaps(a, n);
    }
}

/*The following implementation assumes that the activities
are already sorted according to their finish time*/

import java.util.*;
import java.lang.*;
import java.io.*;
class ActivitySelection
{

/*    Prints a maximum set of activities that can be done by a single
    person, one at a time.
      n   -->  Total number of activities
      s[] -->  An array that contains start time of all activities
      f[] -->  An array that contains finish time of all activities*/

    public static void printMaxActivities(int s[], int f[], int n)
    {
    int i, j;
    System.out.print("Following activities are selected : n");

/*    The first activity always gets selected*/

    i = 0;
    System.out.print(i+" ");

/*    Consider rest of the activities*/

    for (j = 1; j < n; j++)
    {

/*         If this activity has start time greater than or
         equal to the finish time of previously selected
         activity, then select it*/

         if (s[j] >= f[i])
         {
              System.out.print(j+" ");
              i = j;
          }
     }
    }

/*    driver program to test above function*/

    public static void main(String[] args)
    {
    int s[] =  {1, 3, 0, 5, 8, 5};
    int f[] =  {2, 4, 6, 7, 9, 9};
    int n = s.length;
    printMaxActivities(s, f, n);
    }
}

/*java program for the above approach*/

import java.io.*;
import java.lang.*;
import java.util.*;
class GFG {

/*  Pair class*/

  static class Pair {
    int first;
    int second;
    Pair(int first, int second)
    {
      this.first = first;
      this.second = second;
    }
  }

/*    Vector to store results.*/
  static void SelectActivities(int s[], int f[])
  {
    ArrayList<Pair> ans = new ArrayList<>();

/*    Minimum Priority Queue to sort activities in
    ascending order of finishing time (f[i]).*/

    PriorityQueue<Pair> p = new PriorityQueue<>(
      (p1, p2) -> p1.first - p2.first);
    for (int i = 0; i < s.length; i++) {

/*      Pushing elements in priority queue where the
      key is f[i]*/

      p.add(new Pair(f[i], s[i]));
    }
    Pair it = p.poll();
    int start = it.second;
    int end = it.first;
    ans.add(new Pair(start, end));
    while (!p.isEmpty()) {
      Pair itr = p.poll();
      if (itr.second >= end) {
        start = itr.second;
        end = itr.first;
        ans.add(new Pair(start, end));
      }
    }
    System.out.println(
      "Following Activities should be selected. \n");
    for (Pair itr : ans) {
      System.out.println(
        "Activity started at: " + itr.first
        + " and ends at  " + itr.second);
    }
  }

/*  Driver Code*/

  public static void main(String[] args)
  {
    int s[] = { 1, 3, 0, 5, 8, 5 };
    int f[] = { 2, 4, 6, 7, 9, 9 };

/*    Function call*/

    SelectActivities(s, f);
  }
}

/*A Space efficient Dynamic Programming
based Java program to find minimum
number operations to convert str1 to str2*/

import java.util.*;
class GFG
{
static void EditDistDP(String str1, String str2)
{
    int len1 = str1.length();
    int len2 = str2.length();

/*    Create a DP array to memoize result
    of previous computations*/

    int [][]DP = new int[2][len1 + 1];

/*    Base condition when second String
    is empty then we remove all characters*/

    for (int i = 0; i <= len1; i++)
        DP[0][i] = i;

/*    Start filling the DP
    This loop run for every
    character in second String*/

    for (int i = 1; i <= len2; i++)
    {

/*        This loop compares the char from
        second String with first String
        characters*/

        for (int j = 0; j <= len1; j++)
        {

/*            if first String is empty then
            we have to perform add character
            operation to get second String*/

            if (j == 0)
                DP[i % 2][j] = i;

/*            if character from both String
            is same then we do not perform any
            operation . here i % 2 is for bound
            the row number.*/

            else if (str1.charAt(j - 1) == str2.charAt(i - 1)) {
                DP[i % 2][j] = DP[(i - 1) % 2][j - 1];
            }

/*            if character from both String is
            not same then we take the minimum
            from three specified operation*/

            else {
                DP[i % 2][j] = 1 + Math.min(DP[(i - 1) % 2][j],
                                       Math.min(DP[i % 2][j - 1],
                                           DP[(i - 1) % 2][j - 1]));
            }
        }
    }

/*    after complete fill the DP array
    if the len2 is even then we end
    up in the 0th row else we end up
    in the 1th row so we take len2 % 2
    to get row*/

    System.out.print(DP[len2 % 2][len1] +"\n");
}

/*Driver program*/

public static void main(String[] args)
{
    String str1 = "food";
    String str2 = "money";
    EditDistDP(str1, str2);
}
}

import java.util.*;
class GFG
{
static int minDis(String s1, String s2,
                  int n, int m, int[][]dp)
{

/*  If any String is empty,
  return the remaining characters of other String*/

  if(n == 0)   
    return m; 
  if(m == 0)   
    return n;

/*  To check if the recursive tree
  for given n & m has already been executed*/

  if(dp[n][m] != -1)   
    return dp[n][m];

/*  If characters are equal, execute
  recursive function for n-1, m-1*/

  if(s1.charAt(n - 1) == s2.charAt(m - 1))
  {          
    if(dp[n - 1][m - 1] == -1)
    {              
      return dp[n][m] = minDis(s1, s2, n - 1, m - 1, dp);          
    }       
    else
      return dp[n][m] = dp[n - 1][m - 1];  
  }

/*  If characters are nt equal, we need to
  find the minimum cost out of all 3 operations.     */

  else
  {

/*temp variables  */

int m1, m2, m3;        
    if(dp[n-1][m] != -1)
    {   
      m1 = dp[n - 1][m];     
    }          
    else
    {  
      m1 = minDis(s1, s2, n - 1, m, dp);     
    }           
    if(dp[n][m - 1] != -1)
    {               
      m2 = dp[n][m - 1];           
    }           
    else
    {   
      m2 = minDis(s1, s2, n, m - 1, dp);     
    }                                  
    if(dp[n - 1][m - 1] != -1)
    {   
      m3 = dp[n - 1][m - 1];     
    }  
    else
    {  
      m3 = minDis(s1, s2, n - 1, m - 1, dp);      
    }    
    return dp[n][m] = 1 + Math.min(m1, Math.min(m2, m3));       
  }
}

/*Driver program*/

public static void main(String[] args)
{
  String str1 = "voldemort";
  String str2 = "dumbledore";
  int n= str1.length(), m = str2.length();   
  int[][] dp = new int[n + 1][m + 1];
  for(int i = 0; i < n + 1; i++)
  Arrays.fill(dp[i], -1);               
  System.out.print(minDis(str1, str2, n, m, dp));
}
}

/*Java program using memoization*/

import java.io.*;
import java.util.*;
class GFG
{
  static int[][] dp = new int[100][100];

/*  Function for matrix chain multiplication*/

  static int matrixChainMemoised(int[] p, int i, int j)
  {
    if (i == j) 
    {
      return 0;
    }
    if (dp[i][j] != -1) 
    {
      return dp[i][j];
    }
    dp[i][j] = Integer.MAX_VALUE;
    for (int k = i; k < j; k++) 
    {
      dp[i][j] = Math.min(
        dp[i][j], matrixChainMemoised(p, i, k)
        + matrixChainMemoised(p, k + 1, j)
        + p[i - 1] * p[k] * p[j]);
    }
    return dp[i][j];
  }
  static int MatrixChainOrder(int[] p, int n)
  {
    int i = 1, j = n - 1;
    return matrixChainMemoised(p, i, j);
  }

/*  Driver Code*/

  public static void main (String[] args)
  {
    int arr[] = { 1, 2, 3, 4 };
    int n= arr.length;
    for (int[] row : dp)
      Arrays.fill(row, -1);
    System.out.println("Minimum number of multiplications is " + MatrixChainOrder(arr, n));
  }
}

import java.util.*;
class GFG {

/*    pow(base,exp,mod) is used to find
    (base^exp)%mod fast -> O(log(exp))*/

    static long pow(long b, long exp, long mod)
    {
        long ret = 1;
        while (exp > 0) {
            if ((exp & 1) > 0)
                ret = (ret * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return ret;
    }

/*base case*/
    static int nCr(int n, int r)
    {
if (r > n) 
            return 0;

/*        C(n,r) = C(n,n-r) Complexity for
        this code is lesser for lower n-r*/

        if (n - r > r)
            r = n - r;

/*        list to smallest prime factor
        of each number from 1 to n*/

        int[] SPF = new int[n + 1];

/*        set smallest prime factor of each
        number as itself*/

        for (int i = 1; i <= n; i++)
            SPF[i] = i;

/*        set smallest prime factor of all
        even numbers as 2*/

        for (int i = 4; i <= n; i += 2)
            SPF[i] = 2;
        for (int i = 3; i * i < n + 1; i += 2)
        {

/*            Check if i is prime*/

            if (SPF[i] == i)
            {

/*                All multiples of i are
                composite (and divisible by
                i) so add i to their prime
                factorization getpow(j,i)
                times*/

                for (int j = i * i; j < n + 1; j += i)
                    if (SPF[j] == j) {
                        SPF[j] = i;
                    }
            }
        }

/*       Hash Map to store power of
       each prime in C(n,r)*/

       Map<Integer, Integer> prime_pow
            = new HashMap<>();

/*        For numerator count frequency of each prime factor*/

        for (int i = r + 1; i < n + 1; i++)
        {
            int t = i;

/*            Recursive division to find
            prime factorization of i*/

            while (t > 1)
            {
                prime_pow.put(SPF[t],
                    prime_pow.getOrDefault(SPF[t], 0) + 1);
                t /= SPF[t];
            }
        }

/*        For denominator subtract the power of
        each prime factor*/

        for (int i = 1; i < n - r + 1; i++)
        {
            int t = i;

/*            Recursive division to find
            prime factorization of i*/

            while (t > 1)
            {
                prime_pow.put(SPF[t],
                              prime_pow.get(SPF[t]) - 1);
                t /= SPF[t];
            }
        }

/*        long because mod is large and a%mod
        * b%mod can overflow int*/

        long ans = 1, mod = 1000000007;

/*        use (a*b)%mod = (a%mod * b%mod)%mod*/

        for (int i : prime_pow.keySet())

/*            pow(base,exp,mod) is used to
            find (base^exp)%mod fast*/

            ans = (ans * pow(i, prime_pow.get(i), mod))
                  % mod;
        return (int)ans;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int n = 5, r = 2;
        System.out.print("Value of C(" + n + ", " + r
                         + ") is " + nCr(n, r) + "\n");
    }
}

/*Java program of above approach*/

class GFG {

/*    A utility function to get max of two integers*/

    static int max(int x, int y) {
        return (x > y) ? x : y;
    }

/*    Returns the length of the longest palindromic subsequence in seq*/

    static int lps(char seq[], int i, int j) {

/*    Base Case 1: If there is only 1 character*/

        if (i == j) {
            return 1;
        }

/*    Base Case 2: If there are only 2 characters and both are same*/

        if (seq[i] == seq[j] && i + 1 == j) {
            return 2;
        }

/*    If the first and last characters match*/

        if (seq[i] == seq[j]) {
            return lps(seq, i + 1, j - 1) + 2;
        }

/*    If the first and last characters do not match*/

        return max(lps(seq, i, j - 1), lps(seq, i + 1, j));
    }

/* Driver program to test above function */

    public static void main(String[] args) {
        String seq = "GEEKSFORGEEKS";
        int n = seq.length();
        System.out.printf("The length of the LPS is %d", lps(seq.toCharArray(), 0, n - 1));
    }
}

/*Java Solution*/

public class LongestPalinSubstring {

/*    A utility function to print
    a substring str[low..high]*/

    static void printSubStr(
        String str, int low, int high)
    {
        System.out.println(
            str.substring(
                low, high + 1));
    }

/*    This function prints the longest
    palindrome substring of str[].
    It also returns the length of the
    longest palindrome*/

    static int longestPalSubstr(String str)
    {

/*        get length of input string*/

        int n = str.length();

/*        table[i][j] will be false if
        substring str[i..j] is not palindrome.
        Else table[i][j] will be true*/

        boolean table[][] = new boolean[n][n];

/*        All substrings of length 1 are palindromes*/

        int maxLength = 1;
        for (int i = 0; i < n; ++i)
            table[i][i] = true;

/*        check for sub-string of length 2.*/

        int start = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (str.charAt(i) == str.charAt(i + 1)) {
                table[i][i + 1] = true;
                start = i;
                maxLength = 2;
            }
        }

/*        Check for lengths greater than 2.
        k is length of substring*/

        for (int k = 3; k <= n; ++k) {

/*            Fix the starting index*/

            for (int i = 0; i < n - k + 1; ++i) {

/*                Get the ending index of substring from
                starting index i and length k*/

                int j = i + k - 1;

/*                checking for sub-string from ith index to
                jth index iff str.charAt(i+1) to
                str.charAt(j-1) is a palindrome*/

                if (table[i + 1][j - 1]
                    && str.charAt(i) == str.charAt(j)) {
                    table[i][j] = true;
                    if (k > maxLength) {
                        start = i;
                        maxLength = k;
                    }
                }
            }
        }
        System.out.print("Longest palindrome substring is; ");
        printSubStr(str, start,
                    start + maxLength - 1);

/*        return length of LPS*/

        return maxLength;
    }

/*    Driver program to test above functions*/

    public static void main(String[] args)
    {
        String str = "forgeeksskeegfor";
        System.out.println("Length is: " + longestPalSubstr(str));
    }
}

class GFG {

/*    Returns count of all possible
    parenthesizations that lead to
    result true for a boolean
    expression with symbols like true
    and false and operators like &, |
    and ^ filled between symbols*/

    static int countParenth(char symb[],
                            char oper[],
                            int n)
    {
        int F[][] = new int[n][n];
        int T[][] = new int[n][n];

/*        Fill diaginal entries first
        All diagonal entries in T[i][i]
        are 1 if symbol[i] is T (true).
        Similarly, all F[i][i] entries
        are 1 if symbol[i] is F (False)*/

        for (int i = 0; i < n; i++) {
            F[i][i] = (symb[i] == 'F') ? 1 : 0;
            T[i][i] = (symb[i] == 'T') ? 1 : 0;
        }

/*        Now fill T[i][i+1], T[i][i+2],
        T[i][i+3]... in order And F[i][i+1],
        F[i][i+2], F[i][i+3]... in order*/

        for (int gap = 1; gap < n; ++gap)
        {
            for (int i = 0,
                 j = gap; j < n;
                 ++i, ++j)
            {
                T[i][j] = F[i][j] = 0;
                for (int g = 0; g < gap; g++)
                {

/*                    Find place of parenthesization
                    using current value of gap*/

                    int k = i + g;

/*                    Store Total[i][k]
                    and Total[k+1][j]*/

                    int tik = T[i][k]
                      + F[i][k];
                    int tkj = T[k + 1][j]
                      + F[k + 1][j];

/*                    Follow the recursive formulas
                    according to the current operator*/

                    if (oper[k] == '&')
                    {
                        T[i][j] += T[i][k]
                                * T[k + 1][j];
                        F[i][j]
                            += (tik * tkj
                                - T[i][k]
                                * T[k + 1][j]);
                    }
                    if (oper[k] == '|')
                    {
                        F[i][j] += F[i][k]
                                * F[k + 1][j];
                        T[i][j]
                            += (tik * tkj
                                - F[i][k]
                                * F[k + 1][j]);
                    }
                    if (oper[k] == '^')
                    {
                        T[i][j] += F[i][k]
                               * T[k + 1][j]
                                   + T[i][k]
                                   * F[k + 1][j];
                        F[i][j] += T[i][k]
                               * T[k + 1][j]
                                   + F[i][k]
                               * F[k + 1][j];
                    }
                }
            }
        }
        return T[0][n - 1];
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        char symbols[] = "TTFT".toCharArray();
        char operators[] = "|&^".toCharArray();
        int n = symbols.length;

/*        There are 4 ways
        ((T|T)&(F^T)), (T|(T&(F^T))),
        (((T|T)&F)^T) and (T|((T&F)^T))*/

        System.out.println(
            countParenth(symbols, operators, n));
    }
}

import java.io.*;
import java.util.*;
class GFG {

/*CountWays function*/

    public static int countWays(int N, String S)
    {
        int dp[][][] = new int[N + 1][N + 1][2];
        for (int row[][] : dp)
            for (int col[] : row)
                Arrays.fill(col, -1);
        return parenthesis_count(S, 0, N - 1, 1, dp);
    }

/*    Base Condition*/

    public static int parenthesis_count(String str, int i,
                                        int j, int isTrue,
                                        int[][][] dp)
    {
        if (i > j)
            return 0;
        if (i == j)
        {
            if (isTrue == 1)
            {
                return (str.charAt(i) == 'T') ? 1 : 0;
            }
            else
            {
                return (str.charAt(i) == 'F') ? 1 : 0;
            }
        }
        if (dp[i][j][isTrue] != -1)
            return dp[i][j][isTrue];
        int temp_ans = 0;
        int leftTrue, rightTrue, leftFalse, rightFalse;
        for (int k = i + 1; k <= j - 1; k = k + 2)
        {
            if (dp[i][k - 1][1] != -1)
                leftTrue = dp[i][k - 1][1];
            else
            {

/*                Count number of True in left Partition*/

                leftTrue = parenthesis_count(str, i, k - 1,
                                             1, dp);
            }
            if (dp[i][k - 1][0] != -1)
                leftFalse = dp[i][k - 1][0];
            else
            {

/*                Count number of False in left Partition*/

                leftFalse = parenthesis_count(str, i, k - 1,
                                              0, dp);
            }
            if (dp[k + 1][j][1] != -1)
                rightTrue = dp[k + 1][j][1];
            else
            {

/*                Count number of True in right Partition*/

                rightTrue = parenthesis_count(str, k + 1, j,
                                              1, dp);
            }
            if (dp[k + 1][j][0] != -1)
                rightFalse = dp[k + 1][j][0];
            else
            {

/*                Count number of False in right Partition*/

                rightFalse = parenthesis_count(str, k + 1,
                                               j, 0, dp);
            }

/*            Evaluate AND operation*/

            if (str.charAt(k) == '&')
            {
                if (isTrue == 1)
                {
                    temp_ans
                        = temp_ans + leftTrue * rightTrue;
                }
                else
                {
                    temp_ans = temp_ans
                               + leftTrue * rightFalse
                               + leftFalse * rightTrue
                               + leftFalse * rightFalse;
                }
            }

/*            Evaluate OR operation*/

            else if (str.charAt(k) == '|')
            {
                if (isTrue == 1)
                {
                    temp_ans = temp_ans
                               + leftTrue * rightTrue
                               + leftTrue * rightFalse
                               + leftFalse * rightTrue;
                }
                else
                {
                    temp_ans
                        = temp_ans + leftFalse * rightFalse;
                }
            }

/*            Evaluate XOR operation*/

            else if (str.charAt(k) == '^')
            {
                if (isTrue == 1)
                {
                    temp_ans = temp_ans
                               + leftTrue * rightFalse
                               + leftFalse * rightTrue;
                }
                else
                {
                    temp_ans = temp_ans
                               + leftTrue * rightTrue
                               + leftFalse * rightFalse;
                }
            }
            dp[i][j][isTrue] = temp_ans;
        }
        return temp_ans;
    }

/*  Driver code*/

    public static void main(String[] args)
    {
        String symbols = "TTFT";
        String operators = "|&^";
        StringBuilder S = new StringBuilder();
        int j = 0;
        for (int i = 0; i < symbols.length(); i++)
        {
            S.append(symbols.charAt(i));
            if (j < operators.length())
                S.append(operators.charAt(j++));
        }

/*        We obtain the string  T|T&F^T*/

        int N = S.length();

/*        There are 4 ways
        ((T|T)&(F^T)), (T|(T&(F^T))), (((T|T)&F)^T) and
        (T|((T&F)^T))*/

        System.out.println(countWays(N, S.toString()));
    }
}

/*A Dynamic Programming based Java program to
count number of possible numbers of given length*/

class GFG
{

/*Return count of all possible numbers of length n
in a given numeric keyboard*/

static int getCount(char keypad[][], int n)
{
    if(keypad == null || n <= 0)
        return 0;
    if(n == 1)
        return 10;

/*    left, up, right, down move from current location*/

    int row[] = {0, 0, -1, 0, 1};
    int col[] = {0, -1, 0, 1, 0};

/*    taking n+1 for simplicity - count[i][j] will store
    number count starting with digit i and length j*/

    int [][]count = new int[10][n + 1];
    int i = 0, j = 0, k = 0, move = 0,
             ro = 0, co = 0, num = 0;
    int nextNum = 0, totalCount = 0;

/*    count numbers starting with digit i
    and of lengths 0 and 1*/

    for (i = 0; i <= 9; i++)
    {
        count[i][0] = 0;
        count[i][1] = 1;
    }

/*    Bottom up - Get number count of length 2, 3, 4, ... , n*/

    for (k = 2; k <= n; k++)
    {

/*Loop on keypad row*/

for (i = 0; i < 4; i++) 
        {

/*Loop on keypad column*/

for (j = 0; j < 3; j++) 
            {

/*                Process for 0 to 9 digits*/

                if (keypad[i][j] != '*' &&
                    keypad[i][j] != '#')
                {

/*                    Here we are counting the numbers starting with
                    digit keypad[i][j] and of length k keypad[i][j]
                    will become 1st digit, and we need to look for
                    (k-1) more digits*/

                    num = keypad[i][j] - '0';
                    count[num][k] = 0;

/*                    move left, up, right, down from current location
                    and if new location is valid, then get number
                    count of length (k-1) from that new digit and
                    add in count we found so far*/

                    for (move = 0; move < 5; move++)
                    {
                        ro = i + row[move];
                        co = j + col[move];
                        if (ro >= 0 && ro <= 3 && co >= 0 &&
                            co <= 2 && keypad[ro][co] != '*' &&
                                       keypad[ro][co] != '#')
                        {
                            nextNum = keypad[ro][co] - '0';
                            count[num][k] += count[nextNum][k - 1];
                        }
                    }
                }
            }
        }
    }

/*    Get count of all possible numbers of length "n"
    starting with digit 0, 1, 2, ..., 9*/

    totalCount = 0;
    for (i = 0; i <= 9; i++)
        totalCount += count[i][n];
    return totalCount;
}

/*Driver Code*/

public static void main(String[] args)
{
    char keypad[][] = {{'1','2','3'},
                       {'4','5','6'},
                       {'7','8','9'},
                       {'*','0','#'}};
    System.out.printf("Count for numbers of length %d: %d\n", 1,
                                           getCount(keypad, 1));
    System.out.printf("Count for numbers of length %d: %d\n", 2,
                                           getCount(keypad, 2));
    System.out.printf("Count for numbers of length %d: %d\n", 3,
                                           getCount(keypad, 3));
    System.out.printf("Count for numbers of length %d: %d\n", 4,
                                           getCount(keypad, 4));
    System.out.printf("Count for numbers of length %d: %d\n", 5,
                                           getCount(keypad, 5));
}
}

/*A Space Optimized Java program to
count number of possible numbers
of given length*/

class GFG
{

/*Return count of all possible numbers of
length n in a given numeric keyboard*/

static int getCount(char keypad[][], int n)
{
    if(keypad == null || n <= 0)
        return 0;
    if(n == 1)
        return 10;

/*    odd[i], even[i] arrays represent count of
    numbers starting with digit i for any length j*/

    int []odd = new int[10];
    int []even = new int[10];
    int i = 0, j = 0, useOdd = 0, totalCount = 0;
    for (i = 0; i <= 9; i++)

/*for j = 1*/

odd[i] = 1;

/*    Bottom Up calculation from j = 2 to n*/

    for (j = 2; j <= n; j++)
    {
        useOdd = 1 - useOdd;

/*        Here we are explicitly writing lines
        for each number 0 to 9. But it can always be
        written as DFS on 4X3 grid using row,
        column array valid moves*/

        if(useOdd == 1)
        {
            even[0] = odd[0] + odd[8];
            even[1] = odd[1] + odd[2] + odd[4];
            even[2] = odd[2] + odd[1] +
                      odd[3] + odd[5];
            even[3] = odd[3] + odd[2] + odd[6];
            even[4] = odd[4] + odd[1] +
                      odd[5] + odd[7];
            even[5] = odd[5] + odd[2] + odd[4] +
                               odd[8] + odd[6];
            even[6] = odd[6] + odd[3] +
                      odd[5] + odd[9];
            even[7] = odd[7] + odd[4] + odd[8];
            even[8] = odd[8] + odd[0] + odd[5] +
                               odd[7] + odd[9];
            even[9] = odd[9] + odd[6] + odd[8];
        }
        else
        {
            odd[0] = even[0] + even[8];
            odd[1] = even[1] + even[2] + even[4];
            odd[2] = even[2] + even[1] +
                     even[3] + even[5];
            odd[3] = even[3] + even[2] + even[6];
            odd[4] = even[4] + even[1] +
                     even[5] + even[7];
            odd[5] = even[5] + even[2] + even[4] +
                               even[8] + even[6];
            odd[6] = even[6] + even[3] +
                     even[5] + even[9];
            odd[7] = even[7] + even[4] + even[8];
            odd[8] = even[8] + even[0] + even[5] +
                               even[7] + even[9];
            odd[9] = even[9] + even[6] + even[8];
        }
    }

/*    Get count of all possible numbers of
    length "n" starting with digit 0, 1, 2, ..., 9*/

    totalCount = 0;
    if(useOdd == 1)
    {
        for (i = 0; i <= 9; i++)
            totalCount += even[i];
    }
    else
    {
        for (i = 0; i <= 9; i++)
            totalCount += odd[i];
    }
    return totalCount;
}

/*Driver Code*/

public static void main(String[] args)
{
    char keypad[][] = {{'1','2','3'},
                       {'4','5','6'},
                       {'7','8','9'},
                       {'*','0','#'}};
    System.out.printf("Count for numbers of length %d: %d\n", 1,
                                           getCount(keypad, 1));
    System.out.printf("Count for numbers of length %d: %d\n", 2,
                                           getCount(keypad, 2));
    System.out.printf("Count for numbers of length %d: %d\n", 3,
                                           getCount(keypad, 3));
    System.out.printf("Count for numbers of length %d: %d\n", 4,
                                           getCount(keypad, 4));
    System.out.printf("Count for numbers of length %d: %d\n", 5,
                                           getCount(keypad, 5));
}
}

/*Java program to Count of n digit numbers
whose sum of digits equals to given sum*/

public class GFG {
    private static void findCount(int n, int sum) {

/*        in case n = 2 start is 10 and end is (100-1) = 99*/

        int start = (int) Math.pow(10, n-1);
        int end = (int) Math.pow(10, n)-1;
        int count = 0;
        int i = start;
                while(i < end) {
            int cur = 0;
            int temp = i;
            while( temp != 0) {
                cur += temp % 10;
                temp = temp / 10;
            }
            if(cur == sum) {            
                count++;            
                i += 9;        
            }else
                i++;
        }    
        System.out.println(count);

    }

/*Driver Code*/

    public static void main(String[] args) {
        int n = 3;
        int sum = 5;    
        findCount(n,sum);
    }
}

/*A Naive recursive JAVA program to find minimum of coins
to make a given change V*/

class coin
{

/*    m is size of coins array (number of different coins)*/

    static int minCoins(int coins[], int m, int V)
    {

/*       base case*/

       if (V == 0) return 0;

/*       Initialize result*/

       int res = Integer.MAX_VALUE;

/*       Try every coin that has smaller value than V*/

       for (int i=0; i<m; i++)
       {
         if (coins[i] <= V)
         {
             int sub_res = minCoins(coins, m, V-coins[i]);

/*             Check for INT_MAX to avoid overflow and see if
             result can minimized*/

             if (sub_res != Integer.MAX_VALUE && sub_res + 1 < res)
                res = sub_res + 1;
         }
       }
       return res;
    }

/*Driver program to test above function*/

    public static void main(String args[])
    {
       int coins[] =  {9, 6, 5, 1};
       int m = coins.length;
       int V = 11;
       System.out.println("Minimum coins required is "+ minCoins(coins, m, V) );
    }
}

/*A Dynamic Programming based Java
program to find minimum of coins
to make a given change V*/

import java.io.*;
class GFG
{

/*    m is size of coins array
    (number of different coins)*/

    static int minCoins(int coins[], int m, int V)
    {

/*        table[i] will be storing
        the minimum number of coins
        required for i value. So
        table[V] will have result*/

        int table[] = new int[V + 1];

/*        Base case (If given value V is 0)*/

        table[0] = 0;

/*        Initialize all table values as Infinite*/

        for (int i = 1; i <= V; i++)
        table[i] = Integer.MAX_VALUE;

/*        Compute minimum coins required for all
        values from 1 to V*/

        for (int i = 1; i <= V; i++)
        {

/*            Go through all coins smaller than i*/

            for (int j = 0; j < m; j++)
            if (coins[j] <= i)
            {
                int sub_res = table[i - coins[j]];
                if (sub_res != Integer.MAX_VALUE
                       && sub_res + 1 < table[i])
                       table[i] = sub_res + 1;
            }
        }
          if(table[V]==Integer.MAX_VALUE)
            return -1;
        return table[V];
    }

/*    Driver program*/

    public static void main (String[] args)
    {
        int coins[] = {9, 6, 5, 1};
        int m = coins.length;
        int V = 11;
        System.out.println ( "Minimum coins required is "
                            + minCoins(coins, m, V));
    }
}

/*Following program is a Java implementation
of Rabin Karp Algorithm given in the CLRS book*/

public class Main
{

/*    d is the number of characters in the input alphabet*/

    public final static int d = 256;

/* pat -> pattern
        txt -> text
        q -> A prime number
    */

    static void search(String pat, String txt, int q)
    {
        int M = pat.length();
        int N = txt.length();
        int i, j;

/*hash value for pattern*/

int p = 0;

/*hash value for txt*/

int t = 0; 
        int h = 1;

/*        The value of h would be "pow(d, M-1)%q"*/

        for (i = 0; i < M-1; i++)
            h = (h*d)%q;

/*        Calculate the hash value of pattern and first
        window of text*/

        for (i = 0; i < M; i++)
        {
            p = (d*p + pat.charAt(i))%q;
            t = (d*t + txt.charAt(i))%q;
        }

/*        Slide the pattern over text one by one*/

        for (i = 0; i <= N - M; i++)
        {

/*            Check the hash values of current window of text
            and pattern. If the hash values match then only
            check for characters on by one*/

            if ( p == t )
            {

/* Check for characters one by one */

                for (j = 0; j < M; j++)
                {
                    if (txt.charAt(i+j) != pat.charAt(j))
                        break;
                }

/*                if p == t and pat[0...M-1] = txt[i, i+1, ...i+M-1]*/

                if (j == M)
                    System.out.println("Pattern found at index " + i);
            }

/*            Calculate hash value for next window of text: Remove
            leading digit, add trailing digit*/

            if ( i < N-M )
            {
                t = (d*(t - txt.charAt(i)*h) + txt.charAt(i+M))%q;

/*                We might get negative value of t, converting it
                to positive*/

                if (t < 0)
                t = (t + q);
            }
        }
    }

/* Driver Code */

    public static void main(String[] args)
    {
        String txt = "GEEKS FOR GEEKS";
        String pat = "GEEK";

/*          A prime number*/

        int q = 101;

/*          Function Call*/

        search(pat, txt, q);
    }
}

/* Java program for A modified Naive Pattern Searching
algorithm that is optimized for the cases when all
characters of pattern are different */

class GFG
{

/* A modified Naive Pettern Searching
algorithn that is optimized for the
cases when all characters of pattern are different */

static void search(String pat, String txt)
{
    int M = pat.length();
    int N = txt.length();
    int i = 0;
    while (i <= N - M)
    {
        int j;

/* For current index i, check for pattern match */

        for (j = 0; j < M; j++)
            if (txt.charAt(i + j) != pat.charAt(j))
                break;

/*if pat[0...M-1] = txt[i, i+1, ...i+M-1]*/

if (j == M) 
        {
            System.out.println("Pattern found at index "+i);
            i = i + M;
        }
        else if (j == 0)
            i = i + 1;
        else

/*slide the pattern by j*/

i = i + j; 
    }
}

/* Driver code*/

public static void main (String[] args)
{
    String txt = "ABCEABCDABCEABCD";
    String pat = "ABCD";
    search(pat, txt);
}
}

/*Java program for Finite Automata Pattern
searching Algorithm*/

class GFG {
    static int NO_OF_CHARS = 256;
    static int getNextState(char[] pat, int M,  
                             int state, int x)
    {

/*        If the character c is same as next
        character in pattern,then simply 
        increment state*/

        if(state < M && x == pat[state])
            return state + 1;

/*        ns stores the result which is next state*/

        int ns, i;

/*        ns finally contains the longest prefix
        which is also suffix in "pat[0..state-1]c"
        Start from the largest possible value
        and stop when you find a prefix which
        is also suffix*/

        for (ns = state; ns > 0; ns--)
        {
            if (pat[ns-1] == x)
            {
                for (i = 0; i < ns-1; i++)
                    if (pat[i] != pat[state-ns+1+i])
                        break;
                    if (i == ns-1)
                        return ns;
            }
        }
            return 0;
    }

/* This function builds the TF table which
    represents Finite Automata for a given pattern */

    static void computeTF(char[] pat, int M, int TF[][])
    {
        int state, x;
        for (state = 0; state <= M; ++state)
            for (x = 0; x < NO_OF_CHARS; ++x)
                TF[state][x] = getNextState(pat, M, state, x);
    }

/* Prints all occurrences of pat in txt */

    static void search(char[] pat, char[] txt)
    {
        int M = pat.length;
        int N = txt.length;
        int[][] TF = new int[M+1][NO_OF_CHARS];
        computeTF(pat, M, TF);

/*        Process txt over FA.*/

        int i, state = 0;
        for (i = 0; i < N; i++)
        {
            state = TF[state][txt[i]];
            if (state == M)
                System.out.println("Pattern found "
                          + "at index " + (i-M+1));
        }
    }

/*    Driver code*/

    public static void main(String[] args) 
    {
        char[] pat = "AABAACAADAABAAABAA".toCharArray();
        char[] txt = "AABA".toCharArray();
        search(txt,pat);
    }
}

/* Java Program for Bad Character Heuristic of Boyer
Moore String Matching Algorithm */

class AWQ{
     static int NO_OF_CHARS = 256;

/*    A utility function to get maximum of two integers*/

     static int max (int a, int b) { return (a > b)? a: b; }

/*     The preprocessing function for Boyer Moore's
     bad character heuristic*/

     static void badCharHeuristic( char []str, int size,int badchar[])
     {

/*      Initialize all occurrences as -1*/

      for (int i = 0; i < NO_OF_CHARS; i++)
           badchar[i] = -1;

/*      Fill the actual value of last occurrence
      of a character (indeces of table are ascii and values are index of occurence)*/

      for (i = 0; i < size; i++)
           badchar[(int) str[i]] = i;
     }

/* A pattern searching function that uses Bad
     Character Heuristic of Boyer Moore Algorithm */

     static void search( char txt[],  char pat[])
     {
      int m = pat.length;
      int n = txt.length;
      int badchar[] = new int[NO_OF_CHARS];

/* Fill the bad character array by calling
         the preprocessing function badCharHeuristic()
         for given pattern */

      badCharHeuristic(pat, m, badchar);

/*s is shift of the pattern with respect to text*/

int s = 0;

/*there are n-m+1 potential allignments*/

      while(s <= (n - m))
      {
          int j = m-1;

/* Keep reducing index j of pattern while
             characters of pattern and text are
             matching at this shift s */

          while(j >= 0 && pat[j] == txt[s+j])
              j--;

/* If the pattern is present at current
             shift, then index j will become -1 after
             the above loop */

          if (j < 0)
          {
              System.out.println("Patterns occur at shift = " + s);

/* Shift the pattern so that the next
                 character in text aligns with the last
                 occurrence of it in pattern.
                 The condition s+m < n is necessary for
                 the case when pattern occurs at the end
                 of text txt[s+m] is character after the pattern in text*/

              s += (s+m < n)? m-badchar[txt[s+m]] : 1;
          }
          else

/* Shift the pattern so that the bad character
                 in text aligns with the last occurrence of
                 it in pattern. The max function is used to
                 make sure that we get a positive shift.
                 We may get a negative shift if the last
                 occurrence  of bad character in pattern
                 is on the right side of the current
                 character. */

              s += max(1, j - badchar[txt[s+j]]);
      }
     }

/* Driver program to test above function */

    public static void main(String []args) {
         char txt[] = "ABAAABCD".toCharArray();
         char pat[] = "ABC".toCharArray();
         search(txt, pat);
    }
}

/*Java program to implement Manacher's Algorithm */

import java.util.*;
class GFG 
{
    static void findLongestPalindromicString(String text) 
    {
        int N = text.length();
        if (N == 0)
            return;

/*Position count*/

N = 2 * N + 1;

/*LPS Length Array*/

int[] L = new int[N + 1]; 
        L[0] = 0;
        L[1] = 1;

/*centerPosition*/

int C = 1;

/*centerRightPosition*/

int R = 2;

/*currentRightPosition*/

int i = 0;

/*currentLeftPosition*/

int iMirror; 
        int maxLPSLength = 0;
        int maxLPSCenterPosition = 0;
        int start = -1;
        int end = -1;
        int diff = -1;

/*        Uncomment it to print LPS Length array
        printf("%d %d ", L[0], L[1]);*/

        for (i = 2; i < N; i++) 
        {

/*            get currentLeftPosition iMirror 
            for currentRightPosition i*/

            iMirror = 2 * C - i;
            L[i] = 0;
            diff = R - i;

/*            If currentRightPosition i is within 
            centerRightPosition R*/

            if (diff > 0)
                L[i] = Math.min(L[iMirror], diff);

/*            Attempt to expand palindrome centered at 
            currentRightPosition i. Here for odd positions, 
            we compare characters and if match then 
            increment LPS Length by ONE. If even position, 
            we just increment LPS by ONE without 
            any character comparison*/

            while (((i + L[i]) + 1 < N && (i - L[i]) > 0) && 
                               (((i + L[i] + 1) % 2 == 0) || 
                         (text.charAt((i + L[i] + 1) / 2) == 
                          text.charAt((i - L[i] - 1) / 2))))
            {
                L[i]++;
            }

/*Track maxLPSLength*/

if (L[i] > maxLPSLength) 
            {
                maxLPSLength = L[i];
                maxLPSCenterPosition = i;
            }

/*            If palindrome centered at currentRightPosition i
            expand beyond centerRightPosition R,
            adjust centerPosition C based on expanded palindrome.*/

            if (i + L[i] > R) 
            {
                C = i;
                R = i + L[i];
            }

/*            Uncomment it to print LPS Length array
            printf("%d ", L[i]);*/

        }
        start = (maxLPSCenterPosition - maxLPSLength) / 2;
        end = start + maxLPSLength - 1;
        System.out.printf("LPS of string is %s : ", text);
        for (i = start; i <= end; i++)
            System.out.print(text.charAt(i));
        System.out.println();
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        String text = "babcbabcbaccba";
        findLongestPalindromicString(text);
        text = "abaaba";
        findLongestPalindromicString(text);
        text = "abababa";
        findLongestPalindromicString(text);
        text = "abcbabcbabcba";
        findLongestPalindromicString(text);
        text = "forgeeksskeegfor";
        findLongestPalindromicString(text);
        text = "caba";
        findLongestPalindromicString(text);
        text = "abacdfgdcaba";
        findLongestPalindromicString(text);
        text = "abacdfgdcabba";
        findLongestPalindromicString(text);
        text = "abacdedcaba";
        findLongestPalindromicString(text);
    }
}

/*Java program to print permutations
of a given string with
spaces*/

import java.io.*;
class Permutation
{

/*    Function recursively prints
    the strings having space
    pattern i and j are indices in 'String str' and
    'buf[]' respectively*/

    static void printPatternUtil(String str, char buf[],
                                 int i, int j, int n)
    {
        if (i == n)
        {
            buf[j] = '\0';
            System.out.println(buf);
            return;
        }

/*        Either put the character*/

        buf[j] = str.charAt(i);
        printPatternUtil(str, buf, i + 1,
                               j + 1, n);

/*        Or put a space followed
        by next character*/

        buf[j] = ' ';
        buf[j + 1] = str.charAt(i);
        printPatternUtil(str, buf, i + 1,
                              j + 2, n);
    }

/*    Function creates buf[] to
    store individual output
    string and uses printPatternUtil()
    to print all
    permutations*/

    static void printPattern(String str)
    {
        int len = str.length();

/*        Buffer to hold the string
        containing spaces
        2n-1 characters and 1
        string terminator*/

        char[] buf = new char[2 * len];

/*        Copy the first character as it is, since it will
        be always at first position*/

        buf[0] = str.charAt(0);
        printPatternUtil(str, buf, 1, 1, len);
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        String str = "ABCD";
        printPattern(str);
    }
}

/*Java program for above approach*/

public class Suduko {

/*    N is the size of the 2D matrix   N*N*/

    static int N = 9;

/* A utility function to print grid */

    static void print(int[][] grid)
    {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++)
                System.out.print(grid[i][j] + " ");
            System.out.println();
        }
    }

/*    Check whether it will be legal
    to assign num to the
    given row, col*/

    static boolean isSafe(int[][] grid, int row, int col,
                          int num)
    {

/*        Check if we find the same num
        in the similar row , we
        return false*/

        for (int x = 0; x <= 8; x++)
            if (grid[row][x] == num)
                return false;

/*        Check if we find the same num
        in the similar column ,
        we return false*/

        for (int x = 0; x <= 8; x++)
            if (grid[x][col] == num)
                return false;

/*        Check if we find the same num
        in the particular 3*3
        matrix, we return false*/

        int startRow = row - row % 3, startCol
                                      = col - col % 3;
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (grid[i + startRow][j + startCol] == num)
                    return false;
        return true;
    }

/* Takes a partially filled-in grid and attempts
    to assign values to all unassigned locations in
    such a way to meet the requirements for
    Sudoku solution (non-duplication across rows,
    columns, and boxes) */

    static boolean solveSuduko(int grid[][], int row,
                               int col)
    {

/*if we have reached the 8th
           row and 9th column (0
           indexed matrix) ,
           we are returning true to avoid further
           backtracking       */

        if (row == N - 1 && col == N)
            return true;

/*        Check if column value  becomes 9 ,
        we move to next row
        and column start from 0*/

        if (col == N) {
            row++;
            col = 0;
        }

/*        Check if the current position
        of the grid already
        contains value >0, we iterate
        for next column*/

        if (grid[row][col] != 0)
            return solveSuduko(grid, row, col + 1);
        for (int num = 1; num < 10; num++) {

/*            Check if it is safe to place
            the num (1-9)  in the
            given row ,col ->we move to next column*/

            if (isSafe(grid, row, col, num)) {

/*  assigning the num in the current
                (row,col)  position of the grid and
                assuming our assined num in the position
                is correct */

                grid[row][col] = num;

/*                Checking for next
                possibility with next column*/

                if (solveSuduko(grid, row, col + 1))
                    return true;
            }

/* removing the assigned num , since our
               assumption was wrong , and we go for next
               assumption with diff num value   */

            grid[row][col] = 0;
        }
        return false;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int grid[][] = { { 3, 0, 6, 5, 0, 8, 4, 0, 0 },
                         { 5, 2, 0, 0, 0, 0, 0, 0, 0 },
                         { 0, 8, 7, 0, 0, 0, 0, 3, 1 },
                         { 0, 0, 3, 0, 1, 0, 0, 8, 0 },
                         { 9, 0, 0, 8, 6, 3, 0, 0, 5 },
                         { 0, 5, 0, 0, 9, 0, 6, 0, 0 },
                         { 1, 3, 0, 0, 0, 0, 2, 5, 0 },
                         { 0, 0, 0, 0, 0, 0, 0, 7, 4 },
                         { 0, 0, 5, 2, 0, 6, 3, 0, 0 } };
        if (solveSuduko(grid, 0, 0))
            print(grid);
        else
            System.out.println("No Solution exists");
    }

}

/* Java code for extended version of power function
that can work for float x and negative y */

class GFG {
    static float power(float x, int y)
    {
        float temp;
        if( y == 0)
            return 1;
        temp = power(x, y/2);
        if (y%2 == 0)
            return temp*temp;
        else
        {
            if(y > 0)
                return x * temp * temp;
            else
                return (temp * temp) / x;
        }
    }

/* Program to test function power */

    public static void main(String[] args)
    {
        float x = 2;
        int y = -3;
        System.out.printf("%f", power(x, y));
    }
}

/*A Simple Merge based O(n) solution
to find median of two sorted arrays*/

class Main
{

/*    function to calculate median*/

    static int getMedian(int ar1[], int ar2[], int n)
    {  
        int i = 0; 
        int j = 0;
        int count;
        int m1 = -1, m2 = -1;

/* Since there are 2n elements, median will
           be average of elements at index n-1 and
           n in the array obtained after merging ar1
           and ar2 */

        for (count = 0; count <= n; count++)
        {

/* Below is to handle case where all
              elements of ar1[] are smaller than
              smallest(or first) element of ar2[] */

            if (i == n)
            {
                m1 = m2;
                m2 = ar2[0];
                break;
            }

/* Below is to handle case where all
               elements of ar2[] are smaller than
               smallest(or first) element of ar1[] */

            else if (j == n)
            {
                m1 = m2;
                m2 = ar1[0];
                break;
            }

/* equals sign because if two
               arrays have some common elements */

            if (ar1[i] <= ar2[j])
            {

/* Store the prev median */

                m1 = m2; 
                m2 = ar1[i];
                i++;
            }
            else
            {

/* Store the prev median */

                m1 = m2; 
                m2 = ar2[j];
                j++;
            }
        }
        return (m1 + m2)/2;
    }

/* Driver program to test above function */

    public static void main (String[] args)
    {
        int ar1[] = {1, 12, 15, 26, 38};
        int ar2[] = {2, 13, 17, 30, 45};
        int n1 = ar1.length;
        int n2 = ar2.length;
        if (n1 == n2)
            System.out.println("Median is " +
                        getMedian(ar1, ar2, n1));
        else
            System.out.println("arrays are of unequal size");
    }   
}

/*A Java program to divide and conquer based
efficient solution to find
median of two sorted arrays
of same size.*/

import java.util.*;
class GfG {

/* This function returns median
    of ar1[] and ar2[].
    Assumptions in this function:
        Both ar1[] and ar2[] are
        sorted arrays
        Both have n elements */

    static int getMedian(
        int[] a, int[] b, int startA,
        int startB, int endA, int endB)
    {
        if (endA - startA == 1) {
            return (
                       Math.max(a[startA],
                                b[startB])
                       + Math.min(a[endA], b[endB]))
                / 2;
        }

/* get the median of
    the first array */

        int m1 = median(a, startA, endA);

/* get the median of
    the second array */

        int m2 = median(b, startB, endB);

/* If medians are equal then
    return either m1 or m2 */

        if (m1 == m2) {
            return m1;
        }

/* if m1 < m2 then median must
    exist in ar1[m1....] and
                ar2[....m2] */

        else if (m1 < m2) {
            return getMedian(
                a, b, (endA + startA + 1) / 2,
                startB, endA,
                (endB + startB + 1) / 2);
        }

/* if m1 > m2 then median must
    exist in ar1[....m1] and
    ar2[m2...] */

        else {
            return getMedian(
                a, b, startA,
                (endB + startB + 1) / 2,
                (endA + startA + 1) / 2, endB);
        }
    }

/* Function to get median
    of a sorted array */

    static int median(
        int[] arr, int start, int end)
    {
        int n = end - start + 1;
        if (n % 2 == 0) {
            return (
                       arr[start + (n / 2)]
                       + arr[start + (n / 2 - 1)])
                / 2;
        }
        else {
            return arr[start + n / 2];
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int ar1[] = { 1, 2, 3, 6 };
        int ar2[] = { 4, 6, 8, 10 };
        int n1 = ar1.length;
        int n2 = ar2.length;
        if (n1 != n2) {
            System.out.println(
                "Doesn't work for arrays "
                + "of unequal size");
        }
        else if (n1 == 0) {
            System.out.println("Arrays are empty.");
        }
        else if (n1 == 1) {
            System.out.println((ar1[0] + ar2[0]) / 2);
        }
        else {
            System.out.println(
                "Median is "
                + getMedian(
                      ar1, ar2, 0, 0,
                      ar1.length - 1, ar2.length - 1));
        }
    }
}

/*Java program to print all
primes smaller than or equal to
n using Sieve of Eratosthenes*/

class SieveOfEratosthenes {
    void sieveOfEratosthenes(int n)
    {

/*        Create a boolean array
        "prime[0..n]" and
        initialize all entries
        it as true. A value in
        prime[i] will finally be
        false if i is Not a
        prime, else true.*/

        boolean prime[] = new boolean[n + 1];
        for (int i = 0; i <= n; i++)
            prime[i] = true;
        for (int p = 2; p * p <= n; p++)
        {

/*            If prime[p] is not changed, then it is a
            prime*/

            if (prime[p] == true)
            {

/*                Update all multiples of p*/

                for (int i = p * p; i <= n; i += p)
                    prime[i] = false;
            }
        }

/*        Print all prime numbers*/

        for (int i = 2; i <= n; i++)
        {
            if (prime[i] == true)
                System.out.print(i + " ");
        }
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int n = 30;
        System.out.print(
            "Following are the prime numbers ");
        System.out.println("smaller than or equal to " + n);
        SieveOfEratosthenes g = new SieveOfEratosthenes();
        g.sieveOfEratosthenes(n);
    }
}

/*Java program to print the
Number which has the maximum
number of distinct prime
factors of numbers in range
m to n*/

import java.io.*;
class GFG
{

/*Function to return
the maximum number*/

static int maximumNumberDistinctPrimeRange(int m,
                                           int n)
{

/*    array to store the
    number of distinct primes*/

    long factorCount[] = new long[n + 1];

/*    true if index 'i'
    is a prime*/

    boolean prime[] = new boolean[n + 1];

/*    initializing the number
    of factors to 0 and*/

    for (int i = 0; i <= n; i++)
    {
        factorCount[i] = 0;

/*Used in Sieve*/

prime[i] = true; 
    }
    for (int i = 2; i <= n; i++)
    {

/*        condition works only when
        'i' is prime, hence for
        factors of all prime number,
        the prime status is changed to false*/

        if (prime[i] == true)
        {

/*            Number is prime*/

            factorCount[i] = 1;

/*            number of factor of
            a prime number is 1*/

            for (int j = i * 2; j <= n; j += i)
            {

/*                incrementing factorCount
                all the factors of i*/

                factorCount[j]++;

/*                and changing prime
                status to false*/

                prime[j] = false;
            }
        }
    }

/*    Initialize the max and num*/

    int max = (int)factorCount[m];
    int num = m;

/*    Gets the maximum number*/

    for (int i = m; i <= n; i++)
    {

/*        Gets the maximum number*/

        if (factorCount[i] > max)
        {
            max = (int)factorCount[i];
            num = i;
        }
    }
    return num;
}

/*Driver code*/

public static void main (String[] args)
{
int m = 4, n = 6;

/*Calling function*/

System.out.println(maximumNumberDistinctPrimeRange(m, n));
}
}

/* Sample run of the Algo for V1 with capacity 3 and V2 with capacity 7
1. Fill V1:                             V1 = 3, V2 = 0
2. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 3
2. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 6
3. Transfer from V1 to V2, and empty V2: V1 = 2, V2 = 0
4. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 2
5. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 5
6. Transfer from V1 to V2, and empty V2: V1 = 1, V2 = 0
7. Stop as V1 now contains 1 litre.
Note that V2 was made empty in steps 3 and 6 because it became full */

class GFG
{

/*    A utility function to get GCD of two numbers*/

    static int gcd(int a, int b) 
    {
        return b > 0 ? gcd(b, a % b) : a;
    }

/*    Class to represent a Vessel*/

    static class Vessel 
    {

/*        A vessel has capacity, and 
        current amount of water in it*/

        int capacity, current;

/*        Constructor: initializes capacity
        as given, and current as 0*/

        public Vessel(int capacity)
        {
            this.capacity = capacity;
            current = 0;
        }

/*        The main function to fill one litre 
        in this vessel. Capacity of V2 must be
        greater than this vessel and two capacities
        must be coprime*/

        void makeOneLitre(Vessel V2)
        {

/*            solution exists iff a and b are co-prime*/

            if (gcd(capacity, V2.capacity) != 1)
                return;
            while (current != 1)
            {

/*                fill A (smaller vessel)*/

                if (current == 0)
                    current = capacity;
                System.out.print("Vessel 1: " + current + 
                            " Vessel 2: " + V2.current + "\n");

/*                Transfer water from V1 to V2 and 
                reduce current of V1 by
                the amount equal to transferred water*/

                current = current - V2.transfer(current);
            }

/*            Finally, there will be 1 litre in vessel 1*/

            System.out.print("Vessel 1: " + current + 
                        " Vessel 2: " + V2.current + "\n");
        }

/*        Fills vessel with given amount and 
        returns the amount of water
        transferred to it. If the vessel 
        becomes full, then the vessel
        is made empty*/

        int transfer(int amount)
        {

/*            If the vessel can accommodate the given amount*/

            if (current + amount < capacity) 
            {
                current += amount;
                return amount;
            }

/*            If the vessel cannot accommodate
            the given amount, then store
            the amount of water transferred*/

            int transferred = capacity - current;

/*            Since the vessel becomes full, make the vessel
            empty so that it can be filled again*/

            current = 0;
            return transferred;
        }
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {

/*a must be smaller than b*/

int a = 3, b = 7;

/*        Create two vessels of capacities a and b*/

        Vessel V1 = new Vessel(a);
        Vessel V2 = new Vessel(b);

/*        Get 1 litre in first vessel*/

        V1.makeOneLitre(V2);
    }
}

/*Java program to print all combination of size r in an array of size n*/

import java.io.*;
class Combination {

/*    The main function that prints all combinations of size r
    in arr[] of size n. This function mainly uses combinationUtil()*/

    static void printCombination(int arr[], int n, int r)
    {

/*        A temporary array to store all combination one by one*/

        int data[]=new int[r];

/*        Print all combination using temprary array 'data[]'*/

        combinationUtil(arr, data, 0, n-1, 0, r);
    }

/* arr[]  ---> Input Array
    data[] ---> Temporary array to store current combination
    start & end ---> Staring and Ending indexes in arr[]
    index  ---> Current index in data[]
    r ---> Size of a combination to be printed */

    static void combinationUtil(int arr[], int data[], int start,
                                int end, int index, int r)
    {

/*        Current combination is ready to be printed, print it*/

        if (index == r)
        {
            for (int j=0; j<r; j++)
                System.out.print(data[j]+" ");
            System.out.println("");
            return;
        }

/*        replace index with all possible elements. The condition
        "end-i+1 >= r-index" makes sure that including one element
        at index will make a combination with remaining elements
        at remaining positions*/

        for (int i=start; i<=end && end-i+1 >= r-index; i++)
        {
            data[index] = arr[i];
            combinationUtil(arr, data, i+1, end, index+1, r);
        }
    }

/*Driver function to check for above function*/

    public static void main (String[] args) {
        int arr[] = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.length;
        printCombination(arr, n, r);
    }
}

/*Java program to print all combination of size r in an array of size n*/

import java.io.*;
class Combination {

/*    The main function that prints all combinations of size r
    in arr[] of size n. This function mainly uses combinationUtil()*/

    static void printCombination(int arr[], int n, int r)
    {

/*        A temporary array to store all combination one by one*/

        int data[]=new int[r];

/*        Print all combination using temprary array 'data[]'*/

        combinationUtil(arr, n, r, 0, data, 0);
    }

/* arr[]  ---> Input Array
    data[] ---> Temporary array to store current combination
    start & end ---> Staring and Ending indexes in arr[]
    index  ---> Current index in data[]
    r ---> Size of a combination to be printed */

    static void combinationUtil(int arr[], int n, int r, int index,
                                int data[], int i)
    {

/*        Current combination is ready to be printed, print it*/

        if (index == r)
        {
            for (int j=0; j<r; j++)
                System.out.print(data[j]+" ");
            System.out.println("");
        return;
        }

/*        When no more elements are there to put in data[]*/

        if (i >= n)
        return;

/*        current is included, put next at next location*/

        data[index] = arr[i];
        combinationUtil(arr, n, r, index+1, data, i+1);

/*        current is excluded, replace it with next (Note that
        i+1 is passed, but index is not changed)*/

        combinationUtil(arr, n, r, index, data, i+1);
    }

/*Driver function to check for above function*/

    public static void main (String[] args) {
        int arr[] = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.length;
        printCombination(arr, n, r);
    }
}

class CatalnNumber {

/*    A recursive function to find nth catalan number*/

    int catalan(int n)
    {

/*        Base case*/

        if (n <= 1)
        {
            return 1;
        }

/*    catalan(n) is sum of
    catalan(i)*catalan(n-i-1)*/

        int res = 0;
        for (int i = 0; i < n; i++)
        {
            res += catalan(i)
                * catalan(n - i - 1);
        }
        return res;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        CatalnNumber cn = new CatalnNumber();
        for (int i = 0; i < 10; i++)
        {
            System.out.print(cn.catalan(i) + " ");
        }
    }
}

/*Java program for nth Catalan Number*/

class GFG {

/*    Returns value of Binomial Coefficient C(n, k)*/

    static long binomialCoeff(int n, int k)
    {
        long res = 1;

/*        Since C(n, k) = C(n, n-k)*/

        if (k > n - k) {
            k = n - k;
        }

/*        Calculate value of [n*(n-1)*---*(n-k+1)] /
        [k*(k-1)*---*1]*/

        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    A Binomial coefficient based function
      to find nth catalan number in O(n) time*/

    static long catalan(int n)
    {

/*        Calculate value of 2nCn*/

        long c = binomialCoeff(2 * n, n);

/*        return 2nCn/(n+1)*/

        return c / (n + 1);
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        for (int i = 0; i < 10; i++) {
            System.out.print(catalan(i) + " ");
        }
    }
}

/*Java program to find Excel
column name from a given
column number*/

public class ExcelColumnTitle {

/*    Function to print Excel column
    name for a given column number*/

    private static void printString(int columnNumber)
    {

/*        To store result (Excel column name)*/

        StringBuilder columnName = new StringBuilder();
        while (columnNumber > 0) {

/*            Find remainder*/

            int rem = columnNumber % 26;

/*            If remainder is 0, then a
            'Z' must be there in output*/

            if (rem == 0) {
                columnName.append("Z");
                columnNumber = (columnNumber / 26) - 1;
            }

/*If remainder is non-zero*/

else 
            {
                columnName.append((char)((rem - 1) + 'A'));
                columnNumber = columnNumber / 26;
            }
        }

/*        Reverse the string and print result*/

        System.out.println(columnName.reverse());
    }

/*    Driver program to test above function*/

    public static void main(String[] args)
    {
        printString(26);
        printString(51);
        printString(52);
        printString(80);
        printString(676);
        printString(702);
        printString(705);
    }
}

import java.util.*;
class GFG{
static void printString(int n)
{
    int []arr = new int[10000];
    int i = 0;

/*    Step 1: Converting to number
    assuming 0 in number system*/

    while (n > 0)
    {
        arr[i] = n % 26;
        n = n / 26;
        i++;
    }

/*    Step 2: Getting rid of 0, as 0 is
    not part of number system*/

    for(int j = 0; j < i - 1; j++)
    {
        if (arr[j] <= 0)
        {
            arr[j] += 26;
            arr[j + 1] = arr[j + 1] - 1;
        }
    }
    for(int j = i; j >= 0; j--)
    {
        if (arr[j] > 0)
            System.out.print(
                (char)('A' + arr[j] - 1));
    }
    System.out.println();
}

/*Driver code*/

public static void main(String[] args)
{
    printString(26);
    printString(51);
    printString(52);
    printString(80);
    printString(676);
    printString(702);
    printString(705);
}
}

/*Java program to find angle between hour and minute hands*/

import java.io.*;
class GFG
{

/*    Function to calculate the angle*/

    static int calcAngle(double h, double m)
    {

/*        validate the input*/

        if (h <0 || m < 0 || h >12 || m > 60)
            System.out.println("Wrong input");
        if (h == 12)
            h = 0;
             if (m == 60)
       {
        m = 0;
        h += 1;
        if(h>12)
          h = h-12;
        }

/*        Calculate the angles moved by hour and minute hands
        with reference to 12:00*/

        int hour_angle = (int)(0.5 * (h*60 + m));
        int minute_angle = (int)(6*m);

/*        Find the difference between two angles*/

        int angle = Math.abs(hour_angle - minute_angle);

/*        smaller angle of two possible angles*/

        angle = Math.min(360-angle, angle);
        return angle;
    }

/*    Driver Code*/

    public static void main (String[] args)
    {
        System.out.println(calcAngle(9, 60)+" degree");
        System.out.println(calcAngle(3, 30)+" degree");
    }
}

public class GFG {
    static int countSetBits(int n)
    {
        int i = 0;

/*        ans store sum of set bits from 0 to n*/

        int ans = 0;

/*        while n greater than equal to 2^i*/

        while ((1 << i) <= n) {

/*            This k will get flipped after
            2^i iterations*/

            boolean k = false;

/*            change is iterator from 2^i to 1*/

            int change = 1 << i;

/*            This will loop from 0 to n for
            every bit position*/

            for (int j = 0; j <= n; j++) {
                if (k == true)
                    ans += 1;
                else
                    ans += 0;
                if (change == 1) {

/*                    When change = 1 flip the bit*/

                    k = !k;

/*                    again set change to 2^i*/

                    change = 1 << i;
                }
                else {
                    change--;
                }
            }

/*            increment the position*/

            i++;
        }
        return ans;
    }

/*    Driver program*/

    public static void main(String[] args)
    {
        int n = 17;
        System.out.println(countSetBits(n));
    }
}

class GFG
{
    static int swapBits(int num, int p1, int p2, int n)
    {
        int shift1, shift2, value1, value2;
        while (n-- > 0)
        {

/*            Setting bit at p1 position to 1*/

            shift1 = 1 << p1;

/*            Setting bit at p2 position to 1*/

            shift2 = 1 << p2;

/*            value1 and value2 will have 0 if num
            at the respective positions - p1 and p2 is 0.*/

            value1 = ((num & shift1));
            value2 = ((num & shift2));

/*            check if value1 and value2 are different
            i.e. at one position bit is set and other it is not*/

            if ((value1 == 0 && value2 != 0) ||
                (value2 == 0 && value1 != 0))
            {

/*                if bit at p1 position is set*/

                if (value1 != 0)
                {

/*                    unset bit at p1 position*/

                    num = num & (~shift1);

/*                    set bit at p2 position*/

                    num = num | shift2;
                }

/*                if bit at p2 position is set*/

                else
                {

/*                    set bit at p2 position*/

                    num = num & (~shift2);

/*                    unset bit at p2 position*/

                    num = num | shift1;
                }
            }
            p1++;
            p2++;
        }

/*        return final result*/

        return num;
    }

/*  Driver code*/

  public static void main(String[] args)
  {
    int res = swapBits(28, 0, 3, 2);
    System.out.println("Result = " + res);
  }
}

/*Java Implementation on above approach*/

class GFG
{

/*this function returns next higher
number with same number of set bits as x.*/

static int snoob(int x)
{
int rightOne, nextHigherOneBit, rightOnesPattern, next = 0;
if(x > 0)
{

/*    right most set bit*/

    rightOne = x & -x;

/*    reset the pattern and set next higher bit
    left part of x will be here*/

    nextHigherOneBit = x + rightOne;

/*    nextHigherOneBit is now part [D] of the above explanation.
    isolate the pattern*/

    rightOnesPattern = x ^ nextHigherOneBit;

/*    right adjust pattern*/

    rightOnesPattern = (rightOnesPattern)/rightOne;

/*    correction factor*/

    rightOnesPattern >>= 2;

/*    rightOnesPattern is now part [A] of the above explanation.
    integrate new pattern (Add [D] and [A])*/

    next = nextHigherOneBit | rightOnesPattern;
}
return next;
}

/*Driver code*/

public static void main (String[] args)
{
    int x = 156;
    System.out.println("Next higher number with same" +
                    "number of set bits is "+snoob(x));
}
}

/*Java program to check
if given number is
power of 4 or not*/

import java.io.*;
class GFG
{

/*Function to check if x is power of 4*/

    static int isPowerOfFour(int n)
    {
        int count = 0;

/*Check if there is
        only one bit set in n*/

        int x = n & (n - 1);
        if ( n > 0 && x == 0)
        {

/* count 0 bits
            before set bit */

            while(n > 1)
            {
                n >>= 1;
                count += 1;
            }

/*If count is even
            then return true
            else false*/

            return (count % 2 == 0) ? 1 : 0;
        }

/* If there are more than
            1 bit set then n is not a
            power of 4*/

        return 0;
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int test_no = 64;
        if(isPowerOfFour(test_no)>0)
            System.out.println(test_no +
                               " is a power of 4");
        else
            System.out.println(test_no +
                               " is not a power of 4");
    }
}

/*Java Program for above approach*/

public class UniqueNumbers {

/*    This function sets the values of
    *x and *y to non-repeating elements
    in an array arr[] of size n*/

    public static void UniqueNumbers2(int[] arr,int n)
    {
        int sum =0;
        for(int i = 0;i<n;i++)
        {

/*            Xor  all the elements of the array
            all the elements occuring twice will
            cancel out each other remaining
            two unnique numbers will be xored*/

            sum = (sum^arr[i]);
        }

/*        Bitwise & the sum with it's 2's Complement
        Bitwise & will give us the sum containing
        only the rightmost set bit*/

        sum = (sum&-sum);

/*        sum1 and sum2 will contains 2 unique
        elements elements initialized with 0 box
        number xored with 0 is number itself*/

        int sum1 = 0;
        int sum2 = 0;

/*        traversing the array again*/

        for(int i = 0;i<arr.length;i++)
        {

/*            Bitwise & the arr[i] with the sum
            Two possibilities either result == 0
            or result > 0*/

            if((arr[i]&sum) > 0)
            {

/*                if result > 0 then arr[i] xored
                with the sum1*/

                sum1 = (sum1^arr[i]);
            }
            else
            {

/*                if result == 0 then arr[i]
                xored with sum2*/

                sum2 = (sum2^arr[i]);
            }
        }

/*        print the the two unique numbers*/

        System.out.println("The non-repeating elements are "+
                                          sum1+" and "+sum2);
    }

/*Driver Code*/

    public static void main(String[] args)
    {
        int[] arr = new int[]{2, 3, 7, 9, 11, 2, 3, 11};
        int n = arr.length;
        UniqueNumbers2(arr,n);
    }
}

