        System.out.println(findDisappearedNumbers(a));
    }
}

/*Java program to count 1's in a sorted array*/

class CountOnes
{

/* Returns counts of 1's in arr[low..high].  The
       array is assumed to be sorted in non-increasing
       order */

    int countOnes(int arr[], int low, int high)
    {
        if (high >= low)
        {

/*            get the middle index*/

            int mid = low + (high - low) / 2;

/*            check if the element at middle index is last
            1*/

            if ((mid == high || arr[mid + 1] == 0)
                && (arr[mid] == 1))
                return mid + 1;

/*            If element is not last 1, recur for right
            side*/

            if (arr[mid] == 1)
                return countOnes(arr, (mid + 1), high);

/*            else recur for left side*/

            return countOnes(arr, low, (mid - 1));
        }
        return 0;
    }

/* Driver code */

    public static void main(String args[])
    {
        CountOnes ob = new CountOnes();
        int arr[] = { 1, 1, 1, 1, 0, 0, 0 };
        int n = arr.length;
        System.out.println("Count of 1's in given array is "
                           + ob.countOnes(arr, 0, n - 1));
    }
}

/*Java program to find missing element
from one array such that it has all
elements of other array except one.
Elements in two arrays can be in any order.*/


import java.io.*;
class Missing {

/*    This function mainly does XOR of
    all elements of arr1[] and arr2[]*/

    void findMissing(int arr1[], int arr2[],
                              int M, int N)
    {
        if (M != N - 1 && N != M - 1) {
        System.out.println("Invalid Input");
            return;
        }

/*        Do XOR of all element*/

        int res = 0;
        for (int i = 0; i < M; i++)
            res = res ^ arr1[i];
        for (int i = 0; i < N; i++)
            res = res ^ arr2[i];

        System.out.println("Missing element is "
                                          + res);
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        Missing obj = new Missing();
        int arr1[] = { 4, 1, 5, 9, 7 };
        int arr2[] = { 7, 5, 9, 4 };
        int M = arr1.length;
        int N = arr2.length;
        obj.findMissing(arr1, arr2, M, N);
    }
}

