/*Java program to find a pair with the given difference*/

import java.io.*;

class PairDifference
{

/*    The function assumes that the array is sorted*/

    static boolean findPair(int arr[],int n)
    {
        int size = arr.length;

/*        Initialize positions of two elements*/

        int i = 0, j = 1;

/*        Search for a pair*/

        while (i < size && j < size)
        {
            if (i != j && arr[j]-arr[i] == n)
            {
                System.out.print("Pair Found: "+
                                 "( "+arr[i]+", "+ arr[j]+" )");
                return true;
            }
            else if (arr[j] - arr[i] < n)
                j++;
            else
                i++;
        }

        System.out.print("No such pair");
        return false;
    }

/*    Driver program to test above function*/

    public static void main (String[] args)
    {
        int arr[] = {1, 8, 30, 40, 100};
        int n = 60;
        findPair(arr,n);
    }
}

/*A hashing based Java program to find
if there are four elements with given sum.*/

import java.util.HashMap;
class GFG {
    static class pair {
        int first, second;
        public pair(int first, int second)
        {
            this.first = first;
            this.second = second;
        }
    }

/*    The function finds four elements
    with given sum X*/

    static void findFourElements(int arr[], int n, int X)
    {

/*        Store sums of all pairs in a hash table*/

        HashMap<Integer, pair> mp
            = new HashMap<Integer, pair>();
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n; j++)
                mp.put(arr[i] + arr[j], new pair(i, j));

/*        Traverse through all pairs and search
        for X - (current pair sum).*/

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int sum = arr[i] + arr[j];

/*                If X - sum is present in hash table,*/

                if (mp.containsKey(X - sum)) {

/*                    Making sure that all elements are
                    distinct array elements and an
                    element is not considered more than
                    once.*/

                    pair p = mp.get(X - sum);
                    if (p.first != i && p.first != j
                        && p.second != i && p.second != j) {
                        System.out.print(
                            arr[i] + ", " + arr[j] + ", "
                            + arr[p.first] + ", "
                            + arr[p.second]);
                        return;
                    }
                }
            }
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        int arr[] = { 10, 20, 30, 40, 1, 2 };
        int n = arr.length;
        int X = 91;

/*        Function call*/

        findFourElements(arr, n, X);
    }
}

/*Java program to find four
elements with the given sum*/

import java.util.*;

class fourElementWithSum {

/*    Function to find 4 elements that add up to
    given sum*/

    public static void fourSum(int X, int[] arr,
                               Map<Integer, pair> map)
    {
        int[] temp = new int[arr.length];

/*        Iterate from 0 to temp.length*/

        for (int i = 0; i < temp.length; i++)
            temp[i] = 0;

/*        Iterate from 0 to arr.length*/

        for (int i = 0; i < arr.length - 1; i++) {

/*            Iterate from i + 1 to arr.length*/

            for (int j = i + 1; j < arr.length; j++) {

/*                Store curr_sum = arr[i] + arr[j]*/

                int curr_sum = arr[i] + arr[j];

/*                Check if X - curr_sum if present
                in map*/

                if (map.containsKey(X - curr_sum)) {

/*                    Store pair having map value
                    X - curr_sum*/

                    pair p = map.get(X - curr_sum);

                    if (p.first != i && p.sec != i
                        && p.first != j && p.sec != j
                        && temp[p.first] == 0
                        && temp[p.sec] == 0 && temp[i] == 0
                        && temp[j] == 0) {

/*                        Print the output*/

                        System.out.printf(
                            "%d,%d,%d,%d", arr[i], arr[j],
                            arr[p.first], arr[p.sec]);
                        temp[p.sec] = 1;
                        temp[i] = 1;
                        temp[j] = 1;
                        break;
                    }
                }
            }
        }
    }

/*    Program for two Sum*/

    public static Map<Integer, pair> twoSum(int[] nums)
    {
        Map<Integer, pair> map = new HashMap<>();
        for (int i = 0; i < nums.length - 1; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                map.put(nums[i] + nums[j], new pair(i, j));
            }
        }
        return map;
    }

/*    to store indices of two sum pair*/

    public static class pair {
        int first, sec;

        public pair(int first, int sec)
        {
            this.first = first;
            this.sec = sec;
        }
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int[] arr = { 10, 20, 30, 40, 1, 2 };
        int n = arr.length;
        int X = 91;
        Map<Integer, pair> map = twoSum(arr);

/*        Function call*/

        fourSum(X, arr, map);
    }
}

/*Java program to find third
Largest element in an array
of distinct elements*/


class GFG
{
static void thirdLargest(int arr[],
                         int arr_size)
{

/* There should be
    atleast three elements */

    if (arr_size < 3)
    {
        System.out.printf(" Invalid Input ");
        return;
    }

/*    Find first
    largest element*/

    int first = arr[0];
    for (int i = 1;
             i < arr_size ; i++)
        if (arr[i] > first)
            first = arr[i];

/*    Find second
    largest element*/

    int second = Integer.MIN_VALUE;
    for (int i = 0;
             i < arr_size ; i++)
        if (arr[i] > second &&
            arr[i] < first)
            second = arr[i];

/*    Find third
    largest element*/

    int third = Integer.MIN_VALUE;
    for (int i = 0;
             i < arr_size ; i++)
        if (arr[i] > third &&
            arr[i] < second)
            third = arr[i];

    System.out.printf("The third Largest " +
                  "element is %d\n", third);
}

/*Driver code*/

public static void main(String []args)
{
    int arr[] = {12, 13, 1,
                 10, 34, 16};
    int n = arr.length;
    thirdLargest(arr, n);
}
}

/*Java program to find third Largest element in an array*/

class GFG {

    static void thirdLargest(int arr[], int arr_size) {

/* There should be atleast three elements */

        if (arr_size < 3) {
            System.out.printf(" Invalid Input ");
            return;
        }

/*        Initialize first, second and third Largest element*/

        int first = arr[0], second = Integer.MIN_VALUE,
                            third = Integer.MIN_VALUE;

/*        Traverse array elements to find the third Largest*/

        for (int i = 1; i < arr_size; i++) {

/* If current element is greater than first,
        then update first, second and third */

            if (arr[i] > first) {
                third = second;
                second = first;
                first = arr[i];
            }

/* If arr[i] is in between first and second */

            else if (arr[i] > second) {
                third = second;
                second = arr[i];
            }

/* If arr[i] is in between second and third */

            else if (arr[i] > third) {
                third = arr[i];
            }
        }

        System.out.printf("The third Largest element is %d\n", third);
    }

/* Driver program to test above function */

    public static void main(String []args) {
        int arr[] = {12, 13, 1, 10, 34, 16};
        int n = arr.length;
        thirdLargest(arr, n);
    }
}

/*Java program to find whether two elements exist
whose sum is equal to sum of rest of the elements.*/

import java.util.*;

class GFG
{

/*    Function to check whether two elements exist
    whose sum is equal to sum of rest of the elements.*/

    static boolean checkPair(int arr[], int n)
    {

/*        Find sum of whole array*/

        int sum = 0;
        for (int i = 0; i < n; i++)
        {
            sum += arr[i];
        }

/*        If sum of array is not even than we can not
        divide it into two part*/

        if (sum % 2 != 0)
        {
            return false;
        }

        sum = sum / 2;

/*        For each element arr[i], see if there is
        another element with vaalue sum - arr[i]*/

        HashSet<Integer> s = new HashSet<Integer>();
        for (int i = 0; i < n; i++)
        {
            int val = sum - arr[i];

/*            If element exist than return the pair*/

            if (s.contains(val) &&
                val == (int) s.toArray()[s.size() - 1])
            {
                System.out.printf("Pair elements are %d and %d\n",
                        arr[i], val);
                return true;
            }
            s.add(arr[i]);
        }
        return false;
    }

/*    Driver program.*/

    public static void main(String[] args)
    {
        int arr[] = {2, 11, 5, 1, 4, 7};
        int n = arr.length;
        if (checkPair(arr, n) == false)
        {
            System.out.printf("No pair found");
        }
    }
}

/*Java implementation to search an element in
the unsorted array using minimum number of
comparisons*/

import java.io.*;

class GFG {

/*    Function to search an element in
    minimum number of comparisons*/

    static String search(int arr[], int n, int x)
    {

/*        1st comparison*/

        if (arr[n - 1] == x)
            return "Found";

        int backup = arr[n - 1];
        arr[n - 1] = x;

/*        no termination condition and thus
        no comparison*/

        for (int i = 0;; i++) {

/*            this would be executed at-most n times
            and therefore at-most n comparisons*/

            if (arr[i] == x) {

/*                replace arr[n-1] with its actual element
                as in original 'arr[]'*/

                arr[n - 1] = backup;

/*                if 'x' is found before the '(n-1)th'
                index, then it is present in the array
                final comparison*/

                if (i < n - 1)
                    return "Found";

/*                else not present in the array*/

                return "Not Found";
            }
        }
    }

/*    driver program*/

    public static void main(String[] args)
    {
        int arr[] = { 4, 6, 1, 5, 8 };
        int n = arr.length;
        int x = 1;
        System.out.println(search(arr, n, x));
    }
}

/*Java program to find the first, second
and third minimum element in an array*/

