/*Java program to find uncommon elements
of two sorted arrays*/

import java.io.*;

class GFG {

    static void printUncommon(int arr1[],
                     int arr2[], int n1, int n2)
    {

        int i = 0, j = 0, k = 0;
        while (i < n1 && j < n2) {

/*            If not common, print smaller*/

            if (arr1[i] < arr2[j]) {
                System.out.print(arr1[i] + " ");
                i++;
                k++;
            }
            else if (arr2[j] < arr1[i]) {
                System.out.print(arr2[j] + " ");
                k++;
                j++;
            }

/*            Skip common element*/

            else {
                i++;
                j++;
            }
        }

/*        printing remaining elements*/

        while (i < n1) {
            System.out.print(arr1[i] + " ");
            i++;
            k++;
        }
        while (j < n2) {
            System.out.print(arr2[j] + " ");
            j++;
            k++;
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr1[] = { 10, 20, 30 };
        int arr2[] = { 20, 25, 30, 40, 50 };

        int n1 = arr1.length;
        int n2 = arr2.length;

        printUncommon(arr1, arr2, n1, n2);
    }
}

/*Java program to find the least frequent element
in an array.*/

import java.io.*;
import java.util.*;

class GFG {

    static int leastFrequent(int arr[], int n)
    {

/*        Sort the array*/

        Arrays.sort(arr);

/*        find the min frequency using
        linear traversal*/

        int min_count = n+1, res = -1;
        int curr_count = 1;

        for (int i = 1; i < n; i++) {
            if (arr[i] == arr[i - 1])
                curr_count++;
            else {
                if (curr_count < min_count) {
                    min_count = curr_count;
                    res = arr[i - 1];
                }

                curr_count = 1;
            }
        }

/*        If last element is least frequent*/

        if (curr_count < min_count)
        {
            min_count = curr_count;
            res = arr[n - 1];
        }

        return res;
    }

/*    driver program*/

    public static void main(String args[])
    {
        int arr[] = {1, 3, 2, 1, 2, 2, 3, 1};
        int n = arr.length;
        System.out.print(leastFrequent(arr, n));

    }
}

/*Java program to find
maximum sum by selecting
a element from n arrays*/

import java.io.*;

class GFG
{
    static int M = 4;
    static int arr[][] = {{1, 7, 3, 4},
                          {4, 2, 5, 1},
                          {9, 5, 1, 8}};

    static void sort(int a[][],
                     int row, int n)
    {
        for (int i = 0; i < M - 1; i++)
        {
            if(a[row][i] > a[row][i + 1])
            {
                int temp = a[row][i];
                a[row][i] = a[row][i + 1];
                a[row][i + 1] = temp;
            }
        }
    }

/*    To calculate maximum
    sum by selecting element
    from each array*/

    static int maximumSum(int a[][],
                          int n)
    {

/*    Sort each array*/

    for (int i = 0; i < n; i++)
        sort(a, i, n);

/*    Store maximum element
    of last array*/

    int sum = a[n - 1][M - 1];
    int prev = a[n - 1][M - 1];
    int i, j;

/*    Selecting maximum element
    from previoulsy selected
    element*/

    for (i = n - 2; i >= 0; i--)
    {
        for (j = M - 1; j >= 0; j--)
        {
            if (a[i][j] < prev)
            {
                prev = a[i][j];
                sum += prev;
                break;
            }
        }

/*        j = -1 means no element
        is found in a[i] so
        return 0*/

        if (j == -1)
        return 0;
    }    
    return sum;
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        int n = arr.length;
        System.out.print(maximumSum(arr, n));
    }
}

/*Java program to find Min distance
of maximum element*/

class GFG
{

/*    function to return min distance*/

    static int minDistance (int arr[], int n)
    {
        int maximum_element = arr[0];
        int min_dis = n;
        int index = 0;

        for (int i=1; i<n; i++)
        {

/*            case a*/

            if (maximum_element == arr[i])
            {
                min_dis = Math.min(min_dis, (i-index));
                index = i;
            }

/*            case b*/

            else if (maximum_element < arr[i])
            {
                maximum_element = arr[i];
                min_dis = n;
                index = i;
            }

/*            case c*/

            else
                continue;
        }

        return min_dis;
    }

/*    Driver code*/

    public static void main (String[] args)
    {
        int arr[] = {6, 3, 1, 3, 6, 4, 6};
        int n = arr.length;
        System.out.print("Minimum distance = "+minDistance(arr, n));
    }
}

