/*Java code to find maximum
number of consecutive steps.*/

import java.io.*;

class GFG {

/*    Function to count consecutive steps*/

    static int find_consecutive_steps(int arr[],
                                        int len)
    {
        int count = 0;
        int maximum = 0;

        for (int index = 1; index < len; index++) {

/*            count the number of consecutive
            increasing height building*/

            if (arr[index] > arr[index - 1])
                count++;
            else
            {
                maximum = Math.max(maximum, count);
                count = 0;
            }
        }

        return Math.max(maximum, count);
    }

/*    Driver code*/

    public static void main (String[] args) {

        int arr[] = { 1, 2, 3, 4 };
        int len = arr.length;

        System.out.println(find_consecutive_steps(arr,
                                                len));
    }
}

/*Java program to find element closet to given target.*/

import java.util.*;
import java.lang.*;
import java.io.*;

class FindClosestNumber {

/*    Returns element closest to target in arr[]*/

    public static int findClosest(int arr[], int target)
    {
        int n = arr.length;

/*        Corner cases*/

        if (target <= arr[0])
            return arr[0];
        if (target >= arr[n - 1])
            return arr[n - 1];

/*        Doing binary search*/

        int i = 0, j = n, mid = 0;
        while (i < j) {
            mid = (i + j) / 2;

            if (arr[mid] == target)
                return arr[mid];

/* If target is less than array element,
               then search in left */

            if (target < arr[mid]) {

/*                If target is greater than previous
                to mid, return closest of two*/

                if (mid > 0 && target > arr[mid - 1])
                    return getClosest(arr[mid - 1],
                                  arr[mid], target);

/* Repeat for left half */

                j = mid;             
            }

/*            If target is greater than mid*/

            else {
                if (mid < n-1 && target < arr[mid + 1])
                    return getClosest(arr[mid],
                          arr[mid + 1], target);

/*update i*/

i = mid + 1; 
            }
        }

/*        Only single element left after search*/

        return arr[mid];
    }

/*    Method to compare which one is the more close
    We find the closest by taking the difference
      between the target and both values. It assumes
    that val2 is greater than val1 and target lies
    between these two.*/

    public static int getClosest(int val1, int val2,
                                         int target)
    {
        if (target - val1 >= val2 - target)
            return val2;       
        else
            return val1;       
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 4, 5, 6, 6, 8, 9 };
        int target = 11;
        System.out.println(findClosest(arr, target));
    }
}

/*Java program to count pairs
with maximum sum.*/

import java.io.*;
class GFG {

/*function to find the number
of maximum pair sums*/

static int sum(int a[], int n)
{

/*    Find maximum and second maximum
    elements. Also find their counts.*/

    int maxVal = a[0], maxCount = 1;
    int secondMax = Integer.MIN_VALUE,
        secondMaxCount = 0;
    for (int i = 1; i < n; i++) {
        if (a[i] == maxVal)
            maxCount++;
        else if (a[i] > maxVal) {
            secondMax = maxVal;
            secondMaxCount = maxCount;
            maxVal = a[i];
            maxCount = 1;
        }
        else if (a[i] == secondMax) {
            secondMax = a[i];
            secondMaxCount++;
        }
        else if (a[i] > secondMax) {
            secondMax = a[i];
            secondMaxCount = 1;
        }
    }

/*    If maximum element appears
    more than once.*/

    if (maxCount > 1)
        return maxCount * (maxCount - 1) / 2;

/*    If maximum element appears
    only once.*/

    return secondMaxCount;
}

/*driver program*/

public static void main(String[] args)
{
    int array[] = { 1, 1, 1, 2, 2, 2, 3 };
    int n = array.length;
    System.out.println(sum(array, n));
}
}

/*Java program to find missing k numbers
in an array.*/

import java.util.Arrays;

class GFG {

/*    Prints first k natural numbers in
    arr[0..n-1]*/

    static void printKMissing(int[] arr, int n, int k)
    {
        Arrays.sort(arr);

/*        Find first positive number*/

        int i = 0;
        while (i < n && arr[i] <= 0)
            i++;

/*        Now find missing numbers
        between array elements*/

        int count = 0, curr = 1;
        while (count < k && i < n) {
            if (arr[i] != curr) {
                System.out.print(curr + " ");
                count++;
            }
            else
                i++;
            curr++;
        }

/*        Find missing numbers after
        maximum.*/

        while (count < k) {
            System.out.print(curr + " ");
            curr++;
            count++;
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int[] arr = { 2, 3, 4 };
        int n = arr.length;
        int k = 3;
        printKMissing(arr, n, k);
    }
}

/*Java program to find maximum product of
a subset.*/

class GFG {

    static int minProductSubset(int a[], int n)
    {
        if (n == 1)
            return a[0];

/*        Find count of negative numbers,
        count of zeros, maximum valued
        negative number, minimum valued
        positive number and product of
        non-zero numbers*/

        int negmax = Integer.MIN_VALUE;
        int posmin = Integer.MAX_VALUE;
        int count_neg = 0, count_zero = 0;
        int product = 1;

        for (int i = 0; i < n; i++) {

/*            if number is zero,count it
            but dont multiply*/

            if (a[i] == 0) {
                count_zero++;
                continue;
            }

/*            count the negative numbers
            and find the max negative number*/

            if (a[i] < 0) {
                count_neg++;
                negmax = Math.max(negmax, a[i]);
            }

/*            find the minimum positive number*/

            if (a[i] > 0 && a[i] < posmin)
                posmin = a[i];

            product *= a[i];
        }

/*        if there are all zeroes
        or zero is present but no
        negative number is present*/

        if (count_zero == n
            || (count_neg == 0 && count_zero > 0))
            return 0;

/*        If there are all positive*/

        if (count_neg == 0)
            return posmin;

/*        If there are even number except
        zero of negative numbers*/

        if (count_neg % 2 == 0 && count_neg != 0) {

/*            Otherwise result is product of
            all non-zeros divided by maximum
            valued negative.*/

            product = product / negmax;
        }

        return product;
    }

/*    main function*/

    public static void main(String[] args)
    {

        int a[] = { -1, -1, -2, 4, 3 };
        int n = 5;

        System.out.println(minProductSubset(a, n));
    }
}

/*Java program for above implementation*/

import java.io.*;
import java.util.*;

class GFG {

static int Mod = 1000000007;

/*Function to find the maximum sum*/

static long findSum(int arr[], int n) {
    long sum = 0;

/*    Sort the array first*/

    Arrays.sort(arr);

/*    First multiply negative numbers
    pairwise and sum up from starting
    as to get maximum sum.*/

    int i = 0;
    while (i < n && arr[i] < 0) {
    if (i != n - 1 && arr[i + 1] <= 0) {
        sum = (sum + (arr[i] * arr[i + 1]) % Mod) % Mod;
        i += 2;
    }
    else
        break;
    }

/*    Second multiply positive numbers
    pairwise and summed up from the
    last as to get maximum sum.*/

    int j = n - 1;
    while (j >= 0 && arr[j] > 0) {
    if (j != 0 && arr[j - 1] > 0) {
        sum = (sum + (arr[j] * arr[j - 1]) % Mod) % Mod;
        j -= 2;
    } else
        break;
    }

/*    To handle case if positive and negative
    numbers both are odd in counts.*/

    if (j > i)
    sum = (sum + (arr[i] * arr[j]) % Mod) % Mod;

/*    If one of them occurs odd times*/

    else if (i == j)
    sum = (sum + arr[i]) % Mod;

    return sum;
}

/*Drivers code*/

public static void main(String args[]) {
    int arr[] = {-1, 9, 4, 5, -4, 7};
    int n = arr.length;
    System.out.println(findSum(arr, n));
}
}

/* This function is in LinkedList class.
Inserts a new node after the given prev_node. This method is
defined inside LinkedList class shown above */

public void insertAfter(Node prev_node, int new_data)
{

/* 1. Check if the given Node is null */

    if (prev_node == null)
    {
        System.out.println("The given previous node cannot be null");
        return;
    }

/* 2. Allocate the Node &
    3. Put in the data*/

    Node new_node = new Node(new_data);

