/*Java program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

import java.util.*;

class GFG
{

/*class node*/

static class Node
{
    int data;
    Node next;
}

/*A utility function to print
linked list*/

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data +" ");
        node = node.next;
    }
    System.out.println();
}

/*Function to create newNode
in a linkedlist*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*Function to insert at beginning*/

static Node insertBeg(Node head, int val)
{
    Node temp = newNode(val);
    temp.next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

static void rearrangeOddEven(Node head)
{
    Stack<Node> odd=new Stack<Node>();
    Stack<Node> even=new Stack<Node>();
    int i = 1;

    while (head != null) {

        if (head.data % 2 != 0 && i % 2 == 0)
        {

/*            Odd Value in Even Position
            Add pointer to current node
            in odd stack*/

            odd.push(head);
        }

        else if (head.data % 2 == 0 && i % 2 != 0)
        {

/*            Even Value in Odd Position
            Add pointer to current node
            in even stack*/

            even.push(head);
        }

        head = head.next;
        i++;
    }

    while (odd.size() > 0 && even.size() > 0)
    {

/*        Swap Data at the top of two stacks*/

        int k=odd.peek().data;
        odd.peek().data=even.peek().data;
        even.peek().data=k;
        odd.pop();
        even.pop();
    }
}

/*Driver code*/

public static void main(String args[])
{
    Node head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 5);
    head = insertBeg(head, 3);
    head = insertBeg(head, 2);
    head = insertBeg(head, 1);

    System.out.println( "Linked List:" );
    printList(head);
    rearrangeOddEven(head);

    System.out.println( "Linked List after "+
                        "Rearranging:" );
    printList(head);
}
}

/*Java program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

class GFG
{

/*Structure node*/

static class Node
{
    int data;
    Node next;
};

/*A utility function to print
linked list*/

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + " ");
        node = node.next;
    }
    System.out.println();
}

/*Function to create newNode
in a linkedlist*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*Function to insert at beginning*/

static Node insertBeg(Node head, int val)
{
    Node temp = newNode(val);
    temp.next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

static Node rearrange(Node head)
{

/*    Step 1: Segregate even and odd nodes
    Step 2: Split odd and even lists
    Step 3: Merge even list into odd list*/

    Node even;
    Node temp, prev_temp;
    Node i, j, k, l, ptr=null;

/*    Step 1: Segregate Odd and Even Nodes*/

    temp = (head).next;
    prev_temp = head;

    while (temp != null)
    {

/*        Backup next pointer of temp*/

        Node x = temp.next;

/*        If temp is odd move the node
        to beginning of list*/

        if (temp.data % 2 != 0)
        {
            prev_temp.next = x;
            temp.next = (head);
            (head) = temp;
        }
        else
        {
            prev_temp = temp;
        }

/*        Advance Temp Pointer*/

        temp = x;
    }

/*    Step 2
    Split the List into Odd and even*/

    temp = (head).next;
    prev_temp = (head);

    while (temp != null && temp.data % 2 != 0)
    {
        prev_temp = temp;
        temp = temp.next;
    }

    even = temp;

/*    End the odd List (Make last node null)*/

    prev_temp.next = null;

/*    Step 3:
    Merge Even List into odd*/

    i = head;
    j = even;

    while (j != null && i != null)
    {

/*        While both lists are not
        exhausted Backup next
        pointers of i and j*/

        k = i.next;
        l = j.next;

        i.next = j;
        j.next = k;

/*        ptr points to the latest node added*/

        ptr = j;

/*        Advance i and j pointers*/

        i = k;
        j = l;
    }

    if (i == null)
    {

/*        Odd list exhausts before even,
        append remainder of even list to odd.*/

        ptr.next = j;
    }

/*    The case where even list exhausts before
    odd list is automatically handled since we
    merge the even list into the odd list*/

    return head;
}

/*Driver Code*/

public static void main(String args[])
{
    Node head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 3);
    head = insertBeg(head, 5);
    head = insertBeg(head, 1);
    head = insertBeg(head, 2);
    head = insertBeg(head, 10);

    System.out.println("Linked List:" );
    printList(head);
    System.out.println("Rearranged List" );
    head=rearrange(head);
    printList(head);
}
}

static void AlternatingSplit(Node source, Node aRef,
                            Node bRef)
{
  Node aDummy = new Node();
  Node aTail = aDummy;

/* points to the last node in 'a' */

  Node bDummy = new Node();
  Node bTail = bDummy;

/* points to the last node in 'b' */

  Node current = source;
  aDummy.next = null;
  bDummy.next = null;
  while (current != null)
  {
    MoveNode((aTail.next), current);

/* add at 'a' tail */

    aTail = aTail.next;

/* advance the 'a' tail */

    if (current != null)
    {
      MoveNode((bTail.next), current);
      bTail = bTail.next;
    }
  }
  aRef = aDummy.next;
  bRef = bDummy.next;
}

/*Java program for flattening a Linked List*/

class LinkedList
{

/*head of list*/

Node head;

/* Linked list Node*/

    class Node
    {
        int data;
        Node right, down;
        Node(int data)
        {
            this.data = data;
            right = null;
            down = null;
        }
    }

/*    An utility function to merge two sorted linked lists*/

    Node merge(Node a, Node b)
    {

/*        if first linked list is empty then second
        is the answer*/

        if (a == null)     return b;

/*        if second linked list is empty then first
        is the result*/

        if (b == null)      return a;

/*        compare the data members of the two linked lists
        and put the larger one in the result*/

        Node result;

        if (a.data < b.data)
        {
            result = a;
            result.down =  merge(a.down, b);
        }

        else
        {
            result = b;
            result.down = merge(a, b.down);
        }

        result.right = null; 
        return result;
    }

    Node flatten(Node root)
    {

/*        Base Cases*/

        if (root == null || root.right == null)
            return root;

/*        recur for list on right*/

        root.right = flatten(root.right);

/*        now merge*/

        root = merge(root, root.right);

/*        return the root
        it will be in turn merged with its left*/

        return root;
    }

/* Utility function to insert a node at beginning of the
       linked list */

    Node push(Node head_ref, int data)
    {

/* 1 & 2: Allocate the Node &
                  Put in the data*/

        Node new_node = new Node(data);

/* 3. Make next of new Node as head */

        new_node.down = head_ref;

/* 4. Move the head to point to new Node */

        head_ref = new_node;

/*5. return to link it back */

        return head_ref;
    }

    void printList()
    {
        Node temp = head;
        while (temp != null)
        {
            System.out.print(temp.data + " ");
            temp = temp.down;
        }
        System.out.println();
    }

/* Driver program to test above functions */

    public static void main(String args[])
    {
        LinkedList L = new LinkedList();

/* Let us create the following linked list
            5 -> 10 -> 19 -> 28
            |    |     |     |
            V    V     V     V
            7    20    22    35
            |          |     |
            V          V     V
            8          50    40
            |                |
            V                V
            30               45
        */


        L.head = L.push(L.head, 30);
        L.head = L.push(L.head, 8);
        L.head = L.push(L.head, 7);
        L.head = L.push(L.head, 5);

        L.head.right = L.push(L.head.right, 20);
        L.head.right = L.push(L.head.right, 10);

        L.head.right.right = L.push(L.head.right.right, 50);
        L.head.right.right = L.push(L.head.right.right, 22);
        L.head.right.right = L.push(L.head.right.right, 19);

        L.head.right.right.right = L.push(L.head.right.right.right, 45);
        L.head.right.right.right = L.push(L.head.right.right.right, 40);
        L.head.right.right.right = L.push(L.head.right.right.right, 35);
        L.head.right.right.right = L.push(L.head.right.right.right, 20);

/*        flatten the list*/

        L.head = L.flatten(L.head);

        L.printList();
    }
}

/*Java program to sort a linked list of 0, 1 and 2*/

class LinkedList
{

/*head of list*/

Node head;

/* Linked list Node*/

    class Node
    {
        int data;
        Node next;
        Node(int d) {data = d; next = null; }
    }

    void sortList()
    {

/*       initialise count of 0 1 and 2 as 0*/

       int count[] = {0, 0, 0};

       Node ptr = head;

/* count total number of '0', '1' and '2'
        * count[0] will store total number of '0's
        * count[1] will store total number of '1's
        * count[2] will store total number of '2's  */

       while (ptr != null)
       {
            count[ptr.data]++;
            ptr = ptr.next;
       }

       int i = 0;
       ptr = head;

/* Let say count[0] = n1, count[1] = n2 and count[2] = n3
        * now start traversing list from head node,
        * 1) fill the list with 0, till n1 > 0
        * 2) fill the list with 1, till n2 > 0
        * 3) fill the list with 2, till n3 > 0  */

        while (ptr != null)
        {
            if (count[i] == 0)
                i++;
            else
            {
               ptr.data= i;
               --count[i];
               ptr = ptr.next;
            }
         }
    }

/* Inserts a new Node at front of the list. */

    public void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
                  Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

/* Function to print linked list */

    void printList()
    {
        Node temp = head;
        while (temp != null)
        {
           System.out.print(temp.data+" ");
           temp = temp.next;
        } 
        System.out.println();
    }

/* Driver program to test above functions */

    public static void main(String args[])
    {
        LinkedList llist = new LinkedList();

/* Constructed Linked List is 1->2->3->4->5->6->7->
           8->8->9->null */

        llist.push(0);
        llist.push(1);
        llist.push(0);
        llist.push(2);
        llist.push(1);
        llist.push(1);
        llist.push(2);
        llist.push(1);
        llist.push(2);

        System.out.println("Linked List before sorting");
        llist.printList();

        llist.sortList();

        System.out.println("Linked List after sorting");
        llist.printList();
    }
}

/*Java code to rearrange linked list in place*/

class Geeks {

    static class Node {
        int data;
        Node next;
    }

/*    function for rearranging a linked list
    with high and low value.*/

    static Node rearrange(Node head)
    {

/*Base case.*/

if (head == null) 
            return null;

/*        two pointer variable.*/

        Node prev = head, curr = head.next;

        while (curr != null) {

/*            swap function for swapping data.*/

            if (prev.data > curr.data) {
                int t = prev.data;
                prev.data = curr.data;
                curr.data = t;
            }

/*            swap function for swapping data.*/

            if (curr.next != null
                && curr.next.data > curr.data) {
                int t = curr.next.data;
                curr.next.data = curr.data;
                curr.data = t;
            }

            prev = curr.next;

            if (curr.next == null)
                break;
            curr = curr.next.next;
        }
        return head;
    }

/*    function to insert a Node in
    the linked list at the beginning.*/

    static Node push(Node head, int k)
    {
        Node tem = new Node();
        tem.data = k;
        tem.next = head;
        head = tem;
        return head;
    }

/*    function to display Node of linked list.*/

    static void display(Node head)
    {
        Node curr = head;
        while (curr != null) {
            System.out.printf("%d ", curr.data);
            curr = curr.next;
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {

        Node head = null;

/*        let create a linked list.
        9 . 6 . 8 . 3 . 7*/

        head = push(head, 7);
        head = push(head, 3);
        head = push(head, 8);
        head = push(head, 6);
        head = push(head, 9);

        head = rearrange(head);

        display(head);
    }
}

