import java.io.*;

/*Creating the structure for node*/

class Node {
    int data;
    Node next;
    Node(int key)
    {
        data = key;
        next = null;
    }
}

class GFG {

    Node left = null;

/*    Function to print the list*/

    void printlist(Node head)
    {
        while (head != null) {
            System.out.print(head.data + " ");
            if (head.next != null) {
                System.out.print("->");
            }
            head = head.next;
        }
        System.out.println();
    }

/*    Function to rearrange*/

    void rearrange(Node head)
    {

        if (head != null) {
            left = head;
            reorderListUtil(left);
        }
    }

    void reorderListUtil(Node right)
    {

        if (right == null) {
            return;
        }

        reorderListUtil(right.next);

/*        we set left = null, when we reach stop condition,
        so no processing required after that*/

        if (left == null) {
            return;
        }

/*        Stop condition: odd case : left = right, even
        case : left.next = right*/

        if (left != right && left.next != right) {
            Node temp = left.next;
            left.next = right;
            right.next = temp;
            left = temp;
        }

/*stop condition , set null to left nodes*/

else { 
            if (left.next == right) {

/*even case*/

left.next.next = null; 
                left = null;
            }
            else {

/*odd case*/

left.next = null; 
                left = null;
            }
        }
    }

/*    Drivers Code*/

    public static void main(String[] args)
    {

        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        head.next.next.next.next = new Node(5);

        GFG gfg = new GFG();

/*        Print original list*/

        gfg.printlist(head);

/*        Modify the list*/

        gfg.rearrange(head);

/*        Print modified list*/

        gfg.printlist(head);
    }
}

/*Java program to rearrange a linked list
in such a way that all odd positioned 
node are stored before all even positioned nodes*/

class GfG
{

/*Linked List Node*/

static class Node
{
    int data;
    Node next;
}

/*A utility function to create a new node*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*Rearranges given linked list
such that all even positioned
nodes are before odd positioned.
Returns new head of linked List.*/

static Node rearrangeEvenOdd(Node head)
{

/*    Corner case*/

    if (head == null)
        return null;

/*    Initialize first nodes of even and
    odd lists*/

    Node odd = head;
    Node even = head.next;

/*    Remember the first node of even list so
    that we can connect the even list at the
    end of odd list.*/

    Node evenFirst = even;

    while (1 == 1)
    {

/*        If there are no more nodes, 
        then connect first node of even 
        list to the last node of odd list*/

        if (odd == null || even == null ||
                        (even.next) == null)
        {
            odd.next = evenFirst;
            break;
        }

/*        Connecting odd nodes*/

        odd.next = even.next;
        odd = even.next;

/*        If there are NO more even nodes 
        after current odd.*/

        if (odd.next == null)
        {
            even.next = null;
            odd.next = evenFirst;
            break;
        }

/*        Connecting even nodes*/

        even.next = odd.next;
        even = odd.next;
    }
    return head;
}

/*A utility function to print a linked list*/

static void printlist(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + "->");
        node = node.next;
    }
    System.out.println("NULL") ;
}

/*Driver code*/

public static void main(String[] args)
{
    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);

    System.out.println("Given Linked List");
    printlist(head);

    head = rearrangeEvenOdd(head);

    System.out.println("Modified Linked List");
    printlist(head);
}
}

