}

public class GFG {

    private Node head;

/*    Print Linked List*/

    public void printLL()
    {
        Node t = head;
        while (t != null) {
            System.out.print(t.data + " ->");
            t = t.next;
        }
        System.out.println();
    }

/*    Swap both nodes*/

    public void swap(Node a, Node b)
    {
        if (a == null || b == null)
            return;
        int temp = a.data;
        a.data = b.data;
        b.data = temp;
    }

/*    Rearrange the linked list
    in zig zag way*/

    public Node zigZag(Node node, int flag)
    {
        if (node == null || node.next == null) {
            return node;
        }
        if (flag == 0) {
            if (node.data > node.next.data) {
                swap(node, node.next);
            }
            return zigZag(node.next, 1);
        }
        else {
            if (node.data < node.next.data) {
                swap(node, node.next);
            }
            return zigZag(node.next, 0);
        }
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        GFG lobj = new GFG();
        lobj.head = new Node(11);
        lobj.head.next = new Node(15);
        lobj.head.next.next = new Node(20);
        lobj.head.next.next.next = new Node(5);
        lobj.head.next.next.next.next = new Node(10);
        lobj.printLL();

/*        0 means the current element
        should be smaller than the next*/

        int flag = 0;
        lobj.zigZag(lobj.head, flag);
        System.out.println("LL in zig zag fashion : ");
        lobj.printLL();
    }
}

/*Recursive Java program to add 1 to a linked list*/

class GfG {

/* Linked list node */

    static class Node
    {
        int data;
        Node next;
    }

/* Function to create a new node with given data */

    static Node newNode(int data)
    {
        Node new_node = new Node();
        new_node.data = data;
        new_node.next = null;
        return new_node;
    }

/*    Recursively add 1 from end to beginning and returns
    carry after all nodes are processed.*/

    static int addWithCarry(Node head)
    {

/*        If linked list is empty, then
        return carry*/

        if (head == null)
            return 1;

/*        Add carry returned be next node call*/

        int res = head.data + addWithCarry(head.next);

/*        Update data and return new carry*/

        head.data = (res) % 10;
        return (res) / 10;
    }

/*    This function mainly uses addWithCarry().*/

    static Node addOne(Node head)
    {

/*        Add 1 to linked list from end to beginning*/

        int carry = addWithCarry(head);

/*        If there is carry after processing all nodes,
        then we need to add a new node to linked list*/

        if (carry > 0)
        {
            Node newNode = newNode(carry);
            newNode.next = head;

/*New node becomes head now*/

return newNode; 
        }

        return head;
    }

/*    A utility function to print a linked list*/

    static void printList(Node node)
    {
        while (node != null)
        {
            System.out.print(node.data);
            node = node.next;
        }
        System.out.println();
    }

/* Driver code */

    public static void main(String[] args)
    {
        Node head = newNode(1);
        head.next = newNode(9);
        head.next.next = newNode(9);
        head.next.next.next = newNode(9);

        System.out.print("List is ");
        printList(head);

        head = addOne(head);
        System.out.println();
        System.out.print("Resultant list is ");
        printList(head);
    }
}

/*Java program to point arbit pointers to highest
value on its right*/

class GfG
{

/* Link list node */

    static class Node
    {
        int data;
        Node next, arbit;
    }

    static Node maxNode;

/*    This function populates arbit pointer in every
    node to the greatest value to its right.*/

    static void populateArbit(Node head)
    {

/*        if head is null simply return the list*/

        if (head == null)
            return;

/* if head->next is null it means we reached at
        the last node just update the max and maxNode */

        if (head.next == null)
        {
            maxNode = head;
            return;
        }

/* Calling the populateArbit to the next node */

        populateArbit(head.next);

/* updating the arbit node of the current
        node with the maximum value on the right side */

        head.arbit = maxNode;

/* if current Node value id greater then
        the previous right node then update it */

        if (head.data > maxNode.data)
            maxNode = head;

        return;
    }

/*    Utility function to print result linked list*/

    static void printNextArbitPointers(Node node)
    {
        System.out.println("Node\tNext Pointer\tArbit Pointer");
        while (node != null)
        {
            System.out.print(node.data + "\t\t\t");

            if (node.next != null)
                System.out.print(node.next.data + "\t\t\t\t");
            else
                System.out.print("NULL" +"\t\t\t");

            if (node.arbit != null)
                System.out.print(node.arbit.data);
            else
                System.out.print("NULL");

            System.out.println();
            node = node.next;
        }
    }

/* Function to create a new node with given data */

    static Node newNode(int data)
    {
        Node new_node = new Node();
        new_node.data = data;
        new_node.next = null;
        return new_node;
    }

/* Driver code*/

    public static void main(String[] args)
    {
        Node head = newNode(5);
        head.next = newNode(10);
        head.next.next = newNode(2);
        head.next.next.next = newNode(3);

        populateArbit(head);

        System.out.println("Resultant Linked List is: ");
        printNextArbitPointers(head);

    }
}

/*Java program to demonstrate deletion of last
Node in singly linked list*/

class GFG
{

/*A linked list Node*/

static class Node
{
    int data;
    Node next;
};

/*Function to delete the last occurrence*/

static void deleteLast(Node head, int x)
{
    Node temp = head, ptr = null;
    while (temp!=null)
    {

/*        If found key, update*/

        if (temp.data == x)
            ptr = temp;    
        temp = temp.next;
    }

/*    If the last occurrence is the last node*/

    if (ptr != null && ptr.next == null)
    {
        temp = head;
        while (temp.next != ptr)
            temp = temp.next;
        temp.next = null;
    }

/*    If it is not the last node*/

    if (ptr != null && ptr.next != null)
    {
        ptr.data = ptr.next.data;
        temp = ptr.next;
        ptr.next = ptr.next.next;
        System.gc();
    }
}

/* Utility function to create a new node with
given key */

static Node newNode(int x)
{
    Node node = new Node();
    node.data = x;
    node.next = null;
    return node;
}

/*This function prints contents of linked list
starting from the given Node*/

static void display(Node head)
{
    Node temp = head;
    if (head == null)
    {
        System.out.print("null\n");
        return;
    }
    while (temp != null)
    {
        System.out.printf("%d --> ", temp.data);
        temp = temp.next;
    }
    System.out.print("null\n");
}

/* Driver code*/

public static void main(String[] args)
{
    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);
    head.next.next.next.next.next = newNode(4);
    head.next.next.next.next.next.next = newNode(4);
    System.out.print("Created Linked list: ");
    display(head);
    deleteLast(head, 4);
    System.out.print("List after deletion of 4: ");
    display(head);
}
}

/*Java program to subtract smaller valued
list from larger valued list and return
result as a list.*/

import java.util.*;
import java.lang.*;
import java.io.*;

class LinkedList {

/*head of list*/

static Node head; 
    boolean borrow;

/* Node Class */

    static class Node {
        int data;
        Node next;
        Node(int d)
        {
            data = d;
            next = null;
        }
    }

/* A utility function to get length of
    linked list */

    int getLength(Node node)
    {
        int size = 0;
        while (node != null) {
            node = node.next;
            size++;
        }
        return size;
    }

/* A Utility that padds zeros in front
    of the Node, with the given diff */

    Node paddZeros(Node sNode, int diff)
    {
        if (sNode == null)
            return null;

        Node zHead = new Node(0);
        diff--;
        Node temp = zHead;
        while ((diff--) != 0) {
            temp.next = new Node(0);
            temp = temp.next;
        }
        temp.next = sNode;
        return zHead;
    }

/* Subtract LinkedList Helper is a recursive
    function, move till the last Node, and
    subtract the digits and create the Node and
    return the Node. If d1 < d2, we borrow the
    number from previous digit. */

    Node subtractLinkedListHelper(Node l1, Node l2)
    {
        if (l1 == null && l2 == null && borrow == false)
            return null;

        Node previous
            = subtractLinkedListHelper(
                (l1 != null) ? l1.next
                             : null,
                (l2 != null) ? l2.next : null);

        int d1 = l1.data;
        int d2 = l2.data;
        int sub = 0;

/* if you have given the value value to
        next digit then reduce the d1 by 1 */

        if (borrow) {
            d1--;
            borrow = false;
        }

/* If d1 < d2, then borrow the number from
        previous digit. Add 10 to d1 and set
        borrow = true; */

        if (d1 < d2) {
            borrow = true;
            d1 = d1 + 10;
        }

/* subtract the digits */

        sub = d1 - d2;

/* Create a Node with sub value */

        Node current = new Node(sub);

/* Set the Next pointer as Previous */

        current.next = previous;

        return current;
    }

/* This API subtracts two linked lists and
    returns the linked list which shall have the
    subtracted result. */

    Node subtractLinkedList(Node l1, Node l2)
    {

/*        Base Case.*/

        if (l1 == null && l2 == null)
            return null;

/*        In either of the case, get the lengths
        of both Linked list.*/

        int len1 = getLength(l1);
        int len2 = getLength(l2);

        Node lNode = null, sNode = null;

        Node temp1 = l1;
        Node temp2 = l2;

/*        If lengths differ, calculate the smaller
        Node and padd zeros for smaller Node and
        ensure both larger Node and smaller Node
        has equal length.*/

        if (len1 != len2) {
            lNode = len1 > len2 ? l1 : l2;
            sNode = len1 > len2 ? l2 : l1;
            sNode = paddZeros(sNode, Math.abs(len1 - len2));
        }

        else {

/*            If both list lengths are equal, then
            calculate the larger and smaller list.
            If 5-6-7 & 5-6-8 are linked list, then
            walk through linked list at last Node
            as 7 < 8, larger Node is 5-6-8 and
            smaller Node is 5-6-7.*/

            while (l1 != null && l2 != null) {
                if (l1.data != l2.data) {
                    lNode = l1.data > l2.data ? temp1 : temp2;
                    sNode = l1.data > l2.data ? temp2 : temp1;
                    break;
                }
                l1 = l1.next;
                l2 = l2.next;
            }
        }

/*        After calculating larger and smaller Node,
        call subtractLinkedListHelper which returns
        the subtracted linked list.*/

        borrow = false;
        return subtractLinkedListHelper(lNode, sNode);
    }

/*    function to display the linked list*/

    static void printList(Node head)
    {
        Node temp = head;
        while (temp != null) {
            System.out.print(temp.data + " ");
            temp = temp.next;
        }
    }

/*    Driver program to test above*/

    public static void main(String[] args)
    {
        Node head = new Node(1);
        head.next = new Node(0);
        head.next.next = new Node(0);

        Node head2 = new Node(1);

        LinkedList ob = new LinkedList();
        Node result = ob.subtractLinkedList(head, head2);

        printList(result);
    }
}

/*Java program to partition a
linked list around a given value.*/

class GfG
{

/* Link list Node */

static class Node
{
    int data;
    Node next;
}

/*A utility function to create a new node*/

static Node newNode(int data)
{
    Node new_node = new Node();
    new_node.data = data;
    new_node.next = null;
    return new_node;
}

/*Function to make two separate lists and return
head after concatenating*/

static Node partition(Node head, int x)
{

/* Let us initialize first and last nodes of
    three linked lists
        1) Linked list of values smaller than x.
        2) Linked list of values equal to x.
        3) Linked list of values greater than x.*/

    Node smallerHead = null, smallerLast = null;
    Node greaterLast = null, greaterHead = null;
    Node equalHead = null, equalLast =null;

/*    Now iterate original list and connect nodes
    of appropriate linked lists.*/

    while (head != null)
    {

/*        If current node is equal to x, append it
        to the list of x values*/

        if (head.data == x)
        {
            if (equalHead == null)
                equalHead = equalLast = head;
            else
            {
                equalLast.next = head;
                equalLast = equalLast.next;
            }
        }

/*        If current node is less than X, append
        it to the list of smaller values*/

        else if (head.data < x)
        {
            if (smallerHead == null)
                smallerLast = smallerHead = head;
            else
            {
                smallerLast.next = head;
                smallerLast = head;
            }
        }

/*Append to the list of greater values*/

else 
        {
            if (greaterHead == null)
                greaterLast = greaterHead = head;
            else
            {
                greaterLast.next = head;
                greaterLast = head;
            }
        }
        head = head.next;
    }

/*    Fix end of greater linked list to NULL if this
    list has some nodes*/

    if (greaterLast != null)
        greaterLast.next = null;

/*    Connect three lists*/

/*    If smaller list is empty*/

    if (smallerHead == null)
    {
        if (equalHead == null)
            return greaterHead;
        equalLast.next = greaterHead;
        return equalHead;
    }

/*    If smaller list is not empty
    and equal list is empty*/

    if (equalHead == null)
    {
        smallerLast.next = greaterHead;
        return smallerHead;
    }

/*    If both smaller and equal list
    are non-empty*/

    smallerLast.next = equalHead;
    equalLast.next = greaterHead;
    return smallerHead;
}

/* Function to print linked list */

static void printList(Node head)
{
    Node temp = head;
    while (temp != null)
    {
        System.out.print(temp.data + " ");
        temp = temp.next;
    }
}

/*Driver code*/

public static void main(String[] args)
{

/* Start with the empty list */

    Node head = newNode(10);
    head.next = newNode(4);
    head.next.next = newNode(5);
    head.next.next.next = newNode(30);
    head.next.next.next.next = newNode(2);
    head.next.next.next.next.next = newNode(50);

    int x = 3;
    head = partition(head, x);
    printList(head);
}
}

/*Java program to check if a linked list
with loop is palindrome or not.*/

import java.util.*;

class GfG
{

/* Link list node */

static class Node
{
    int data;
    Node next;
}

/* Function to find loop starting node.
loop_node --> Pointer to one of
the loop nodes head --> Pointer to
the start node of the linked list */

static Node getLoopstart(Node loop_node,
                            Node head)
{
    Node ptr1 = loop_node;
    Node ptr2 = loop_node;

/*    Count the number of nodes in loop*/

    int k = 1, i;
    while (ptr1.next != ptr2)
    {
        ptr1 = ptr1.next;
        k++;
    }

/*    Fix one pointer to head*/

    ptr1 = head;

/*    And the other pointer to k
    nodes after head*/

    ptr2 = head;
    for (i = 0; i < k; i++)
        ptr2 = ptr2.next;

/* Move both pointers at the same pace,
    they will meet at loop starting node */

    while (ptr2 != ptr1)
    {
        ptr1 = ptr1.next;
        ptr2 = ptr2.next;
    }
    return ptr1;
}

/* This function detects and find
loop starting node in the list*/

static Node detectAndgetLoopstarting(Node head)
{
    Node slow_p = head, fast_p = head,loop_start = null;

/*    Start traversing list and detect loop*/

    while (slow_p != null && fast_p != null &&
            fast_p.next != null)
    {
        slow_p = slow_p.next;
        fast_p = fast_p.next.next;

/* If slow_p and fast_p meet then find
        the loop starting node*/

        if (slow_p == fast_p)
        {
            loop_start = getLoopstart(slow_p, head);
            break;
        }
    }

/*    Return starting node of loop*/

    return loop_start;
}

/*Utility function to check if 
a linked list with loop is
palindrome with given starting point.*/

static boolean isPalindromeUtil(Node head,
                            Node loop_start)
{
    Node ptr = head;
    Stack<Integer> s = new Stack<Integer> ();

/*    Traverse linked list until last node 
    is equal to loop_start and store the 
    elements till start in a stack*/

    int count = 0;
    while (ptr != loop_start || count != 1)
    {
        s.push(ptr.data);
        if (ptr == loop_start)
            count = 1;
        ptr = ptr.next;
    }
    ptr = head;
    count = 0;

/*    Traverse linked list until last node is
    equal to loop_start second time*/

    while (ptr != loop_start || count != 1)
    {

/*        Compare data of node with the top of stack
        If equal then continue*/

        if (ptr.data == s.peek())
            s.pop();

/*        Else return false*/

        else
            return false;

        if (ptr == loop_start)
            count = 1;
        ptr = ptr.next;
    }

/*    Return true if linked list is palindrome*/

    return true;
}

/*Function to find if linked list
is palindrome or not*/

static boolean isPalindrome(Node head)
{

/*    Find the loop starting node*/

    Node loop_start = detectAndgetLoopstarting(head);

/*    Check if linked list is palindrome*/

    return isPalindromeUtil(head, loop_start);
}

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/* Driver code*/

public static void main(String[] args)
{
    Node head = newNode(50);
    head.next = newNode(20);
    head.next.next = newNode(15);
    head.next.next.next = newNode(20);
    head.next.next.next.next = newNode(50);

/* Create a loop for testing */

    head.next.next.next.next.next = head.next.next;

    if(isPalindrome(head) == true)
        System.out.println("Palindrome");
    else
        System.out.println("Not Palindrome");

}
}

/*Java program to move all occurrences of a
given key to end.*/

class GFG {

/*    A Linked list Node*/

    static class Node {
        int data;
        Node next;
    }

/*    A urility function to create a new node.*/

    static Node newNode(int x)
    {
        Node temp = new Node();
        temp.data = x;
        temp.next = null;
        return temp;
    }

/*    Utility function to print the elements
    in Linked list*/

    static void printList(Node head)
    {
        Node temp = head;
        while (temp != null) {
            System.out.printf("%d ", temp.data);
            temp = temp.next;
        }
        System.out.printf("\n");
    }

/*    Moves all occurrences of given key to
    end of linked list.*/

    static void moveToEnd(Node head, int key)
    {

/*        Keeps track of locations where key
        is present.*/

        Node pKey = head;

/*        Traverse list*/

        Node pCrawl = head;
        while (pCrawl != null) {

/*            If current pointer is not same as pointer
            to a key location, then we must have found
            a key in linked list. We swap data of pCrawl
            and pKey and move pKey to next position.*/

            if (pCrawl != pKey && pCrawl.data != key) {
                pKey.data = pCrawl.data;
                pCrawl.data = key;
                pKey = pKey.next;
            }

/*            Find next position where key is present*/

            if (pKey.data != key)
                pKey = pKey.next;

/*            Moving to next Node*/

            pCrawl = pCrawl.next;
        }
    }

/*    Driver code*/

    public static void main(String args[])
    {
        Node head = newNode(10);
        head.next = newNode(20);
        head.next.next = newNode(10);
        head.next.next.next = newNode(30);
        head.next.next.next.next = newNode(40);
        head.next.next.next.next.next = newNode(10);
        head.next.next.next.next.next.next = newNode(60);

        System.out.printf("Before moveToEnd(), the Linked list is\n");
        printList(head);

        int key = 10;
        moveToEnd(head, key);

        System.out.printf("\nAfter moveToEnd(), the Linked list is\n");
        printList(head);
    }
}

/*Java code to remove key element to end of linked list*/

import java.util.*;

/*Node class*/

class Node {
    int data;
    Node next;

    public Node(int data)
    {
        this.data = data;
        this.next = null;
    }
}

class gfg {

    static Node root;

/*    Function to remove key to end*/

    public static Node keyToEnd(Node head, int key)
    {

/*        Node to keep pointing to tail*/

        Node tail = head;

        if (head == null) {
            return null;
        }

        while (tail.next != null) {
            tail = tail.next;
        }

/*        Node to point to last of linked list*/

        Node last = tail;

        Node current = head;
        Node prev = null;

/*        Node prev2 to point to previous when head.data!=key*/

        Node prev2 = null;

/*        loop to perform operations to remove key to end*/

        while (current != tail) {
            if (current.data == key && prev2 == null) {
                prev = current;
                current = current.next;
                head = current;
                last.next = prev;
                last = last.next;
                last.next = null;
                prev = null;
            }
            else {
                if (current.data == key && prev2 != null) {
                    prev = current;
                    current = current.next;
                    prev2.next = current;
                    last.next = prev;
                    last = last.next;
                    last.next = null;
                }
                else if (current != tail) {
                    prev2 = current;
                    current = current.next;
                }
            }
        }
        return head;
    }

/*    Function to display linked list*/

    public static void display(Node root)
    {
        while (root != null) {
            System.out.print(root.data + " ");
            root = root.next;
        }
    }

/*    Driver Code*/

    public static void main(String args[])
    {
        root = new Node(5);
        root.next = new Node(2);
        root.next.next = new Node(2);
        root.next.next.next = new Node(7);
        root.next.next.next.next = new Node(2);
        root.next.next.next.next.next = new Node(2);
        root.next.next.next.next.next.next = new Node(2);

        int key = 2;
        System.out.println("Linked List before operations :");
        display(root);
        System.out.println("\nLinked List after operations :");
        root = keyToEnd(root, key);
        display(root);
    }
}

/*Java program to delete every k-th Node
of a singly linked list.*/

class GFG
{

/* Linked list Node */

static class Node
{
    int data;
    Node next;
}

/*To remove complete list (Needed for
case when k is 1)*/

static Node freeList(Node node)
{
    while (node != null)
    {
        Node next = node.next;
        node = next;
    }
    return node;
}

/*Deletes every k-th node and
returns head of modified list.*/

static Node deleteKthNode(Node head, int k)
{

/*    If linked list is empty*/

    if (head == null)
        return null;

    if (k == 1)
    {
        head = freeList(head);
        return null;
    }

/*    Initialize ptr and prev before
    starting traversal.*/

    Node ptr = head, prev = null;

/*    Traverse list and delete
    every k-th node*/

    int count = 0;
    while (ptr != null)
    {

/*        increment Node count*/

        count++;

/*        check if count is equal to k
        if yes, then delete current Node*/

        if (k == count)
        {

/*            put the next of current Node in
            the next of previous Node*/

            prev.next = ptr.next;

/*            set count = 0 to reach further
            k-th Node*/

            count = 0;
        }

/*        update prev if count is not 0*/

        if (count != 0)
            prev = ptr;

        ptr = prev.next;
    }
    return head;
}

/* Function to print linked list */

