    Node next;
}

/*Function to check the length of linklist*/

static int LinkedListLength(Node head)
{
    while (head != null && head.next != null)
    {
        head = head.next.next;
    }
    if (head == null)
        return 0;
    return 1;
}

/*Push function*/

static void push(Node head, int info)
{

/*    Allocating node*/

    Node node = new Node();

/*    Info into node*/

    node.data = info;

/*    Next of new node to head*/

    node.next = (head);

/*    head points to new node*/

    (head) = node;
}

