}

/*Java implementation to find the sum of
last 'n' nodes of the Linked List*/

import java.util.*;

class GFG
{

/* A Linked list node */

static class Node
{
    int data;
    Node next;
};
static Node head;
static int n, sum;

/*function to insert a node at the
beginning of the linked list*/

static void push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list to the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    head = head_ref;
}

/*function to recursively find the sum of last
'n' nodes of the given linked list*/

static void sumOfLastN_Nodes(Node head)
{

/*    if head = NULL*/

    if (head == null)
        return;

/*    recursively traverse the remaining nodes*/

    sumOfLastN_Nodes(head.next);

/*    if node count 'n' is greater than 0*/

    if (n > 0)
    {

/*        accumulate sum*/

        sum = sum + head.data;

/*        reduce node count 'n' by 1*/

        --n;
    }
}

/*utility function to find the sum of last 'n' nodes*/

static int sumOfLastN_NodesUtil(Node head, int n)
{

/*    if n == 0*/

    if (n <= 0)
        return 0;

    sum = 0;

/*    find the sum of last 'n' nodes*/

    sumOfLastN_Nodes(head);

/*    required sum*/

    return sum;
}

/*Driver Code*/

public static void main(String[] args)
{
    head = null;

/*    create linked list 10.6.8.4.12*/

    push(head, 12);
    push(head, 4);
    push(head, 8);
    push(head, 6);
    push(head, 10);

    n = 2;
    System.out.print("Sum of last " + n +
                     " nodes = " +
                     sumOfLastN_NodesUtil(head, n));
}
}

Node SortedMerge(Node a, Node b)
{
Node result = null;

/* point to the last result pointer */

Node lastPtrRef = result;

while(1)
{
    if (a == null)
    {
    lastPtrRef = b;
    break;
    }
    else if (b==null)
    {
    lastPtrRef = a;
    break;
    }
    if(a.data <= b.data)
    {
    MoveNode(lastPtrRef, a);
    }
    else
    {
    MoveNode(lastPtrRef, b);
    }

/* tricky: advance to point to the next ".next" field */

    lastPtrRef = ((lastPtrRef).next);
}
return(result);
}

/*Java program to merge k sorted
arrays of size n each*/

import java.io.*;

/*A Linked List node*/

class Node
{
  int data;
  Node next;

/*  Utility function to create a new node.*/

  Node(int key)
  {
    data = key;
    next = null;
  }
}
class GFG {

  static Node head;
  static Node temp;

/* Function to print nodes in
   a given linked list */

  static void printList(Node node)
  {
    while(node != null)
    {
      System.out.print(node.data + " ");

      node = node.next;
    }
    System.out.println();
  }

/*  The main function that
  takes an array of lists
  arr[0..last] and generates
  the sorted output*/

  static Node mergeKLists(Node arr[], int last)
  {

/*    Traverse form second list to last*/

    for (int i = 1; i <= last; i++)
    {
      while(true)
      {

/*        head of both the lists,
        0 and ith list. */

        Node head_0 = arr[0];
        Node head_i = arr[i];

/*        Break if list ended*/

        if (head_i == null)
          break;

/*        Smaller than first element*/

        if(head_0.data >= head_i.data)
        {
          arr[i] = head_i.next;
          head_i.next = head_0;
          arr[0] = head_i;
        }
        else
        {

/*          Traverse the first list*/

          while (head_0.next != null)
          {

/*            Smaller than next element*/

            if (head_0.next.data >= head_i.data)
            {
              arr[i] = head_i.next;
              head_i.next = head_0.next;
              head_0.next = head_i;
              break;
            }

/*            go to next node*/

            head_0 = head_0.next;

/*            if last node*/

            if (head_0.next == null)
            {
              arr[i] = head_i.next;
              head_i.next = null;
              head_0.next = head_i;
              head_0.next.next = null;
              break;
            }
          }
        }
      }
    }
    return arr[0];
  }

/*  Driver program to test
  above functions */

  public static void main (String[] args)
  {

/*    Number of linked lists*/

    int k = 3;

/*    Number of elements in each list*/

    int n = 4;

/*    an array of pointers storing the
    head nodes of the linked lists*/


    Node[] arr = new Node[k];

    arr[0] = new Node(1);
    arr[0].next = new Node(3);
    arr[0].next.next = new Node(5);
    arr[0].next.next.next = new Node(7);

    arr[1] = new Node(2);
    arr[1].next = new Node(4);
    arr[1].next.next = new Node(6);
    arr[1].next.next.next = new Node(8);

    arr[2] = new Node(0);
    arr[2].next = new Node(9);
    arr[2].next.next = new Node(10);
    arr[2].next.next.next = new Node(11);

/*    Merge all lists*/

    head = mergeKLists(arr, k - 1);
    printList(head);

  }
}

/*Java program to merge two sorted
linked lists in-place.*/

class GFG {

    static class Node {
        int data;
        Node next;
    };

/*    Function to create newNode in a linkedlist*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    A utility function to print linked list*/

    static void printList(Node node)
    {
        while (node != null) {
            System.out.printf("%d ", node.data);
            node = node.next;
        }
    }

/*    Merges two given lists in-place. This function
    mainly compares head nodes and calls mergeUtil()*/

    static Node merge(Node h1, Node h2)
    {
        if (h1 == null)
            return h2;
        if (h2 == null)
            return h1;

/*        start with the linked list
        whose head data is the least*/

        if (h1.data < h2.data) {
            h1.next = merge(h1.next, h2);
            return h1;
        }
        else {
            h2.next = merge(h1, h2.next);
            return h2;
        }
    }

/*    Driver program*/

    public static void main(String args[])
    {
        Node head1 = newNode(1);
        head1.next = newNode(3);
        head1.next.next = newNode(5);

/*        1.3.5 LinkedList created*/


        Node head2 = newNode(0);
        head2.next = newNode(2);
        head2.next.next = newNode(4);

/*        0.2.4 LinkedList created*/


        Node mergedhead = merge(head1, head2);

        printList(mergedhead);
    }
}

/*Java program to merge two sorted
linked lists in-place.*/

class GfG {

/*Linked List node*/

    static class Node {
        int data;
        Node next;
    }

/*    Function to create newNode in a linkedlist*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    A utility function to print linked list*/

    static void printList(Node node)
    {
        while (node != null) {
            System.out.print(node.data + " ");
            node = node.next;
        }
    }

/*    Merges two lists with headers as h1 and h2.
    It assumes that h1's data is smaller than
    or equal to h2's data.*/

    static Node mergeUtil(Node h1, Node h2)
    {

/*        if only one node in first list
        simply point its head to second list*/

        if (h1.next == null) {
            h1.next = h2;
            return h1;
        }

/*        Initialize current and next pointers of
        both lists*/

        Node curr1 = h1, next1 = h1.next;
        Node curr2 = h2, next2 = h2.next;

        while (next1 != null && curr2 != null) {

/*            if curr2 lies in between curr1 and next1
            then do curr1->curr2->next1*/

            if ((curr2.data) >= (curr1.data) && (curr2.data) <= (next1.data)) {
                next2 = curr2.next;
                curr1.next = curr2;
                curr2.next = next1;

/*                now let curr1 and curr2 to point
                to their immediate next pointers*/

                curr1 = curr2;
                curr2 = next2;
            }
            else {

/*                if more nodes in first list*/

                if (next1.next != null) {
                    next1 = next1.next;
                    curr1 = curr1.next;
                }

/*                else point the last node of first list
                to the remaining nodes of second list*/

                else {
                    next1.next = curr2;
                    return h1;
                }
            }
        }
        return h1;
    }

/*    Merges two given lists in-place. This function
    mainly compares head nodes and calls mergeUtil()*/

    static Node merge(Node h1, Node h2)
    {
        if (h1 == null)
            return h2;
        if (h2 == null)
            return h1;

/*        start with the linked list
        whose head data is the least*/

        if (h1.data < h2.data)
            return mergeUtil(h1, h2);
        else
            return mergeUtil(h2, h1);
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        Node head1 = newNode(1);
        head1.next = newNode(3);
        head1.next.next = newNode(5);

/*        1->3->5 LinkedList created*/


        Node head2 = newNode(0);
        head2.next = newNode(2);
        head2.next.next = newNode(4);

/*        0->2->4 LinkedList created*/


        Node mergedhead = merge(head1, head2);

        printList(mergedhead);
    }
}

/*Java code for Union and Intersection of two
Linked Lists*/

import java.util.HashMap;
import java.util.HashSet;

class LinkedList {

/*head of list*/

Node head;

/* Linked list Node*/

    class Node {
        int data;
        Node next;
        Node(int d)
        {
            data = d;
            next = null;
        }
    }

/* Utility function to print list */

    void printList()
    {
        Node temp = head;
        while (temp != null) {
            System.out.print(temp.data + " ");
            temp = temp.next;
        }
        System.out.println();
    }

/* Inserts a node at start of linked list */

    void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
        Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

    public void append(int new_data)
    {
        if (this.head == null) {
            Node n = new Node(new_data);
            this.head = n;
            return;
        }
        Node n1 = this.head;
        Node n2 = new Node(new_data);
        while (n1.next != null) {
            n1 = n1.next;
        }

        n1.next = n2;
        n2.next = null;
    }

/* A utility function that returns true if data is
    present in linked list else return false */

    boolean isPresent(Node head, int data)
    {
        Node t = head;
        while (t != null) {
            if (t.data == data)
                return true;
            t = t.next;
        }
        return false;
    }

    LinkedList getIntersection(Node head1, Node head2)
    {
        HashSet<Integer> hset = new HashSet<>();
        Node n1 = head1;
        Node n2 = head2;
        LinkedList result = new LinkedList();

/*        loop stores all the elements of list1 in hset*/

        while (n1 != null) {
            if (hset.contains(n1.data)) {
                hset.add(n1.data);
            }
            else {
                hset.add(n1.data);
            }
            n1 = n1.next;
        }

/*        For every element of list2 present in hset
        loop inserts the element into the result*/

        while (n2 != null) {
            if (hset.contains(n2.data)) {
                result.push(n2.data);
            }
            n2 = n2.next;
        }
        return result;
    }

    LinkedList getUnion(Node head1, Node head2)
    {

/*        HashMap that will store the
        elements of the lists with their counts*/

        HashMap<Integer, Integer> hmap = new HashMap<>();
        Node n1 = head1;
        Node n2 = head2;
        LinkedList result = new LinkedList();

/*        loop inserts the elements and the count of
        that element of list1 into the hmap*/

        while (n1 != null) {
            if (hmap.containsKey(n1.data)) {
                int val = hmap.get(n1.data);
                hmap.put(n1.data, val + 1);
            }
            else {
                hmap.put(n1.data, 1);
            }
            n1 = n1.next;
        }

/*        loop further adds the elements of list2 with
        their counts into the hmap*/

        while (n2 != null) {
            if (hmap.containsKey(n2.data)) {
                int val = hmap.get(n2.data);
                hmap.put(n2.data, val + 1);
            }
            else {
                hmap.put(n2.data, 1);
            }
            n2 = n2.next;
        }

/*        Eventually add all the elements
        into the result that are present in the hmap*/

        for (int a : hmap.keySet()) {
            result.append(a);
        }
        return result;
    }

/* Driver program to test above functions */

    public static void main(String args[])
    {
        LinkedList llist1 = new LinkedList();
        LinkedList llist2 = new LinkedList();
        LinkedList union = new LinkedList();
        LinkedList intersection = new LinkedList();

/*create a linked list 10->15->4->20 */

        llist1.push(20);
        llist1.push(4);
        llist1.push(15);
        llist1.push(10);

/*create a linked list 8->4->2->10 */

        llist2.push(10);
        llist2.push(2);
        llist2.push(4);
        llist2.push(8);

        intersection
            = intersection.getIntersection(llist1.head,
                                           llist2.head);
        union = union.getUnion(llist1.head, llist2.head);

        System.out.println("First List is");
        llist1.printList();

        System.out.println("Second List is");
        llist2.printList();

        System.out.println("Intersection List is");
        intersection.printList();

        System.out.println("Union List is");
        union.printList();
    }
}

/*Java implementation of recursive selection sort
for singly linked list | Swapping node links*/

class GFG
{

/*A Linked list node*/

static class Node
{
    int data;
    Node next;
};

/*function to swap nodes 'currX' and 'currY' in a
linked list without swapping data*/

static Node swapNodes( Node head_ref, Node currX,
                        Node currY, Node prevY)
{

/*    make 'currY' as new head*/

    head_ref = currY;

/*    adjust links*/

    prevY.next = currX;

/*    Swap next pointers*/

    Node temp = currY.next;
    currY.next = currX.next;
    currX.next = temp;
    return head_ref;
}

/*function to sort the linked list using
recursive selection sort technique*/

static Node recurSelectionSort( Node head)
{

/*    if there is only a single node*/

    if (head.next == null)
        return head;

/*    'min' - pointer to store the node having
    minimum data value*/

    Node min = head;

/*    'beforeMin' - pointer to store node previous
    to 'min' node*/

    Node beforeMin = null;
    Node ptr;

/*    traverse the list till the last node*/

    for (ptr = head; ptr.next != null; ptr = ptr.next)
    {

/*        if true, then update 'min' and 'beforeMin'*/

        if (ptr.next.data < min.data)
        {
            min = ptr.next;
            beforeMin = ptr;
        }
    }

/*    if 'min' and 'head' are not same,
    swap the head node with the 'min' node*/

    if (min != head)
        head = swapNodes(head, head, min, beforeMin);

/*    recursively sort the remaining list*/

    head.next = recurSelectionSort(head.next);

    return head;
}

/*function to sort the given linked list*/

static Node sort( Node head_ref)
{

/*    if list is empty*/

    if ((head_ref) == null)
        return null;

/*    sort the list using recursive selection
    sort technique*/

    head_ref = recurSelectionSort(head_ref);
    return head_ref;
}

/*function to insert a node at the
beginning of the linked list*/

static Node push( Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    link the old list to the new node*/

    new_node.next = (head_ref);

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*function to print the linked list*/

static void printList( Node head)
{
    while (head != null)
    {
        System.out.print( head.data + " ");
        head = head.next;
    }
}

/*Driver code*/

public static void main(String args[])
{
    Node head = null;

/*    create linked list 10.12.8.4.6*/

    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 12);
    head = push(head, 10);

    System.out.println( "Linked list before sorting:");
    printList(head);

/*    sort the linked list*/

    head = sort(head);

    System.out.print( "\nLinked list after sorting:");
    printList(head);
}
}

/*Java implementation to insert node
at the middle of the linked list*/

import java.util.*;
import java.lang.*;
import java.io.*;

class LinkedList
{

/*head of list*/

static Node head;

/* Node Class */

    static class Node {
        int data;
        Node next;

/*        Constructor to create a new node*/

        Node(int d) {
            data = d;
            next = null;
        }
    }

/*    function to insert node at the
    middle of the linked list*/

    static void insertAtMid(int x)
    {

/*        if list is empty*/

        if (head == null)
            head = new Node(x);
        else {

/*            get a new node*/

            Node newNode = new Node(x);

            Node ptr = head;
            int len = 0;

/*            calculate length of the linked list
            , i.e, the number of nodes*/

            while (ptr != null) {
                len++;
                ptr = ptr.next;
            }

/*            'count' the number of nodes after which
            the new node is to be inserted*/

            int count = ((len % 2) == 0) ? (len / 2) :
                                        (len + 1) / 2;
            ptr = head;

/*            'ptr' points to the node after which
            the new node is to be inserted*/

            while (count-- > 1)
                ptr = ptr.next;

/*            insert the 'newNode' and adjust
            the required links*/

            newNode.next = ptr.next;
            ptr.next = newNode;
        }
    }

/*    function to display the linked list*/

    static void display()
    {
        Node temp = head;
        while (temp != null)
        {
            System.out.print(temp.data + " ");
            temp = temp.next;
        }
    }

/*    Driver program to test above*/

    public static void main (String[] args)
    {

/*        Creating the list 1.2.4.5*/

        head = null;
        head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(4);
        head.next.next.next = new Node(5);

        System.out.println("Linked list before "+
                           "insertion: ");
        display();

        int x = 3;
        insertAtMid(x);

        System.out.println("\nLinked list after"+
                           " insertion: ");
        display();
    }
}

/*Java implementation to insert node
at the middle of the linked list*/

import java.util.*;
import java.lang.*;
import java.io.*;

class LinkedList
{

/*head of list*/

static Node head;

/* Node Class */

    static class Node {
        int data;
        Node next;

        Node(int d) {
            data = d;
            next = null;
        }
    }

/*    function to insert node at the
    middle of the linked list*/

    static void insertAtMid(int x)
    {

/*        if list is empty*/

        if (head == null)
        head = new Node(x);

        else {

/*            get a new node*/

            Node newNode = new Node(x);

/*            assign values to the slow
            and fast pointers*/

            Node slow = head;
            Node fast = head.next;

            while (fast != null && fast.next
                                  != null)
            {

/*                move slow pointer to next node*/

                slow = slow.next;

/*                move fast pointer two nodes
                at a time*/

                fast = fast.next.next;
            }

/*            insert the 'newNode' and adjust
            the required links*/

            newNode.next = slow.next;
            slow.next = newNode;
        }
    }

/*    function to display the linked list*/

    static void display()
    {
        Node temp = head;
        while (temp != null)
        {
            System.out.print(temp.data + " ");
            temp = temp.next;
        }
    }

/*    Driver program to test above*/

    public static void main (String[] args)
    {

/*        Creating the list 1.2.4.5*/

        head = null;
        head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(4);
        head.next.next.next = new Node(5);

        System.out.println("Linked list before"+
                           " insertion: ");
        display();

        int x = 3;
        insertAtMid(x);

        System.out.println("\nLinked list after"+
                           " insertion: ");
        display();
    }
}

/*Java program to rotate a linked list block wise*/

import java.util.*;
class GFG
{

/* Link list node */

static class Node
{
    int data;
    Node next;
};
static Node tail;

/*Recursive function to rotate one block*/

static Node rotateHelper(Node blockHead,
                        Node blockTail,
                        int d,
                        int k)
{
    if (d == 0)
        return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
        Node temp = blockHead;
        for (int i = 1; temp.next.next!=null &&
                        i < k - 1; i++)
            temp = temp.next;
        blockTail.next = blockHead;
        tail = temp;
        return rotateHelper(blockTail, temp,
                            d - 1,  k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
        blockTail.next = blockHead;
        tail = blockHead;
        return rotateHelper(blockHead.next,
                blockHead, d + 1,  k);
    }
    return blockHead;
}

/*Function to rotate the linked list block wise*/

static Node rotateByBlocks(Node head,
                                int k, int d)
{

/*    If length is 0 or 1 return head*/

    if (head == null || head.next == null)
        return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
        return head;

    Node temp = head;
    tail = null;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp.next != null && i < k; i++)
        temp = temp.next;

/*    storing the first node of next block*/

    Node nextBlock = temp.next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
        head = rotateHelper(head, temp, d % k,
                                   i);
    else
        head = rotateHelper(head, temp, d % k,
                                    k);

/*    Append the new head of next block to
    the tail of this block*/

    tail.next = rotateByBlocks(nextBlock, k,
                                    d % k);

/*    return head of updated Linked List*/

    return head;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static Node push(Node head_ref, int new_data)
{
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;

}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void main(String[] args)
{

/* Start with the empty list */

    Node head = null;

/*    create a list 1.2.3.4.5.
    6.7.8.9.null*/

    for (int i = 9; i > 0; i -= 1)
        head = push(head, i);
    System.out.print("Given linked list \n");
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);
    System.out.print("\nRotated by blocks Linked list \n");
    printList(head);
}
}

/* Given a node as prev_node, insert a new node after the given node */

public void InsertAfter(Node prev_Node, int new_data)
{

/*1. check if the given prev_node is NULL */

    if (prev_Node == null) {
        System.out.println("The given previous node cannot be NULL ");
        return;
    }

/* 2. allocate node
    * 3. put in the data */

    Node new_node = new Node(new_data);

/* 4. Make next of new node as next of prev_node */

    new_node.next = prev_Node.next;

/* 5. Make the next of prev_node as new_node */

    prev_Node.next = new_node;

/* 6. Make prev_node as previous of new_node */

    new_node.prev = prev_Node;

/* 7. Change previous of new_node's next node */

    if (new_node.next != null)
        new_node.next.prev = new_node;
}

/*Add a node at the end of the list*/

void append(int new_data)
{

/* 1. allocate node
     * 2. put in the data */

    Node new_node = new Node(new_data);

    Node last = head;

/* 3. This new node is going to be the last node, so
     * make next of it as NULL*/

    new_node.next = null;

/* 4. If the Linked List is empty, then make the new
     * node as head */

    if (head == null) {
        new_node.prev = null;
        head = new_node;
        return;
    }

/* 5. Else traverse till the last node */

    while (last.next != null)
        last = last.next;

/* 6. Change the next of last node */

    last.next = new_node;

/* 7. Make last node as previous of new node */

    new_node.prev = last;
}

/*Java implementation for Sorted merge of two
sorted doubly circular linked list*/

class GFG
{

static class Node
{
    int data;
    Node next, prev;
};

/*A utility function to insert a new node at the
beginning of doubly circular linked list*/

static Node insert(Node head_ref, int data)
{

/*    allocate space*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = data;

/*    if list is empty*/

    if (head_ref == null)
    {
        new_node.next = new_node;
        new_node.prev = new_node;
    }

    else
    {

/*        pointer points to last Node*/

        Node last = (head_ref).prev;

/*        setting up previous and next of new node*/

        new_node.next = head_ref;
        new_node.prev = last;

/*        update next and previous pointers of head_ref
        and last.*/

        last.next = (head_ref).prev = new_node;
    }

/*    update head_ref pointer*/

    head_ref = new_node;
    return head_ref;
}

/*function for Sorted merge of two
sorted doubly linked list*/

static Node merge(Node first, Node second)
{

/*    If first list is empty*/

    if (first == null)
        return second;

/*    If second list is empty*/

    if (second == null)
        return first;

/*    Pick the smaller value and adjust
    the links*/

    if (first.data < second.data)
    {
        first.next = merge(first.next, second);
        first.next.prev = first;
        first.prev = null;
        return first;
    }
    else
    {
        second.next = merge(first, second.next);
        second.next.prev = second;
        second.prev = null;
        return second;
    }
}

/*function for Sorted merge of two sorted
doubly circular linked list*/

static Node mergeUtil(Node head1, Node head2)
{

/*    if 1st list is empty*/

    if (head1 == null)
        return head2;

/*    if 2nd list is empty*/

    if (head2 == null)
        return head1;

/*    get pointer to the node which will be the
    last node of the final list*/

    Node last_node;
    if (head1.prev.data < head2.prev.data)
        last_node = head2.prev;
    else
        last_node = head1.prev;

/*    store null to the 'next' link of the last nodes
    of the two lists*/

    head1.prev.next = head2.prev.next = null;

/*    sorted merge of head1 and head2*/

    Node finalHead = merge(head1, head2);

/*    'prev' of 1st node pointing the last node
    'next' of last node pointing to 1st node*/

    finalHead.prev = last_node;
    last_node.next = finalHead;

    return finalHead;
}

/*function to print the list*/

static void printList(Node head)
{
    Node temp = head;

    while (temp.next != head)
    {
        System.out.print ( temp.data+ " ");
        temp = temp.next;
    }
    System.out.print ( temp.data + " ");
}

/*Driver code*/

public static void main(String args[])
{
    Node head1 = null, head2 = null;

/*    list 1:*/

    head1 = insert(head1, 8);
    head1 = insert(head1, 5);
    head1 = insert(head1, 3);
    head1 = insert(head1, 1);

/*    list 2:*/

    head2 = insert(head2, 11);
    head2 = insert(head2, 9);
    head2 = insert(head2, 7);
    head2 = insert(head2, 2);

    Node newHead = mergeUtil(head1, head2);

    System.out.print( "Final Sorted List: ");
    printList(newHead);
}
}

/*Java implementation for insertion Sort
on a doubly linked list*/

class Solution
{

/*Node of a doubly linked list*/

static class Node
{
    int data;
    Node prev, next;
};

/*function to create and return a new node
of a doubly linked list*/

static Node getNode(int data)
{

/*    allocate node*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.prev = newNode.next = null;
    return newNode;
}

/*function to insert a new node in sorted way in
a sorted doubly linked list*/

static Node sortedInsert(Node head_ref, Node newNode)
{
    Node current;

/*    if list is empty*/

    if (head_ref == null)
        head_ref = newNode;

/*    if the node is to be inserted at the beginning
    of the doubly linked list*/

    else if ((head_ref).data >= newNode.data)
    {
        newNode.next = head_ref;
        newNode.next.prev = newNode;
        head_ref = newNode;
    }

    else
    {
        current = head_ref;

/*        locate the node after which the new node
        is to be inserted*/

        while (current.next != null &&
            current.next.data < newNode.data)
            current = current.next;

/*        Make the appropriate links /*/


        newNode.next = current.next;

/*        if the new node is not inserted
        at the end of the list*/

        if (current.next != null)
            newNode.next.prev = newNode;

        current.next = newNode;
        newNode.prev = current;
    }
    return head_ref;
}

/*function to sort a doubly linked list using insertion sort*/

static Node insertionSort(Node head_ref)
{

/*    Initialize 'sorted' - a sorted doubly linked list*/

    Node sorted = null;

/*    Traverse the given doubly linked list and
    insert every node to 'sorted'*/

    Node current = head_ref;
    while (current != null)
    {

/*        Store next for next iteration*/

        Node next = current.next;

/*        removing all the links so as to create 'current'
        as a new node for insertion*/

        current.prev = current.next = null;

/*        insert current in 'sorted' doubly linked list*/

        sorted=sortedInsert(sorted, current);

/*        Update current*/

        current = next;
    }

/*    Update head_ref to point to sorted doubly linked list*/

    head_ref = sorted;

    return head_ref;
}

/*function to print the doubly linked list*/

static void printList(Node head)
{
    while (head != null)
    {
        System.out.print(head.data + " ");
        head = head.next;
    }
}

/*function to insert a node at the beginning of
the doubly linked list*/

static Node push(Node head_ref, int new_data)
{

/*    allocate node /*/

    Node new_node = new Node();

/*    put in the data /*/

    new_node.data = new_data;

/*    Make next of new node as head and previous as null /*/

    new_node.next = (head_ref);
    new_node.prev = null;

/*    change prev of head node to new node /*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node /*/

    (head_ref) = new_node;

    return head_ref;
}

/*Driver code*/

public static void main(String args[])
{

/*    start with the empty doubly linked list /*/

    Node head = null;

/*    insert the following data*/

    head=push(head, 9);
    head=push(head, 3);
    head=push(head, 5);
    head=push(head, 10);
    head=push(head, 12);
    head=push(head, 8);

    System.out.println( "Doubly Linked List Before Sorting\n");
    printList(head);

    head=insertionSort(head);

    System.out.println("\nDoubly Linked List After Sorting\n");
    printList(head);

}
}

/*Java program to print Nodes level by level between given two levels*/

import java.util.LinkedList;
import java.util.Queue;

/* A binary tree Node has key, pointer to left and right children */

class Node
{
    int data;
    Node left, right;

    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

class BinaryTree
{
    Node root;

/* Given a binary tree, print nodes from level number 'low' to level
       number 'high'*/

    void printLevels(Node node, int low, int high)
    {
        Queue<Node> Q = new LinkedList<>();

/*Marker node to indicate end of level*/

Node  marker = new Node(4);

/*Initialize level number*/

int level = 1;

/*        Enqueue the only first level node and marker node for end of level*/

        Q.add(node);
        Q.add(marker);

/*        Simple level order traversal loop*/

        while (Q.isEmpty() == false)
        {

/*            Remove the front item from queue*/

            Node  n = Q.peek();
            Q.remove();

/*            Check if end of level is reached*/

            if (n == marker)
            {

/*                print a new line and increment level number*/

                System.out.println("");
                level++;

/*                Check if marker node was last node in queue or
                level number is beyond the given upper limit*/

                if (Q.isEmpty() == true || level > high)
                    break;

/*                Enqueue the marker for end of next level*/

                Q.add(marker);

/*                If this is marker, then we don't need print it
                and enqueue its children*/

                continue;
            }

/*            If level is equal to or greater than given lower level,
            print it*/

            if (level >= low)
                System.out.print( n.data + " ");

/*            Enqueue children of non-marker node*/

            if (n.left != null)
                Q.add(n.left);

            if (n.right != null)
                Q.add(n.right);

        }
    }

/*    Driver program to test for above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.right = new Node(22);

        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);

        System.out.print("Level Order traversal between given two levels is ");
        tree.printLevels(tree.root, 2, 3);

    }
}

/*Java program to print nodes at k distance from root*/

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

class Node
{
    int data;
    Node left, right;

    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

class BinaryTree
{
