    root.left.left = newNode(4);
    root.right.left = newNode(5);
    root.right.right = newNode(8);
    root.right.left.left = newNode(6);
    root.right.left.right = newNode(7);
    root.right.right.left = newNode(9);
    root.right.right.right = newNode(10);

/*    Print leaf nodes of the given tree*/

    printLeafNodes(root);
}
}

/*Java program to print all nodes at a distance k from given node*/

/*A binary tree node*/

class Node
{
    int data;
    Node left, right;

    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

class BinaryTree
{
    Node root;

/* Recursive function to print all the nodes at distance k in
       tree (or subtree) rooted with given root. */


    void printkdistanceNodeDown(Node node, int k)
    {

/*        Base Case*/

        if (node == null || k < 0)
            return;

/*        If we reach a k distant node, print it*/

        if (k == 0)
        {
            System.out.print(node.data);
            System.out.println("");
            return;
        }

/*        Recur for left and right subtrees*/

        printkdistanceNodeDown(node.left, k - 1);
        printkdistanceNodeDown(node.right, k - 1);
    }

/*    Prints all nodes at distance k from a given target node.
    The k distant nodes may be upward or downward.This function
    Returns distance of root from target node, it returns -1
    if target node is not present in tree rooted with root.*/

    int printkdistanceNode(Node node, Node target, int k)
    {

/*        Base Case 1: If tree is empty, return -1*/

        if (node == null)
            return -1;

/*        If target is same as root.  Use the downward function
        to print all nodes at distance k in subtree rooted with
        target or root*/

        if (node == target)
        {
            printkdistanceNodeDown(node, k);
            return 0;
        }

/*        Recur for left subtree*/

        int dl = printkdistanceNode(node.left, target, k);

/*        Check if target node was found in left subtree*/

        if (dl != -1)
        {

/*            If root is at distance k from target, print root
            Note that dl is Distance of root's left child from
            target*/

            if (dl + 1 == k)
            {
                System.out.print(node.data);
                System.out.println("");
            }

/*            Else go to right subtree and print all k-dl-2 distant nodes
            Note that the right child is 2 edges away from left child*/

            else
                printkdistanceNodeDown(node.right, k - dl - 2);

/*            Add 1 to the distance and return value for parent calls*/

            return 1 + dl;
        }

/*        MIRROR OF ABOVE CODE FOR RIGHT SUBTREE
        Note that we reach here only when node was not found in left
        subtree*/

        int dr = printkdistanceNode(node.right, target, k);
        if (dr != -1)
        {
            if (dr + 1 == k)
            {
                System.out.print(node.data);
                System.out.println("");
            }
            else
                printkdistanceNodeDown(node.left, k - dr - 2);
            return 1 + dr;
        }

/*        If target was neither present in left nor in right subtree*/

        return -1;
    }

/*    Driver program to test the above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/* Let us construct the tree shown in above diagram */

        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.right = new Node(22);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);
        Node target = tree.root.left.right;
        tree.printkdistanceNode(tree.root, target, 2);
    }
}

/*Java program to print all nodes
that don't have sibling*/

/*A binary tree node*/

class Node
{
    int data;
    Node left, right;

    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

class BinaryTree
{
    Node root;

/*    Function to print all non-root nodes
    that don't have a sibling*/

    void printSingles(Node node)
    {

/*    Base case*/

    if (node == null)
      return;

/*    If this is an internal node, recur for left
    and right subtrees*/

    if (node.left != null && node.right != null)
    {
        printSingles(node.left);
        printSingles(node.right);
    }

/*    If left child is NULL and right
    is not, print right child
    and recur for right child*/

    else if (node.right != null)
    {
        System.out.print(node.right.data + " ");
        printSingles(node.right);
    }

/*    If right child is NULL and left
    is not, print left child
    and recur for left child*/

    else if (node.left != null)
    {
        System.out.print( node.left.data + " ");
        printSingles(node.left);
    }
}

/*    Driver program to test the above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/* Let us construct the tree
           shown in above diagram */

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.right = new Node(4);
        tree.root.right.left = new Node(5);
        tree.root.right.left.right = new Node(6);
        tree.printSingles(tree.root);
    }
}

/*Java program to print all nodes at a distance k from leaf
A binary tree node*/

class Node {
    int data;
    Node left, right;

    Node(int item)
    {
        data = item;
        left = right = null;
    }
}

class BinaryTree {
    Node root;

/* This function prints all nodes that are distance k from a leaf node
     path[] --> Store ancestors of a node
     visited[] --> Stores true if a node is printed as output.  A node may
     be k distance away from many leaves, we want to print it once */

    void kDistantFromLeafUtil(Node node, int path[], boolean visited[],
                              int pathLen, int k)
    {

/*        Base case*/

        if (node == null)
            return;

/* append this Node to the path array */

        path[pathLen] = node.data;
        visited[pathLen] = false;
        pathLen++;

/* it's a leaf, so print the ancestor at distance k only
         if the ancestor is not already printed  */

        if (node.left == null && node.right == null
            && pathLen - k - 1 >= 0 && visited[pathLen - k - 1] == false) {
            System.out.print(path[pathLen - k - 1] + " ");
            visited[pathLen - k - 1] = true;
            return;
        }

/* If not leaf node, recur for left and right subtrees */

        kDistantFromLeafUtil(node.left, path, visited, pathLen, k);
        kDistantFromLeafUtil(node.right, path, visited, pathLen, k);
    }

/* Given a binary tree and a nuber k, print all nodes that are k
     distant from a leaf*/

    void printKDistantfromLeaf(Node node, int k)
    {
        int path[] = new int[1000];
        boolean visited[] = new boolean[1000];
        kDistantFromLeafUtil(node, path, visited, 0, k);
    }

/*    Driver program to test the above functions*/

    public static void main(String args[])
    {
        BinaryTree tree = new BinaryTree();

/* Let us construct the tree shown in above diagram */

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        tree.root.right.left.right = new Node(8);

        System.out.println(" Nodes at distance 2 are :");
        tree.printKDistantfromLeaf(tree.root, 2);
    }
}

/*Java program to print left view of binary tree*/

/* Class containing left and right child of current
node and key value*/

class Node {
    int data;
    Node left, right;

    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/* Class to print the left view */

class BinaryTree {
    Node root;
    static int max_level = 0;

/*    recursive function to print left view*/

    void leftViewUtil(Node node, int level)
    {

/*        Base Case*/

        if (node == null)
            return;

/*        If this is the first node of its level*/

        if (max_level < level) {
            System.out.print(" " + node.data);
            max_level = level;
        }

/*        Recur for left and right subtrees*/

        leftViewUtil(node.left, level + 1);
        leftViewUtil(node.right, level + 1);
    }

/*    A wrapper over leftViewUtil()*/

    void leftView()
    {
        leftViewUtil(root, 1);
    }

