class GFG{

/*Function to calculate the maximum
sum of length k*/

static int MaxSum(int []arr,
                  int n, int k)
{
  int i, max_sum = 0, sum = 0;

/*  Calculating the max sum for
  the first k elements*/

  for (i = 0; i < k; i++)
  {
    sum += arr[i];
  }
  max_sum = sum;

/*  Find subarray with maximum sum*/

  while (i < n)
  {

/*    Update the sum*/

    sum = sum - arr[i - k] +
                arr[i];
    if (max_sum < sum)
    {
      max_sum = sum;
    }
    i++;
  }

/*  Return maximum sum*/

  return max_sum;
}

/*Function to calculate gcd
  of the two numbers n1 and n2*/

static int gcd(int n1, int n2)
{

/*  Base Case*/

  if (n2 == 0)
  {
    return n1;
  }

/*  Recursively find the GCD*/

  else
  {
    return gcd(n2, n1 % n2);
  }
}

/*Function to rotate the array by Y*/

static int []RotateArr(int []arr,
                       int n, int d)
{

/*  For handling k >= N*/

  int i = 0, j = 0;
  d = d % n;

/*  Dividing the array into
  number of sets*/

  int no_of_sets = gcd(d, n);

  for (i = 0; i < no_of_sets; i++)
  {
    int temp = arr[i];
    j = i;

/*    Rotate the array by Y*/

    while (true)
    {
      int k = j + d;

      if (k >= n)
        k = k - n;

      if (k == i)
        break;

      arr[j] = arr[k];
      j = k;
    }

/*    Update arr[j]*/

    arr[j] = temp;
  }

/*  Return the rotated array*/

  return arr;
}

/*Function that performs the queries
on the given array*/

static void performQuery(int []arr,
                         int Q[][], int q)
{
  int N = arr.length;

/*  Traverse each query*/

  for (int i = 0; i < q; i++)
  {

/*    If query of type X = 1*/

    if (Q[i][0] == 1)
    {
      arr = RotateArr(arr, N,
                      Q[i][1]);

/*      Print the array*/

      for (int t : arr)
      {
        System.out.print(t + " ");
      }
      System.out.print("\n");
    }

/*    If query of type X = 2*/

    else
    {
      System.out.print(MaxSum(arr, N,
                              Q[i][1]) + "\n");
    }
  }
}

/*Driver Code*/

public static void main(String[] args)
{

/*  Given array arr[]*/

  int []arr = {1, 2, 3, 4, 5};

  int q = 5;

/*  Given Queries*/

  int Q[][] = {{1, 2}, {2, 3},
               {1, 3}, {1, 1},
               {2, 4}};

/*  Function Call*/

  performQuery(arr, Q, q);
}
}

