    arr[1] = 2;
    arr[2] = 3;
    arr[3] = 4;

    for(int i = 0; i < 4; i++)
    {
        fun(arr, i);

        System.out.print("[");
        for(int j = 0; j < 4; j++)
        {
            System.out.print(arr[j] + ", ");
        }
        System.out.print("]");
    }
}
}

