    rotations*/

    public static int countRotation(int[] arr,
                                    int n)
    {
        for (int i = 1; i < n; i++) {

/*            Find the smallest element*/

            if (arr[i] < arr[i - 1]) {

/*                Return its index*/

                return i;
            }
        }

/*        If array is not
        rotated at all*/

        return 0;
    }

/*    Driver Code*/

