/*Java implementation of the above approach*/

import java.util.*;

class Solution
{

/*Definition of node of linkedlist*/

static class ListNode {
    int data;
     ListNode next;
}

/*This function take head pointer of list, start and
end points of sublist that is to be rotated and the
number k and rotate the sublist to right by k places.*/

static void rotateSubList(ListNode A, int m, int n, int k)
{
    int size = n - m + 1;

/*    If k is greater than size of sublist then 
    we will take its modulo with size of sublist*/

    if (k > size) {
        k = k % size;
    }

/*    If k is zero or k is equal to size or k is
    a multiple of size of sublist then list 
    remains intact*/

    if (k == 0 || k == size) {
        ListNode head = A;
        while (head != null) {
            System.out.print( head.data);
            head = head.next;
        }
        return;
    }

/*m-th node*/

ListNode link = null;  
    if (m == 1) {
        link = A;
    }

/*    This loop will traverse all node till
    end node of sublist.    
Current traversed node*/

ListNode c = A;

/*Count of traversed nodes*/

int count = 0;  
    ListNode end = null;

/*Previous of m-th node*/

ListNode pre = null; 
    while (c != null) {
        count++;

/*        We will save (m-1)th node and later
        make it point to (n-k+1)th node*/

        if (count == m - 1) {
            pre = c;
            link = c.next;
        }
        if (count == n - k) {
            if (m == 1) {
                end = c;
                A = c.next;
            }
            else {
                end = c;

/*                That is how we bring (n-k+1)th
                node to front of sublist.*/

                pre.next = c.next;
            }
        }

/*        This keeps rest part of list intact.*/

        if (count == n) {
            ListNode d = c.next;
            c.next = link;
            end.next = d;
            ListNode head = A;
            while (head != null) {
                System.out.print( head.data+" ");
                head = head.next;
            }
            return;
        }
        c = c.next;
    }
}

/*Function for creating and linking new nodes*/

static ListNode push( ListNode head, int val)
{
     ListNode new_node = new ListNode();
    new_node.data = val;
    new_node.next = (head);
    (head) = new_node;
    return head;
}

/*Driver code*/

public static void main(String args[])
{
     ListNode head = null;
    head =push(head, 70);
    head =push(head, 60);
    head =push(head, 50);
    head =push(head, 40);
    head =push(head, 30);
    head =push(head, 20);
    head =push(head, 10);
    ListNode tmp = head;
    System.out.print("Given List: ");
    while (tmp != null) {
        System.out.print( tmp.data + " ");
        tmp = tmp.next;
    }
    System.out.println();

    int m = 3, n = 6, k = 2;
    System.out.print( "After rotation of sublist: ");
    rotateSubList(head, m, n, k);

}
}

/*Java program to check if an
array is sorted and rotated
clockwise*/

import java.io.*;

class GFG {

/*    Function to check if an array is
    sorted and rotated clockwise*/

    static void checkIfSortRotated(int arr[], int n)
    {
        int minEle = Integer.MAX_VALUE;
        int maxEle = Integer.MIN_VALUE;

        int minIndex = -1;

/*        Find the minimum element
        and it's index*/

        for (int i = 0; i < n; i++) {
            if (arr[i] < minEle) {
                minEle = arr[i];
                minIndex = i;
            }
        }

        boolean flag1 = true;

/*        Check if all elements before
        minIndex are in increasing order*/

        for (int i = 1; i < minIndex; i++) {
            if (arr[i] < arr[i - 1]) {
                flag1 = false;
                break;
            }
        }

        boolean flag2 = true;

/*        Check if all elements after
        minIndex are in increasing order*/

        for (int i = minIndex + 1; i < n; i++) {
            if (arr[i] < arr[i - 1]) {
                flag2 = false;
                break;
            }
        }

/*        check if the minIndex is 0, i.e the first element
        is the smallest , which is the case when array is
        sorted but not rotated.*/

        if (minIndex == 0) {
            System.out.print("NO");
            return;
        }

/*        Check if last element of the array
        is smaller than the element just
        before the element at minIndex
        starting element of the array
        for arrays like [3,4,6,1,2,5] - not sorted
        circular array*/

        if (flag1 && flag2 && (arr[n - 1] < arr[0]))
            System.out.println("YES");
        else
            System.out.print("NO");
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 3, 4, 5, 1, 2 };

        int n = arr.length;

/*        Function Call*/

        checkIfSortRotated(arr, n);
    }
}

import java.io.*;

class GFG {

/*    Function to check if an array is
    Sorted and rotated clockwise*/

    static boolean checkIfSortRotated(int arr[], int n)
    {

/*        Initializing two variables x,y as zero.*/

        int x = 0, y = 0;

/*        Traversing array 0 to last element.
        n-1 is taken as we used i+1.*/

        for (int i = 0; i < n - 1; i++) {
            if (arr[i] < arr[i + 1])
                x++;
            else
                y++;
        }

/*        If till now both x,y are greater
        then 1 means array is not sorted.
        If both any of x,y is zero means
        array is not rotated.*/

        if (x == 1 || y == 1) {

/*            Checking for last element with first.*/

            if (arr[n - 1] < arr[0])
                x++;
            else
                y++;

/*            Checking for final result.*/

            if (x == 1 || y == 1)
                return true;
        }

/*        If still not true then definetly false.*/

        return false;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = { 5, 1, 2, 3, 4 };

        int n = arr.length;

/*        Function Call*/

        boolean x = checkIfSortRotated(arr, n);
        if (x == true)
            System.out.println("YES");
        else
            System.out.println("NO");
    }
}

/*Java implementation to find
elements that appeared only once*/

class GFG
{

/*Function to find the elements that
appeared only once in the array*/

static void occurredOnce(int arr[], int n)
{
    int i = 1, len = n;

/*    Check if the first and last
    element is equal. If yes,
    remove those elements*/

    if (arr[0] == arr[len - 1])
    {
        i = 2;
        len--;
    }

/*    Start traversing the
    remaining elements*/

    for (; i < n; i++)

/*        Check if current element is
        equal to the element at
        immediate previous index
        If yes, check the same
        for next element*/

        if (arr[i] == arr[i - 1])
            i++;

/*        Else print the current element*/

        else
            System.out.print(arr[i - 1] + " ");

/*    Check for the last element*/

    if (arr[n - 1] != arr[0] &&
        arr[n - 1] != arr[n - 2])
        System.out.print(arr[n - 1]);
}

/*Driver code*/

public static void main(String args[])
{
    int arr[] = {7, 7, 8, 8, 9,
                 1, 1, 4, 2, 2};
