    occurredOnce(arr, n);
}
}

/*Java program to check if two strings are rotations
of each other.*/

import java.util.*;
import java.lang.*;
import java.io.*;
class stringMatching {
    public static boolean isRotation(String a, String b)
    {
        int n = a.length();
        int m = b.length();
        if (n != m)
            return false;

/*        create lps[] that will hold the longest
        prefix suffix values for pattern*/

        int lps[] = new int[n];

/*        length of the previous longest prefix suffix*/

        int len = 0;
        int i = 1;

/*lps[0] is always 0*/

lps[0] = 0;

/*        the loop calculates lps[i] for i = 1 to n-1*/

        while (i < n) {
            if (a.charAt(i) == b.charAt(len)) {
                lps[i] = ++len;
                ++i;
            }
            else {
                if (len == 0) {
                    lps[i] = 0;
                    ++i;
                }
                else {
                    len = lps[len - 1];
                }
            }
        }

        i = 0;

/*        match from that rotating point*/

        for (int k = lps[n - 1]; k < m; ++k) {
            if (b.charAt(k) != a.charAt(i++))
                return false;
        }
        return true;
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        String s1 = "ABACD";
        String s2 = "CDABA";

        System.out.println(isRotation(s1, s2) ? "1" : "0");
    }
}

/*Java program to count all
rotations divisible by 8*/

import java.io.*;

class GFG
{

/*    function to count of all
    rotations divisible by 8*/

    static int countRotationsDivBy8(String n)
    {
        int len = n.length();
        int count = 0;

/*        For single digit number*/

        if (len == 1) {
            int oneDigit = n.charAt(0) - '0';
            if (oneDigit % 8 == 0)
                return 1;
            return 0;
        }

/*        For two-digit numbers
        (considering all pairs)*/

        if (len == 2) {

/*            first pair*/

            int first = (n.charAt(0) - '0') *
                        10 + (n.charAt(1) - '0');

/*            second pair*/

            int second = (n.charAt(1) - '0') *
                         10 + (n.charAt(0) - '0');

            if (first % 8 == 0)
                count++;
            if (second % 8 == 0)
                count++;
            return count;
        }

/*        considering all three-digit sequences*/

        int threeDigit;
        for (int i = 0; i < (len - 2); i++)
        {
            threeDigit = (n.charAt(i) - '0') * 100 +
                        (n.charAt(i + 1) - '0') * 10 +
                        (n.charAt(i + 2) - '0');
            if (threeDigit % 8 == 0)
                count++;
        }

/*        Considering the number formed by the
        last digit and the first two digits*/

        threeDigit = (n.charAt(len - 1) - '0') * 100 +
                    (n.charAt(0) - '0') * 10 +
                    (n.charAt(1) - '0');

        if (threeDigit % 8 == 0)
            count++;

/*        Considering the number formed by the last
        two digits and the first digit*/

        threeDigit = (n.charAt(len - 2) - '0') * 100 +
                    (n.charAt(len - 1) - '0') * 10 +
                    (n.charAt(0) - '0');
        if (threeDigit % 8 == 0)
            count++;

/*        required count of rotations*/

        return count;
    }

/*    Driver program*/

    public static void main (String[] args)
    {
        String n = "43262488612";
        System.out.println( "Rotations: "
                       +countRotationsDivBy8(n));

    }
}

/*Java implementation for restoring original
sort in rotated sorted array*/

class GFG
{

/*Function to restore the Original Sort*/

static void restoreSortedArray(int arr[], int n)
{
    for (int i = 0; i < n; i++)
    {
        if (arr[i] > arr[i + 1])
        {

/*            In reverse(), the first parameter
            is iterator to beginning element
            and second parameter is iterator
            to last element plus one.*/

            reverse(arr,0,i);
            reverse(arr , i + 1, n);
            reverse(arr,0, n);
        }
    }
}

static void reverse(int[] arr, int i, int j)
{
    int temp;
    while(i < j)
    {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

/*Function to print the Array*/

static void printArray(int arr[], int size)
{
    for (int i = 0; i < size; i++)
        System.out.print(arr[i] + " ");
}

/*Driver code*/

public static void main(String[] args)
{
    int arr[] = { 3, 4, 5, 1, 2 };
    int n = arr.length;
    restoreSortedArray(arr, n - 1);
    printArray(arr, n);
}
}

/*Java implementation for restoring original
sort in rotated sorted array using binary search*/

import java.util.*;

class GFG
{

/*    Function to find start index of array*/

    static int findStartIndexOfArray(int arr[],
                            int low, int high)
    {
        if (low > high)
        {
            return -1;
        }

        if (low == high)
        {
            return low;
        }

        int mid = low + (high - low) / 2;
        if (arr[mid] > arr[mid + 1])
        {
            return mid + 1;
        }

        if (arr[mid - 1] > arr[mid])
        {
            return mid;
        }

        if (arr[low] > arr[mid])
        {
            return findStartIndexOfArray(arr, low, mid - 1);
        }
        else
        {
            return findStartIndexOfArray(arr, mid + 1, high);
        }
    }

/*    Function to restore the Original Sort*/

    static void restoreSortedArray(int arr[], int n)
    {

/*        array is already sorted*/

        if (arr[0] < arr[n - 1])
        {
            return;
        }

        int start = findStartIndexOfArray(arr, 0, n - 1);

/*        In reverse(), the first parameter
        is iterator to beginning element
        and second parameter is iterator
        to last element plus one.*/

        Arrays.sort(arr, 0, start);
        Arrays.sort(arr, start, n);
        Arrays.sort(arr);

    }

/*    Function to print the Array*/

    static void printArray(int arr[], int size)
    {
        for (int i = 0; i < size; i++)
        {
            System.out.print(arr[i] + " ");
        }
    }

/*    Driver code*/

    public static void main(String[] args)
    {
        int arr[] = {1, 2, 3, 4, 5};
        int n = arr.length;
        restoreSortedArray(arr, n);
        printArray(arr, n);
    }
}

/*Java program to rotate a linked list block wise*/

import java.util.*;
class GFG
{

/* Link list node */

static class Node
{
    int data;
    Node next;
};
static Node tail;

/*Recursive function to rotate one block*/

static Node rotateHelper(Node blockHead,
                        Node blockTail,
                        int d,
                        int k)
{
    if (d == 0)
        return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
        Node temp = blockHead;
        for (int i = 1; temp.next.next!=null &&
                        i < k - 1; i++)
            temp = temp.next;
        blockTail.next = blockHead;
        tail = temp;
        return rotateHelper(blockTail, temp,
                            d - 1,  k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
        blockTail.next = blockHead;
        tail = blockHead;
        return rotateHelper(blockHead.next,
                blockHead, d + 1,  k);
    }
    return blockHead;
}

/*Function to rotate the linked list block wise*/

static Node rotateByBlocks(Node head,
                                int k, int d)
{

/*    If length is 0 or 1 return head*/

    if (head == null || head.next == null)
        return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
        return head;

    Node temp = head;
    tail = null;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp.next != null && i < k; i++)
        temp = temp.next;

/*    storing the first node of next block*/

    Node nextBlock = temp.next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
        head = rotateHelper(head, temp, d % k,
                                   i);
    else
        head = rotateHelper(head, temp, d % k,
                                    k);

/*    Append the new head of next block to
    the tail of this block*/

    tail.next = rotateByBlocks(nextBlock, k,
                                    d % k);

/*    return head of updated Linked List*/

    return head;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static Node push(Node head_ref, int new_data)
{
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;

}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        System.out.print(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void main(String[] args)
{

/* Start with the empty list */

    Node head = null;

/*    create a list 1.2.3.4.5.
    6.7.8.9.null*/

    for (int i = 9; i > 0; i -= 1)
        head = push(head, i);
    System.out.print("Given linked list \n");
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);
    System.out.print("\nRotated by blocks Linked list \n");
    printList(head);
}
}

/*Java program to check if two numbers are bit rotations
of each other.*/

class GFG {

/*function to check if two numbers are equal
after bit rotation*/

    static boolean isRotation(long x, long y) {

/*        x64 has concatenation of x with itself.*/

        long x64 = x | (x << 32);

        while (x64 >= y) {

/*            comapring only last 32 bits*/

            if (x64 == y) {
                return true;
            }

/*            right shift by 1 unit*/

            x64 >>= 1;
        }
        return false;
    }

/*driver code to test above function*/

    public static void main(String[] args) {
        long x = 122;
        long y = 2147483678L;

        if (isRotation(x, y) == false) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

/*Java program to count
all rotation divisible
by 4.*/

import java.io.*;

class GFG {

/*    Returns count of all
    rotations divisible
    by 4*/

    static int countRotations(String n)
    {
        int len = n.length();

/*        For single digit number*/

        if (len == 1)
        {
          int oneDigit = n.charAt(0)-'0';

          if (oneDigit % 4 == 0)
              return 1;

          return 0;
        }

/*        At-least 2 digit
        number (considering all
        pairs)*/

        int twoDigit, count = 0;
        for (int i = 0; i < (len-1); i++)
        {
          twoDigit = (n.charAt(i)-'0') * 10 +
                     (n.charAt(i+1)-'0');

          if (twoDigit%4 == 0)
              count++;
        }

/*        Considering the number
        formed by the pair of
        last digit and 1st digit*/

        twoDigit = (n.charAt(len-1)-'0') * 10 +
                   (n.charAt(0)-'0');

        if (twoDigit%4 == 0)
            count++;

        return count;
    }

/*    Driver program*/

    public static void main(String args[])
    {
        String n = "4834";
        System.out.println("Rotations: " +
                          countRotations(n));
    }
}

/*Java program for the above approach*/


import java.io.*;
import java.util.*;

class GFG {
    static Node head;

/*    Node structure of the circular
    Linked list*/

    static class Node {
        int data;
        Node next;

/*        Constructor*/

        public Node(int data)
        {
            this.data = data;
            this.next = null;
        }
    }

/*    Function to print the elements
    of a Linked list*/

    static void print(Node head)
    {
        Node temp = head;

/*        Iterate the linked list*/

        while (temp != null) {

/*            Print the data*/

            System.out.print(
                temp.data + " ");
            temp = temp.next;
        }
    }

/*    Function to find the next
    greater element for each node*/

    static void NextGreaterElement(Node head)
    {

/*        Stores the head of circular
        Linked list*/

        Node H = head;

/*        Stores the head of the
        resulting linked list*/

        Node res = null;

/*        Stores the temporary head of
        the resulting Linked list*/

        Node tempList = null;

/*        Iterate until head
        is not equal to H*/

        do {

/*            Used to iterate over the
            circular Linked List*/

            Node curr = head;

/*            Stores if there exist
            any next Greater element*/

            int Val = -1;

/*            Iterate until head is
            not equal to curr*/

            do {

/*                If the current node
                is smaller*/

                if (head.data < curr.data) {

/*                    Update the value
                    of Val*/

                    Val = curr.data;
                    break;
                }

/*                Update curr*/

                curr = curr.next;

            } while (curr != head);

/*            If res is Null*/

            if (res == null) {

/*                Create new Node with
                value curr.data*/

                res = new Node(Val);

/*                Assign address of
                res to tempList*/

                tempList = res;
            }
            else {

/*                Update tempList*/

                tempList.next = new Node(Val);

/*                Assign address of the
                next node to tempList*/

                tempList = tempList.next;
            }

/*            Update the value of
            head node*/

            head = head.next;
        } while (head != H);

/*        Print the resulting
        Linked list*/

        print(res);
    }

/*    Driver Code*/

    public static void main(String[] args)
    {
        head = new Node(1);
        head.next = new Node(5);
        head.next.next = new Node(12);
        head.next.next.next = new Node(10);

        head.next.next.next.next = new Node(0);
        head.next.next.next.next.next = head;

        NextGreaterElement(head);
    }
}

/*Java program to remove all
the Even Parity Nodes from a
circular singly linked list*/

class GFG{

/*Structure for a node*/

static class Node
{
    int data;
    Node next;
};

/*Function to insert a node at
the beginning of a Circular
linked list*/

static Node push(Node head_ref, int data)
{

/*    Create a new node
    and make head as next
    of it.*/

    Node ptr1 = new Node();

    Node temp = head_ref;
    ptr1.data = data;
    ptr1.next = head_ref;

/*    If linked list is not null then
    set the next of last node*/

    if (head_ref != null)
    {

/*        Find the node before head
        and update next of it.*/

        while (temp.next != head_ref)
            temp = temp.next;

        temp.next = ptr1;
    }
    else

/*        Point for the first node*/

        ptr1.next = ptr1;

    head_ref = ptr1;
    return head_ref;
}

/*Function to delete the node
from a Circular Linked list*/

static void deleteNode(Node head_ref,
                       Node del)
{

/*    If node to be deleted is
    head node*/

    if (head_ref == del)
        head_ref = del.next;

    Node temp = head_ref;

/*    Traverse list till not found
    delete node*/

    while (temp.next != del)
    {
        temp = temp.next;
    }

/*    Copy the address of the node*/

    temp.next = del.next;

/*    Finally, free the memory
    occupied by del*/

    System.gc();

    return;
}

/*Function that returns true if count
of set bits in x is even*/

static boolean isEvenParity(int x)
{

/*    Parity will store the
    count of set bits*/

    int parity = 0;

    while (x != 0)
    {
        if ((x & 1) != 0)
            parity++;

        x = x >> 1;
    }

    if (parity % 2 == 0)
        return true;
    else
        return false;
}

/*Function to delete all the
Even Parity Nodes from the
singly circular linked list*/

static void deleteEvenParityNodes(Node head)
{
    if (head == null)
        return;

    if (head == head.next)
    {
        if (isEvenParity(head.data))
            head = null;

        return;
    }

    Node ptr = head;
    Node next;

/*    Traverse the list till the end*/

    do
    {
        next = ptr.next;

/*        If the node's data has
        even parity, delete node 'ptr'*/

        if (isEvenParity(ptr.data))
            deleteNode(head, ptr);

/*        Point to the next node*/

        ptr = next;

    } while (ptr != head);

    if (head == head.next)
    {
        if (isEvenParity(head.data))
            head = null;

        return;
    }
}

/*Function to print nodes in a
given Circular linked list*/

static void printList(Node head)
{
    if (head == null)
    {
        System.out.print("Empty List\n");
        return;
    }

    Node temp = head;
    if (head != null)
    {
        do
        {
            System.out.printf("%d ", temp.data);
            temp = temp.next;
        } while (temp != head);
    }
}

/*Driver code*/

public static void main(String[] args)
{

/*    Initialize lists as empty*/

    Node head = null;

/*    Created linked list will be
    11.9.34.6.13.21*/

    head = push(head, 21);
    head = push(head, 13);
    head = push(head, 6);
    head = push(head, 34);
    head = push(head, 9);
    head = push(head, 11);

    deleteEvenParityNodes(head);

    printList(head);
}
}

/*Java program to remove all
the Even Digit Sum Nodes from a
circular singly linked list*/

import java.util.*;

class GFG{

/*Structure for a node*/

static class Node
{
    int data;
    Node next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

static Node push(Node head_ref, int data)
{

/*    Create a new node and make head
    as next of it.*/

    Node ptr1 = new Node();

    Node temp = head_ref;
    ptr1.data = data;
    ptr1.next = head_ref;

/*    If linked list is not null then
    set the next of last node*/

    if (head_ref != null)
    {

/*        Find the node before head
        and update next of it.*/

        while (temp.next != head_ref)
            temp = temp.next;

        temp.next = ptr1;
    }
    else

/*        Point for the first node*/

        ptr1.next = ptr1;

    head_ref = ptr1;
    return head_ref;
}

/*Function to delete the node from a
Circular Linked list*/

static void deleteNode(Node head_ref, Node del)
{
    Node temp = head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Traverse list till not found
    delete node*/

    while (temp.next != del)
    {
        temp = temp.next;
    }

/*    Copy the address of the node*/

    temp.next = del.next;

/*    Finally, free the memory
    occupied by del*/

    del = null;

    return;
}

/*Function to find the digit sum
for a number*/

static int digitSum(int num)
{
    int sum = 0;

    while (num > 0)
    {
        sum += (num % 10);
        num /= 10;
    }
    return sum;
}

/*Function to delete all the Even Digit
Sum Nodes from the singly circular
linked list*/

static void deleteEvenDigitSumNodes(Node head)
{
    Node ptr = head;
    Node next;

/*    Traverse the list till the end*/

    do
    {

/*        If the node's data is Fibonacci,
        delete node 'ptr'*/

        if (!(digitSum(ptr.data) % 2 == 1))
            deleteNode(head, ptr);

/*        Point to the next node*/

        next = ptr.next;
        ptr = next;
    } while (ptr != head);
}

